            613 => static function ($self, $stackPos) {
                 $self->semValue = $self->semStack[$stackPos-(3-2)];
            },
            614 => null,
            615 => null,
            616 => static function ($self, $stackPos) {
                 $self->semValue = $self->semStack[$stackPos-(3-2)];
            },
            617 => null,
            618 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\Error($self->getAttributes($self->tokenStartStack[$stackPos-(1-1)], $self->tokenEndStack[$stackPos])); $self->errorState = 2;
            },
            619 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\List_($self->semStack[$stackPos-(4-3)], $self->getAttributes($self->tokenStartStack[$stackPos-(4-1)], $self->tokenEndStack[$stackPos])); $self->semValue->setAttribute('kind', Expr\List_::KIND_LIST);
            $self->postprocessList($self->semValue);
            },
            620 => static function ($self, $stackPos) {
                 $self->semValue = $self->semStack[$stackPos-(1-1)]; $end = count($self->semValue)-1; if ($self->semValue[$end]->value instanceof Expr\Error) array_pop($self->semValue);
            },
            621 => null,
            622 => static function ($self, $stackPos) {
                 /* do nothing -- prevent default action of $$=$self->semStack[$1]. See $551. */
            },
            623 => static function ($self, $stackPos) {
                 $self->semStack[$stackPos-(3-1)][] = $self->semStack[$stackPos-(3-3)]; $self->semValue = $self->semStack[$stackPos-(3-1)];
            },
            624 => static function ($self, $stackPos) {
                 $self->semValue = array($self->semStack[$stackPos-(1-1)]);
            },
            625 => static function ($self, $stackPos) {
                 $self->semValue = new Node\ArrayItem($self->semStack[$stackPos-(1-1)], null, false, $self->getAttributes($self->tokenStartStack[$stackPos-(1-1)], $self->tokenEndStack[$stackPos]));
            },
            626 => static function ($self, $stackPos) {
                 $self->semValue = new Node\ArrayItem($self->semStack[$stackPos-(2-2)], null, true, $self->getAttributes($self->tokenStartStack[$stackPos-(2-1)], $self->tokenEndStack[$stackPos]));
            },
            627 => static function ($self, $stackPos) {
                 $self->semValue = new Node\ArrayItem($self->semStack[$stackPos-(1-1)], null, false, $self->getAttributes($self->tokenStartStack[$stackPos-(1-1)], $self->tokenEndStack[$stackPos]));
            },
            628 => static function ($self, $stackPos) {
                 $self->semValue = new Node\ArrayItem($self->semStack[$stackPos-(3-3)], $self->semStack[$stackPos-(3-1)], false, $self->getAttributes($self->tokenStartStack[$stackPos-(3-1)], $self->tokenEndStack[$stackPos]));
            },
            629 => static function ($self, $stackPos) {
                 $self->semValue = new Node\ArrayItem($self->semStack[$stackPos-(4-4)], $self->semStack[$stackPos-(4-1)], true, $self->getAttributes($self->tokenStartStack[$stackPos-(4-1)], $self->tokenEndStack[$stackPos]));
            },
            630 => static function ($self, $stackPos) {
                 $self->semValue = new Node\ArrayItem($self->semStack[$stackPos-(3-3)], $self->semStack[$stackPos-(3-1)], false, $self->getAttributes($self->tokenStartStack[$stackPos-(3-1)], $self->tokenEndStack[$stackPos]));
            },
            631 => static function ($self, $stackPos) {
                 $self->semValue = new Node\ArrayItem($self->semStack[$stackPos-(2-2)], null, false, $self->getAttributes($self->tokenStartStack[$stackPos-(2-1)], $self->tokenEndStack[$stackPos]), true);
            },
            632 => static function ($self, $stackPos) {
                 /* Create an Error node now to remember the position. We'll later either report an error,
             or convert this into a null element, depending on whether this is a creation or destructuring context. */
          $attrs = $self->createEmptyElemAttributes($self->tokenPos);
          $self->semValue = new Node\ArrayItem(new Expr\Error($attrs), null, false, $attrs);
            },
            633 => static function ($self, $stackPos) {
                 $self->semStack[$stackPos-(2-1)][] = $self->semStack[$stackPos-(2-2)]; $self->semValue = $self->semStack[$stackPos-(2-1)];
            },
            634 => static function ($self, $stackPos) {
                 $self->semStack[$stackPos-(2-1)][] = $self->semStack[$stackPos-(2-2)]; $self->semValue = $self->semStack[$stackPos-(2-1)];
            },
            635 => static function ($self, $stackPos) {
                 $self->semValue = array($self->semStack[$stackPos-(1-1)]);
            },
            636 => static function ($self, $stackPos) {
                 $self->semValue = array($self->semStack[$stackPos-(2-1)], $self->semStack[$stackPos-(2-2)]);
            },
            637 => static function ($self, $stackPos) {
                 $attrs = $self->getAttributes($self->tokenStartStack[$stackPos-(1-1)], $self->tokenEndStack[$stackPos]); $attrs['rawValue'] = $self->semStack[$stackPos-(1-1)]; $self->semValue = new Node\InterpolatedStringPart($self->semStack[$stackPos-(1-1)], $attrs);
            },
            638 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\Variable($self->semStack[$stackPos-(1-1)], $self->getAttributes($self->tokenStartStack[$stackPos-(1-1)], $self->tokenEndStack[$stackPos]));
            },
            639 => null,
            640 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\ArrayDimFetch($self->semStack[$stackPos-(4-1)], $self->semStack[$stackPos-(4-3)], $self->getAttributes($self->tokenStartStack[$stackPos-(4-1)], $self->tokenEndStack[$stackPos]));
            },
            641 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\PropertyFetch($self->semStack[$stackPos-(3-1)], $self->semStack[$stackPos-(3-3)], $self->getAttributes($self->tokenStartStack[$stackPos-(3-1)], $self->tokenEndStack[$stackPos]));
            },
            642 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\NullsafePropertyFetch($self->semStack[$stackPos-(3-1)], $self->semStack[$stackPos-(3-3)], $self->getAttributes($self->tokenStartStack[$stackPos-(3-1)], $self->tokenEndStack[$stackPos]));
            },
            643 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\Variable($self->semStack[$stackPos-(3-2)], $self->getAttributes($self->tokenStartStack[$stackPos-(3-1)], $self->tokenEndStack[$stackPos]));
            },
            644 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\Variable($self->semStack[$stackPos-(3-2)], $self->getAttributes($self->tokenStartStack[$stackPos-(3-1)], $self->tokenEndStack[$stackPos]));
            },
            645 => static function ($self, $stackPos) {
                 $self->semValue = new Expr\ArrayDimFetch($self->semStack[$stackPos-(6-2)], $self->semStack[$stackPos-(6-4)], $self->getAttributes($self->tokenStartStack[$stackPos-(6-1)], $self->tokenEndStack[$stackPos]));
            },
            646 => static function ($self, $stackPos) {
                 $self->semValue = $self->semStack[$stackPos-(3-2)];
            },
            647 => static function ($self, $stackPos) {
                 $self->semValue = new Scalar\String_($self->semStack[$stackPos-(1-1)], $self->getAttributes($self->tokenStartStack[$stackPos-(1-1)], $self->tokenEndStack[$stackPos]));
            },
            648 => static function ($self, $stackPos) {
                 $self->semValue = $self->parseNumString($self->semStack[$stackPos-(1-1)], $self->getAttributes($self->tokenStartStack[$stackPos-(1-1)], $self->tokenEndStack[$stackPos]));
            },
            649 => static function ($self, $stackPos) {
                 $self->semValue = $self->parseNumString('-' . $self->semStack[$stackPos-(2-2)], $self->getAttributes($self->tokenStartStack[$stackPos-(2-1)], $self->tokenEndStack[$stackPos]));
            },
            650 => null,
        ];
    }
}
}

namespace RunletVendor\PhpParser {

use RunletVendor\PhpParser\Parser\Php7;
use RunletVendor\PhpParser\Parser\Php8;

class ParserFactory {
    /**
     * Create a parser targeting the given version on a best-effort basis. The parser will generally
     * accept code for the newest supported version, but will try to accommodate code that becomes
     * invalid in newer versions or changes in interpretation.
     */
    public function createForVersion(PhpVersion $version): Parser {
        if ($version->isHostVersion()) {
            $lexer = new Lexer();
        } else {
            $lexer = new Lexer\Emulative($version);
        }
        if ($version->id >= 80000) {
            return new Php8($lexer, $version);
        }
        return new Php7($lexer, $version);
    }

    /**
     * Create a parser targeting the newest version supported by this library. Code for older
     * versions will be accepted if there have been no relevant backwards-compatibility breaks in
     * PHP.
     */
    public function createForNewestSupportedVersion(): Parser {
        return $this->createForVersion(PhpVersion::getNewestSupported());
    }

    /**
     * Create a parser targeting the host PHP version, that is the PHP version we're currently
     * running on. This parser will not use any token emulation.
     */
    public function createForHostVersion(): Parser {
        return $this->createForVersion(PhpVersion::getHostVersion());
    }
}
}

namespace RunletVendor\PhpParser {

/**
 * A PHP version, representing only the major and minor version components.
 */
class PhpVersion {
    /** @var int Version ID in PHP_VERSION_ID format */
    public int $id;

    /** @var int[] Minimum versions for builtin types */
    private const BUILTIN_TYPE_VERSIONS = [
        'array'    => 50100,
        'callable' => 50400,
        'bool'     => 70000,
        'int'      => 70000,
        'float'    => 70000,
        'string'   => 70000,
        'iterable' => 70100,
        'void'     => 70100,
        'object'   => 70200,
        'null'     => 80000,
        'false'    => 80000,
        'mixed'    => 80000,
        'never'    => 80100,
        'true'     => 80200,
    ];

    private function __construct(int $id) {
        $this->id = $id;
    }

    /**
     * Create a PhpVersion object from major and minor version components.
     */
    public static function fromComponents(int $major, int $minor): self {
        return new self($major * 10000 + $minor * 100);
    }

    /**
     * Get the newest PHP version supported by this library. Support for this version may be partial,
     * if it is still under development.
     */
    public static function getNewestSupported(): self {
        return self::fromComponents(8, 5);
    }

    /**
     * Get the host PHP version, that is the PHP version we're currently running on.
     */
    public static function getHostVersion(): self {
        return self::fromComponents(\PHP_MAJOR_VERSION, \PHP_MINOR_VERSION);
    }

    /**
     * Parse the version from a string like "8.1".
     */
    public static function fromString(string $version): self {
        if (!preg_match('/^(\d+)\.(\d+)/', $version, $matches)) {
            throw new \LogicException("Invalid PHP version \"$version\"");
        }
        return self::fromComponents((int) $matches[1], (int) $matches[2]);
    }

    /**
     * Check whether two versions are the same.
     */
    public function equals(PhpVersion $other): bool {
        return $this->id === $other->id;
    }

    /**
     * Check whether this version is greater than or equal to the argument.
     */
    public function newerOrEqual(PhpVersion $other): bool {
        return $this->id >= $other->id;
    }

    /**
     * Check whether this version is older than the argument.
     */
    public function older(PhpVersion $other): bool {
        return $this->id < $other->id;
    }

    /**
     * Check whether this is the host PHP version.
     */
    public function isHostVersion(): bool {
        return $this->equals(self::getHostVersion());
    }

    /**
     * Check whether this PHP version supports the given builtin type. Type name must be lowercase.
     */
    public function supportsBuiltinType(string $type): bool {
        $minVersion = self::BUILTIN_TYPE_VERSIONS[$type] ?? null;
        return $minVersion !== null && $this->id >= $minVersion;
    }

    /**
     * Whether this version supports [] array literals.
     */
    public function supportsShortArraySyntax(): bool {
        return $this->id >= 50400;
    }

    /**
     * Whether this version supports [] for destructuring.
     */
    public function supportsShortArrayDestructuring(): bool {
        return $this->id >= 70100;
    }

    /**
     * Whether this version supports flexible heredoc/nowdoc.
     */
    public function supportsFlexibleHeredoc(): bool {
        return $this->id >= 70300;
    }

    /**
     * Whether this version supports trailing commas in parameter lists.
     */
    public function supportsTrailingCommaInParamList(): bool {
        return $this->id >= 80000;
    }

    /**
     * Whether this version allows "$var =& new Obj".
     */
    public function allowsAssignNewByReference(): bool {
        return $this->id < 70000;
    }

    /**
     * Whether this version allows invalid octals like "08".
     */
    public function allowsInvalidOctals(): bool {
        return $this->id < 70000;
    }

    /**
     * Whether this version allows DEL (\x7f) to occur in identifiers.
     */
    public function allowsDelInIdentifiers(): bool {
        return $this->id < 70100;
    }

    /**
     * Whether this version supports yield in expression context without parentheses.
     */
    public function supportsYieldWithoutParentheses(): bool {
        return $this->id >= 70000;
    }

    /**
     * Whether this version supports unicode escape sequences in strings.
     */
    public function supportsUnicodeEscapes(): bool {
        return $this->id >= 70000;
    }

    /*
     * Whether this version supports attributes.
     */
    public function supportsAttributes(): bool {
        return $this->id >= 80000;
    }

    public function supportsNewDereferenceWithoutParentheses(): bool {
        return $this->id >= 80400;
    }
}
}

namespace RunletVendor\PhpParser {

/**
 * A PHP token. On PHP 8.0 this extends from PhpToken.
 */
class Token extends Internal\TokenPolyfill {
    /** Get (exclusive) zero-based end position of the token. */
    public function getEndPos(): int {
        return $this->pos + \strlen($this->text);
    }

    /** Get 1-based end line number of the token. */
    public function getEndLine(): int {
        return $this->line + \substr_count($this->text, "\n");
    }
}
}

/*
 * Runlet run inspector: the object drivers report queries, mail, log messages, HTML, and
 * their own sections to, plus the database hooks every driver inherits. Declared by the
 * runner before the driver API (Drivers.php). See docs/drivers.md, "Run inspector".
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace Runlet {

/**
 * The run inspector: what a run did besides its output. Runlet shows each section next to
 * the output: SQL queries, mail, log messages, HTML, and sections a driver defines itself
 * ("Cache", "HTTP calls", ...).
 *
 * Runlet creates one Inspector per snippet run and passes it to Driver::inspect() after
 * bootstrap() and before the snippet runs. Snippets reach it with Inspector::current().
 * No method throws, so all of them are safe inside event listeners. Recorded values are
 * bounded like other output, and recording stops at the run's limits (Runlet then reports
 * how many records it left out).
 *
 * notice(), warning(), and error() are output, not records: like \Runlet\notice() and
 * friends, they show a card in the output even when the inspector is off (#196).
 */
final class Inspector
{
    public const QUERIES = 'Queries';
    public const MAIL = 'Mail';
    public const LOG = 'Log';
    public const HTML = 'HTML';

    /** @var Inspector|null */
    private static $current;

    /** @var \Closure(string, array<string, mixed>): void */
    private $emit;
    /** @var \Closure(mixed): array<string, mixed> */
    private $normalize;
    /** @var bool */
    private $enabled;
    /** @var bool */
    private $interceptMail;
    /** @var array<string, int> */
    private $limits;
    /** @var string[] */
    private $sections = [];
    /** @var int */
    private $index = 0;
    /** @var int */
    private $queries = 0;
    /** @var int */
    private $records = 0;
    /** @var int */
    private $bytes = 0;
    /** @var array<string, array{omitted: int, reason: string}> */
    private $omitted = [];
    /** @var array<string, true> */
    private $once = [];
    /** @var callable[] */
    private $finishers = [];
    /** @var bool */
    private $interceptingMail = false;
    /** @var string|null */
    private $interceptMailReason;
    /** @var bool */
    private $finished = false;

    /**
     * @internal Runlet creates the inspector for each run.
     * @param array<string, mixed> $options `enabled`, `interceptMail`, and the record limits
     */
    public function __construct(array $options, \Closure $emit, \Closure $normalize)
    {
        $this->enabled = ($options['enabled'] ?? false) === true;
        $this->interceptMail = ($options['interceptMail'] ?? false) === true;
        $this->emit = $emit;
        $this->normalize = $normalize;
        $this->limits = [
            'maxQueries' => max(0, (int) ($options['maxQueries'] ?? 2000)),
            'maxRecords' => max(0, (int) ($options['maxRecords'] ?? 2000)),
            'maxRecordBytes' => max(0, (int) ($options['maxRecordBytes'] ?? 8388608)),
            'maxBodyBytes' => max(0, (int) ($options['maxBodyBytes'] ?? 2097152)),
        ];
    }

    /** The current run's inspector, or null outside a snippet run (for example while Runlet lists commands). */
    public static function current(): ?self
    {
        return self::$current;
    }

    /** @internal */
    public static function setCurrent(?self $inspector): void
    {
        self::$current = $inspector;
    }

    /** Whether this run records anything; the inspector can be turned off in Runlet's settings. */
    public function isEnabled(): bool
    {
        return $this->enabled;
    }

    /** Shows $section in Runlet for this run even when nothing is recorded in it ("0 queries"). */
    public function section(string $section): void
    {
        $section = self::sectionName($section);
        if ($this->enabled && !in_array($section, $this->sections, true)) {
            $this->sections[] = $section;
        }
    }

    /**
     * Records one SQL statement in the Queries section.
     *
     * @param array<int|string, mixed> $bindings positional values (a list) or named ones (name => value)
     * @param float|null $ms how long the statement took, in milliseconds
     * @param string|null $connection the connection's name, shown next to the statement
     * @param array<string, mixed> $details optional `driver` (mysql, pgsql, sqlite, ...), `rawSql` (the
     *        statement with its bindings substituted by the database layer), and `location`
     *        (from location(), when the statement is reported after it ran), and `databaseAPI`
     *        (eloquent, doctrine, wordpress, pdo) for Explain's connection template (#4)
     */
    public function query(string $sql, array $bindings = [], ?float $ms = null, ?string $connection = null, array $details = []): void
    {
        if (!$this->enabled) {
            return;
        }
        try {
            [$text, $omittedBytes] = self::clip($sql, 65536);
            $data = ['sql' => $text];
            if ($omittedBytes > 0) {
                $data['omittedBytes'] = $omittedBytes;
            }
            $list = [];
            $shown = 0;
            foreach ($bindings as $name => $value) {
                if ($shown >= 100) {
                    break;
                }
                $shown++;
                $list[] = self::binding($value, is_string($name) ? ltrim($name, ':') : null);
            }
            $data['bindings'] = $list;
            if ($shown < count($bindings)) {
                $data['omittedBindings'] = count($bindings) - $shown;
            }
            if ($ms !== null && is_finite($ms)) {
                $data['timeMs'] = round($ms, 3);
            }
            if ($connection !== null && $connection !== '') {
                $data['connection'] = self::clip($connection, 200)[0];
            }
            if (isset($details['driver']) && is_string($details['driver']) && $details['driver'] !== '') {
                $data['driver'] = self::clip($details['driver'], 50)[0];
            }
            if (isset($details['databaseAPI']) && is_string($details['databaseAPI'])) {
                $data['databaseAPI'] = self::clip($details['databaseAPI'], 50)[0];
            }
            if (isset($details['rawSql']) && is_string($details['rawSql']) && $details['rawSql'] !== $sql) {
                $data['rawSql'] = self::clip($details['rawSql'], 65536)[0];
            }
            $location = isset($details['location']) && is_array($details['location']) ? $details['location'] : $this->location();
            $this->emitRecord(self::QUERIES, 'query', null, $data, $location);
        } catch (\Throwable $error) {
            // Recording must never break the code that ran the query.
        }
    }

    /**
     * Records one mail message in the Mail section: a Symfony Mime Email, a SwiftMailer
     * message, or an array with `subject`, `from`, `to`, `cc`, `bcc`, `replyTo` (addresses as
     * strings, `address => name` arrays, or Address objects), `html`, `text`, `attachments`
     * (each with `filename`, `contentType`, `size`), `mailer`, `mailable`, and `caller` (who
     * sent it, when that isn't the snippet: a plugin, a class).
     *
     * @param object|array<string, mixed> $message
     * @param array<string, mixed> $details merged over the message: `intercepted` (true when the
     *        mail was not sent), `error` (why sending failed), `queued`, `queueConnection`,
     *        `mailer`, `mailable`, `caller`, and `location` (from location(), for a message
     *        reported after it was sent)
     */
    public function mail($message, array $details = []): void
    {
        if (!$this->enabled) {
            return;
        }
        try {
            $fields = is_object($message) ? self::mimeMessage($message) : (is_array($message) ? $message : []);
            $fields = $details + $fields;
            $data = [];
            foreach (['subject', 'mailer', 'mailable', 'caller', 'queueConnection', 'queue'] as $key) {
                if (isset($fields[$key]) && is_scalar($fields[$key]) && (string) $fields[$key] !== '') {
                    $data[$key] = self::clip($key === 'mailable' ? self::className((string) $fields[$key]) : (string) $fields[$key], 1000)[0];
                }
            }
            foreach (['from', 'to', 'cc', 'bcc', 'replyTo'] as $key) {
                $data[$key] = self::addresses($fields[$key] ?? []);
            }
            $budget = $this->limits['maxBodyBytes'];
            foreach (['html', 'text'] as $key) {
                if (isset($fields[$key]) && is_string($fields[$key])) {
                    [$body, $omitted] = self::clip($fields[$key], $budget);
                    $data[$key] = $body;
                    if ($omitted > 0) {
                        $data[$key . 'OmittedBytes'] = $omitted;
                    }
                }
            }
            $attachments = [];
            foreach (is_array($fields['attachments'] ?? null) ? $fields['attachments'] : [] as $attachment) {
                if (count($attachments) >= 50 || !is_array($attachment)) {
                    continue;
                }
                $entry = [];
                foreach (['filename', 'contentType'] as $key) {
                    if (isset($attachment[$key]) && is_scalar($attachment[$key])) {
                        $entry[$key] = self::clip((string) $attachment[$key], 300)[0];
                    }
                }
                if (isset($attachment['size']) && is_int($attachment['size'])) {
                    $entry['size'] = $attachment['size'];
                }
                if (($attachment['inline'] ?? false) === true) {
                    $entry['inline'] = true;
                }
                $attachments[] = $entry;
            }
            $data['attachments'] = $attachments;
            $data['intercepted'] = ($fields['intercepted'] ?? false) === true;
            if (($fields['queued'] ?? false) === true) {
                $data['queued'] = true;
            }
            if (isset($fields['error']) && is_scalar($fields['error']) && (string) $fields['error'] !== '') {
                $data['error'] = self::clip((string) $fields['error'], 4000)[0];
            }
            $location = isset($details['location']) && is_array($details['location']) ? $details['location'] : $this->location();
            $this->emitRecord(self::MAIL, 'mail', null, $data, $location);
        } catch (\Throwable $error) {
            // Never break the mailer.
        }
    }

    /** Records rendered HTML (a page, an email, a fragment), previewed in a locked-down web view. */
    public function html(string $title, string $html, string $section = self::HTML): void
    {
        if (!$this->enabled) {
            return;
        }
        try {
            [$body, $omitted] = self::clip($html, $this->limits['maxBodyBytes']);
            $data = ['html' => $body];
            if ($omitted > 0) {
                $data['omittedBytes'] = $omitted;
            }
            $this->emitRecord(self::sectionName($section), 'html', $title, $data, $this->location());
        } catch (\Throwable $error) {
            // Never break the caller.
        }
    }

    /**
     * Records a log message in the Log section.
     *
     * @param array<mixed> $context shown as an expandable value
     */
    public function log(string $level, string $message, array $context = [], ?string $channel = null): void
    {
        if (!$this->enabled) {
            return;
        }
        try {
            $data = ['level' => strtolower(self::clip($level, 30)[0]), 'message' => self::clip($message, 16384)[0]];
            if ($channel !== null && $channel !== '') {
                $data['channel'] = self::clip($channel, 200)[0];
            }
            if ($context !== []) {
                $data['context'] = ($this->normalize)($context);
            }
            $this->emitRecord(self::LOG, 'log', null, $data, $this->location());
        } catch (\Throwable $error) {
            // Never break the logger.
        }
    }

    /**
     * Records any value under $title in a section of your own, such as "Cache" or
     * "HTTP calls". The value is shown like a dump (bounded, without calling its methods).
     *
     * @param mixed $value
     */
    public function record(string $section, string $title, $value): void
    {
        if (!$this->enabled) {
            return;
        }
        try {
            $this->emitRecord(self::sectionName($section), 'value', $title, ['value' => ($this->normalize)($value)], $this->location());
        } catch (\Throwable $error) {
            // Never break the caller.
        }
    }

    /**
     * @internal Records a benchmark (Runlet\bench(), Laravel's Benchmark::dd()) or a Profile
     * Run's profile. Recorded even with the inspector turned off: the run asked for them.
     *
     * @param array<string, mixed> $data
     * @param array<string, mixed>|null $location defaults to location()
     */
    public function measurement(string $section, string $kind, string $title, array $data, ?array $location = null): void
    {
        try {
            $this->emitRecord(self::sectionName($section), $kind, $title, $data, $location ?? $this->location());
        } catch (\Throwable $error) {
            // Never break the caller.
        }
    }

    /**
     * Records the queries a PDO connection runs through prepare() and execute(), for code
     * that uses PDO directly (PDO cannot be hooked globally). It installs a statement class
     * on $pdo, so it is skipped for connections that already use their own (as database
     * layers often do) and for persistent connections. PDO::query() and PDO::exec() are not
     * seen. Returns whether the connection is watched.
     */
    public function watchPdo(\PDO $pdo, string $connection = 'pdo'): bool
    {
        if (!$this->enabled || !class_exists(InspectedPdoStatement::class, false)) {
            return false;
        }
        if (!$this->once('pdo:' . spl_object_id($pdo))) {
            return true;
        }
        try {
            $current = $pdo->getAttribute(\PDO::ATTR_STATEMENT_CLASS);
            if (is_array($current) && isset($current[0]) && is_string($current[0]) && strcasecmp($current[0], 'PDOStatement') !== 0) {
                $this->runletNotice('Runlet does not record queries on the "' . $connection . '" PDO connection: it already uses its own statement class (' . $current[0] . ').');

                return false;
            }
            $driver = (string) $pdo->getAttribute(\PDO::ATTR_DRIVER_NAME);
            $pdo->setAttribute(\PDO::ATTR_STATEMENT_CLASS, [InspectedPdoStatement::class, [$this, $connection, $driver]]);
            $this->section(self::QUERIES);

            return true;
        } catch (\Throwable $error) {
            $this->runletNotice('Runlet does not record queries on the "' . $connection . '" PDO connection: ' . $error->getMessage());

            return false;
        }
    }

    /** Whether this run asks drivers to intercept mail instead of sending it (Runlet's Intercept Mail setting). */
    public function shouldInterceptMail(): bool
    {
        return $this->enabled && $this->interceptMail;
    }

    /**
     * Tells Runlet that this run intercepts mail: messages are recorded but not sent. Call it
     * from inspect() when your driver honours shouldInterceptMail(); Runlet warns when
     * interception was asked for and no driver confirmed it.
     */
    public function interceptingMail(): void
    {
        $this->interceptingMail = true;
    }

    /**
     * Tells Runlet why this run can't intercept mail although it was asked to ("A plugin
     * (acme-smtp) replaces wp_mail(); Runlet can't stop its mail."). Runlet adds it to its
     * warning. A driver that also calls interceptingMail() makes this moot.
     */
    public function cannotInterceptMail(string $reason): void
    {
        $this->interceptMailReason = self::clip(trim($reason), 1000)[0];
    }

    /** True the first time $key is passed during this run; hooks use it to attach only once. */
    public function once(string $key): bool
    {
        if (isset($this->once[$key])) {
            return false;
        }
        $this->once[$key] = true;

        return true;
    }

    /** Calls $callback when the run finishes, before Runlet reports it (to flush a query log, for example). */
    public function atFinish(callable $callback): void
    {
        $this->finishers[] = $callback;
    }

    /**
     * Where the code running now comes from: the snippet line, else the first project file
     * outside vendor/. Pass it as `location` to query() when you report a query later.
     *
     * @return array{inSnippet?: bool, snippetLine?: int, file?: string, line?: int}
     */
    public function location(): array
    {
        return self::callerLocation();
    }

    /**
     * Shows a notice card in Runlet's output, with the line that called it: the same as
     * \Runlet\notice(). Shown whether or not the inspector is on; the run goes on.
     *
     * @param array<mixed> $context shown under the message as an expandable value
     */
    public function notice(string $message, array $context = []): void
    {
        \RunletRunner\SnippetMessages::emit('notice', $message, $context);
    }

    /**
     * Shows a warning card in Runlet's output, with the line that called it: the same as
     * \Runlet\warning(). Shown whether or not the inspector is on; the run goes on.
     *
     * @param array<mixed> $context shown under the message as an expandable value
     */
    public function warning(string $message, array $context = []): void
    {
        \RunletRunner\SnippetMessages::emit('warning', $message, $context);
    }

    /**
     * Shows an error card in Runlet's output, with the line that called it, without ending
     * the run or marking it failed: the same as \Runlet\error(). A Throwable shows its class,
     * message, and stack trace. Shown whether or not the inspector is on.
     *
     * @param string|\Throwable $message
     * @param array<mixed> $context shown under the message as an expandable value
     */
    public function error($message, array $context = []): void
    {
        \RunletRunner\SnippetMessages::emit('error', $message, $context);
    }

    /**
     * @internal location() without an inspector: \Runlet\notice() and friends use it too.
     *
     * @return array{inSnippet?: bool, snippetLine?: int, file?: string, line?: int}
     */
    public static function callerLocation(): array
    {
        $candidate = [];
        foreach (debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS) as $frame) {
            $file = $frame['file'] ?? null;
            if (!is_string($file)) {
                continue;
            }
            if (substr($file, -13) === "eval()'d code") {
                if (\RunletRunner\Runner::isSnippetFile($file)) {
                    return ['inSnippet' => true, 'snippetLine' => (int) ($frame['line'] ?? 0)];
                }
                continue;
            }
            if ($candidate === [] && strpos($file, 'Standard input code') !== 0 && $file !== '-' && strpos($file, '/vendor/') === false) {
                $candidate = ['inSnippet' => false, 'file' => $file, 'line' => (int) ($frame['line'] ?? 0)];
            }
        }

        return $candidate;
    }

    /** @internal Reports which sections this run shows and whether mail is intercepted. */
    public function ready(string $driverName): void
    {
        if (!$this->enabled) {
            return;
        }
        $payload = [
            'sections' => $this->sections,
            'interceptMail' => $this->interceptMail,
            'interceptingMail' => $this->interceptMail && $this->interceptingMail,
            'driverName' => $driverName,
        ];
        if ($this->interceptMail && !$this->interceptingMail && $this->interceptMailReason !== null && $this->interceptMailReason !== '') {
            $payload['interceptMailReason'] = $this->interceptMailReason;
        }
        ($this->emit)('inspector', $payload);
    }

    /** @internal Runs the finish callbacks and reports records left out by the limits. */
    public function finish(): void
    {
        if ($this->finished) {
            return;
        }
        foreach ($this->finishers as $callback) {
            try {
                $callback();
            } catch (\Throwable $error) {
                // A failing flush loses only its own records.
            }
        }
        $this->finished = true;
        foreach ($this->omitted as $section => $omitted) {
            ($this->emit)('recordLimit', ['section' => $section, 'omitted' => $omitted['omitted'], 'reason' => $omitted['reason']]);
        }
    }

    /**
     * @param array<string, mixed> $data
     * @param array<string, mixed> $location
     */
    private function emitRecord(string $section, string $kind, ?string $title, array $data, array $location): void
    {
        if ($this->finished) {
            return;
        }
        $this->section($section);
        $isQuery = $kind === 'query';
        if ($isQuery ? $this->queries >= $this->limits['maxQueries'] : $this->records >= $this->limits['maxRecords']) {
            $this->omit($section, 'count');

            return;
        }
        $size = strlen((string) json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR));
        if ($this->bytes + $size > $this->limits['maxRecordBytes']) {
            $this->omit($section, 'bytes');

            return;
        }
        $this->bytes += $size;
        if ($isQuery) {
            $this->queries++;
        } else {
            $this->records++;
        }
        $payload = ['index' => ++$this->index, 'section' => $section, 'kind' => $kind];
        if ($title !== null) {
            $payload['title'] = self::clip($title, 300)[0];
        }
        foreach (['inSnippet', 'snippetLine', 'file', 'line'] as $key) {
            if (isset($location[$key])) {
                $payload[$key] = $location[$key];
            }
        }
        $payload['data'] = $data;
        ($this->emit)('record', $payload);
    }

    private function omit(string $section, string $reason): void
    {
        if (!isset($this->omitted[$section])) {
            $this->omitted[$section] = ['omitted' => 0, 'reason' => $reason];
        }
        $this->omitted[$section]['omitted']++;
    }

    /** Runlet's own notice (no level, no location), unlike the public notice(). */
    private function runletNotice(string $message): void
    {
        ($this->emit)('notice', ['message' => $message]);
    }

    /**
     * A class name without the file and line PHP appends to anonymous classes
     * ("class@anonymous<NUL>/path:3$0").
     *
     * @internal
     */
    public static function className(string $class): string
    {
        $nul = strpos($class, "\0");

        return $nul === false ? $class : substr($class, 0, $nul);
    }

    private static function sectionName(string $section): string
    {
        $section = trim(self::clip(trim($section), 60)[0]);

        return $section === '' ? 'Custom' : $section;
    }

    /**
     * Valid UTF-8 cut to at most $limit bytes, and the number of bytes left out. Invalid
     * bytes become U+FFFD.
     *
     * @internal
     * @return array{0: string, 1: int}
     */
    public static function clip(string $text, int $limit): array
    {
        $omitted = 0;
        if (strlen($text) > $limit) {
            $omitted = strlen($text) - $limit;
            $text = substr($text, 0, $limit);
            for ($i = 0; $i < 4 && $text !== '' && preg_match('//u', $text) !== 1; $i++) {
                $text = substr($text, 0, -1);
                $omitted++;
            }
        }
        if (preg_match('//u', $text) !== 1) {
            $text = function_exists('mb_convert_encoding')
                ? (string) mb_convert_encoding($text, 'UTF-8', 'UTF-8')
                : (string) preg_replace('/[\x80-\xFF]/', "\u{FFFD}", $text);
        }

        return [$text, $omitted];
    }

    /**
     * @param mixed $value
     * @return array<string, mixed>
     */
    private static function binding($value, ?string $name): array
    {
        $entry = $name === null ? [] : ['name' => $name];
        if ($value === null) {
            return $entry + ['type' => 'null'];
        }
        if (is_bool($value)) {
            return $entry + ['type' => 'bool', 'value' => $value ? 'true' : 'false'];
        }
        if (is_int($value)) {
            return $entry + ['type' => 'int', 'value' => (string) $value];
        }
        if (is_float($value)) {
            return $entry + ['type' => 'float', 'value' => is_finite($value) ? var_export($value, true) : (string) $value];
        }
        if (is_string($value)) {
            if (preg_match('//u', $value) !== 1) {
                return $entry + ['type' => 'binary', 'size' => strlen($value)];
            }
            [$text, $omitted] = self::clip($value, 1024);
            $entry += ['type' => 'string', 'value' => $text];

            return $omitted > 0 ? $entry + ['omittedBytes' => $omitted] : $entry;
        }
        if ($value instanceof \DateTimeInterface) {
            return $entry + ['type' => 'datetime', 'value' => $value->format('Y-m-d H:i:s')];
        }
        if (function_exists('enum_exists') && $value instanceof \BackedEnum) {
            return self::binding($value->value, $name);
        }
        if (is_resource($value)) {
            return $entry + ['type' => 'resource', 'value' => get_resource_type($value)];
        }
        if (is_array($value)) {
            return $entry + ['type' => 'array', 'value' => 'array(' . count($value) . ')'];
        }

        return $entry + ['type' => 'object', 'value' => is_object($value) ? get_class($value) : gettype($value)];
    }

    /**
     * Addresses as [{address, name?}], from strings ("Ada <ada@example.com>"),
     * `address => name` arrays, `['address' => …, 'name' => …]` entries, or Address objects.
     *
     * @param mixed $value
     * @return array<int, array{address: string, name?: string}>
     */
    private static function addresses($value): array
    {
        if ($value === null || $value === '' || $value === []) {
            return [];
        }
        $result = [];
        foreach (is_array($value) ? $value : [$value] as $key => $item) {
            if (count($result) >= 50) {
                break;
            }
            $address = '';
            $name = '';
            if (is_object($item) && method_exists($item, 'getAddress')) {
                $address = (string) $item->getAddress();
                $name = method_exists($item, 'getName') ? (string) $item->getName() : '';
            } elseif (is_array($item)) {
                $address = (string) ($item['address'] ?? $item['email'] ?? '');
                $name = (string) ($item['name'] ?? '');
            } elseif (is_string($key) && strpos($key, '@') !== false) {
                $address = $key;
                $name = is_string($item) ? $item : '';
            } elseif (is_string($item)) {
                if (preg_match('/^\s*"?([^"<]*)"?\s*<([^>]+)>\s*$/', $item, $match)) {
                    $name = trim($match[1]);
                    $address = trim($match[2]);
                } else {
                    $address = trim($item);
                }
            }
            if ($address === '') {
                continue;
            }
            $entry = ['address' => self::clip($address, 320)[0]];
            if ($name !== '') {
                $entry['name'] = self::clip($name, 320)[0];
            }
            $result[] = $entry;
        }

        return $result;
    }

    /**
     * The fields of a Symfony Mime Email or SwiftMailer message. Inline images (`cid:`
     * references) become data: URLs, so previews show them without loading anything.
     *
     * @return array<string, mixed>
     */
    private static function mimeMessage(object $message): array
    {
        $fields = [];
        $inline = [];
        if (is_a($message, 'Symfony\Component\Mime\Email')) {
            $fields['subject'] = $message->getSubject();
            foreach (['from' => 'getFrom', 'to' => 'getTo', 'cc' => 'getCc', 'bcc' => 'getBcc', 'replyTo' => 'getReplyTo'] as $key => $method) {
                $fields[$key] = $message->$method();
            }
            $fields['html'] = self::bodyString($message->getHtmlBody());
            $fields['text'] = self::bodyString($message->getTextBody());
            $attachments = [];
            foreach ($message->getAttachments() as $part) {
                $body = method_exists($part, 'getBody') ? (string) $part->getBody() : '';
                $type = method_exists($part, 'getMediaType') ? $part->getMediaType() . '/' . $part->getMediaSubtype() : null;
                $isInline = method_exists($part, 'getDisposition') && $part->getDisposition() === 'inline';
                if (method_exists($part, 'getContentId')) {
                    $inline[(string) $part->getContentId()] = [$type ?? 'application/octet-stream', $body];
                }
                $attachments[] = array_filter([
                    'filename' => method_exists($part, 'getFilename') ? $part->getFilename() : null,
                    'contentType' => $type,
                    'size' => strlen($body),
                    'inline' => $isInline ? true : null,
                ], static function ($value): bool {
                    return $value !== null;
                });
            }
            $fields['attachments'] = $attachments;
        } elseif (is_a($message, 'Swift_Mime_SimpleMessage')) {
            $fields['subject'] = $message->getSubject();
            foreach (['from' => 'getFrom', 'to' => 'getTo', 'cc' => 'getCc', 'bcc' => 'getBcc', 'replyTo' => 'getReplyTo'] as $key => $method) {
                $fields[$key] = $message->$method();
            }
            $bodies = [[(string) $message->getContentType(), (string) $message->getBody()]];
            $attachments = [];
            foreach ($message->getChildren() as $child) {
                $type = (string) $child->getContentType();
                if (is_a($child, 'Swift_Mime_Attachment')) {
                    $body = (string) $child->getBody();
                    if (is_a($child, 'Swift_Mime_EmbeddedFile')) {
                        $inline[(string) $child->getId()] = [$type, $body];
                    }
                    $attachments[] = ['filename' => $child->getFilename(), 'contentType' => $type, 'size' => strlen($body), 'inline' => is_a($child, 'Swift_Mime_EmbeddedFile')];
                } else {
                    $bodies[] = [$type, (string) $child->getBody()];
                }
            }
            foreach ($bodies as [$type, $body]) {
                if (stripos($type, 'html') !== false && !isset($fields['html'])) {
                    $fields['html'] = $body;
                } elseif (stripos($type, 'text/plain') !== false && !isset($fields['text'])) {
                    $fields['text'] = $body;
                }
            }
            $fields['attachments'] = $attachments;
        }
        if (isset($fields['html']) && is_string($fields['html']) && $inline !== [] && strpos($fields['html'], 'cid:') !== false) {
            $budget = 4 * 1048576;
            foreach ($inline as $id => [$type, $body]) {
                if ($id === '' || strlen($body) > $budget || strpos($fields['html'], 'cid:' . $id) === false) {
                    continue;
                }
                $budget -= strlen($body);
                $fields['html'] = str_replace('cid:' . $id, 'data:' . $type . ';base64,' . base64_encode($body), $fields['html']);
            }
        }

        return $fields;
    }

    /** @param mixed $body */
    private static function bodyString($body): ?string
    {
        if (is_resource($body)) {
            @rewind($body);
            $contents = stream_get_contents($body);
            @rewind($body);

            return $contents === false ? null : $contents;
        }

        return is_string($body) ? $body : null;
    }
}

if (class_exists('PDOStatement', false)) {
    /**
     * @internal The statement class Inspector::watchPdo() installs: reports every execute()
     * with its bound values and timing.
     */
    class InspectedPdoStatement extends \PDOStatement
    {
        /** @var Inspector */
        private $inspector;
        /** @var string */
        private $connection;
        /** @var string */
        private $driver;
        /** @var array<int|string, mixed> */
        private $bound = [];

        protected function __construct(Inspector $inspector, string $connection, string $driver)
        {
            $this->inspector = $inspector;
            $this->connection = $connection;
            $this->driver = $driver;
        }

        #[\ReturnTypeWillChange]
        public function bindValue($param, $value, $type = \PDO::PARAM_STR)
        {
            $this->bound[$param] = $value;

            return parent::bindValue($param, $value, $type);
        }

        #[\ReturnTypeWillChange]
        public function bindParam($param, &$var, $type = \PDO::PARAM_STR, $maxLength = 0, $driverOptions = null)
        {
            $this->bound[$param] = &$var;
            if (func_num_args() >= 5) {
                return parent::bindParam($param, $var, $type, $maxLength, $driverOptions);
            }
            if (func_num_args() === 4) {
                return parent::bindParam($param, $var, $type, $maxLength);
            }

            return parent::bindParam($param, $var, $type);
        }

        #[\ReturnTypeWillChange]
        public function execute($params = null)
        {
            $started = microtime(true);
            try {
                return $params === null ? parent::execute() : parent::execute($params);
            } finally {
                $values = is_array($params) ? $params : $this->bound;
                if (!is_array($params)) {
                    ksort($values);
                }
                $this->inspector->query((string) $this->queryString, $values, (microtime(true) - $started) * 1000, $this->connection, ['driver' => $this->driver, 'databaseAPI' => 'pdo']);
            }
        }
    }
}

/**
 * Query recording for the database layers Runlet knows: illuminate/database (Eloquent, with
 * or without Laravel), Doctrine DBAL 2 to 4, and WordPress's $wpdb. Every driver has these
 * as protected methods; call them from inspect().
 */
trait InspectsDatabases
{
    /**
     * Records queries from illuminate/database (Eloquent and the query builder), with or
     * without Laravel. $database is a Capsule manager, a DatabaseManager, or a single
     * Connection; by default it is whatever Eloquent models use (or Capsule's global
     * instance). Returns whether any connection was found.
     *
     * Queries stream live, with the snippet line, through the connections' event
     * dispatcher. When they have none and illuminate/events is installed, Runlet gives them
     * one for this run. Without illuminate/events it falls back to each connection's query
     * log: queries then arrive as the next one starts and when the run finishes, and on
     * Laravel 7 and older without a snippet line.
     *
     * @param object|null $database
     */
    protected function inspectEloquent(Inspector $inspector, $database = null): bool
    {
        [$connections, $container, $manager] = self::eloquentConnections($database);
        if ($connections === [] && $manager === null) {
            return false;
        }
        $inspector->section(Inspector::QUERIES);
        $dispatcher = self::eloquentDispatcher($connections, $container);
        if ($dispatcher !== null) {
            foreach ($connections as $connection) {
                if (method_exists($connection, 'getEventDispatcher') && $connection->getEventDispatcher() === null) {
                    $connection->setEventDispatcher($dispatcher);
                }
            }
            if ($inspector->once('eloquent:' . spl_object_id($dispatcher))) {
                $dispatcher->listen('Illuminate\Database\Events\QueryExecuted', static function ($event) use ($inspector): void {
                    self::recordEloquentQuery($inspector, $event->sql ?? '', $event->bindings ?? [], $event->time ?? null, $event->connection ?? null, $event->connectionName ?? null, null);
                });
            }

            return true;
        }
        if ($manager !== null) {
            // Without events, only connections that exist now can keep a query log. Creating a
            // Connection object opens nothing (PDO connects on first use).
            foreach (self::configuredConnectionNames($container) as $name) {
                try {
                    $manager->connection($name);
                } catch (\Throwable $error) {
                    // A connection Runlet cannot create (unknown driver) is not used by the app either.
                }
            }
            $connections = array_values($manager->getConnections());
        }
        foreach ($connections as $connection) {
            self::eloquentQueryLog($inspector, $connection);
        }

        return $connections !== [];
    }

    /**
     * Records queries on a Doctrine DBAL connection (DBAL 2, 3, or 4), for Symfony or
     * standalone DBAL. $name labels the connection in Runlet. Returns whether it is hooked.
     *
     * @param object $connection a Doctrine\DBAL\Connection
     */
    protected function inspectDoctrine(Inspector $inspector, $connection, string $name = 'doctrine'): bool
    {
        if (!is_object($connection) || !is_a($connection, 'Doctrine\DBAL\Connection')) {
            return false;
        }
        $inspector->section(Inspector::QUERIES);
        if (!$inspector->once('doctrine:' . spl_object_id($connection))) {
            return true;
        }
        $params = method_exists($connection, 'getParams') ? $connection->getParams() : [];
        $driver = isset($params['driver']) && is_string($params['driver']) ? (string) preg_replace('/^pdo_/', '', $params['driver']) : null;
        if (interface_exists('Doctrine\DBAL\Logging\SQLLogger')) {
            // DBAL 2 and 3: an SQL logger, chained to the one the application set.
            $configuration = $connection->getConfiguration();
            $configuration->setSQLLogger(new class ($inspector, $name, $driver, $configuration->getSQLLogger()) implements \Doctrine\DBAL\Logging\SQLLogger {
                /** @var Inspector */
                private $inspector;
                /** @var string */
                private $name;
                /** @var string|null */
                private $driver;
                /** @var \Doctrine\DBAL\Logging\SQLLogger|null */
                private $previous;
                /** @var array{0: string, 1: array<int|string, mixed>, 2: float}|null */
                private $current;

                public function __construct(Inspector $inspector, string $name, ?string $driver, $previous)
                {
                    $this->inspector = $inspector;
                    $this->name = $name;
                    $this->driver = $driver;
                    $this->previous = $previous;
                }

                public function startQuery($sql, ?array $params = null, ?array $types = null)
                {
                    $this->current = [(string) $sql, $params ?? [], microtime(true)];
                    if ($this->previous !== null) {
                        $this->previous->startQuery($sql, $params, $types);
                    }
                }

                public function stopQuery()
                {
                    if ($this->previous !== null) {
                        $this->previous->stopQuery();
                    }
                    if ($this->current === null) {
                        return;
                    }
                    [$sql, $params, $started] = $this->current;
                    $this->current = null;
                    // DBAL logs transaction control as quoted pseudo statements ("COMMIT").
                    $sql = (string) preg_replace('/^"([A-Z ]+)"$/', '$1', $sql);
                    $this->inspector->query($sql, $params, (microtime(true) - $started) * 1000, $this->name, ['driver' => $this->driver, 'databaseAPI' => 'doctrine']);
                }
            });

            return true;
        }
        if (PHP_VERSION_ID >= 80100 && class_exists('Doctrine\DBAL\Driver\Middleware\AbstractConnectionMiddleware')) {
            // DBAL 4: wrap the driver (or the open driver connection) in a timing middleware.
            if (!class_exists('Runlet\Doctrine\InspectedConnection', false)) {
                eval(self::doctrineMiddleware());
            }
            $record = static function (string $sql, array $params, int $started) use ($inspector, $name, $driver): void {
                $inspector->query($sql, $params, (hrtime(true) - $started) / 1e6, $name, ['driver' => $driver, 'databaseAPI' => 'doctrine']);
            };
            if ($connection->isConnected()) {
                $inner = self::readProperty($connection, '_conn', 'Doctrine\DBAL\Connection');
                if (is_object($inner)) {
                    self::writeProperty($connection, '_conn', new \Runlet\Doctrine\InspectedConnection($inner, $record), 'Doctrine\DBAL\Connection');
                }
            } else {
                $inner = self::readProperty($connection, 'driver', 'Doctrine\DBAL\Connection');
                if (is_object($inner)) {
                    self::writeProperty($connection, 'driver', new \Runlet\Doctrine\InspectedDriver($inner, $record), 'Doctrine\DBAL\Connection');
                }
            }

            return true;
        }

        return false;
    }

    /**
     * Records WordPress's queries through $wpdb: live with timings when SAVEQUERIES is on
     * (Runlet's WordPress driver turns it on unless wp-config.php sets it), otherwise
     * through the `query` filter, without timings.
     */
    protected function inspectWordPress(Inspector $inspector): bool
    {
        $wpdb = $GLOBALS['wpdb'] ?? null;
        if (!is_object($wpdb) || !is_a($wpdb, 'wpdb') || !function_exists('add_filter')) {
            return false;
        }
        $inspector->section(Inspector::QUERIES);
        if (!$inspector->once('wordpress')) {
            return true;
        }
        $driver = is_a($wpdb, 'WP_SQLite_DB') ? 'sqlite' : 'mysql';
        if (defined('SAVEQUERIES') && SAVEQUERIES && isset($GLOBALS['wp_version']) && version_compare((string) $GLOBALS['wp_version'], '5.3', '>=')) {
            add_filter('log_query_custom_data', static function ($data, $query, $time) use ($inspector, $driver) {
                $inspector->query((string) $query, [], is_numeric($time) ? (float) $time * 1000 : null, 'wpdb', ['driver' => $driver, 'databaseAPI' => 'wordpress']);

                return $data;
            }, 10, 3);
        } else {
            add_filter('query', static function ($query) use ($inspector, $driver) {
                $inspector->query((string) $query, [], null, 'wpdb', ['driver' => $driver, 'databaseAPI' => 'wordpress']);

                return $query;
            }, PHP_INT_MAX, 1);
        }

        return true;
    }

    /** DBAL 4 middleware classes, evaluated only when DBAL 4 (PHP 8.1+) is in use. */
    private static function doctrineMiddleware(): string
    {
        return <<<'PHP'
namespace Runlet\Doctrine;

final class InspectedDriver extends \Doctrine\DBAL\Driver\Middleware\AbstractDriverMiddleware
{
    private \Closure $record;

    public function __construct(\Doctrine\DBAL\Driver $driver, \Closure $record)
    {
        parent::__construct($driver);
        $this->record = $record;
    }

    public function connect(#[\SensitiveParameter] array $params): \Doctrine\DBAL\Driver\Connection
    {
        return new InspectedConnection(parent::connect($params), $this->record);
    }
}

final class InspectedConnection extends \Doctrine\DBAL\Driver\Middleware\AbstractConnectionMiddleware
{
    private \Closure $record;

    public function __construct(\Doctrine\DBAL\Driver\Connection $connection, \Closure $record)
    {
        parent::__construct($connection);
        $this->record = $record;
    }

    public function prepare(string $sql): \Doctrine\DBAL\Driver\Statement
    {
        return new InspectedStatement(parent::prepare($sql), $sql, $this->record);
    }

    public function query(string $sql): \Doctrine\DBAL\Driver\Result
    {
        $started = hrtime(true);
        try {
            return parent::query($sql);
        } finally {
            ($this->record)($sql, [], $started);
        }
    }

    public function exec(string $sql): int|string
    {
        $started = hrtime(true);
        try {
            return parent::exec($sql);
        } finally {
            ($this->record)($sql, [], $started);
        }
    }
}

final class InspectedStatement extends \Doctrine\DBAL\Driver\Middleware\AbstractStatementMiddleware
{
    private array $params = [];
    private string $sql;
    private \Closure $record;

    public function __construct(\Doctrine\DBAL\Driver\Statement $statement, string $sql, \Closure $record)
    {
        parent::__construct($statement);
        $this->sql = $sql;
        $this->record = $record;
    }

    public function bindValue(int|string $param, mixed $value, \Doctrine\DBAL\ParameterType $type = \Doctrine\DBAL\ParameterType::STRING): void
    {
        $this->params[$param] = $value;
        parent::bindValue($param, $value, $type);
    }

    public function execute(): \Doctrine\DBAL\Driver\Result
    {
        $started = hrtime(true);
        try {
            return parent::execute();
        } finally {
            ($this->record)($this->sql, $this->params, $started);
        }
    }
}
PHP;
    }

    /**
     * The illuminate/database connections to watch, the container they were configured in,
     * and their DatabaseManager.
     *
     * @param object|null $database
     * @return array{0: array<int, object>, 1: object|null, 2: object|null}
     */
    private static function eloquentConnections($database): array
    {
        if ($database === null) {
            // Only classes the application already loaded: detection never autoloads.
            if (class_exists('Illuminate\Database\Eloquent\Model', false)) {
                $database = \Illuminate\Database\Eloquent\Model::getConnectionResolver();
            }
            if ($database === null && class_exists('Illuminate\Database\Capsule\Manager', false)) {
                $database = self::readStaticProperty('Illuminate\Database\Capsule\Manager', 'instance');
            }
        }
        if (!is_object($database)) {
            return [[], null, null];
        }
        $container = null;
        if (is_a($database, 'Illuminate\Database\Capsule\Manager')) {
            $container = $database->getContainer();
            $database = $database->getDatabaseManager();
        }
        if (is_a($database, 'Illuminate\Database\DatabaseManager')) {
            $container = $container ?? self::readProperty($database, 'app');

            return [array_values($database->getConnections()), is_object($container) ? $container : null, $database];
        }
        if (is_a($database, 'Illuminate\Database\Connection')) {
            return [[$database], null, null];
        }
        if (is_a($database, 'Illuminate\Database\ConnectionResolver')) {
            $connections = self::readProperty($database, 'connections');

            return [is_array($connections) ? array_values(array_filter($connections, 'is_object')) : [], null, null];
        }

        return [[], null, null];
    }

    /**
     * The dispatcher that QueryExecuted events go to: the connections' own, the container's
     * `events`, or (when illuminate/events is installed) a new one bound into the container,
     * so connections created later during the run get it too.
     *
     * @param array<int, object> $connections
     * @param object|null $container
     * @return object|null
     */
    private static function eloquentDispatcher(array $connections, $container)
    {
        foreach ($connections as $connection) {
            if (method_exists($connection, 'getEventDispatcher') && is_object($connection->getEventDispatcher())) {
                return $connection->getEventDispatcher();
            }
        }
        $isContainer = is_object($container) && is_a($container, 'Illuminate\Contracts\Container\Container');
        if ($isContainer && $container->bound('events')) {
            $events = $container->make('events');
            if (is_object($events) && method_exists($events, 'listen')) {
                return $events;
            }
        }
        if (!class_exists('Illuminate\Events\Dispatcher')) {
            return null;
        }
        $dispatcher = new \Illuminate\Events\Dispatcher($isContainer ? $container : null);
        if ($isContainer) {
            $container->instance('events', $dispatcher);
        }

        return $dispatcher;
    }

    /**
     * Names in the container's `database.connections` configuration.
     *
     * @param object|null $container
     * @return string[]
     */
    private static function configuredConnectionNames($container): array
    {
        try {
            $connections = is_object($container) && $container instanceof \ArrayAccess ? $container['config']['database.connections'] : null;
        } catch (\Throwable $error) {
            return [];
        }

        return is_array($connections) ? array_map('strval', array_keys($connections)) : [];
    }

    /**
     * Fallback without an event dispatcher: turns on the connection's query log and reports
     * each logged query when the next one starts (beforeExecuting(), Laravel 8+) and at the
     * end of the run.
     *
     * @param object $connection
     */
    private static function eloquentQueryLog(Inspector $inspector, $connection): void
    {
        if (!is_a($connection, 'Illuminate\Database\Connection') || !$inspector->once('eloquent-log:' . spl_object_id($connection))) {
            return;
        }
        $connection->enableQueryLog();
        $reported = count($connection->getQueryLog());
        $pending = null;
        $flush = static function () use ($inspector, $connection, &$reported, &$pending): void {
            $log = $connection->getQueryLog();
            $count = count($log);
            for ($index = $reported; $index < $count; $index++) {
                $entry = is_array($log[$index]) ? $log[$index] : [];
                self::recordEloquentQuery($inspector, $entry['query'] ?? '', $entry['bindings'] ?? [], $entry['time'] ?? null, $connection, null, $pending ?? []);
                $pending = null;
            }
            $reported = $count;
        };
        if (method_exists($connection, 'beforeExecuting')) {
            $connection->beforeExecuting(static function () use ($inspector, $flush, &$pending): void {
                $flush();
                // A query that failed was never logged; its location is dropped here.
                $pending = $inspector->location();
            });
        }
        $inspector->atFinish($flush);
    }

    /**
     * @param mixed $sql
     * @param mixed $bindings
     * @param mixed $time
     * @param object|null $connection
     * @param array<string, mixed>|null $location
     */
    private static function recordEloquentQuery(Inspector $inspector, $sql, $bindings, $time, $connection, $name, ?array $location): void
    {
        $sql = is_string($sql) ? $sql : '';
        $bindings = is_array($bindings) ? $bindings : [];
        $details = $location === null ? [] : ['location' => $location];
        $details['databaseAPI'] = 'eloquent';
        if (is_object($connection)) {
            try {
                $name = $name ?? $connection->getName();
                $details['driver'] = $connection->getDriverName();
                $bindings = $connection->prepareBindings($bindings);
                $grammar = $connection->getQueryGrammar();
                if (is_object($grammar) && method_exists($grammar, 'substituteBindingsIntoRawSql')) {
                    $details['rawSql'] = $grammar->substituteBindingsIntoRawSql($sql, $bindings);
                }
            } catch (\Throwable $error) {
                // Keep what is known; the query itself is still recorded.
            }
        }
        $inspector->query($sql, $bindings, is_numeric($time) ? (float) $time : null, is_scalar($name) ? (string) $name : null, $details);
    }

    /**
     * @param object $object
     * @return mixed
     */
    protected static function readProperty($object, string $property, ?string $class = null)
    {
        try {
            $reflection = new \ReflectionProperty($class ?? get_class($object), $property);
            if (PHP_VERSION_ID < 80100) {
                $reflection->setAccessible(true);
            }

            return $reflection->getValue($object);
        } catch (\Throwable $error) {
            return null;
        }
    }

    /**
     * @param object $object
     * @param mixed $value
     */
    protected static function writeProperty($object, string $property, $value, ?string $class = null): void
    {
        $reflection = new \ReflectionProperty($class ?? get_class($object), $property);
        if (PHP_VERSION_ID < 80100) {
            $reflection->setAccessible(true);
        }
        $reflection->setValue($object, $value);
    }

    /** @return mixed */
    private static function readStaticProperty(string $class, string $property)
    {
        try {
            $reflection = new \ReflectionProperty($class, $property);
            if (PHP_VERSION_ID < 80100) {
                $reflection->setAccessible(true);
            }

            return $reflection->getValue();
        } catch (\Throwable $error) {
            return null;
        }
    }
}
}

/*
 * Runlet driver API, declared by the runner before anything from the project loads.
 *
 * A driver boots one kind of application for a run and hands variables to the snippet.
 * Runlet ships the built-in drivers below; a project adds its own in
 * `<project>/.runlet/*Driver.php` by extending Runlet\Driver or a built-in driver.
 * See docs/drivers.md.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace Runlet {

/**
 * Base class for every Runlet driver.
 *
 * Runlet calls, in order: canBootstrap(), bootstrap(), variables(), version(), name(),
 * environment(), and then inspect() before a snippet runs, commands() when it lists the
 * project's commands instead, or panels() for App Info. Each run is a fresh PHP process, so a
 * driver boots exactly once per run.
 */
abstract class Driver
{
    use InspectsDatabases;

    /** Name shown in Runlet's status bar. Defaults to the short class name. */
    public function name(): string
    {
        $class = get_class($this);
        $separator = strrpos($class, '\\');

        return $separator === false ? $class : substr($class, $separator + 1);
    }

    /**
     * Whether this driver can boot the project at $projectPath (the run's working
     * directory). Project drivers default to true.
     */
    public function canBootstrap(string $projectPath): bool
    {
        return true;
    }

    /** Boots the application. Throw to report a bootstrap error. */
    abstract public function bootstrap(string $projectPath): void;

    /**
     * Variables available in every snippet, as name => value. Called after bootstrap().
     *
     * @return array<string, mixed>
     */
    public function variables(): array
    {
        return [];
    }

    /** Application or framework version shown next to the driver name, if any. */
    public function version(): ?string
    {
        return null;
    }

    /**
     * The application's environment name ("local", "staging", "production", …), if it has
     * one. Called after bootstrap(). Runlet compares it with how the target is marked: when
     * the application says production and the target isn't marked production, the tab offers
     * to mark it. Return the name only, never other configuration. Throwing is noted in the
     * Run Log; the run continues without an environment.
     *
     * No native return type, so project drivers written before this hook (with their own
     * environment() method) keep loading; overrides may declare `: ?string`.
     *
     * @return string|null
     */
    public function environment()
    {
        return null;
    }

    /**
     * Commands listed in Runlet's Commands panel, keyed by name. Called after bootstrap(),
     * only when the panel loads commands, never during a snippet run. Each entry is
     *
     *     'name' => ['command' => 'php artisan name', 'description' => '…', 'group' => 'ns']
     *
     * where `command` is a shell command line run in the project directory (inside the
     * container for Docker targets), and `description` and `group` are optional. A string
     * value is shorthand for `['command' => …]`. Extend a built-in driver's list with
     * `parent::commands() + [...]` or array_merge(). Composer scripts are added by Runlet.
     *
     * @return array<string, array{command: string, description?: string|null, group?: string|null}|string>
     */
    public function commands(): array
    {
        return [];
    }

    /**
     * Commands that run on the Mac, in the project's folder there (for Docker targets, the
     * profile's local source folder), instead of inside the target: tools installed on the
     * host such as `docker compose` or your own CLIs. Same entries as commands(), plus
     * command sources, tools Runlet asks for their commands each time the list loads:
     *
     *     'up'    => ['command' => 'docker compose up -d', 'description' => 'Start the stack'],
     *     // Prints {"commands": [{"name", "command", "description"?, "group"?, "needsInput"?}]}
     *     'tools' => ['list' => 'mytool runlet:commands'],
     *     // A Symfony Console app (Laravel Zero, Artisan-style): reads `mytool list --format=json`
     *     'mytool' => ['console' => 'mytool'],
     *
     * Command lines run in your login shell's environment (PATH included). Called before
     * bootstrap(), so these commands are listed even when the application cannot boot:
     * return declarations only, without running anything.
     *
     * @return array<string, array{command?: string, list?: string, console?: string, description?: string|null, group?: string|null}|string>
     */
    public function hostCommands(): array
    {
        return [];
    }

    /**
     * Where this application writes its logs (#20), for Runlet's log viewer (View > Logs):
     * paths relative to the project, or absolute as the application sees them (inside its
     * container or on its server). Each is a file, a folder (its `*.log` files are listed), or
     * a pattern with `*` in its last part:
     *
     *     return ['storage/logs/worker.log', 'var/log', 'logs/app-*.log'];
     *
     * Runlet lists these before the files it finds by itself (Laravel's storage/logs, Symfony's
     * var/log, WordPress's wp-content/debug.log). Called before bootstrap(), when Runlet lists
     * the project's commands: return declarations only, without running anything. The log
     * viewer reads the files themselves and never calls this method.
     *
     * @return array<int, string>
     */
    public function logPaths(): array
    {
        return [];
    }

    /**
     * SQL tabs (#35): how a statement from an SQL tab reaches this application's database.
     * `$connection` is the name chosen in the tab, or null for the default connection.
     * Return one of:
     *
     *  - a \PDO: Runlet prepares and runs the statement on it;
     *  - a callable `function (string $sql)` that runs the statement and returns its rows (an
     *    iterable of associative arrays or objects) or, for a statement without a result
     *    set, the number of affected rows (an int);
     *  - null when this driver has no connection for SQL tabs. Runlet then uses an Eloquent
     *    connection or WordPress's $wpdb if the application set one up, and otherwise says
     *    that the project has no SQL connection. The application's own connections need no
     *    credentials from Runlet; a user can also save a connection for the target (#138),
     *    which runs without booting the project and never calls this method.
     *
     * Throw to report a problem, such as an unknown connection name: the tab shows the
     * message. Called after bootstrap(), only when an SQL tab runs. The built-in drivers
     * return the application's own connection (Laravel's DB::connection(), Symfony's
     * Doctrine registry, WordPress's PDO from wp-config.php or else $wpdb, #208);
     * SqlConnections has helpers for your own.
     *
     * @return \PDO|callable|null
     */
    public function sqlConnection(?string $connection)
    {
        return null;
    }

    /**
     * SQL tabs (#35): the names of the application's database connections, the default
     * first, for the tab's connection picker. Called when an SQL tab runs; return [] to list
     * none (the tab can still name a connection).
     *
     * @return string[]
     */
    public function sqlConnections(): array
    {
        return [];
    }

    /**
     * Redis tabs (#190): how a command from a Redis tab reaches this application's Redis.
     * `$connection` is the name chosen in the tab, or null for the default connection. Return
     * a phpredis \Redis, a Predis client, a Laravel Redis connection, a callable
     * `function (array $argv)` that sends the command and returns its reply, or null when this
     * driver has no Redis connection. Called after bootstrap(), only when a Redis tab runs. The
     * built-in Laravel driver returns Redis::connection($connection). A saved Redis connection
     * never calls it.
     *
     * @return mixed
     */
    public function redisConnection(?string $connection)
    {
        return null;
    }

    /**
     * Redis tabs (#190): the names of the application's Redis connections, the default first,
     * for the tab's connection picker.
     *
     * @return string[]
     */
    public function redisConnections(): array
    {
        return [];
    }

    /**
     * SQL tabs (#128): the tables and columns of a connection, for completion. Return null
     * (the default) and Runlet reads them through sqlConnection(): information_schema on
     * MySQL, MariaDB, PostgreSQL, and SQL Server, sqlite_master on SQLite. Return them
     * yourself when your connection is a callable Runlet can't query that way:
     *
     *     return ['users' => ['id' => 'integer', 'email' => 'varchar'], 'orders' => ['id', 'total']];
     *
     * (column => type, or a list of column names). Called only when the user loads the
     * schema in an SQL tab, or after a statement ran there.
     *
     * @return array<string, array<int|string, string>>|null
     */
    public function sqlSchema(?string $connection): ?array
    {
        return null;
    }

    /**
     * Extra sections for Runlet's App Info popover (#19), shown after its own (the framework's
     * details and PHP). Called after bootstrap(), only when the user opens App Info, never
     * during a snippet run. Keyed by section title, each holding `label => value` rows; a value
     * is a string, number, bool, null, or a list of strings:
     *
     *     'Tenant' => ['Name' => 'acme', 'Workers' => 3, 'Features' => ['beta', 'new-ui']],
     *
     * Runlet bounds the sections and hides secret-looking values (see docs/drivers.md).
     * Extend a built-in driver's with `parent::panels() + [...]`.
     *
     * @return array<string, array<string, mixed>>
     */
    public function panels(): array
    {
        return [];
    }

    /**
     * Run inspector hook: called after bootstrap() and before the snippet runs (never when
     * Runlet lists commands). Report what the run does through $inspector: SQL queries,
     * mail, log messages, HTML, or sections of your own. Runlet turns anything this method
     * throws into a notice; the run continues.
     *
     * The default finds Eloquent connections (Laravel, or illuminate/database through
     * Capsule) and WordPress's $wpdb. Call parent::inspect() to keep that when you add your
     * own hooks, or override it with an empty method to record nothing.
     */
    public function inspect(Inspector $inspector): void
    {
        $this->inspectAutomatically($inspector);
    }

    /** What inspect() detects by default: Eloquent and WordPress. */
    protected function inspectAutomatically(Inspector $inspector): void
    {
        $this->inspectEloquent($inspector);
        $this->inspectWordPress($inspector);
    }

    /**
     * Rendered HTML for a value the snippet returned or dumped, shown as a preview next to
     * its value tree. Called only for objects, and only while Settings ▸ Output renders
     * previews. Return null for values without a preview. The default renders Laravel
     * mailables, mail notifications (MailMessage, or a Notification's toMail()), views,
     * Htmlable and Renderable objects, and HTML Symfony responses. Rendering runs the
     * application's view code; Runlet reports anything it throws on the preview.
     *
     * @param mixed $value
     * @return array{html: string, title?: string, subject?: string, text?: string, kind?: string}|null
     */
    public function preview($value): ?array
    {
        if (!is_object($value)) {
            return null;
        }
        $class = get_class($value);
        if ($value instanceof \Illuminate\Notifications\Notification && method_exists($value, 'toMail')
            && class_exists('Illuminate\Notifications\AnonymousNotifiable')) {
            try {
                $mail = $value->toMail(new \Illuminate\Notifications\AnonymousNotifiable());
            } catch (\Throwable $error) {
                throw new \RuntimeException($class . '::toMail() needs a notifiable for the preview (' . $error->getMessage() . '). Return $notification->toMail($user) instead.', 0, $error);
            }
            $preview = is_object($mail) ? $this->preview($mail) : null;

            return $preview === null ? null : ['title' => $class] + $preview;
        }
        if ($value instanceof \Illuminate\Mail\Mailable) {
            $text = null;
            if (method_exists($value, 'renderForAssertions')) {
                // Laravel 10+: the HTML and plain-text bodies, as the mail would carry them.
                $method = new \ReflectionMethod($value, 'renderForAssertions');
                if (PHP_VERSION_ID < 80100) {
                    $method->setAccessible(true);
                }
                [$html, $text] = $method->invoke($value);
            } else {
                $html = $value->render();
            }
            $subject = isset($value->subject) && is_scalar($value->subject) ? (string) $value->subject : null;

            return array_filter(['kind' => 'mail', 'title' => $class, 'subject' => $subject, 'html' => (string) $html, 'text' => $text === null || $text === '' ? null : (string) $text], 'is_string');
        }
        if ($value instanceof \Illuminate\Notifications\Messages\MailMessage) {
            $text = null;
            if (isset($value->markdown) && is_string($value->markdown) && class_exists('Illuminate\Mail\Markdown') && class_exists('Illuminate\Container\Container')) {
                try {
                    $text = (string) \Illuminate\Container\Container::getInstance()->make('Illuminate\Mail\Markdown')->renderText($value->markdown, $value->data());
                } catch (\Throwable $error) {
                    $text = null;
                }
            }
            $subject = isset($value->subject) && is_scalar($value->subject) ? (string) $value->subject : null;

            return array_filter(['kind' => 'mail', 'title' => $class, 'subject' => $subject, 'html' => (string) $value->render(), 'text' => $text], 'is_string');
        }
        if ($value instanceof \Illuminate\Contracts\View\View) {
            $name = method_exists($value, 'name') ? (string) $value->name() : $class;

            return ['kind' => 'view', 'title' => $name, 'html' => (string) $value->render()];
        }
        if ($value instanceof \Symfony\Component\HttpFoundation\Response) {
            $type = (string) $value->headers->get('Content-Type', '');
            $content = $value->getContent();
            if (!is_string($content) || ($type !== '' ? stripos($type, 'html') === false : !preg_match('/^\s*</', $content))) {
                return null;
            }

            return ['kind' => 'response', 'title' => $class . ' ' . $value->getStatusCode(), 'html' => $content];
        }
        if ($value instanceof \Illuminate\Contracts\Support\Htmlable) {
            return ['kind' => 'html', 'title' => $class, 'html' => (string) $value->toHtml()];
        }
        if ($value instanceof \Illuminate\Contracts\Support\Renderable) {
            return ['kind' => 'html', 'title' => $class, 'html' => (string) $value->render()];
        }

        return null;
    }


    /**
     * Describes Symfony Console commands (Artisan, bin/console, ...) for commands():
     * aliases and hidden commands are skipped, and each command is grouped by its
     * namespace (`make:model` in "make"; `migrate` joins "migrate" when `migrate:*` exists).
     *
     * @param iterable<mixed> $commands name => Symfony\Component\Console\Command\Command, as from Application::all()
     * @param string $commandPrefix the console invocation, e.g. "php artisan"
     * @return array<string, array{command: string, description: string|null, group: string|null, needsInput?: bool}>
     */
    protected function consoleCommands(iterable $commands, string $commandPrefix): array
    {
        $descriptions = [];
        $needsInput = [];
        foreach ($commands as $key => $command) {
            if (!is_object($command) || !method_exists($command, 'getName')) {
                continue;
            }
            $name = (string) $command->getName();
            // Application::all() lists every alias as its own key.
            if ($name === '' || (is_string($key) && $key !== $name) || isset($descriptions[$name])) {
                continue;
            }
            if (method_exists($command, 'isHidden') && $command->isHidden()) {
                continue;
            }
            $description = method_exists($command, 'getDescription') ? trim((string) $command->getDescription()) : '';
            $descriptions[$name] = $description === '' ? null : $description;
            if (method_exists($command, 'getDefinition')) {
                foreach ($command->getDefinition()->getArguments() as $argument) {
                    if ($argument->isRequired()) {
                        $needsInput[$name] = true;
                        break;
                    }
                }
            }
        }
        ksort($descriptions, SORT_STRING);

        $namespaces = [];
        foreach (array_keys($descriptions) as $name) {
            $colon = strpos((string) $name, ':');
            if ($colon !== false && $colon > 0) {
                $namespaces[substr((string) $name, 0, $colon)] = true;
            }
        }

        $result = [];
        foreach ($descriptions as $name => $description) {
            $name = (string) $name;
            $colon = strpos($name, ':');
            if ($colon !== false && $colon > 0) {
                $group = substr($name, 0, $colon);
            } else {
                $group = isset($namespaces[$name]) ? $name : null;
            }
            $argument = preg_match('/^[A-Za-z0-9:._-]+$/', $name) ? $name : escapeshellarg($name);
            $result[$name] = ['command' => $commandPrefix . ' ' . $argument, 'description' => $description, 'group' => $group];
            if (isset($needsInput[$name])) {
                // Required arguments: Runlet types the command without running it.
                $result[$name]['needsInput'] = true;
            }
        }

        return $result;
    }

    /**
     * Explains an exit() during bootstrap, e.g. a redirect the application tried to send.
     * Appended to Runlet's "called exit() while bootstrapping" error; null when unknown.
     */
    public function bootstrapExitHint(): ?string
    {
        return null;
    }

    /** Adds a line to the app's Run Log (Run ▸ Show Run Log), e.g. a boot step or a timing. */
    protected function log(string $message, ?string $detail = null): void
    {
        \RunletRunner\Runner::log('driver', $message, $detail);
    }

    /**
     * "main @ 3f2a1c9" for the git checkout at $projectPath, read from the `.git` files
     * (HEAD, loose refs, packed-refs; linked worktrees too) without running git. A detached
     * HEAD gives just the short commit. Null when there is no readable checkout, e.g. a
     * container image without the `.git` directory. Useful in version():
     *
     *     public function version(): ?string { return $this->gitRevision(dirname(__DIR__)); }
     */
    protected function gitRevision(string $projectPath): ?string
    {
        $gitDir = rtrim($projectPath, '/') . '/.git';
        if (is_file($gitDir)) {
            // A linked worktree: ".git" is a file with "gitdir: <path>".
            $pointer = @file_get_contents($gitDir);
            if ($pointer === false || !preg_match('/^gitdir:\s*(.+)$/m', $pointer, $match)) {
                return null;
            }
            $gitDir = trim($match[1]);
            if ($gitDir !== '' && $gitDir[0] !== '/') {
                $gitDir = rtrim($projectPath, '/') . '/' . $gitDir;
            }
        }
        $head = @file_get_contents($gitDir . '/HEAD');
        if ($head === false) {
            return null;
        }
        $head = trim($head);
        if (preg_match('/^[0-9a-f]{40,64}$/', $head)) {
            return substr($head, 0, 7);
        }
        if (!preg_match('#^ref:\s*(refs/\S+)$#', $head, $match)) {
            return null;
        }
        $ref = $match[1];
        $branch = preg_replace('#^refs/heads/#', '', $ref);
        // Shared refs live in the common directory of a linked worktree.
        $commonDir = $gitDir;
        $common = @file_get_contents($gitDir . '/commondir');
        if ($common !== false && trim($common) !== '') {
            $common = trim($common);
            $commonDir = $common[0] === '/' ? $common : $gitDir . '/' . $common;
        }
        $commit = null;
        foreach ([$gitDir, $commonDir] as $dir) {
            $loose = @file_get_contents($dir . '/' . $ref);
            if ($loose !== false && preg_match('/^[0-9a-f]{40,64}/', trim($loose), $sha)) {
                $commit = $sha[0];
                break;
            }
        }
        if ($commit === null) {
            $packed = @file_get_contents($commonDir . '/packed-refs');
            if ($packed !== false && preg_match('/^([0-9a-f]{40,64}) ' . preg_quote($ref, '/') . '$/m', $packed, $sha)) {
                $commit = $sha[1];
            }
        }

        return $commit === null ? $branch : $branch . ' @ ' . substr($commit, 0, 7);
    }
}

/**
 * SQL tabs (#35): ready-made sqlConnection() results for common database layers. The
 * built-in drivers use them, and a project driver can too:
 *
 *     public function sqlConnection(?string $connection)
 *     {
 *         return SqlConnections::doctrine($this->container->get('reports'));
 *     }
 */
final class SqlConnections
{
    /**
     * An Eloquent connection's PDO: `$database` is a DatabaseManager, a Capsule manager, a
     * connection resolver, or one Connection; `$connection` names one (null: the default).
     *
     * @param object $database
     */
    public static function eloquent($database, ?string $connection = null): \PDO
    {
        $resolved = $database;
        if (is_object($resolved) && !method_exists($resolved, 'getPdo') && method_exists($resolved, 'connection')) {
            $resolved = $resolved->connection($connection);
        }
        if (!is_object($resolved) || !method_exists($resolved, 'getPdo')) {
            throw new \InvalidArgumentException('SqlConnections::eloquent() needs a database manager, a connection resolver, or a Connection.');
        }
        $pdo = $resolved->getPdo();
        if (!$pdo instanceof \PDO) {
            $name = method_exists($resolved, 'getName') ? (string) $resolved->getName() : ($connection ?? 'default');
            throw new \RuntimeException('The ' . $name . ' connection has no PDO, so SQL tabs can\'t run statements on it.');
        }

        return $pdo;
    }

    /**
     * A Doctrine DBAL connection (DBAL 2, 3, or 4): its PDO when it has one, otherwise a
     * callable that runs the statement through DBAL.
     *
     * @param object $connection
     * @return \PDO|callable
     */
    public static function doctrine($connection)
    {
        $native = null;
        try {
            if (method_exists($connection, 'getNativeConnection')) {
                $native = $connection->getNativeConnection(); // DBAL 3.3+
            } elseif (method_exists($connection, 'getWrappedConnection')) {
                $native = $connection->getWrappedConnection(); // DBAL 2: a PDO for pdo_* drivers
            }
        } catch (\LogicException $error) {
            $native = null; // A driver whose native connection DBAL doesn't expose.
        }
        if ($native instanceof \PDO) {
            return $native;
        }

        return static function (string $sql) use ($connection) {
            $result = $connection->executeQuery($sql);
            if ($result->columnCount() === 0) {
                return $result->rowCount();
            }

            return (static function () use ($result) {
                if (method_exists($result, 'fetchAssociative')) {
                    while (($row = $result->fetchAssociative()) !== false) {
                        yield $row;
                    }
                } else {
                    while (($row = $result->fetch(\PDO::FETCH_ASSOC)) !== false) {
                        yield $row;
                    }
                }
            })();
        };
    }

    /**
     * WordPress's $wpdb: a callable that runs the statement with $wpdb->query(). WordPress
     * reports affected rows for INSERT, UPDATE, DELETE, and REPLACE, nothing for DDL, and
     * rows for everything else.
     *
     * @param object $wpdb
     */
    public static function wpdb($wpdb): callable
    {
        return static function (string $sql) use ($wpdb) {
            // wpdb::query() classifies a statement by its first word, so leading comments go.
            $sql = (string) preg_replace('~^(\s*(--[^\n]*(\n|$)|#[^\n]*(\n|$)|/\*.*?\*/))+~s', '', $sql);
            $suppressed = method_exists($wpdb, 'suppress_errors') ? $wpdb->suppress_errors(true) : null;
            try {
                $returned = $wpdb->query($sql);
            } finally {
                if ($suppressed !== null) {
                    $wpdb->suppress_errors($suppressed);
                }
            }
            if ($returned === false) {
                $error = isset($wpdb->last_error) && is_string($wpdb->last_error) ? $wpdb->last_error : '';
                throw new \RuntimeException($error !== '' ? $error : 'WordPress could not run the statement.');
            }
            if (preg_match('/^\s*(create|alter|truncate|drop|insert|delete|update|replace)\s/i', $sql)) {
                return is_int($returned) ? $returned : 0;
            }

            return isset($wpdb->last_result) && is_array($wpdb->last_result) ? $wpdb->last_result : [];
        };
    }
}
}

namespace Runlet\Drivers {

use Runlet\Driver;
use Runlet\Inspector;
use Runlet\SqlConnections;

/** A directory without Composer or framework markers: nothing is loaded. */
class PlainDriver extends Driver
{
    public function name(): string
    {
        return 'PHP';
    }

    public function bootstrap(string $projectPath): void
    {
    }
}

/** Any Composer project: loads vendor/autoload.php. */
class ComposerDriver extends Driver
{
    public function name(): string
    {
        return 'Composer';
    }

    public function canBootstrap(string $projectPath): bool
    {
        return is_file($projectPath . '/composer.json') || is_file($projectPath . '/vendor/autoload.php');
    }

    public function bootstrap(string $projectPath): void
    {
        $this->requireAutoloader($projectPath);
    }

    /** Loads the project's Composer autoloader, or explains how to install it. */
    protected function requireAutoloader(string $projectPath): void
    {
        $autoload = $projectPath . '/vendor/autoload.php';
        if (!is_file($autoload)) {
            throw new \RuntimeException('Composer dependencies are not installed: ' . $autoload . ' is missing. Run `composer install` in the project.');
        }
        require_once $autoload;
    }
}

/**
 * Laravel, Lumen, and Laravel Zero: loads bootstrap/app.php and bootstraps it like an
 * Artisan command does, so providers, config, facades, and helpers are ready.
 */
class LaravelDriver extends ComposerDriver
{
    /** @var object|null The application returned by bootstrap/app.php. */
    protected $app;
    /** @var string|null */
    private $projectPath;

    public function name(): string
    {
        switch ($this->flavor($this->projectPath ?? '.')) {
            case 'lumen':
                return 'Lumen';
            case 'laravel-zero':
                return 'Laravel Zero';
            default:
                return 'Laravel';
        }
    }

    public function canBootstrap(string $projectPath): bool
    {
        if (!is_file($projectPath . '/bootstrap/app.php')) {
            return false;
        }

        // Laravel and Lumen ship `artisan`; Laravel Zero apps name their entry script themselves.
        return is_file($projectPath . '/artisan') || self::hasPackage($projectPath, 'laravel-zero/framework');
    }

    /**
     * Which Laravel-family framework the project uses: "laravel", "lumen", or "laravel-zero".
     * After bootstrap() this comes from the application class, before it from installed packages.
     */
    public function flavor(string $projectPath): string
    {
        if (is_object($this->app)) {
            if (is_a($this->app, 'Laravel\Lumen\Application')) {
                return 'lumen';
            }
            if (is_a($this->app, 'LaravelZero\Framework\Application')) {
                return 'laravel-zero';
            }

            return 'laravel';
        }
        if (self::hasPackage($projectPath, 'laravel/lumen-framework')) {
            return 'lumen';
        }
        if (self::hasPackage($projectPath, 'laravel-zero/framework')) {
            return 'laravel-zero';
        }

        return 'laravel';
    }

    public function bootstrap(string $projectPath): void
    {
        $this->projectPath = $projectPath;
        $this->requireAutoloader($projectPath);

        $app = require $projectPath . '/bootstrap/app.php';
        if (!is_object($app) || !method_exists($app, 'make')) {
            throw new \RuntimeException('bootstrap/app.php did not return a Laravel application.');
        }
        $this->app = $app;

        if ($this->flavor($projectPath) === 'lumen') {
            // Lumen's console kernel has an empty bootstrap(): constructing it prepares the
            // console environment (facades, URL generation), and boot() boots the providers.
            if (method_exists($app, 'bound') && $app->bound('Illuminate\Contracts\Console\Kernel')) {
                $app->make('Illuminate\Contracts\Console\Kernel');
            }
            if (method_exists($app, 'boot')) {
                $app->boot();
            }

            return;
        }

        // Laravel and Laravel Zero; the kernel skips bootstrappers that already ran.
        $app->make('Illuminate\Contracts\Console\Kernel')->bootstrap();
    }

    /** @return array<string, mixed> */
    public function variables(): array
    {
        return $this->app === null ? [] : ['app' => $this->app];
    }

    /** SQL tabs (#35): the PDO of DB::connection($connection), the application's own. */
    public function sqlConnection(?string $connection)
    {
        $database = $this->resolveService('db');

        return $database === null ? null : SqlConnections::eloquent($database, $connection);
    }

    /** SQL tabs (#35): the keys of config('database.connections'), database.default first. */
    public function sqlConnections(): array
    {
        $config = $this->resolveService('config');
        if ($config === null || !method_exists($config, 'get')) {
            return [];
        }
        $names = array_map('strval', array_keys((array) $config->get('database.connections', [])));
        $default = $config->get('database.default');
        if (is_string($default) && $default !== '') {
            $names = array_merge([$default], array_values(array_diff($names, [$default])));
        }

        return $names;
    }

    /** Redis tabs (#190): Redis::connection($connection), the application's own (phpredis or Predis). */
    public function redisConnection(?string $connection)
    {
        $redis = $this->resolveService('redis');
        if ($redis === null || !method_exists($redis, 'connection')) {
            return null;
        }

        return $redis->connection($connection);
    }

    /** Redis tabs (#190): the connections of config('database.redis'), "default" first. */
    public function redisConnections(): array
    {
        $config = $this->resolveService('config');
        if ($config === null || !method_exists($config, 'get')) {
            return [];
        }
        $names = [];
        foreach (array_keys((array) $config->get('database.redis', [])) as $name) {
            if (!in_array($name, ['client', 'options', 'clusters'], true) && is_array($config->get('database.redis.' . $name))) {
                $names[] = (string) $name;
            }
        }
        if (in_array('default', $names, true)) {
            $names = array_merge(['default'], array_values(array_diff($names, ['default'])));
        }

        return $names;
    }

    /** A service of the booted application, or null when it has none (a Lumen app without the database, …). */
    private function resolveService(string $id)
    {
        if (!is_object($this->app) || !method_exists($this->app, 'make')) {
            return null;
        }
        // Lumen binds core services lazily: bound() is false until first use, make() works.
        $isLumen = is_a($this->app, 'Laravel\Lumen\Application');
        if (!$isLumen && method_exists($this->app, 'bound') && !$this->app->bound($id)) {
            return null;
        }
        try {
            return $this->app->make($id);
        } catch (\Throwable $error) {
            if ($isLumen) {
                return null;
            }
            throw $error;
        }
    }

    /**
     * Queries (the application's database manager), mail, and log messages, through the
     * application's event dispatcher. With mail interception on, MessageSending listeners
     * return false, so Laravel builds each message but sends nothing.
     */
    public function inspect(Inspector $inspector): void
    {
        // Only services the application already resolved: inspecting never boots more of it.
        $resolved = function (string $id): bool {
            return is_object($this->app) && method_exists($this->app, 'resolved') && $this->app->resolved($id);
        };
        if ($resolved('db')) {
            $this->inspectEloquent($inspector, $this->app->make('db'));
        }
        parent::inspect($inspector);
        if (!$resolved('events')) {
            return;
        }
        $events = $this->app->make('events');
        if (is_object($events) && method_exists($events, 'listen')) {
            $this->inspectLaravelMail($inspector, $events);
            $this->inspectLaravelLog($inspector, $events);
        }
    }

    /**
     * Mail sent during the run (MessageSending), intercepted when the run asks for it, and
     * mail pushed to an asynchronous queue, which a worker sends later and Runlet cannot stop.
     *
     * @param object $events the application's event dispatcher
     */
    protected function inspectLaravelMail(Inspector $inspector, $events): void
    {
        if (!$inspector->once('laravel-mail:' . spl_object_id($events))) {
            return;
        }
        $inspector->section(Inspector::MAIL);
        $intercept = $inspector->shouldInterceptMail();
        $events->listen('Illuminate\Mail\Events\MessageSending', static function ($event) use ($inspector, $intercept) {
            $data = isset($event->data) && is_array($event->data) ? $event->data : [];
            $details = ['intercepted' => $intercept];
            foreach (['__laravel_mailable', '__laravel_notification'] as $key) {
                if (isset($data[$key]) && is_string($data[$key])) {
                    $details['mailable'] = $data[$key];
                }
            }
            if (isset($data['mailer']) && is_string($data['mailer'])) {
                $details['mailer'] = $data['mailer'];
            }
            if (isset($event->message) && is_object($event->message)) {
                $inspector->mail($event->message, $details);
            }

            // false stops Laravel from sending; null lets the next listener decide.
            return $intercept ? false : null;
        });
        if ($intercept) {
            $inspector->interceptingMail();
        }
        $events->listen('Illuminate\Queue\Events\JobQueued', static function ($event) use ($inspector): void {
            $job = $event->job ?? null;
            $connection = isset($event->connectionName) && is_string($event->connectionName) ? $event->connectionName : null;
            if (!is_object($job) || $connection === 'sync') {
                return;
            }
            $mailable = null;
            if (is_a($job, 'Illuminate\Mail\SendQueuedMailable') && isset($job->mailable) && is_object($job->mailable)) {
                $mailable = get_class($job->mailable);
            } elseif (is_a($job, 'Illuminate\Notifications\SendQueuedNotifications') && isset($job->notification) && is_object($job->notification)) {
                if (is_array($job->channels ?? null) && !in_array('mail', $job->channels, true)) {
                    return;
                }
                $mailable = get_class($job->notification);
            }
            if ($mailable === null) {
                return;
            }
            $subject = isset($job->mailable->subject) && is_scalar($job->mailable->subject) ? (string) $job->mailable->subject : null;
            $inspector->mail(array_filter([
                'subject' => $subject,
                'mailable' => $mailable,
                'queued' => true,
                'queueConnection' => $connection,
                'queue' => isset($event->queue) && is_string($event->queue) ? $event->queue : null,
                'to' => isset($job->mailable->to) && is_array($job->mailable->to) ? $job->mailable->to : null,
            ], static function ($value): bool {
                return $value !== null;
            }));
        });
    }

    /** @param object $events the application's event dispatcher */
    protected function inspectLaravelLog(Inspector $inspector, $events): void
    {
        if (!$inspector->once('laravel-log:' . spl_object_id($events))) {
            return;
        }
        $inspector->section(Inspector::LOG);
        $events->listen('Illuminate\Log\Events\MessageLogged', static function ($event) use ($inspector): void {
            $message = $event->message ?? '';
            $inspector->log(
                is_scalar($event->level ?? null) ? (string) $event->level : 'log',
                is_scalar($message) ? (string) $message : (is_object($message) ? get_class($message) : gettype($message)),
                isset($event->context) && is_array($event->context) ? $event->context : []
            );
        });
    }

    public function version(): ?string
    {
        if (!is_object($this->app) || !method_exists($this->app, 'version')) {
            return null;
        }
        $version = (string) $this->app->version();
        // Lumen reports "Lumen (10.0.4) (Laravel Components ^10.0)".
        if (preg_match('/^Lumen \(([^)]+)\)/', $version, $match)) {
            return $match[1];
        }

        return $version;
    }

    /**
     * `app()->environment()`: APP_ENV, or `app.env` (Laravel, Lumen, and Laravel Zero).
     *
     * @return string|null
     */
    public function environment()
    {
        if (!is_object($this->app) || !method_exists($this->app, 'environment')) {
            return null;
        }
        $environment = $this->app->environment();

        return is_string($environment) ? $environment : null;
    }

    /** Every visible Artisan command (or the Laravel Zero app's commands), as `php <script> <name>`. */
    public function commands(): array
    {
        if (!is_object($this->app) || !method_exists($this->app, 'make')) {
            return [];
        }
        $kernel = $this->app->make('Illuminate\Contracts\Console\Kernel');
        if (!is_object($kernel) || !method_exists($kernel, 'all')) {
            return [];
        }

        return $this->consoleCommands($kernel->all(), 'php ' . $this->consoleScript($this->projectPath ?? '.'));
    }

    /**
     * The console entry script, relative to the project: `artisan` for Laravel and Lumen; for
     * Laravel Zero, the binary named in composer.json "bin", or the PHP script in the project
     * root that loads bootstrap/app.php.
     */
    protected function consoleScript(string $projectPath): string
    {
        if ($this->flavor($projectPath) !== 'laravel-zero') {
            return 'artisan';
        }
        $manifest = @file_get_contents($projectPath . '/composer.json');
        $composer = is_string($manifest) ? json_decode($manifest, true) : null;
        foreach ((array) ($composer['bin'] ?? []) as $binary) {
            if (is_string($binary) && $binary !== '' && is_file($projectPath . '/' . $binary)) {
                return preg_match('/^[A-Za-z0-9\/._-]+$/', $binary) ? $binary : escapeshellarg($binary);
            }
        }
        foreach ((array) @scandir($projectPath) as $entry) {
            $path = $projectPath . '/' . $entry;
            if (!is_string($entry) || $entry === '' || $entry[0] === '.' || strpos($entry, '.') !== false || !is_file($path)) {
                continue;
            }
            $head = (string) @file_get_contents($path, false, null, 0, 2048);
            if (strpos($head, '#!') === 0 && strpos($head, 'php') !== false && strpos($head, 'bootstrap/app.php') !== false) {
                return preg_match('/^[A-Za-z0-9._-]+$/', $entry) ? $entry : escapeshellarg($entry);
            }
        }

        return is_file($projectPath . '/artisan') ? 'artisan' : 'application';
    }

    private static function hasPackage(string $projectPath, string $package): bool
    {
        if (is_dir($projectPath . '/vendor/' . $package)) {
            return true;
        }
        $manifest = @file_get_contents($projectPath . '/composer.json');
        $composer = is_string($manifest) ? json_decode($manifest, true) : null;
        if (!is_array($composer)) {
            return false;
        }
        foreach (['require', 'require-dev'] as $section) {
            if (isset($composer[$section][$package])) {
                return true;
            }
        }

        return false;
    }
}

/**
 * WordPress: a standard install, Bedrock (web/wp), public/wp, wordpress/, or wp/.
 *
 * WordPress is written for the global scope. Like WP-CLI, Runlet loads it from a function
 * whose WordPress globals are declared `global`, then promotes any other variable the
 * load defined. Snippets run in their own scope: use `global $post;` (or $GLOBALS) for
 * globals other than the injected $wpdb.
 */
class WordPressDriver extends Driver
{
    /** @var array{location: string, status: int, caller: string}|null The last redirect WordPress tried while booting. */
    private static $bootRedirect;
    /** @var bool The request uses the localhost default: take the host from the `home` option once the database is up. */
    private static $hostFromDatabase = false;
    /** @var array<string, float> Boot milestones (microtime) for the Run Log's timing breakdown. */
    private static $bootMarks = [];
    /** @var array<string, float> Seconds spent loading each plugin (by folder or file name). */
    private static $pluginTimes = [];
    /** @var float When the previous plugin finished loading. */
    private static $lastPluginMark = 0.0;
    /** @var WordPressMail|null wp_mail() recording and interception for this run (#192). */
    private $mail;
    /** Globals WordPress core and common setups assign at file scope while loading. */
    private const WORDPRESS_GLOBALS = [
        'wpdb', 'table_prefix', 'wp_version', 'wp_db_version', 'tinymce_version', 'required_php_version',
        'required_php_extensions', 'required_mysql_version', 'wp_local_package', 'blog_id', 'site_id', 'public',
        'current_site', 'current_blog', 'path', 'domain', 'shortcode_tags', 'wp_filter', 'wp_actions', 'wp_filters',
        'wp_current_filter', 'wp_object_cache', 'wp_embed', 'wp_textdomain_registry', 'wp_plugin_paths',
        'wp_the_query', 'wp_query', 'wp_rewrite', 'wp', 'wp_widget_factory', 'wp_roles', 'locale', 'locale_file',
        'wp_locale', 'wp_locale_switcher', 'wp_theme', 'wp_theme_directories', 'pagenow', 'is_lynx', 'is_gecko',
        'is_winIE', 'is_macIE', 'is_opera', 'is_NS4', 'is_safari', 'is_chrome', 'is_iphone', 'is_IE', 'is_edge',
        'is_apache', 'is_nginx', 'is_caddy', 'is_IIS', 'is_iis7', '_wp_switched_stack', 'switched', 'current_user',
        'post', 'posts', 'wp_post_types', 'wp_taxonomies', 'wp_post_statuses', 'wp_scripts', 'wp_styles', 'l10n',
        'allowedposttags', 'allowedtags', 'allowedentitynames', 'allowedxmlentitynames', 'wp_registered_sidebars',
        'wp_registered_widgets', 'wp_meta_boxes', 'wp_settings_errors', 'wp_rest_server', 'wp_sitemaps',
        'mu_plugin', 'network_plugin', 'plugin', '_wp_plugin_file',
    ];

    /** @var array<int, string> */
    private const LOADERS = ['wp-load.php', 'web/wp/wp-load.php', 'public/wp/wp-load.php', 'wordpress/wp-load.php', 'wp/wp-load.php'];

    public function name(): string
    {
        return 'WordPress';
    }

    public function canBootstrap(string $projectPath): bool
    {
        return $this->locateLoader($projectPath) !== null;
    }

    public function bootstrap(string $projectPath): void
    {
        $loader = $this->locateLoader($projectPath);
        if ($loader === null) {
            throw new \RuntimeException('WordPress was not found: there is no wp-load.php in ' . $projectPath . ' (also looked in ' . implode(', ', array_map('dirname', array_slice(self::LOADERS, 1))) . ').');
        }
        $config = self::configFile(dirname($loader));
        if ($config === null) {
            throw new \RuntimeException('WordPress is not configured: wp-config.php was not found next to ' . $loader . ' or one directory above it.');
        }
        if (is_file($projectPath . '/vendor/autoload.php')) {
            require_once $projectPath . '/vendor/autoload.php';
        }

        $this->prepareRequest($config);
        if (!defined('WP_USE_THEMES')) {
            define('WP_USE_THEMES', false);
        }
        $inspector = Inspector::current();
        if ($inspector !== null && $inspector->isEnabled() && !defined('SAVEQUERIES') && strpos((string) @file_get_contents($config), 'SAVEQUERIES') === false) {
            // Query timings for Runlet's inspector come from WordPress's own query log. Left
            // alone when wp-config.php sets SAVEQUERIES itself.
            define('SAVEQUERIES', true);
        }
        if ($inspector !== null && $inspector->isEnabled() && $this->mail === null) {
            // Before WordPress loads, so mail a plugin sends while WordPress boots (on init,
            // say) is recorded, and intercepted when the run asks for it.
            $this->mail = new WordPressMail($inspector);
            $this->mail->install();
        }
        $guard = $this->installBootstrapHooks();
        self::installTimingHooks();

        self::load($loader);

        if (function_exists('remove_filter')) {
            remove_filter('nocache_headers', $guard, 10);
        }
        self::$bootMarks['loaded'] = microtime(true);
        // The admin APIs (get_plugins(), wp_delete_post() helpers, ...), as WP-CLI loads them.
        if (defined('ABSPATH') && is_file(ABSPATH . 'wp-admin/includes/admin.php')) {
            require_once ABSPATH . 'wp-admin/includes/admin.php';
        }
        self::$bootMarks['admin'] = microtime(true);
        self::logBootTimings();
    }

    /**
     * Records WordPress's load milestones (the earliest callback on each) and the time each
     * plugin file took, for the Run Log. Hooks that never fire leave gaps the summary skips.
     */
    private static function installTimingHooks(): void
    {
        self::$bootMarks = ['start' => microtime(true)];
        self::$pluginTimes = [];
        foreach (['muplugins_loaded', 'plugins_loaded', 'setup_theme', 'after_setup_theme', 'init', 'wp_loaded'] as $hook) {
            self::addFilter($hook, static function ($value = null) use ($hook) {
                if (!isset(self::$bootMarks[$hook])) {
                    self::$bootMarks[$hook] = microtime(true);
                }
                if ($hook === 'muplugins_loaded') {
                    self::$lastPluginMark = self::$bootMarks[$hook];
                }

                return $value;
            }, -1000000);
        }
        self::addFilter('plugin_loaded', static function ($plugin = null) {
            $now = microtime(true);
            $since = self::$lastPluginMark > 0 ? self::$lastPluginMark : $now;
            $name = is_string($plugin) ? self::pluginName($plugin) : '?';
            self::$pluginTimes[$name] = (self::$pluginTimes[$name] ?? 0) + ($now - $since);
            self::$lastPluginMark = $now;

            return $plugin;
        });
    }

    /** "sitepress-multilingual-cms" for wp-content/plugins/sitepress-multilingual-cms/sitepress.php. */
    private static function pluginName(string $file): string
    {
        $root = defined('WP_PLUGIN_DIR') ? rtrim((string) WP_PLUGIN_DIR, '/') . '/' : '';
        $relative = $root !== '' && strpos($file, $root) === 0 ? substr($file, strlen($root)) : basename($file);
        $slash = strpos($relative, '/');

        return $slash === false ? basename($relative, '.php') : substr($relative, 0, $slash);
    }

    /** One Run Log line: where WordPress's boot time went, the slowest plugins, and the opcode cache. */
    private static function logBootTimings(): void
    {
        $marks = self::$bootMarks;
        $phases = [
            'core & must-use plugins' => ['start', 'muplugins_loaded'],
            'plugins' => ['muplugins_loaded', 'plugins_loaded'],
            'plugins_loaded hooks' => ['plugins_loaded', 'setup_theme'],
            'theme' => ['setup_theme', 'after_setup_theme'],
            'user & init setup' => ['after_setup_theme', 'init'],
            'init hooks' => ['init', 'wp_loaded'],
            'wp_loaded hooks' => ['wp_loaded', 'loaded'],
            'admin APIs' => ['loaded', 'admin'],
        ];
        $parts = [];
        foreach ($phases as $label => [$from, $to]) {
            if (isset($marks[$from], $marks[$to])) {
                $parts[] = $label . ' ' . (int) round(($marks[$to] - $marks[$from]) * 1000) . ' ms';
            }
        }
        $total = isset($marks['start'], $marks['admin']) ? (int) round(($marks['admin'] - $marks['start']) * 1000) : null;
        $details = [];
        if (self::$pluginTimes !== []) {
            arsort(self::$pluginTimes);
            $slowest = [];
            foreach (array_slice(self::$pluginTimes, 0, 8, true) as $name => $seconds) {
                $slowest[] = $name . ' ' . (int) round($seconds * 1000) . ' ms';
            }
            $details[] = count(self::$pluginTimes) . ' plugins; slowest to load: ' . implode(' · ', $slowest);
        }
        $files = count(get_included_files());
        $cacheOn = function_exists('opcache_get_status') && (bool) ini_get('opcache.enable') && (bool) ini_get('opcache.enable_cli');
        $fileCache = (string) ini_get('opcache.file_cache');
        $details[] = $cacheOn
            ? 'opcode cache: on for the command line' . ($fileCache !== '' ? ', file cache in ' . $fileCache : '') . ' (' . $files . ' files loaded)'
            : 'opcode cache: off for the command line (opcache.enable_cli), so every run compiles all ' . $files . ' files; web requests keep them compiled';
        \RunletRunner\Runner::log('driver', 'WordPress boot' . ($total !== null ? ' ' . $total . ' ms' : '') . ': ' . implode(' · ', $parts), implode("\n", $details));
    }

    /** @return array<string, mixed> */
    public function variables(): array
    {
        return isset($GLOBALS['wpdb']) ? ['wpdb' => $GLOBALS['wpdb']] : [];
    }

    /** Queries ($wpdb) and mail sent with wp_mail(), intercepted when the run asks for it. */
    public function inspect(Inspector $inspector): void
    {
        parent::inspect($inspector);
        $this->inspectWordPressMail($inspector);
    }

    /**
     * Mail sent with wp_mail() (#192): each message in the Mail section, with its recipients,
     * bodies, attachments, and the plugin or theme that sent it. With Intercept Mail on,
     * `pre_wp_mail` stops each message before PHPMailer sees it (WordPress 5.7+), and
     * wp_mail() reports success to its caller. The hooks go in before WordPress loads, so
     * no file is added to the project. Runlet confirms interception only when it is
     * guaranteed; otherwise it says why (an older WordPress, a plugin that replaces wp_mail()
     * or takes over pre_wp_mail).
     */
    protected function inspectWordPressMail(Inspector $inspector): void
    {
        if (!function_exists('add_filter') || !function_exists('wp_mail')) {
            return;
        }
        if ($this->mail === null) {
            // A project driver that loaded WordPress without parent::bootstrap().
            $this->mail = new WordPressMail($inspector);
            $this->mail->install();
        }
        $inspector->section(Inspector::MAIL);
        if (!$inspector->shouldInterceptMail()) {
            return;
        }
        $reason = $this->mail->interceptionBlocker();
        if ($reason === null) {
            $inspector->interceptingMail();
        } else {
            $inspector->cannotInterceptMail($reason);
        }
    }

    /**
     * SQL tabs (#35, #208): WordPress's database, through a PDO connection opened from
     * wp-config.php's own settings when an SQL feature first needs it (MySQL and MariaDB with
     * DB_HOST, DB_NAME, DB_USER, DB_PASSWORD, and TLS; the SQLite Database Integration
     * drop-in's file), else through $wpdb, with the reason in the origin
     * (\RunletRunner\WordPressDatabase). The `wpdb` connection always runs through $wpdb.
     */
    public function sqlConnection(?string $connection)
    {
        $wpdb = $GLOBALS['wpdb'] ?? null;
        if (!is_object($wpdb) || !method_exists($wpdb, 'query')) {
            return null;
        }
        if ($connection !== null && $connection !== 'wpdb') {
            throw new \InvalidArgumentException('WordPress has one database connection, not "' . $connection . '". Choose the default connection, or "wpdb" to run statements through $wpdb.');
        }

        return \RunletRunner\WordPressDatabase::connection($wpdb, $connection === 'wpdb');
    }

    public function bootstrapExitHint(): ?string
    {
        $redirect = self::$bootRedirect;
        if ($redirect === null) {
            return null;
        }
        $text = 'WordPress redirected to ' . $redirect['location'] . ' (' . $redirect['status'] . ')'
            . ($redirect['caller'] !== '' ? ', sent from ' . $redirect['caller'] : '') . ', then exited.';
        if (strpos($redirect['location'], 'wp-admin/install.php') !== false) {
            $text .= ' WordPress found no installation in the database wp-config.php points to: check DB_NAME, DB_HOST, and $table_prefix as PHP on the command line sees them (environment variables, a different DB_HOST than the web server).';
        } elseif (strpos($redirect['location'], 'https://') === 0) {
            $text .= ' Runlet presents the site\'s host and scheme from WP_HOME / WP_SITEURL, or from the home option once the database is up; code that redirects earlier than that (a drop-in, a must-use plugin) still sees http://localhost. Define WP_HOME (https://your-host) in wp-config.php, or let the redirect skip the CLI (php_sapi_name() === \'cli\').';
        }

        return $text;
    }

    public function version(): ?string
    {
        return isset($GLOBALS['wp_version']) ? (string) $GLOBALS['wp_version'] : null;
    }

    /**
     * wp_get_environment_type() (WordPress 5.5+): WP_ENVIRONMENT_TYPE from the environment
     * or wp-config.php, and "production" when neither sets it.
     *
     * @return string|null
     */
    public function environment()
    {
        return function_exists('wp_get_environment_type') ? (string) \wp_get_environment_type() : null;
    }

    /** The wp-load.php to use, or null when the project is not WordPress. */
    protected function locateLoader(string $projectPath): ?string
    {
        foreach (self::LOADERS as $candidate) {
            if (is_file($projectPath . '/' . $candidate)) {
                return $projectPath . '/' . $candidate;
            }
        }

        return null;
    }

    /**
     * Request defaults for a CLI process, so WordPress and plugins find the usual
     * $_SERVER keys. A multisite's main site is taken from DOMAIN_CURRENT_SITE when
     * wp-config.php defines it literally; otherwise set $_SERVER['HTTP_HOST'] in a project
     * driver before calling parent::bootstrap().
     */
    protected function prepareRequest(string $configFile): void
    {
        $url = null;
        $source = null;
        if (!isset($_SERVER['HTTP_HOST'])) {
            // The site's real URL, so canonical-host and force-HTTPS code (page caches such as
            // W3 Total Cache, which cache the host before any hook runs; SSL plugins) sees the
            // request it expects: remembered from an earlier run while wp-config.php is
            // unchanged, else wp-config.php evaluated like WP-CLI does, else read as text.
            $stamp = @filemtime($configFile) . ':' . @filesize($configFile) . ' ';
            $remembered = \RunletRunner\Runner::recalled('wordpress.siteUrl');
            if ($remembered !== null && strpos($remembered, $stamp) === 0 && strlen($remembered) > strlen($stamp)) {
                [$url, $source] = [substr($remembered, strlen($stamp)), 'remembered for this session (wp-config.php unchanged)'];
            } else {
                [$url, $source] = self::probeSiteUrl($configFile);
                if ($url === null) {
                    [$url, $source] = self::staticSiteUrl($configFile, $source);
                }
                if ($url !== null) {
                    \RunletRunner\Runner::remember('wordpress.siteUrl', $stamp . $url);
                }
            }
        }
        $parts = $url === null ? null : parse_url($url);
        $https = is_array($parts) && ($parts['scheme'] ?? 'http') === 'https';
        $hostName = is_array($parts) && isset($parts['host']) && $parts['host'] !== '' ? $parts['host'] : 'localhost';
        $host = $hostName . (is_array($parts) && isset($parts['port']) ? ':' . $parts['port'] : '');
        $path = is_array($parts) && isset($parts['path']) && $parts['path'] !== '' ? rtrim($parts['path'], '/') . '/' : '/';
        $defaults = [
            'HTTP_HOST' => $host,
            'SERVER_NAME' => $hostName,
            'REQUEST_URI' => $path,
            'REQUEST_METHOD' => 'GET',
            'SERVER_PROTOCOL' => 'HTTP/1.1',
            'SERVER_PORT' => is_array($parts) && isset($parts['port']) ? (string) $parts['port'] : ($https ? '443' : '80'),
            'REMOTE_ADDR' => '127.0.0.1',
            'HTTP_USER_AGENT' => 'Runlet',
        ];
        if ($https) {
            $defaults['HTTPS'] = 'on';
        }
        self::$hostFromDatabase = $hostName === 'localhost' && !isset($_SERVER['HTTP_HOST']);
        $preset = isset($_SERVER['HTTP_HOST']);
        foreach ($defaults as $key => $value) {
            if (!isset($_SERVER[$key])) {
                $_SERVER[$key] = $value;
            }
        }
        $scheme = ($_SERVER['HTTPS'] ?? '') === 'on' ? 'https' : 'http';
        \RunletRunner\Runner::log('driver', 'WordPress request: ' . $scheme . '://' . $_SERVER['HTTP_HOST'] . $_SERVER['REQUEST_URI'],
            $preset ? 'HTTP_HOST was already set' : ($url !== null ? 'from ' . $source : 'defaults to localhost: ' . ($source ?? 'no site URL found in wp-config.php or the database')));
    }

    /**
     * Evaluates wp-config.php in a separate PHP process, as WP-CLI does: the line that loads
     * wp-settings.php is removed (so WordPress itself doesn't load there), `__DIR__` and
     * `__FILE__` point at the real file, and output is discarded. Reports the WP_HOME /
     * WP_SITEURL / DOMAIN_CURRENT_SITE that really apply (conditionals, environment
     * variables, included files), else reads `home` from the database with the real settings.
     *
     * @return array{0: string|null, 1: string|null} the URL and where it came from, or why not
     */
    private static function probeSiteUrl(string $configFile): array
    {
        if (!function_exists('proc_open') || PHP_BINARY === '' || !is_executable(PHP_BINARY)) {
            return [null, 'could not start a PHP process to evaluate wp-config.php'];
        }
        $command = [PHP_BINARY, '-d', 'display_errors=0', '-d', 'log_errors=0', '-r', self::CONFIG_PROBE, '--', $configFile];
        $process = @proc_open($command, [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['file', '/dev/null', 'w']], $pipes, dirname($configFile));
        if (!is_resource($process)) {
            return [null, 'could not start a PHP process to evaluate wp-config.php'];
        }
        stream_set_blocking($pipes[1], false);
        $output = '';
        $deadline = microtime(true) + 8;
        while (!feof($pipes[1]) && microtime(true) < $deadline) {
            $read = [$pipes[1]];
            $write = $except = null;
            if (@stream_select($read, $write, $except, 0, 200000) > 0) {
                $output .= (string) fread($pipes[1], 65536);
            }
        }
        $timedOut = !feof($pipes[1]);
        fclose($pipes[1]);
        if ($timedOut) {
            proc_terminate($process, 9);
        }
        proc_close($process);
        $marker = strrpos($output, "\x1eRUNLET_WPCONFIG");
        $result = $marker === false ? null : json_decode(substr($output, $marker + 16), true);
        if (!is_array($result)) {
            return [null, $timedOut ? 'evaluating wp-config.php took longer than 8 s' : 'evaluating wp-config.php reported nothing'];
        }
        if (isset($result['url']) && is_string($result['url']) && $result['url'] !== '') {
            return [$result['url'], (string) ($result['source'] ?? 'wp-config.php')];
        }

        return [null, isset($result['skipped']) ? (string) $result['skipped'] : 'wp-config.php defines no site URL and the home option could not be read'];
    }

    /** Runs in the probe process (see probeSiteUrl); prints a marker and JSON at the end. */
    private const CONFIG_PROBE = <<<'PHP'
error_reporting(0);
$config = (string) end($argv);
$out = [];
$code = @file_get_contents($config);
if (is_string($code)) {
    $code = preg_replace('/\b(?:require|include)(?:_once)?\b[^;]*wp-settings\.php[^;]*;/i', ';', $code, -1, $count);
    if ($count > 0) {
        $code = str_replace(['__FILE__', '__DIR__'], [var_export($config, true), var_export(dirname($config), true)], (string) $code);
        if (!defined('ABSPATH')) {
            define('ABSPATH', dirname($config) . '/');
        }
        ob_start();
        try {
            eval('?>' . $code);
        } catch (\Throwable $error) {
            $out['error'] = get_class($error) . ': ' . $error->getMessage();
        }
        ob_end_clean();
        if (defined('WP_HOME') && (string) WP_HOME !== '') {
            $out = ['url' => (string) WP_HOME, 'source' => 'WP_HOME (wp-config.php, evaluated)'];
        } elseif (defined('WP_SITEURL') && (string) WP_SITEURL !== '') {
            $out = ['url' => (string) WP_SITEURL, 'source' => 'WP_SITEURL (wp-config.php, evaluated)'];
        } elseif (defined('DOMAIN_CURRENT_SITE')) {
            $out = ['url' => 'http://' . DOMAIN_CURRENT_SITE . (defined('PATH_CURRENT_SITE') ? PATH_CURRENT_SITE : '/'), 'source' => 'DOMAIN_CURRENT_SITE (wp-config.php, evaluated)'];
        } elseif (defined('DB_NAME') && defined('DB_USER') && class_exists('mysqli')) {
            $host = defined('DB_HOST') ? (string) DB_HOST : 'localhost';
            $port = null;
            $socket = null;
            if (preg_match('/^(.*?):(\/.+)$/', $host, $match)) {
                [$host, $socket] = [$match[1] === '' ? 'localhost' : $match[1], $match[2]];
            } elseif (preg_match('/^(.+):(\d+)$/', $host, $match)) {
                [$host, $port] = [$match[1], (int) $match[2]];
            }
            $prefix = isset($table_prefix) && is_string($table_prefix) && preg_match('/^[A-Za-z0-9_]+$/', $table_prefix) ? $table_prefix : 'wp_';
            mysqli_report(MYSQLI_REPORT_OFF);
            $link = mysqli_init();
            if ($link !== false) {
                $link->options(MYSQLI_OPT_CONNECT_TIMEOUT, 3);
                if (@$link->real_connect($host, (string) DB_USER, defined('DB_PASSWORD') ? (string) DB_PASSWORD : '', (string) DB_NAME, $port, $socket)) {
                    $result = $link->query("SELECT option_name, option_value FROM `{$prefix}options` WHERE option_name IN ('home', 'siteurl')");
                    $values = [];
                    if ($result instanceof mysqli_result) {
                        while ($row = $result->fetch_assoc()) {
                            $values[$row['option_name']] = (string) $row['option_value'];
                        }
                    }
                    $link->close();
                    $home = $values['home'] ?? ($values['siteurl'] ?? '');
                    if ($home !== '') {
                        $out = ['url' => $home, 'source' => 'the home option (database settings from wp-config.php, evaluated)'];
                    } else {
                        $out['skipped'] = 'the database has no home option in ' . $prefix . 'options';
                    }
                } else {
                    $out['skipped'] = 'could not connect to the database wp-config.php points to';
                }
            }
        } else {
            $out['skipped'] = 'wp-config.php defines no site URL or database settings';
        }
    } else {
        $out['skipped'] = 'wp-config.php does not load wp-settings.php itself, so it was not evaluated';
    }
}
echo "\x1eRUNLET_WPCONFIG" . json_encode($out);
PHP;

    /**
     * Reads wp-config.php as text (comments removed): WP_HOME / WP_SITEURL /
     * DOMAIN_CURRENT_SITE, else `home` from the database with literal settings. Used when the
     * probe can't run. Conditional definitions can't be told apart here.
     *
     * @return array{0: string|null, 1: string|null}
     */
    private static function staticSiteUrl(string $configFile, ?string $why): array
    {
        $config = self::withoutComments((string) @file_get_contents($configFile));
        if (preg_match('/define\(\s*[\'"](?:WP_HOME|WP_SITEURL)[\'"]\s*,\s*[\'"](https?:\/\/[^\'"]+)[\'"]/', $config, $match)) {
            return [$match[1], 'WP_HOME / WP_SITEURL (wp-config.php, read as text)'];
        }
        if (preg_match('/define\(\s*[\'"]DOMAIN_CURRENT_SITE[\'"]\s*,\s*[\'"]([^\'"]+)[\'"]/', $config, $match)) {
            $path = preg_match('/define\(\s*[\'"]PATH_CURRENT_SITE[\'"]\s*,\s*[\'"]([^\'"]+)[\'"]/', $config, $pathMatch) ? $pathMatch[1] : '/';

            return ['http://' . $match[1] . $path, 'DOMAIN_CURRENT_SITE (wp-config.php, read as text)'];
        }
        $home = self::homeFromDatabase($config);
        if ($home !== null) {
            return [$home, 'the home option (read before loading WordPress)'];
        }

        return [null, $why];
    }

    /** PHP source without comments, so commented-out definitions are ignored. */
    private static function withoutComments(string $code): string
    {
        if (!function_exists('token_get_all')) {
            return $code;
        }
        $out = '';
        foreach (@token_get_all($code) as $token) {
            if (is_array($token)) {
                if ($token[0] !== T_COMMENT && $token[0] !== T_DOC_COMMENT) {
                    $out .= $token[1];
                }
            } else {
                $out .= $token;
            }
        }

        return $out;
    }

    /**
     * wp-config.php's literal database settings: DB_NAME, DB_USER, DB_PASSWORD, DB_HOST, and
     * $table_prefix. Null when any of the first three is not a plain string (environment
     * variables, constants built from other values), or for multisite.
     *
     * @return array{name: string, user: string, password: string, host: string, prefix: string}|null
     */
    public static function databaseSettings(string $config): ?array
    {
        if (preg_match('/define\(\s*[\'"]MULTISITE[\'"]\s*,\s*true/i', $config)) {
            return null;
        }
        $literal = static function (string $name) use ($config): ?string {
            if (preg_match('/define\(\s*[\'"]' . $name . '[\'"]\s*,\s*\'((?:[^\'\\\\]|\\\\.)*)\'\s*\)/', $config, $match)) {
                return str_replace(['\\\'', '\\\\'], ['\'', '\\'], $match[1]);
            }
            if (preg_match('/define\(\s*[\'"]' . $name . '[\'"]\s*,\s*"([^"$\\\\]*)"\s*\)/', $config, $match)) {
                return $match[1];
            }

            return null;
        };
        $name = $literal('DB_NAME');
        $user = $literal('DB_USER');
        $password = $literal('DB_PASSWORD');
        if ($name === null || $user === null || $password === null) {
            return null;
        }
        $prefix = preg_match('/\$table_prefix\s*=\s*[\'"]([A-Za-z0-9_]+)[\'"]\s*;/', $config, $match) ? $match[1] : 'wp_';

        return ['name' => $name, 'user' => $user, 'password' => $password, 'host' => $literal('DB_HOST') ?? 'localhost', 'prefix' => $prefix];
    }

    /** The `home` option (else `siteurl`) read with mysqli before WordPress loads; null on any failure. */
    private static function homeFromDatabase(string $config): ?string
    {
        $settings = self::databaseSettings($config);
        if ($settings === null || !class_exists('mysqli')) {
            return null;
        }
        // DB_HOST: "host", "host:port", "host:/path/to.sock", or ":/path/to.sock".
        $host = $settings['host'];
        $port = null;
        $socket = null;
        if (preg_match('/^(.*?):(\/.+)$/', $host, $match)) {
            [$host, $socket] = [$match[1] === '' ? 'localhost' : $match[1], $match[2]];
        } elseif (preg_match('/^(.+):(\d+)$/', $host, $match)) {
            [$host, $port] = [$match[1], (int) $match[2]];
        }
        try {
            if (function_exists('mysqli_report')) {
                mysqli_report(MYSQLI_REPORT_OFF);
            }
            $link = mysqli_init();
            if ($link === false) {
                return null;
            }
            $link->options(MYSQLI_OPT_CONNECT_TIMEOUT, 3);
            if (!@$link->real_connect($host, $settings['user'], $settings['password'], $settings['name'], $port, $socket)) {
                return null;
            }
            $result = $link->query("SELECT option_name, option_value FROM `" . $settings['prefix'] . "options` WHERE option_name IN ('home', 'siteurl')");
            $values = [];
            if ($result instanceof \mysqli_result) {
                while ($row = $result->fetch_assoc()) {
                    $values[$row['option_name']] = (string) $row['option_value'];
                }
                $result->free();
            }
            $link->close();
            $home = $values['home'] ?? ($values['siteurl'] ?? '');

            return $home !== '' ? $home : null;
        } catch (\Throwable $ignored) {
            return null;
        }
    }

    /**
     * Filters registered before WordPress loads (WordPress turns pre-filled $wp_filter
     * entries into hooks). Returns the bootstrap-only nocache_headers guard.
     */
    private function installBootstrapHooks(): \Closure
    {
        $false = static function (): bool {
            return false;
        };
        // WordPress's own fatal-error handler would print an HTML error page, pause the
        // plugin, and possibly email a recovery-mode link after a snippet's fatal error.
        self::addFilter('wp_fatal_error_handler_enabled', $false);
        // Page-cache drop-ins and maintenance mode can serve a page and exit.
        self::addFilter('enable_loading_advanced_cache_dropin', $false);
        self::addFilter('enable_maintenance_mode', $false);
        self::addFilter('ms_site_check', static function (): bool {
            return true;
        });
        // Without WP_HOME / WP_SITEURL / DOMAIN_CURRENT_SITE, the site's real URL lives in the
        // database: once it is connected (after must-use plugins, before regular plugins load),
        // present the `home` option's host and scheme, so canonical-host and force-HTTPS code
        // (page caches such as W3 Total Cache, SSL plugins) doesn't redirect and exit.
        self::addFilter('muplugins_loaded', static function (): void {
            if (!self::$hostFromDatabase || !function_exists('get_option')) {
                return;
            }
            self::$hostFromDatabase = false;
            $home = (string) get_option('home');
            $parts = parse_url($home !== '' ? $home : (string) get_option('siteurl'));
            if (!is_array($parts) || !isset($parts['host']) || $parts['host'] === '') {
                return;
            }
            $https = ($parts['scheme'] ?? 'http') === 'https';
            $_SERVER['HTTP_HOST'] = $parts['host'] . (isset($parts['port']) ? ':' . $parts['port'] : '');
            $_SERVER['SERVER_NAME'] = $parts['host'];
            $_SERVER['SERVER_PORT'] = isset($parts['port']) ? (string) $parts['port'] : ($https ? '443' : '80');
            $_SERVER['REQUEST_URI'] = isset($parts['path']) && $parts['path'] !== '' ? rtrim($parts['path'], '/') . '/' : '/';
            if ($https) {
                $_SERVER['HTTPS'] = 'on';
            }
            \RunletRunner\Runner::log('driver', 'WordPress request: ' . ($https ? 'https' : 'http') . '://' . $_SERVER['HTTP_HOST'] . $_SERVER['REQUEST_URI'], 'from the home option in the database (before plugins load)');
        });
        // A run should not spawn WP-Cron (an HTTP request to the site and a lock write at
        // shutdown, or a redirect with ALTERNATE_WP_CRON). Snippets can still call wp_cron().
        self::addFilter('muplugins_loaded', static function (): void {
            remove_action('init', 'wp_cron');
        });
        // A redirect during bootstrap (not installed → install.php, a forced HTTPS or canonical
        // host, a login wall) is followed by exit(): remember it and who sent it.
        self::addFilter('wp_redirect', static function ($location, $status = 302) {
            $caller = '';
            foreach (debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS) as $frame) {
                $file = $frame['file'] ?? '';
                if ($file !== '' && strpos($file, '/wp-includes/') === false && ($frame['function'] ?? '') !== 'apply_filters') {
                    $caller = $file . ':' . ($frame['line'] ?? 0);
                    break;
                }
            }
            self::$bootRedirect = ['location' => (string) $location, 'status' => (int) $status, 'caller' => $caller];
            \RunletRunner\Runner::log('driver', 'WordPress redirect to ' . $location . ' (' . (int) $status . ')', $caller === '' ? null : 'from ' . $caller);

            return $location;
        });
        // wp_die() prints an HTML page and exits; report its message as an exception instead.
        self::addFilter('wp_die_handler', static function () {
            return static function ($message, $title = '', $args = []): void {
                if (is_object($message) && method_exists($message, 'get_error_message')) {
                    $message = $message->get_error_message();
                }
                $text = is_scalar($message) ? (string) $message : '';
                if ($text === '' && is_scalar($title)) {
                    $text = (string) $title;
                }
                $text = trim(html_entity_decode(strip_tags($text), ENT_QUOTES));

                throw new \RuntimeException('wp_die(): ' . ($text === '' ? 'WordPress stopped the request.' : $text));
            };
        });
        // While loading, nocache_headers() means WordPress is about to redirect and exit
        // because its database is unreachable or it is not installed.
        $guard = static function ($headers) {
            $wpdb = $GLOBALS['wpdb'] ?? null;
            if (is_object($wpdb) && !empty($wpdb->error)) {
                $error = $wpdb->error;
                if (is_object($error) && method_exists($error, 'get_error_message')) {
                    $error = $error->get_error_message();
                }
                throw new \RuntimeException('WordPress could not use its database: ' . trim(strip_tags(is_scalar($error) ? (string) $error : 'unknown error')));
            }
            $installing = function_exists('wp_installing') && wp_installing();
            if (!$installing && function_exists('is_blog_installed') && !is_blog_installed()) {
                throw new \RuntimeException('WordPress is not installed in its database yet. Finish the installation first (for example with `wp core install`).');
            }

            return $headers;
        };
        self::addFilter('nocache_headers', $guard);

        return $guard;
    }

    private static function addFilter(string $hook, callable $callback, int $priority = 10): void
    {
        if (function_exists('add_filter')) {
            add_filter($hook, $callback, $priority, 1);

            return;
        }
        $GLOBALS['wp_filter'][$hook][$priority][] = ['function' => $callback, 'accepted_args' => 1];
    }

    /** Mirrors wp-load.php's lookup: ABSPATH/wp-config.php, or one level up (Bedrock). */
    private static function configFile(string $abspath): ?string
    {
        if (is_file($abspath . '/wp-config.php')) {
            return $abspath . '/wp-config.php';
        }
        $parent = dirname($abspath);
        if (is_file($parent . '/wp-config.php') && !is_file($parent . '/wp-settings.php')) {
            return $parent . '/wp-config.php';
        }

        return null;
    }

    private static function load(string $__runletLoader): void
    {
        foreach (self::WORDPRESS_GLOBALS as $__runletName) {
            global $$__runletName;
        }
        unset($__runletName);
        $__runletBefore = get_defined_vars();

        require $__runletLoader;

        // Anything else WordPress, wp-config.php, or a plugin defined at "file scope" would
        // have been global in a web request.
        foreach (get_defined_vars() as $__runletName => $__runletValue) {
            if ($__runletName !== '__runletBefore' && !array_key_exists($__runletName, $__runletBefore)) {
                $GLOBALS[$__runletName] = $__runletValue;
            }
        }
    }
}

/**
 * @internal wp_mail() for the run inspector (#192), used by WordPressDriver: records each
 * message in the Mail section and, when the run intercepts mail, stops it with `pre_wp_mail`.
 *
 * A message is recorded when WordPress reports how it went (`wp_mail_succeeded`,
 * `wp_mail_failed`), from what PHPMailer was given (`phpmailer_init`: the final recipients,
 * bodies, and attachments, after other plugins' changes). An intercepted message never reaches
 * PHPMailer, so it is recorded from wp_mail()'s arguments, read the way wp_mail() reads them.
 * Without an outcome (WordPress before 5.9, or a plugin's own wp_mail()), the message is
 * recorded when the next one starts or the run ends.
 */
final class WordPressMail
{
    /** @var Inspector */
    private $inspector;
    /** @var array<string, mixed>|null The message wp_mail() is handling now: `atts`, `fields`, `location`, `caller`. */
    private $pending;
    /** @var bool */
    private $installed = false;
    /** @var int Bytes of inline images turned into data: URLs this run. */
    private $inlineBudget = 4194304;

    public function __construct(Inspector $inspector)
    {
        $this->inspector = $inspector;
    }

    /** Adds the hooks: through add_filter() once WordPress is loaded, else into $wp_filter for WordPress to pick up. */
    public function install(): void
    {
        if ($this->installed) {
            return;
        }
        $this->installed = true;
        // Last, so the arguments and the PHPMailer object are final, and so Runlet's answer
        // on pre_wp_mail is the one wp_mail() gets.
        $hooks = [
            ['wp_mail', 'started', 1],
            ['pre_wp_mail', 'beforeSending', 2],
            ['phpmailer_init', 'built', 1],
            ['wp_mail_succeeded', 'succeeded', 1],
            ['wp_mail_failed', 'failed', 1],
        ];
        foreach ($hooks as [$hook, $method, $arguments]) {
            $callback = [$this, $method];
            if (function_exists('add_filter')) {
                add_filter($hook, $callback, PHP_INT_MAX, $arguments);
            } else {
                $GLOBALS['wp_filter'][$hook][PHP_INT_MAX][] = ['function' => $callback, 'accepted_args' => $arguments];
            }
        }
        $this->inspector->atFinish(function (): void {
            $this->flush();
        });
    }

    /**
     * Why this run can't promise that no wp_mail() message is sent, or null when it can.
     * Checked after WordPress loaded (plugins and the theme set up their hooks by then).
     */
    public function interceptionBlocker(): ?string
    {
        $version = isset($GLOBALS['wp_version']) ? (string) $GLOBALS['wp_version'] : '';
        if ($version !== '' && version_compare($version, '5.7', '<')) {
            return 'WordPress ' . $version . ' has no pre_wp_mail filter (WordPress 5.7 added it), so Runlet can\'t stop its mail.';
        }
        $replacement = self::wpMailReplacement();
        if ($replacement !== null) {
            return ucfirst($replacement) . ' replaces wp_mail(); Runlet can\'t stop its mail.';
        }
        $other = $this->otherPreWpMailCallback();
        if ($other !== null) {
            return ucfirst($other) . ' filters pre_wp_mail and could send mail itself before Runlet stops it. Messages marked intercepted were not sent.';
        }

        return null;
    }

    /**
     * `wp_mail` filter: the final arguments of a new message.
     *
     * @param mixed $atts
     * @return mixed
     */
    public function started($atts)
    {
        try {
            // The previous message's outcome was never reported (WordPress before 5.9).
            $this->flush();
            if (is_array($atts)) {
                $this->pending = ['atts' => $atts] + $this->origin();
            }
        } catch (\Throwable $error) {
            // Recording never breaks wp_mail().
        }

        return $atts;
    }

    /**
     * `pre_wp_mail` filter: true stops wp_mail() before PHPMailer, and wp_mail() returns true.
     *
     * @param mixed $return null, or what an earlier callback answered
     * @param mixed $atts
     * @return mixed
     */
    public function beforeSending($return, $atts = null)
    {
        try {
            if ($return !== null || !$this->inspector->shouldInterceptMail() || self::wpMailReplacement() !== null || $this->otherPreWpMailCallback(true) !== null) {
                // Not Runlet's to stop: interception is off, an earlier callback already
                // answered for this message, or a plugin's own wp_mail() or later callback
                // decides what happens next.
                return $return;
            }
            $pending = $this->pending ?? $this->origin();
            $this->pending = null;
            $arguments = is_array($atts) ? $atts : (is_array($pending['atts'] ?? null) ? $pending['atts'] : []);
            $this->report($this->fromArguments($arguments), $pending, ['intercepted' => true]);

            return true;
        } catch (\Throwable $error) {
            return $return;
        }
    }

    /**
     * `phpmailer_init` action: the message as PHPMailer will send it.
     *
     * @param mixed $phpmailer
     */
    public function built($phpmailer): void
    {
        try {
            if (!is_object($phpmailer)) {
                return;
            }
            $fields = $this->fromPhpMailer($phpmailer);
            if ($this->pending === null) {
                $this->pending = $this->origin();
            }
            $this->pending['fields'] = $fields;
        } catch (\Throwable $error) {
            // Recording never breaks wp_mail().
        }
    }

    /**
     * `wp_mail_succeeded` action (WordPress 5.9+).
     *
     * @param mixed $data
     */
    public function succeeded($data = null): void
    {
        $this->flush();
    }

    /**
     * `wp_mail_failed` action: the message, and PHPMailer's error.
     *
     * @param mixed $error a WP_Error
     */
    public function failed($error = null): void
    {
        try {
            $message = is_object($error) && method_exists($error, 'get_error_message') ? (string) $error->get_error_message() : '';
            $data = is_object($error) && method_exists($error, 'get_error_data') ? $error->get_error_data() : null;
            $pending = $this->pending ?? $this->origin();
            $this->pending = null;
            if (!isset($pending['fields'])) {
                $pending['fields'] = $this->fromArguments(is_array($pending['atts'] ?? null) ? $pending['atts'] : (is_array($data) ? $data : []));
            }
            $this->report($pending['fields'], $pending, ['error' => $message !== '' ? $message : 'wp_mail() could not send the message.']);
        } catch (\Throwable $ignored) {
            // Recording never breaks wp_mail().
        }
    }

    /** Records the message in progress as sent, if there is one. */
    private function flush(): void
    {
        $pending = $this->pending;
        if ($pending === null) {
            return;
        }
        $this->pending = null;
        try {
            $fields = $pending['fields'] ?? $this->fromArguments(is_array($pending['atts'] ?? null) ? $pending['atts'] : []);
            $this->report($fields, $pending, []);
        } catch (\Throwable $error) {
            // Recording never breaks wp_mail().
        }
    }

    /**
     * @param array<string, mixed> $fields
     * @param array<string, mixed> $pending
     * @param array<string, mixed> $details
     */
    private function report(array $fields, array $pending, array $details): void
    {
        $details += ['mailer' => 'wp_mail', 'intercepted' => false];
        if (isset($pending['location']) && is_array($pending['location']) && $pending['location'] !== []) {
            $details['location'] = $pending['location'];
        }
        if (isset($pending['caller']) && is_string($pending['caller'])) {
            $details['caller'] = $pending['caller'];
        }
        $this->inspector->mail($fields, $details);
    }

    /**
     * Where wp_mail() was called from: the snippet line when the snippet is on the stack,
     * else the call site; and the plugin, theme, or core function that called it.
     *
     * @return array{location: array<string, mixed>, caller?: string}
     */
    private function origin(): array
    {
        $location = $this->inspector->location();
        $frames = debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS);
        $start = null;
        foreach ($frames as $index => $frame) {
            if (($frame['function'] ?? '') === 'wp_mail' && !isset($frame['class']) && isset($frame['file'])) {
                $start = $index;
                break;
            }
        }
        if ($start === null) {
            return ['location' => $location];
        }
        if (($location['inSnippet'] ?? false) !== true) {
            $location = ['inSnippet' => false, 'file' => (string) $frames[$start]['file'], 'line' => (int) ($frames[$start]['line'] ?? 0)];
        }
        $origin = ['location' => $location];
        $coreFunction = null;
        for ($index = $start; $index < count($frames); $index++) {
            $file = $frames[$index]['file'] ?? null;
            if (!is_string($file) || substr($file, -13) === "eval()'d code" || strpos($file, 'Standard input code') === 0 || $file === '-') {
                break;
            }
            $owner = self::owner($file);
            if ($owner === null) {
                // WordPress core: name the core function that sent it (retrieve_password()).
                if ($coreFunction === null && isset($frames[$index + 1]['function'])) {
                    $outer = $frames[$index + 1];
                    $coreFunction = (isset($outer['class']) ? $outer['class'] . '::' : '') . $outer['function'] . '()';
                }
                continue;
            }
            // "plugin acme-forms (src/Mailer.php:42)"; a one-file plugin: "plugin acme.php (line 3)".
            $short = self::shortPath($file);
            $line = (int) ($frames[$index]['line'] ?? 0);
            $where = substr($owner, -strlen($short) - 1) === ' ' . $short ? 'line ' . $line : $short . ':' . $line;
            $origin['caller'] = $owner . ' (' . $where . ')' . ($coreFunction !== null ? ' through ' . $coreFunction : '');

            return $origin;
        }
        if ($coreFunction !== null) {
            $origin['caller'] = 'WordPress core: ' . $coreFunction;
        }

        return $origin;
    }

    /**
     * The plugin, must-use plugin, or theme a file belongs to ("plugin acme-forms"), "code in
     * <path>" for other files outside WordPress core, or null for core (wp-includes, wp-admin).
     */
    private static function owner(string $file): ?string
    {
        $roots = [];
        if (defined('WPMU_PLUGIN_DIR')) {
            $roots['must-use plugin'] = (string) WPMU_PLUGIN_DIR;
        }
        if (defined('WP_PLUGIN_DIR')) {
            $roots['plugin'] = (string) WP_PLUGIN_DIR;
        }
        if (function_exists('get_theme_root')) {
            $roots['theme'] = (string) get_theme_root();
        } elseif (defined('WP_CONTENT_DIR')) {
            $roots['theme'] = WP_CONTENT_DIR . '/themes';
        }
        foreach ($roots as $kind => $root) {
            $relative = self::relativeTo($file, $root);
            if ($relative !== null) {
                $slash = strpos($relative, '/');

                return $kind . ' ' . ($slash === false ? $relative : substr($relative, 0, $slash));
            }
        }
        if (defined('ABSPATH') && defined('WPINC')) {
            foreach ([ABSPATH . WPINC, ABSPATH . 'wp-admin'] as $core) {
                if (self::relativeTo($file, $core) !== null) {
                    return null;
                }
            }
        }

        return 'code in ' . self::shortPath($file);
    }

    /** $file relative to the folder $root, or null when it is outside it (symbolic links resolved). */
    private static function relativeTo(string $file, string $root): ?string
    {
        $root = rtrim($root, '/');
        if ($root === '') {
            return null;
        }
        foreach (array_unique([$root, (string) realpath($root)]) as $candidate) {
            if ($candidate !== '' && strpos($file, $candidate . '/') === 0) {
                return substr($file, strlen($candidate) + 1);
            }
        }

        return null;
    }

    /** A path relative to the plugin, theme, or WordPress folder it is in. */
    private static function shortPath(string $file): string
    {
        $roots = [];
        foreach (['WPMU_PLUGIN_DIR', 'WP_PLUGIN_DIR'] as $constant) {
            if (defined($constant)) {
                $roots[] = (string) constant($constant);
            }
        }
        if (function_exists('get_theme_root')) {
            $roots[] = (string) get_theme_root();
        }
        foreach ($roots as $root) {
            $relative = self::relativeTo($file, $root);
            if ($relative !== null) {
                $slash = strpos($relative, '/');

                return $slash === false ? $relative : substr($relative, $slash + 1);
            }
        }
        if (defined('ABSPATH')) {
            $relative = self::relativeTo($file, (string) ABSPATH);
            if ($relative !== null) {
                return $relative;
            }
        }

        return basename($file);
    }

    /**
     * Who defined wp_mail() instead of WordPress (`wp-includes/pluggable.php`): "a plugin
     * (acme-smtp)", or null for WordPress's own.
     */
    private static function wpMailReplacement(): ?string
    {
        if (!function_exists('wp_mail') || !defined('ABSPATH') || !defined('WPINC')) {
            return null;
        }
        $file = (string) (new \ReflectionFunction('wp_mail'))->getFileName();
        $core = ABSPATH . WPINC . '/pluggable.php';
        if ($file === $core || realpath($file) === realpath($core)) {
            return null;
        }

        return self::described(self::owner($file) ?? 'code in ' . self::shortPath($file));
    }

    /**
     * A callback on pre_wp_mail that isn't Runlet's ("a plugin (acme-mailer)"), or null.
     * With $afterRunlet, only those that run after Runlet's (they would have the last word).
     */
    private function otherPreWpMailCallback(bool $afterRunlet = false): ?string
    {
        $hook = $GLOBALS['wp_filter']['pre_wp_mail'] ?? null;
        $callbacks = is_object($hook) && isset($hook->callbacks) && is_array($hook->callbacks) ? $hook->callbacks : (is_array($hook) ? $hook : []);
        ksort($callbacks);
        $seenRunlet = false;
        foreach ($callbacks as $entries) {
            foreach (is_array($entries) ? $entries : [] as $entry) {
                $function = is_array($entry) ? ($entry['function'] ?? null) : null;
                if (is_array($function) && ($function[0] ?? null) === $this) {
                    $seenRunlet = true;
                    continue;
                }
                if ($afterRunlet && !$seenRunlet) {
                    continue;
                }
                $file = self::callbackFile($function);

                return self::described($file === null ? 'a plugin' : (self::owner($file) ?? 'WordPress core'));
            }
        }

        return null;
    }

    /** "plugin acme-smtp" → "a plugin (acme-smtp)"; other descriptions stay as they are. */
    private static function described(string $owner): string
    {
        foreach (['must-use plugin', 'plugin', 'theme'] as $kind) {
            if (strpos($owner, $kind . ' ') === 0) {
                return 'a ' . $kind . ' (' . substr($owner, strlen($kind) + 1) . ')';
            }
        }

        return $owner;
    }

    /** @param mixed $callback */
    private static function callbackFile($callback): ?string
    {
        try {
            if (is_string($callback) && strpos($callback, '::') !== false) {
                $callback = explode('::', $callback, 2);
            }
            if (is_array($callback) && count($callback) === 2) {
                $reflection = new \ReflectionMethod($callback[0], (string) $callback[1]);
            } elseif ($callback instanceof \Closure || (is_string($callback) && function_exists($callback))) {
                $reflection = new \ReflectionFunction($callback);
            } elseif (is_object($callback) && method_exists($callback, '__invoke')) {
                $reflection = new \ReflectionMethod($callback, '__invoke');
            } else {
                return null;
            }
            $file = $reflection->getFileName();

            return is_string($file) ? $file : null;
        } catch (\Throwable $error) {
            return null;
        }
    }

    /**
     * A message from wp_mail()'s arguments, read as wp_mail() reads them: its headers (From,
     * Cc, Bcc, Reply-To, Content-Type), its defaults, and the filters that change them
     * (`wp_mail_from`, `wp_mail_from_name`, `wp_mail_content_type`).
     *
     * @param array<string, mixed> $atts
     * @return array<string, mixed>
     */
    private function fromArguments(array $atts): array
    {
        $split = static function ($value): array {
            $items = is_array($value) ? $value : explode(',', (string) $value);

            return array_values(array_filter(array_map(static function ($item): string {
                return is_scalar($item) ? trim((string) $item) : '';
            }, $items), 'strlen'));
        };
        $headers = $atts['headers'] ?? [];
        $lines = is_array($headers) ? $headers : explode("\n", str_replace("\r\n", "\n", (string) $headers));
        $cc = $bcc = $replyTo = [];
        $fromEmail = $fromName = $contentType = null;
        foreach ($lines as $line) {
            if (!is_string($line) || strpos($line, ':') === false) {
                continue;
            }
            [$name, $content] = explode(':', trim($line), 2);
            $content = trim($content);
            switch (strtolower(trim($name))) {
                case 'from':
                    $bracket = strpos($content, '<');
                    if ($bracket !== false) {
                        if ($bracket > 0) {
                            $fromName = trim(str_replace('"', '', substr($content, 0, $bracket)));
                        }
                        $fromEmail = trim(str_replace('>', '', substr($content, $bracket + 1)));
                    } elseif ($content !== '') {
                        $fromEmail = $content;
                    }
                    break;
                case 'content-type':
                    $type = trim(explode(';', $content)[0]);
                    if ($type !== '') {
                        $contentType = $type;
                    }
                    break;
                case 'cc':
                    $cc = array_merge($cc, $split($content));
                    break;
                case 'bcc':
                    $bcc = array_merge($bcc, $split($content));
                    break;
                case 'reply-to':
                    $replyTo = array_merge($replyTo, $split($content));
                    break;
            }
        }
        if ($fromEmail === null) {
            $host = function_exists('network_home_url') ? parse_url((string) network_home_url(), PHP_URL_HOST) : null;
            $fromEmail = 'wordpress@' . (is_string($host) ? preg_replace('/^www\./', '', $host) : '');
        }
        $fromName = $fromName ?? 'WordPress';
        $contentType = $contentType ?? 'text/plain';
        if (function_exists('apply_filters')) {
            $fromEmail = apply_filters('wp_mail_from', $fromEmail);
            $fromName = apply_filters('wp_mail_from_name', $fromName);
            $contentType = apply_filters('wp_mail_content_type', $contentType);
        }
        $message = isset($atts['message']) && is_scalar($atts['message']) ? (string) $atts['message'] : '';
        $fields = [
            'subject' => isset($atts['subject']) && is_scalar($atts['subject']) ? (string) $atts['subject'] : '',
            'from' => [['address' => is_scalar($fromEmail) ? (string) $fromEmail : '', 'name' => is_scalar($fromName) ? (string) $fromName : '']],
            'to' => $split($atts['to'] ?? []),
            'cc' => $cc,
            'bcc' => $bcc,
            'replyTo' => $replyTo,
            ($contentType === 'text/html' ? 'html' : 'text') => $message,
            'attachments' => [],
        ];
        $inline = [];
        $attachments = $atts['attachments'] ?? [];
        foreach (is_array($attachments) ? $attachments : explode("\n", str_replace("\r\n", "\n", (string) $attachments)) as $name => $path) {
            if (is_string($path) && $path !== '' && is_file($path) && is_readable($path)) {
                $fields['attachments'][] = self::fileAttachment($path, is_string($name) && $name !== '' ? $name : basename($path), false);
            }
        }
        $embeds = $atts['embeds'] ?? [];
        foreach (is_array($embeds) ? $embeds : explode("\n", str_replace("\r\n", "\n", (string) $embeds)) as $id => $path) {
            if (is_string($path) && $path !== '' && is_file($path) && is_readable($path)) {
                $fields['attachments'][] = self::fileAttachment($path, basename($path), true);
                $inline[(string) $id] = [$path, false];
            }
        }
        if (isset($fields['html']) && $inline !== []) {
            $fields['html'] = $this->inlineImages($fields['html'], $inline);
        }

        return $fields;
    }

    /**
     * The message PHPMailer was given: recipients, From, subject, bodies, attachments.
     *
     * @return array<string, mixed>
     */
    private function fromPhpMailer(object $mailer): array
    {
        $addresses = static function (object $mailer, string $method): array {
            $list = method_exists($mailer, $method) ? $mailer->$method() : [];
            $result = [];
            foreach (is_array($list) ? $list : [] as $entry) {
                if (is_array($entry) && isset($entry[0]) && is_string($entry[0])) {
                    $result[] = ['address' => $entry[0], 'name' => isset($entry[1]) && is_string($entry[1]) ? $entry[1] : ''];
                }
            }

            return $result;
        };
        $fields = [
            'subject' => isset($mailer->Subject) && is_scalar($mailer->Subject) ? (string) $mailer->Subject : '',
            'from' => [['address' => isset($mailer->From) ? (string) $mailer->From : '', 'name' => isset($mailer->FromName) ? (string) $mailer->FromName : '']],
            'to' => $addresses($mailer, 'getToAddresses'),
            'cc' => $addresses($mailer, 'getCcAddresses'),
            'bcc' => $addresses($mailer, 'getBccAddresses'),
            'replyTo' => $addresses($mailer, 'getReplyToAddresses'),
            'attachments' => [],
        ];
        $body = isset($mailer->Body) && is_scalar($mailer->Body) ? (string) $mailer->Body : '';
        $alternative = isset($mailer->AltBody) && is_scalar($mailer->AltBody) ? (string) $mailer->AltBody : '';
        if (stripos(isset($mailer->ContentType) ? (string) $mailer->ContentType : '', 'html') !== false) {
            $fields['html'] = $body;
            if ($alternative !== '') {
                $fields['text'] = $alternative;
            }
        } else {
            $fields['text'] = $body;
        }
        $inline = [];
        foreach (method_exists($mailer, 'getAttachments') ? (array) $mailer->getAttachments() : [] as $attachment) {
            // [path or contents, file name, name, encoding, type, is string, disposition, cid]
            if (!is_array($attachment) || !isset($attachment[0]) || !is_string($attachment[0])) {
                continue;
            }
            $isString = ($attachment[5] ?? false) === true;
            $isInline = ($attachment[6] ?? '') === 'inline';
            $name = isset($attachment[2]) && is_string($attachment[2]) && $attachment[2] !== '' ? $attachment[2] : (isset($attachment[1]) && is_string($attachment[1]) ? $attachment[1] : '');
            $entry = ['filename' => $name !== '' ? $name : ($isString ? 'attachment' : basename($attachment[0]))];
            if (isset($attachment[4]) && is_string($attachment[4]) && $attachment[4] !== '') {
                $entry['contentType'] = $attachment[4];
            }
            $size = $isString ? strlen($attachment[0]) : (is_file($attachment[0]) ? @filesize($attachment[0]) : false);
            if (is_int($size)) {
                $entry['size'] = $size;
            }
            if ($isInline) {
                $entry['inline'] = true;
                if (isset($attachment[7]) && is_string($attachment[7]) && $attachment[7] !== '') {
                    $inline[$attachment[7]] = [$attachment[0], $isString, $entry['contentType'] ?? null];
                }
            }
            $fields['attachments'][] = $entry;
        }
        if (isset($fields['html']) && $inline !== []) {
            $fields['html'] = $this->inlineImages($fields['html'], $inline);
        }

        return $fields;
    }

    /**
     * An attachment as PHPMailer would add it: typed from its path, named $name.
     *
     * @return array{filename: string, contentType?: string, size?: int, inline?: bool}
     */
    private static function fileAttachment(string $path, string $name, bool $inline): array
    {
        $entry = ['filename' => $name];
        $phpmailer = 'PHPMailer\PHPMailer\PHPMailer';
        if (!class_exists($phpmailer, false) && defined('ABSPATH') && defined('WPINC') && is_file(ABSPATH . WPINC . '/PHPMailer/PHPMailer.php')) {
            // WordPress 5.5+ loads it for every message it sends.
            require_once ABSPATH . WPINC . '/PHPMailer/PHPMailer.php';
        }
        if (class_exists($phpmailer, false) && method_exists($phpmailer, 'filenameToType')) {
            $type = $phpmailer::filenameToType($path);
        } else {
            $type = function_exists('wp_check_filetype') ? (wp_check_filetype($path)['type'] ?? null) : null;
        }
        if (is_string($type) && $type !== '') {
            $entry['contentType'] = $type;
        }
        $size = @filesize($path);
        if (is_int($size)) {
            $entry['size'] = $size;
        }
        if ($inline) {
            $entry['inline'] = true;
        }

        return $entry;
    }

    /**
     * `cid:` references in $html as data: URLs, so the preview shows inline images without
     * loading anything. At most 4 MB of images per run.
     *
     * @param array<string, array<int, mixed>> $inline cid => [path or contents, whether it is the contents, type]
     */
    private function inlineImages(string $html, array $inline): string
    {
        if (strpos($html, 'cid:') === false) {
            return $html;
        }
        foreach ($inline as $id => $image) {
            if ($id === '' || strpos($html, 'cid:' . $id) === false) {
                continue;
            }
            $contents = $image[1] ? $image[0] : (is_file($image[0]) && @filesize($image[0]) <= $this->inlineBudget ? @file_get_contents($image[0]) : false);
            if (!is_string($contents) || strlen($contents) > $this->inlineBudget) {
                continue;
            }
            $this->inlineBudget -= strlen($contents);
            $type = $image[2] ?? null;
            if (!is_string($type) || $type === '') {
                $type = !$image[1] && function_exists('wp_check_filetype') ? (string) (wp_check_filetype($image[0])['type'] ?? '') : '';
            }
            $html = str_replace('cid:' . $id, 'data:' . ($type !== '' ? $type : 'application/octet-stream') . ';base64,' . base64_encode($contents), $html);
        }

        return $html;
    }
}

/**
 * Symfony (Flex skeleton or classic): loads the .env files like the Runtime component,
 * then boots the kernel. Snippets get $kernel and $container.
 */
class SymfonyDriver extends ComposerDriver
{
    /** @var object|null The booted kernel. */
    protected $kernel;

    public function name(): string
    {
        return 'Symfony';
    }

    public function canBootstrap(string $projectPath): bool
    {
        return is_file($projectPath . '/bin/console')
            && (is_file($projectPath . '/src/Kernel.php') || is_file($projectPath . '/config/bundles.php'));
    }

    public function bootstrap(string $projectPath): void
    {
        $this->requireAutoloader($projectPath);
        $this->loadEnvironment($projectPath);

        $class = $this->kernelClass($projectPath);
        $environment = (string) ($_SERVER['APP_ENV'] ?? $_ENV['APP_ENV'] ?? 'dev');
        $debug = $_SERVER['APP_DEBUG'] ?? $_ENV['APP_DEBUG'] ?? ($environment !== 'prod');
        $kernel = new $class($environment, (bool) $debug);
        $kernel->boot();
        $this->kernel = $kernel;
    }

    /** @return array<string, mixed> */
    public function variables(): array
    {
        if (!is_object($this->kernel)) {
            return [];
        }

        return ['kernel' => $this->kernel, 'container' => $this->kernel->getContainer()];
    }

    /**
     * Doctrine DBAL connections from the `doctrine` registry and mail sent through Symfony
     * Mailer (intercepted with MessageEvent::reject(), Symfony 6.3+), plus the automatic
     * detection every driver has.
     */
    public function inspect(Inspector $inspector): void
    {
        parent::inspect($inspector);
        if (!is_object($this->kernel)) {
            return;
        }
        $container = $this->kernel->getContainer();
        if ($container->has('doctrine')) {
            $registry = $container->get('doctrine');
            if (is_object($registry) && method_exists($registry, 'getConnectionNames')) {
                foreach (array_keys($registry->getConnectionNames()) as $name) {
                    // Getting a connection creates the service; DBAL connects on first use.
                    $this->inspectDoctrine($inspector, $registry->getConnection($name), (string) $name);
                }
            }
        }
        $messageEvent = 'Symfony\Component\Mailer\Event\MessageEvent';
        if ($container->has('event_dispatcher') && class_exists($messageEvent) && $inspector->once('symfony-mailer')) {
            $intercept = $inspector->shouldInterceptMail() && method_exists($messageEvent, 'reject');
            $inspector->section(Inspector::MAIL);
            // After the listeners that render templated emails.
            $container->get('event_dispatcher')->addListener($messageEvent, static function ($event) use ($inspector, $intercept): void {
                $queued = method_exists($event, 'isQueued') && $event->isQueued();
                $inspector->mail($event->getMessage(), $queued ? ['queued' => true, 'mailer' => $event->getTransport()] : ['intercepted' => $intercept, 'mailer' => $event->getTransport()]);
                if ($intercept && !$queued) {
                    $event->reject();
                }
            }, -1024);
            if ($intercept) {
                $inspector->interceptingMail();
            }
        }
    }

    /** SQL tabs (#35): the named (or default) connection of the `doctrine` registry. */
    public function sqlConnection(?string $connection)
    {
        $registry = $this->doctrine();

        return $registry === null ? null : SqlConnections::doctrine($registry->getConnection($connection));
    }

    /** SQL tabs (#35): the `doctrine` registry's connection names, the default first. */
    public function sqlConnections(): array
    {
        $registry = $this->doctrine();
        if ($registry === null || !method_exists($registry, 'getConnectionNames')) {
            return [];
        }
        $names = array_map('strval', array_keys($registry->getConnectionNames()));
        $default = method_exists($registry, 'getDefaultConnectionName') ? (string) $registry->getDefaultConnectionName() : '';
        if ($default !== '' && in_array($default, $names, true)) {
            $names = array_merge([$default], array_values(array_diff($names, [$default])));
        }

        return $names;
    }

    /** @return object|null The `doctrine` registry, when DoctrineBundle is installed. */
    private function doctrine()
    {
        if (!is_object($this->kernel)) {
            return null;
        }
        $container = $this->kernel->getContainer();

        return $container->has('doctrine') ? $container->get('doctrine') : null;
    }

    public function version(): ?string
    {
        $constant = 'Symfony\Component\HttpKernel\Kernel::VERSION';

        return defined($constant) ? (string) constant($constant) : null;
    }

    /**
     * The kernel's environment (APP_ENV: dev, test, prod, …).
     *
     * @return string|null
     */
    public function environment()
    {
        return is_object($this->kernel) && method_exists($this->kernel, 'getEnvironment') ? (string) $this->kernel->getEnvironment() : null;
    }

    /** Every visible `bin/console` command of the booted kernel, as `php bin/console <name>`. */
    public function commands(): array
    {
        $application = 'Symfony\Bundle\FrameworkBundle\Console\Application';
        if (!is_object($this->kernel) || !class_exists($application)) {
            return [];
        }
        $console = new $application($this->kernel);

        return $this->consoleCommands($console->all(), 'php bin/console');
    }

    /** Loads .env, .env.local, .env.<env>, ... (Symfony 5.1+ bootEnv; config/bootstrap.php on 4.x). */
    protected function loadEnvironment(string $projectPath): void
    {
        if (is_file($projectPath . '/config/bootstrap.php')) {
            require $projectPath . '/config/bootstrap.php';

            return;
        }
        $dotenv = 'Symfony\Component\Dotenv\Dotenv';
        if (!class_exists($dotenv) || (!is_file($projectPath . '/.env') && !is_file($projectPath . '/.env.dist'))) {
            return;
        }
        if (method_exists($dotenv, 'bootEnv')) {
            (new $dotenv())->bootEnv($projectPath . '/.env');
        } elseif (method_exists($dotenv, 'loadEnv')) {
            (new $dotenv())->loadEnv($projectPath . '/.env');
        }
    }

    /** The kernel class declared in src/Kernel.php (App\Kernel by default). */
    protected function kernelClass(string $projectPath): string
    {
        $source = @file_get_contents($projectPath . '/src/Kernel.php');
        if (is_string($source) && preg_match('/^\s*namespace\s+([A-Za-z0-9_\\\\]+)\s*;/m', $source, $match) && class_exists($match[1] . '\Kernel')) {
            return $match[1] . '\Kernel';
        }
        if (class_exists('App\Kernel')) {
            return 'App\Kernel';
        }

        throw new \RuntimeException('Runlet could not find the Symfony kernel (expected App\Kernel in src/Kernel.php). Add a project driver in .runlet/ to boot this application.');
    }
}
}

/*
 * Runlet benchmarks: Runlet\bench() and the benchmark records behind Runlet's benchmark card,
 * including Laravel's Benchmark::dd() (issue #41). Declared by the runner after the run
 * inspector (Inspector.php). See docs/drivers.md, "Benchmarks".
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace Runlet {

/**
 * Measures callables and records the results in the run inspector's "Benchmarks" section,
 * which Runlet shows as a card: min, mean, median, p95, max, operations per second, the
 * iterations that ran, memory, and the distribution of call times.
 *
 * Every measurement is bounded: at most MAX_ITERATIONS calls per callable, and it stops
 * early when a callable used up its time budget (the card then says how many calls ran).
 * Before measuring, each callable is called once cold and warmed up with a few more calls.
 */
final class Benchmark
{
    public const SECTION = 'Benchmarks';
    public const MAX_ITERATIONS = 100000;
    public const MAX_CALLABLES = 20;
    public const DEFAULT_ITERATIONS = 1000;
    /** Seconds each callable may use, when the call does not say. */
    public const DEFAULT_SECONDS = 1.0;
    public const MAX_SECONDS = 60.0;
    private const HISTOGRAM_BINS = 24;
    private const SERIES_POINTS = 48;
    private const MAX_WARMUP = 10;

    /** @var int The process's real peak memory before a benchmark reset it (PHP 8.2+). */
    private static $peakBeforeReset = 0;

    /**
     * Runs Runlet\bench(): see that function.
     *
     * @param mixed $subject a callable, or an array of callables keyed by label
     * @return array<int|string, mixed>
     */
    public static function bench($subject, int $iterations, ?string $label, ?float $seconds): array
    {
        $single = !is_array($subject) || is_callable($subject);
        $callables = $single ? [$label ?? 'bench()' => $subject] : $subject;
        if ($callables === []) {
            throw new \InvalidArgumentException('Runlet\bench() needs a callable, or an array of callables to compare.');
        }
        if (count($callables) > self::MAX_CALLABLES) {
            throw new \InvalidArgumentException('Runlet\bench() compares up to ' . self::MAX_CALLABLES . ' callables at a time; it got ' . count($callables) . '.');
        }
        foreach ($callables as $key => $callable) {
            if (!is_callable($callable)) {
                throw new \InvalidArgumentException('Runlet\bench(): "' . $key . '" is not callable.');
            }
        }

        $notes = [];
        $requested = $iterations;
        if ($iterations < 1) {
            $iterations = 1;
            $notes[] = 'Iterations below 1 count as 1.';
        } elseif ($iterations > self::MAX_ITERATIONS) {
            $iterations = self::MAX_ITERATIONS;
            $notes[] = 'Iterations are capped at ' . number_format(self::MAX_ITERATIONS) . ' per callable.';
        }
        $budget = $seconds ?? self::DEFAULT_SECONDS;
        if (!is_finite($budget) || $budget <= 0) {
            $budget = self::DEFAULT_SECONDS;
        } elseif ($budget > self::MAX_SECONDS) {
            $budget = self::MAX_SECONDS;
            $notes[] = 'The time budget is capped at ' . (int) self::MAX_SECONDS . ' s per callable.';
        }
        $budgetNs = (int) ($budget * 1e9);
        $overhead = self::timerOverhead();

        $results = [];
        $returned = [];
        foreach ($callables as $key => $callable) {
            $name = $single ? ($label ?? 'bench()') : (is_int($key) ? '#' . ($key + 1) : (string) $key);
            $result = self::measure($callable, $name, $iterations, $requested, $budgetNs);
            $results[] = $result;
            $returned[$key] = self::summary($result);
        }

        $title = $label ?? ($single ? 'bench()' : 'bench(): ' . count($callables) . ' callables');
        self::record($title, [
            'source' => 'runlet',
            'method' => 'bench',
            'results' => $results,
            'budgetMs' => round($budget * 1000, 3),
            'overheadNs' => $overhead,
            'php' => PHP_VERSION,
            'notes' => $notes,
        ]);

        return $single ? reset($returned) : $returned;
    }

    /**
     * Laravel's Benchmark::dd() dumps the average time of each callable ("1.234ms") and
     * exits. Runlet's dump handler calls this for that dump, so it also shows as a benchmark
     * card. Only the averages are known: Laravel measures nothing else.
     *
     * @param mixed $value what Benchmark::dd() dumped
     * @param array<int, mixed> $arguments Benchmark::dd()'s arguments (callables, iterations)
     */
    public static function recordLaravelDump($value, array $arguments): void
    {
        $iterations = isset($arguments[1]) && is_int($arguments[1]) ? max(1, $arguments[1]) : 1;
        $averages = is_array($value) ? $value : ['Benchmark::dd()' => $value];
        $results = [];
        foreach ($averages as $key => $average) {
            if (count($results) >= self::MAX_CALLABLES) {
                break;
            }
            $ms = self::laravelMilliseconds($average);
            if ($ms === null) {
                return;
            }
            $results[] = [
                'label' => is_int($key) ? '#' . ($key + 1) : (string) $key,
                'iterations' => $iterations,
                'meanNs' => round($ms * 1e6, 1),
                'averageOnly' => true,
            ];
        }
        if ($results === []) {
            return;
        }
        self::record('Benchmark::dd()', [
            'source' => 'laravel',
            'method' => 'Benchmark::dd',
            'results' => $results,
            'php' => PHP_VERSION,
            'notes' => ["Laravel's Benchmark reports the mean only (to the microsecond). Runlet\\bench() takes the same arguments and adds min, median, p95, memory, and the distribution."],
        ]);
    }

    /**
     * The real peak memory of this process, counting what a benchmark's
     * memory_reset_peak_usage() call hid.
     *
     * @internal
     */
    public static function realPeakMemory(): int
    {
        return max(self::$peakBeforeReset, memory_get_peak_usage(true));
    }

    /**
     * The p-quantile (0…1) of sorted values, interpolated linearly between the closest ranks.
     *
     * @internal
     * @param array<int, int|float> $sorted ascending
     */
    public static function percentile(array $sorted, float $p)
    {
        $count = count($sorted);
        if ($count === 0) {
            return 0;
        }
        $position = max(0.0, min(1.0, $p)) * ($count - 1);
        $lower = (int) floor($position);
        $upper = (int) ceil($position);
        if ($lower === $upper) {
            return $sorted[$lower];
        }

        return $sorted[$lower] + ($sorted[$upper] - $sorted[$lower]) * ($position - $lower);
    }

    /**
     * Statistics over call times in nanoseconds, in the order they ran: min, max, mean,
     * median, p95, p99, standard deviation, a histogram (see histogram()), and up to
     * SERIES_POINTS chunk means in run order.
     *
     * @internal
     * @param array<int, int> $samples
     * @return array<string, mixed>
     */
    public static function statistics(array $samples): array
    {
        $count = count($samples);
        if ($count === 0) {
            return ['minNs' => 0, 'maxNs' => 0, 'meanNs' => 0.0, 'medianNs' => 0.0, 'p95Ns' => 0.0, 'p99Ns' => 0.0, 'stddevNs' => 0.0, 'totalNs' => 0];
        }
        $sorted = $samples;
        sort($sorted);
        $total = array_sum($samples);
        $mean = $total / $count;
        $squares = 0.0;
        foreach ($samples as $sample) {
            $squares += ($sample - $mean) ** 2;
        }
        $p99 = self::percentile($sorted, 0.99);
        $stats = [
            'totalNs' => $total,
            'minNs' => $sorted[0],
            'maxNs' => $sorted[$count - 1],
            'meanNs' => round($mean, 1),
            'medianNs' => round((float) self::percentile($sorted, 0.5), 1),
            'p95Ns' => round((float) self::percentile($sorted, 0.95), 1),
            'p99Ns' => round((float) $p99, 1),
            'stddevNs' => round($count > 1 ? sqrt($squares / ($count - 1)) : 0.0, 1),
        ];

        // The histogram ends at p99, or earlier at the outlier fence (p75 + 3 × IQR), so a few
        // scheduler hiccups don't squeeze every typical call into the first bins.
        $fence = self::percentile($sorted, 0.75) + 3 * (self::percentile($sorted, 0.75) - self::percentile($sorted, 0.25));
        $stats['histogram'] = self::histogram($sorted, $fence > $sorted[0] ? min((float) $p99, (float) $fence) : (float) $p99);

        $points = min(self::SERIES_POINTS, $count);
        $series = [];
        for ($point = 0; $point < $points; $point++) {
            $from = intdiv($point * $count, $points);
            $to = intdiv(($point + 1) * $count, $points);
            $series[] = round(array_sum(array_slice($samples, $from, $to - $from)) / max(1, $to - $from), 1);
        }
        $stats['series'] = $series;

        return $stats;
    }

    /**
     * Call times from the fastest to $end (p99 or the outlier fence) in up to HISTOGRAM_BINS
     * equal bins; slower calls are counted in `above`. Timers tick in steps (41.67 ns on Apple silicon, which hrtime()
     * rounds to 41 or 42 ns), so when the range spans fewer ticks than bins, each bin is one
     * tick and none stays empty by rounding.
     *
     * @param array<int, int> $sorted ascending
     * @return array<string, mixed>
     */
    private static function histogram(array $sorted, float $end): array
    {
        $count = count($sorted);
        $low = $sorted[0];
        $high = $end > $low ? $end : (float) $sorted[$count - 1];
        // The timer's step: the smallest gap between distinct times above rounding noise (2 ns),
        // averaged over the gaps close to it.
        $gaps = [];
        for ($i = 1; $i < $count; $i++) {
            $difference = $sorted[$i] - $sorted[$i - 1];
            if ($difference > 2) {
                $gaps[] = $difference;
            }
        }
        $step = 0.0;
        if ($gaps !== []) {
            $smallest = min($gaps);
            $near = array_filter($gaps, static function ($gap) use ($smallest): bool {
                return $gap <= $smallest * 1.5;
            });
            $step = array_sum($near) / count($near);
        }
        $ticks = $step > 0 ? (int) round(($high - $low) / $step) + 1 : 1;
        $perTick = $step > 0 && $ticks <= self::HISTOGRAM_BINS;
        $binCount = $perTick ? $ticks : self::HISTOGRAM_BINS;
        $width = $perTick ? $step : ($high - $low) / $binCount;
        $bins = array_fill(0, $binCount, 0);
        $above = 0;
        foreach ($sorted as $sample) {
            if ($sample > $high + ($perTick ? $step / 2 : 0)) {
                $above++;
                continue;
            }
            if ($width <= 0) {
                $bin = 0;
            } else {
                $bin = $perTick ? (int) round(($sample - $low) / $width) : (int) floor(($sample - $low) / $width);
            }
            $bins[max(0, min($binCount - 1, $bin))]++;
        }

        return ['lowNs' => $low, 'highNs' => round($high, 1), 'binNs' => round($width, 1), 'counts' => $bins, 'above' => $above];
    }

    /**
     * One callable: a cold call, a warm-up, then up to $iterations timed calls within the
     * budget, with memory measured around the timed calls.
     *
     * @return array<string, mixed>
     */
    private static function measure(callable $callable, string $label, int $iterations, int $requested, int $budgetNs): array
    {
        gc_collect_cycles();
        $before = memory_get_usage();
        $started = hrtime(true);
        $callable();
        $firstNs = hrtime(true) - $started;
        $firstBytes = memory_get_usage() - $before;

        // Warm-up: up to 1% of the iterations (at most 10) within a tenth of the budget.
        $warmup = 1;
        $warmTarget = min(self::MAX_WARMUP, intdiv($iterations, 100));
        $warmStarted = hrtime(true);
        while ($warmup <= $warmTarget && $firstNs < $budgetNs / 10 && hrtime(true) - $warmStarted < $budgetNs / 10) {
            $callable();
            $warmup++;
        }

        // The samples are preallocated, so they don't count as the callable's memory.
        $samples = new \SplFixedArray($iterations);
        gc_collect_cycles();
        $resetsPeak = function_exists('memory_reset_peak_usage');
        if ($resetsPeak) {
            self::$peakBeforeReset = max(self::$peakBeforeReset, memory_get_peak_usage(true));
            memory_reset_peak_usage();
        }
        $peakBefore = memory_get_peak_usage();
        $baseline = memory_get_usage();

        $count = 0;
        $stoppedBy = 'iterations';
        $start = hrtime(true);
        while ($count < $iterations) {
            $callStarted = hrtime(true);
            $callable();
            $ended = hrtime(true);
            $samples[$count++] = $ended - $callStarted;
            if ($ended - $start >= $budgetNs && $count < $iterations) {
                $stoppedBy = 'time';
                break;
            }
        }
        $retained = memory_get_usage() - $baseline;
        $peak = memory_get_peak_usage();

        $samples->setSize($count);
        $result = ['label' => $label, 'iterations' => $count, 'requestedIterations' => $requested, 'warmup' => $warmup, 'stoppedBy' => $stoppedBy, 'firstNs' => $firstNs]
            + self::statistics($samples->toArray());
        $mean = (float) $result['meanNs'];
        $result['opsPerSec'] = $mean > 0 ? round(1e9 / $mean, 2) : null;
        $result['memory'] = [
            // The highest memory use while the timed calls ran, above what was in use before.
            'peakBytes' => $resetsPeak || $peak > $peakBefore ? max(0, $peak - $baseline) : null,
            // Memory still held after the calls, per call (0 when the callable keeps nothing).
            'perCallBytes' => round($retained / max(1, $count), 1),
            'firstCallBytes' => $firstBytes,
        ];

        return $result;
    }

    /**
     * What a bench() call returns per callable: times in milliseconds, like Laravel's Benchmark.
     *
     * @param array<string, mixed> $result
     * @return array<string, mixed>
     */
    private static function summary(array $result): array
    {
        $ms = static function ($ns): float {
            return round((float) $ns / 1e6, 6);
        };

        return [
            'label' => $result['label'],
            'iterations' => $result['iterations'],
            'mean_ms' => $ms($result['meanNs']),
            'median_ms' => $ms($result['medianNs']),
            'min_ms' => $ms($result['minNs']),
            'max_ms' => $ms($result['maxNs']),
            'p95_ms' => $ms($result['p95Ns']),
            'ops_per_sec' => $result['opsPerSec'],
            'memory_peak_bytes' => $result['memory']['peakBytes'],
            'memory_per_call_bytes' => $result['memory']['perCallBytes'],
        ];
    }

    /** The median time of an empty call: the floor every measured call includes. */
    private static function timerOverhead(): float
    {
        $noop = static function (): void {
        };
        $samples = [];
        for ($i = 0; $i < 201; $i++) {
            $started = hrtime(true);
            $noop();
            $samples[] = hrtime(true) - $started;
        }
        sort($samples);

        return (float) $samples[100];
    }

    /** "1,234.567ms" (number_format()) as milliseconds, or null when it is something else. */
    private static function laravelMilliseconds($average): ?float
    {
        if (is_int($average) || is_float($average)) {
            return (float) $average;
        }
        if (!is_string($average) || !preg_match('/^\s*(-?[0-9][0-9,]*(?:\.[0-9]+)?)\s*ms\s*$/', $average, $match)) {
            return null;
        }

        return (float) str_replace(',', '', $match[1]);
    }

    /** @param array<string, mixed> $data */
    private static function record(string $title, array $data): void
    {
        $inspector = Inspector::current();
        if ($inspector !== null) {
            $inspector->measurement(self::SECTION, 'benchmark', $title, $data);
        }
    }
}

/**
 * Measures $callables and shows the result as a benchmark card in Runlet's output (and in the
 * Benchmarks section): min, mean, median, p95, max, operations per second, memory, and the
 * distribution of call times.
 *
 *     Runlet\bench(fn () => collect(range(1, 1000))->sum());
 *     Runlet\bench(['map' => fn () => array_map(...), 'loop' => fn () => ...], 500);
 *
 * Pass an array of callables, keyed by label, to compare them side by side. Each callable is
 * called once cold and warmed up, then up to $iterations times (at most 100,000) until it has
 * used $seconds (1 s by default, at most 60 s); the card says when the time budget ended it
 * early. Takes the same arguments as Laravel's Benchmark::measure().
 *
 * @param callable|array<int|string, callable> $callables
 * @param int $iterations timed calls per callable (1–100,000)
 * @param string|null $label the card's title
 * @param float|null $seconds time budget per callable, in seconds
 * @return array<int|string, mixed> times in milliseconds (`mean_ms`, `median_ms`, `min_ms`,
 *         `max_ms`, `p95_ms`), `ops_per_sec`, `iterations`, and memory; keyed like
 *         $callables when it is an array of callables
 */
function bench($callables, int $iterations = Benchmark::DEFAULT_ITERATIONS, ?string $label = null, ?float $seconds = null): array
{
    return Benchmark::bench($callables, $iterations, $label, $seconds);
}
}

/*
 * Runlet Profile Run: samples the snippet with the Excimer extension and reports the samples
 * as collapsed stacks for Runlet's flame graph (issue #41). Declared by the runner before
 * Runner.php. See docs/architecture.md, "Profile Run".
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

/**
 * One Profile Run's sampling profiler. Excimer (https://www.mediawiki.org/wiki/Excimer)
 * interrupts PHP every period and records the call stack. Only the snippet is profiled, not
 * the application's bootstrap, and the result is bounded: at most MAX_STACKS distinct stacks
 * (the rest are folded into "[other stacks]") of at most MAX_DEPTH frames each.
 *
 * SPX is detected but not used: it profiles only processes started with SPX_ENABLED=1 and
 * writes its reports to files in spx.data_dir (or stderr), with no API that hands the data to
 * the running script.
 */
final class Profiler
{
    public const SECTION = 'Profile';
    public const MAX_STACKS = 4000;
    public const MAX_DEPTH = 200;
    /** Distinct stacks kept while sampling, before the final cut to MAX_STACKS. */
    private const MAX_COLLECTED = 30000;
    private const MAX_COLLAPSED_BYTES = 2097152;
    private const FLUSH_ENTRIES = 2000;
    public const OTHER = '[other stacks]';
    public const DEEPER = '[deeper frames]';

    /** @var \ExcimerProfiler */
    private $excimer;
    /** @var string wall or cpu */
    private $eventType;
    /** @var float */
    private $periodMs;
    /** @var int */
    private $startedAt;
    /** @var int|null */
    private $stoppedAt;
    /** @var string */
    private $workingDirectory;
    /** @var array<string, int> collapsed stack => samples */
    private $stacks = [];
    /** @var array<string, array{file: string|null, inSnippet: bool, lines: array<int, int>}> */
    private $frames = [];
    /** @var int */
    private $samples = 0;
    /** @var int Samples outside the snippet (the runner's own code around it). */
    private $outside = 0;
    /** @var int Samples taken while this profiler aggregated its log. */
    private $overhead = 0;
    /** @var int */
    private $deep = 0;
    /** @var bool */
    private $collapsedOverflow = false;

    /**
     * The profiler extensions this PHP loads, with their versions.
     *
     * @return array<string, string>
     */
    public static function loaded(): array
    {
        $loaded = [];
        foreach (['excimer', 'spx'] as $extension) {
            if (extension_loaded($extension)) {
                $version = phpversion($extension);
                $loaded[$extension] = is_string($version) ? $version : '';
            }
        }

        return $loaded;
    }

    /** Why this PHP can't profile a run, or null when it can. */
    public static function unavailableReason(): ?string
    {
        if (class_exists('ExcimerProfiler', false)) {
            return null;
        }
        $php = 'PHP ' . PHP_VERSION . ' (' . PHP_BINARY . ')';
        if (extension_loaded('spx')) {
            return 'Profile Run uses the Excimer extension. ' . $php . ' loads SPX, which Runlet can\'t read profiles from (SPX writes them to files in spx.data_dir and only profiles processes started with SPX_ENABLED=1). Install Excimer to profile here. Nothing ran.';
        }

        return 'Profile Run needs the Excimer extension, and ' . $php . ' doesn\'t load it. Install it (pecl install excimer, or the php-excimer package) and run again. Nothing ran.';
    }

    /** @param array<string, mixed> $options `periodMs` (default 1) and `eventType` (`wall` or `cpu`) */
    public static function start(array $options, string $workingDirectory): self
    {
        $profiler = new self();
        $profiler->workingDirectory = rtrim($workingDirectory, '/');
        $period = isset($options['periodMs']) && is_numeric($options['periodMs']) ? (float) $options['periodMs'] : 1.0;
        $profiler->periodMs = max(0.1, min(1000.0, $period));
        $cpu = ($options['eventType'] ?? 'wall') === 'cpu' && defined('EXCIMER_CPU') && PHP_OS_FAMILY !== 'Darwin';
        $profiler->eventType = $cpu ? 'cpu' : 'wall';

        $excimer = new \ExcimerProfiler();
        $excimer->setPeriod($profiler->periodMs / 1000);
        $excimer->setEventType($cpu ? EXCIMER_CPU : EXCIMER_REAL);
        $excimer->setFlushCallback(static function ($log) use ($profiler): void {
            $profiler->collect($log);
        }, self::FLUSH_ENTRIES);
        $profiler->excimer = $excimer;
        $profiler->startedAt = hrtime(true);
        $excimer->start();

        return $profiler;
    }

    /** Stops sampling; safe to call more than once. */
    public function stop(): void
    {
        if ($this->stoppedAt !== null) {
            return;
        }
        $this->excimer->stop();
        $this->stoppedAt = hrtime(true);
        $this->collect($this->excimer->getLog());
    }

    /**
     * The `profile` record: collapsed stacks (root first, "frame;frame;frame count" per
     * line), what each frame name stands for, and what the bounds left out.
     *
     * @return array<string, mixed>
     */
    public function record(): array
    {
        $this->stop();
        arsort($this->stacks);
        $lines = [];
        $bytes = 0;
        $kept = 0;
        $folded = 0;
        $foldedStacks = 0;
        $used = [];
        foreach ($this->stacks as $stack => $count) {
            $stack = (string) $stack;
            if ($stack === self::OTHER || $kept >= self::MAX_STACKS || $bytes + strlen($stack) + 12 > self::MAX_COLLAPSED_BYTES) {
                $folded += $count;
                $foldedStacks += $stack === self::OTHER ? 0 : 1;
                continue;
            }
            $kept++;
            $lines[] = $stack . ' ' . $count;
            $bytes += strlen($stack) + 12;
            foreach (explode(';', $stack) as $name) {
                $used[$name] = true;
            }
        }
        if ($folded > 0) {
            $lines[] = self::OTHER . ' ' . $folded;
        }

        $frames = [];
        foreach ($used as $name => $true) {
            $frame = $this->frames[$name] ?? null;
            if ($frame === null) {
                continue;
            }
            arsort($frame['lines']);
            $entry = ['line' => (int) key($frame['lines'])];
            if ($frame['inSnippet']) {
                $entry['inSnippet'] = true;
            } elseif ($frame['file'] !== null) {
                $entry['file'] = $frame['file'];
            }
            $frames[(string) $name] = $entry;
        }

        $truncated = [];
        if ($foldedStacks > 0 || $this->collapsedOverflow) {
            $truncated['stacks'] = $foldedStacks;
            $truncated['foldedSamples'] = $folded;
        }
        if ($this->deep > 0) {
            $truncated['deepSamples'] = $this->deep;
        }

        return [
            'engine' => 'excimer',
            'version' => (string) phpversion('excimer'),
            'eventType' => $this->eventType,
            'periodMs' => $this->periodMs,
            'samples' => $this->samples,
            'durationMs' => round((($this->stoppedAt ?? hrtime(true)) - $this->startedAt) / 1e6, 3),
            'outsideSamples' => $this->outside + $this->overhead,
            'maxStacks' => self::MAX_STACKS,
            'maxDepth' => self::MAX_DEPTH,
            'collapsed' => implode("\n", $lines),
            'frames' => (object) $frames,
            'truncated' => (object) $truncated,
            'php' => PHP_VERSION,
        ];
    }

    /** Adds a log's samples to the collapsed stacks (also Excimer's flush callback). */
    private function collect(\ExcimerLog $log): void
    {
        foreach ($log as $entry) {
            $count = (int) $entry->getEventCount();
            if ($count <= 0) {
                continue;
            }
            $trace = $entry->getTrace();
            // Innermost frame first; the snippet is what Runner::evaluate() evaluates.
            $evaluate = null;
            foreach ($trace as $index => $frame) {
                $class = $frame['class'] ?? '';
                if ($class === __CLASS__) {
                    $this->overhead += $count;
                    continue 2;
                }
                if ($class === Runner::class && ($frame['function'] ?? '') === 'evaluate') {
                    $evaluate = $index;
                    break;
                }
            }
            if ($evaluate === null || $evaluate === 0) {
                $this->outside += $count;
                continue;
            }
            $this->samples += $count;
            $names = [];
            for ($index = $evaluate - 1; $index >= 0; $index--) {
                if (count($names) >= self::MAX_DEPTH - 1 && $index > 0) {
                    $names[] = self::DEEPER;
                    $this->deep += $count;
                    break;
                }
                $names[] = $this->frameName($trace[$index], $index === $evaluate - 1, $count);
            }
            $stack = implode(';', $names);
            if (!isset($this->stacks[$stack]) && count($this->stacks) >= self::MAX_COLLECTED) {
                $stack = self::OTHER;
                $this->collapsedOverflow = true;
            }
            $this->stacks[$stack] = ($this->stacks[$stack] ?? 0) + $count;
        }
    }

    /**
     * A frame's name in the collapsed stacks: `snippet:<line>` for the snippet's own lines,
     * `Class::method`, `function`, `{closure:<file>:<line>}`, or an included file's path.
     *
     * @param array<string, mixed> $frame
     */
    private function frameName(array $frame, bool $snippetRoot, int $count): string
    {
        $file = isset($frame['file']) && is_string($frame['file']) ? $frame['file'] : '';
        $line = isset($frame['line']) && is_int($frame['line']) ? $frame['line'] : 0;
        $inSnippet = $file !== '' && Runner::isSnippetFile($file);
        $function = isset($frame['function']) && is_string($frame['function']) ? $frame['function'] : '';
        $class = isset($frame['class']) && is_string($frame['class']) ? \Runlet\Inspector::className($frame['class']) : '';
        if ($snippetRoot && $function === '') {
            $name = 'snippet:' . $line;
        } elseif ($function !== '' && strpos($function, '{closure') === 0) {
            $where = $inSnippet ? 'snippet' : basename($file);
            $name = '{closure:' . $where . ':' . (int) ($frame['closure_line'] ?? $line) . '}';
        } elseif ($function !== '') {
            $name = ($class !== '' ? $class . '::' : '') . $function;
        } elseif (substr($file, -13) === "eval()'d code") {
            $name = $inSnippet ? 'snippet:' . $line : "eval()'d code";
        } else {
            $name = $this->relative($file);
        }
        $name = str_replace([';', "\n", "\r"], [',', ' ', ' '], $name);
        if (!isset($this->frames[$name])) {
            $this->frames[$name] = ['file' => $inSnippet || $file === '' ? null : $file, 'inSnippet' => $inSnippet, 'lines' => []];
        }
        $lines = &$this->frames[$name]['lines'];
        if (isset($lines[$line]) || count($lines) < 64) {
            $lines[$line] = ($lines[$line] ?? 0) + $count;
        }

        return $name;
    }

    private function relative(string $file): string
    {
        if ($file === '') {
            return '{main}';
        }
        $prefix = $this->workingDirectory . '/';

        return $this->workingDirectory !== '' && strpos($file, $prefix) === 0 ? substr($file, strlen($prefix)) : $file;
    }
}
}

/*
 * Runlet PHP runner.
 *
 * Executed once per run by a fresh PHP CLI process (local or `docker exec`). The
 * whole bundle (this file plus a namespace-scoped copy of nikic/php-parser) is
 * streamed to `php` on stdin, followed by a call to Runner::main() carrying the
 * base64-encoded request. Nothing is written into the user's project or container.
 *
 * Machine events are written to stdout as nonce-framed records:
 *
 *     "\x1e" . "RL1:" . <nonce> . ":" . <byte length> . ":" . <json> . "\n"
 *
 * Everything else on stdout/stderr is the application's own raw output. The
 * nonce is random per run, so snippet output cannot forge or corrupt a frame.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

final class NoResult
{
    /** @var NoResult|null */
    private static $instance;

    public static function instance(): self
    {
        if (self::$instance === null) {
            self::$instance = new self();
        }

        return self::$instance;
    }
}

final class Channel
{
    /** @var resource */
    private static $stream;
    /** @var string */
    private static $nonce = '';
    /** @var string[] A saved connection's password and its encoded forms (#138), longest first. */
    private static $secrets = [];
    /** @var bool Whether results are scrubbed too (passwords of 4+ characters; see addSecret()). */
    private static $scrubResults = false;

    public static function open(string $nonce): void
    {
        self::$nonce = $nonce;
        $stream = fopen('php://stdout', 'wb');
        if ($stream === false) {
            throw new \RuntimeException('Runlet runner could not open stdout');
        }
        self::$stream = $stream;
    }

    /**
     * A saved connection's password (#138): from now on every event replaces it, and its
     * URL-encoded and slashed forms, with •••. Errors, notices, and log lines always are; result
     * rows and values only for passwords of 4 or more characters, so a very short password
     * doesn't garble every result. `$inResults` false (WordPress's DB_PASSWORD, #208) leaves
     * results alone: they are the application's own data, as in its PHP tabs.
     */
    public static function addSecret(string $secret, bool $inResults = true): void
    {
        if ($secret === '') {
            return;
        }
        foreach ([$secret, urlencode($secret), rawurlencode($secret), addslashes($secret)] as $form) {
            if (!in_array($form, self::$secrets, true)) {
                self::$secrets[] = $form;
            }
        }
        usort(self::$secrets, static function (string $a, string $b): int {
            return strlen($b) <=> strlen($a);
        });
        self::$scrubResults = self::$scrubResults || ($inResults && strlen($secret) >= 4);
    }

    /** The text with any registered secret replaced by •••. */
    public static function scrub(string $text): string
    {
        return self::$secrets === [] ? $text : str_replace(self::$secrets, '•••', $text);
    }

    /**
     * @param mixed $value
     * @return mixed
     */
    private static function scrubValue($value)
    {
        if (is_string($value)) {
            return self::scrub($value);
        }
        if (is_array($value)) {
            foreach ($value as $key => $item) {
                if (is_string($item) || is_array($item)) {
                    $value[$key] = self::scrubValue($item);
                }
            }
        }

        return $value;
    }

    /** @param array<string, mixed> $payload */
    public static function emit(string $type, array $payload): void
    {
        if (self::$secrets !== [] && (self::$scrubResults || in_array($type, ['error', 'notice', 'log'], true))) {
            $payload = self::scrubValue($payload);
        }
        $json = json_encode(
            ['type' => $type, 'payload' => $payload],
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION | JSON_PARTIAL_OUTPUT_ON_ERROR
        );
        if ($json === false) {
            $json = json_encode(['type' => 'error', 'payload' => [
                'stage' => 'transport',
                'message' => 'Runlet could not encode a ' . $type . ' event: ' . json_last_error_msg(),
            ]]);
        }
        $frame = "\x1eRL1:" . self::$nonce . ':' . strlen((string) $json) . ':' . $json . "\n";
        $length = strlen($frame);
        $written = 0;
        while ($written < $length) {
            $result = @fwrite(self::$stream, substr($frame, $written));
            if ($result === false || $result === 0) {
                return;
            }
            $written += $result;
        }
        @fflush(self::$stream);
    }
}

/**
 * Converts arbitrary PHP values into bounded ValueNode trees without invoking
 * user code: no getters, __toString, __debugInfo, __get, or JSON serialization.
 */
final class ValueNormalizer
{
    /** @var int */
    private $maxDepth;
    /** @var int */
    private $maxChildren;
    /** @var int */
    private $maxStringBytes;
    /** @var int */
    private $maxNodes;
    /** @var int */
    private $maxBytes;

    /** @var int */
    private $nextId = 1;
    /** @var int */
    private $nodes = 0;
    /** @var int */
    private $bytes = 0;
    /** @var array<int, true> */
    private $seenObjects = [];
    /** @var array<string, true> */
    private $activeReferences = [];
    /** @var bool */
    private $budgetExceeded = false;

    /** @param array<string, int> $limits */
    public function __construct(array $limits)
    {
        $this->maxDepth = (int) ($limits['maxDepth'] ?? 8);
        $this->maxChildren = (int) ($limits['maxChildren'] ?? 200);
        $this->maxStringBytes = (int) ($limits['maxStringBytes'] ?? 65536);
        $this->maxNodes = (int) ($limits['maxNodes'] ?? 20000);
        $this->maxBytes = (int) ($limits['maxValueBytes'] ?? 2097152);
    }

    /**
     * @param mixed $value
     * @return array<string, mixed>
     */
    public function normalize($value): array
    {
        $this->nextId = 1;
        $this->nodes = 0;
        $this->bytes = 0;
        $this->seenObjects = [];
        $this->activeReferences = [];
        $this->budgetExceeded = false;

        $node = $this->node($value, 0);
        if ($this->budgetExceeded) {
            $node['budgetExceeded'] = true;
        }

        return $node;
    }

    /**
     * @param mixed $value
     * @return array<string, mixed>
     */
    private function node($value, int $depth): array
    {
        $this->nodes++;
        $id = $this->nextId++;

        if ($value === null) {
            return ['id' => $id, 'type' => 'null'];
        }
        if (is_bool($value)) {
            return ['id' => $id, 'type' => 'bool', 'scalar' => $value ? 'true' : 'false'];
        }
        if (is_int($value)) {
            return ['id' => $id, 'type' => 'int', 'scalar' => (string) $value];
        }
        if (is_float($value)) {
            return ['id' => $id, 'type' => 'float', 'scalar' => self::floatString($value)];
        }
        if (is_string($value)) {
            return $this->stringNode($id, $value);
        }
        if (is_array($value)) {
            return $this->arrayNode($id, $value, $depth);
        }
        if (is_object($value)) {
            return $this->objectNode($id, $value, $depth);
        }
        if (is_resource($value) || gettype($value) === 'resource (closed)') {
            return [
                'id' => $id,
                'type' => 'resource',
                'className' => is_resource($value) ? get_resource_type($value) : 'closed',
                'scalar' => (string) (int) $value,
            ];
        }

        return ['id' => $id, 'type' => 'unknown', 'scalar' => gettype($value)];
    }

    public static function floatString(float $value): string
    {
        if (is_nan($value)) {
            return 'NAN';
        }
        if (is_infinite($value)) {
            return $value > 0 ? 'INF' : '-INF';
        }
        $string = var_export($value, true);

        return $string;
    }

    /** @return array<string, mixed> */
    private function stringNode(int $id, string $value): array
    {
        $length = strlen($value);
        $truncatedBy = 0;
        $limit = min($this->maxStringBytes, max(0, $this->maxBytes - $this->bytes));
        if ($length > $limit) {
            $truncatedBy = $length - $limit;
            $value = substr($value, 0, $limit);
            if ($limit < $this->maxStringBytes) {
                $this->budgetExceeded = true;
            }
        }
        $this->bytes += strlen($value);

        $node = ['id' => $id, 'type' => 'string', 'length' => $length];
        if (self::isValidUtf8($value)) {
            $node['scalar'] = $value;
        } else {
            // Keep a valid UTF-8 prefix if the cut split a multibyte sequence.
            if ($truncatedBy > 0 && self::isValidUtf8(self::trimPartialUtf8($value))) {
                $node['scalar'] = self::trimPartialUtf8($value);
            } else {
                $node['scalar'] = base64_encode($value);
                $node['encoding'] = 'base64';
            }
        }
        if ($truncatedBy > 0) {
            $node['truncation'] = ['reason' => 'length', 'omitted' => $truncatedBy];
        }

        return $node;
    }

    private static function isValidUtf8(string $value): bool
    {
        return preg_match('//u', $value) === 1;
    }

    private static function trimPartialUtf8(string $value): string
    {
        for ($i = 0; $i < 4 && $value !== ''; $i++) {
            if (self::isValidUtf8($value)) {
                return $value;
            }
            $value = substr($value, 0, -1);
        }

        return $value;
    }

    /**
     * @param array<mixed> $value
     * @return array<string, mixed>
     */
    private function arrayNode(int $id, array $value, int $depth): array
    {
        $count = count($value);
        $node = ['id' => $id, 'type' => 'array', 'count' => $count];
        if ($count === 0) {
            $node['entries'] = [];

            return $node;
        }
        if ($depth >= $this->maxDepth) {
            $node['truncation'] = ['reason' => 'depth', 'omitted' => $count];

            return $node;
        }

        $entries = [];
        $shown = 0;
        foreach ($value as $key => $_) {
            if ($shown >= $this->maxChildren || $this->overBudget()) {
                break;
            }
            $shown++;
            $entry = ['key' => is_int($key) ? (string) $key : $this->keyString((string) $key), 'keyType' => is_int($key) ? 'int' : 'string'];

            $refId = null;
            if (class_exists(\ReflectionReference::class)) {
                $reference = \ReflectionReference::fromArrayElement($value, $key);
                if ($reference !== null) {
                    $refId = $reference->getId();
                }
            }

            if ($refId !== null && isset($this->activeReferences[$refId])) {
                // A PHP reference that points back at an array already being walked.
                $this->nodes++;
                $entry['value'] = ['id' => $this->nextId++, 'type' => 'array', 'recursion' => true, 'referenceId' => substr(md5($refId), 0, 12)];
            } else {
                if ($refId !== null) {
                    $this->activeReferences[$refId] = true;
                }
                $entry['value'] = $this->node($value[$key], $depth + 1);
                if ($refId !== null) {
                    unset($this->activeReferences[$refId]);
                    $entry['isReference'] = true;
                }
            }
            $entries[] = $entry;
        }

        $node['entries'] = $entries;
        if ($shown < $count) {
            $node['truncation'] = ['reason' => $this->budgetExceeded ? 'budget' : 'children', 'omitted' => $count - $shown];
        }

        return $node;
    }

    private function keyString(string $key): string
    {
        $this->bytes += strlen($key);
        if (self::isValidUtf8($key)) {
            return $key;
        }

        return 'base64:' . base64_encode($key);
    }

    private function overBudget(): bool
    {
        if ($this->nodes >= $this->maxNodes || $this->bytes >= $this->maxBytes) {
            $this->budgetExceeded = true;

            return true;
        }

        return false;
    }

    /** @return array<string, mixed> */
    private function objectNode(int $id, object $value, int $depth): array
    {
        $class = get_class($value);
        $objectId = spl_object_id($value);
        // Anonymous classes are named "class@anonymous<NUL>/path:line$0": show the readable part.
        $node = ['id' => $id, 'type' => 'object', 'className' => \Runlet\Inspector::className($class), 'referenceId' => (string) $objectId];

        if (function_exists('enum_exists') && $value instanceof \UnitEnum) {
            $node['type'] = 'enum';
            $node['scalar'] = $value->name;
            if ($value instanceof \BackedEnum) {
                $backing = $value->value;
                $node['backingValue'] = is_int($backing) ? (string) $backing : $backing;
            }

            return $node;
        }

        if (isset($this->seenObjects[$objectId])) {
            $node['repeated'] = true;

            return $node;
        }
        $this->seenObjects[$objectId] = true;

        if ($value instanceof \Closure) {
            $node['type'] = 'closure';
            try {
                $reflection = new \ReflectionFunction($value);
                $file = $reflection->getFileName();
                $node['summary'] = ($file !== false ? $file : 'internal') . ':' . (int) $reflection->getStartLine();
            } catch (\Throwable $e) {
                // Leave the closure without a location.
            }

            return $node;
        }

        if ($value instanceof \DateTimeInterface) {
            $node['summary'] = $value->format('Y-m-d H:i:s.u P') . ' (' . $value->getTimezone()->getName() . ')';
        }

        if ($depth >= $this->maxDepth) {
            $node['truncation'] = ['reason' => 'depth', 'omitted' => -1];

            return $node;
        }

        $properties = function_exists('get_mangled_object_vars') ? get_mangled_object_vars($value) : (array) $value;
        if ($value instanceof \ArrayObject || $value instanceof \ArrayIterator) {
            $properties["\0" . get_class($value) . "\0storage"] = $value->getArrayCopy();
        }

        $count = count($properties);
        $node['count'] = $count;
        $entries = [];
        $shown = 0;
        foreach ($properties as $mangled => $propertyValue) {
            if ($shown >= $this->maxChildren || $this->overBudget()) {
                break;
            }
            $shown++;
            $mangled = (string) $mangled;
            $visibility = 'public';
            $declaringClass = null;
            $name = $mangled;
            if ($mangled !== '' && $mangled[0] === "\0") {
                $parts = explode("\0", $mangled, 3);
                $name = $parts[2] ?? $mangled;
                if (($parts[1] ?? '') === '*') {
                    $visibility = 'protected';
                } else {
                    $visibility = 'private';
                    $declaringClass = $parts[1] ?? null;
                }
            }
            $entry = ['key' => $this->keyString($name), 'keyType' => 'property', 'visibility' => $visibility];
            if ($declaringClass !== null && $declaringClass !== $class) {
                $entry['declaringClass'] = $declaringClass;
            }
            $entry['value'] = $this->node($propertyValue, $depth + 1);
            $entries[] = $entry;
        }
        $node['entries'] = $entries;
        if ($shown < $count) {
            $node['truncation'] = ['reason' => $this->budgetExceeded ? 'budget' : 'children', 'omitted' => $count - $shown];
        }

        return $node;
    }
}

final class SnippetCompiler
{
    /** Prefix added in front of tagless snippets. Same line, so line numbers stay intact. */
    public const TAG_PREFIX = '<?php ';

    /** Inserted on the opening tag's line when the run asks for strict types. */
    public const STRICT_TYPES = 'declare(strict_types=1);';

    /**
     * Returns [evalCode, prefixLength, hasImplicitResult, notice, magic].
     *
     * With $strictTypes, `declare(strict_types=1);` becomes the first statement unless the
     * snippet declares strict_types itself. Magic comments (`//?`, `/*?*\/`, …) become probe
     * calls inserted on their own lines; `magic` lists them (`probes`, `rejected`, and a
     * `notice` when they could not be added), or is null without magic comments. Line numbers
     * never change.
     *
     * @return array{0: string, 1: int, 2: bool, 3: string|null, 4: array{probes: array<int, array{line: int, kind: string, comment: string}>, rejected: array<int, array{line: int, comment: string, reason: string}>}|null}
     */
    public static function compile(string $code, bool $strictTypes = false, bool $magicComments = true): array
    {
        $prefix = '';
        if (!preg_match('/^\s*<\?php\b/', $code) && !preg_match('/^\s*<\?=/', $code)) {
            $prefix = self::TAG_PREFIX;
        }
        $source = $prefix . $code;
        $applyStrictTypes = $strictTypes && !self::declaresStrictTypes($source);

        if (!function_exists('token_get_all') || !class_exists(\RunletVendor\PhpParser\ParserFactory::class)) {
            $source .= "\n;return \\RunletRunner\\NoResult::instance();";

            return [self::evalReady($applyStrictTypes ? self::withStrictTypes($source) : $source), strlen($prefix), false, 'The tokenizer extension is unavailable, so the final expression value is not captured.'];
        }

        $parser = (new \RunletVendor\PhpParser\ParserFactory())->createForHostVersion();
        $statements = null;
        $firstError = null;
        try {
            $statements = $parser->parse($source);
        } catch (\RunletVendor\PhpParser\Error $error) {
            $firstError = $error;
            // An omitted final semicolon is accepted when the snippet is otherwise valid.
            try {
                $withSemicolon = $source . "\n;";
                $statements = $parser->parse($withSemicolon);
                $source = $withSemicolon;
            } catch (\RunletVendor\PhpParser\Error $ignored) {
                throw new SnippetParseError($firstError->getRawMessage(), $firstError->getStartLine(), self::column($source, $firstError), strlen($prefix));
            }
        }

        if ($statements === null) {
            $statements = [];
        }

        $list = $statements;
        $container = null;
        while (count($list) > 0) {
            $last = self::lastStatement($list);
            if ($last instanceof \RunletVendor\PhpParser\Node\Stmt\Namespace_) {
                $container = $last;
                $list = $last->stmts ?? [];
                continue;
            }
            break;
        }

        // Trailing comments (`1 + 1; // note`) become Nop statements: skip them.
        $last = self::lastStatement($list);
        $hasResult = false;
        $returned = null;
        /** @var array<int, array<int, mixed>> $edits [offset, deleteLength, text, group, key1, key2]; see applyEdits() */
        $edits = [];
        if ($last instanceof \RunletVendor\PhpParser\Node\Stmt\Expression && !($last->expr instanceof \RunletVendor\PhpParser\Node\Expr\Exit_)) {
            // `<expr> …;` becomes `return <expr>;`.
            $start = $last->getStartFilePos();
            $end = $last->getEndFilePos();
            $exprStart = $last->expr->getStartFilePos();
            $exprEnd = $last->expr->getEndFilePos();
            if ($start < $exprStart) {
                $edits[] = [$start, $exprStart - $start, '', 1, 0, 0];
            }
            $edits[] = [$exprStart, 0, 'return ', 3, 0, 0];
            $edits[] = [$exprEnd + 1, $end - $exprEnd, ';', 1, 0, 0];
            $hasResult = true;
            $returned = $last;
        } elseif ($last instanceof \RunletVendor\PhpParser\Node\Stmt\Return_) {
            $hasResult = true;
        }

        $sentinel = "\nreturn \\RunletRunner\\NoResult::instance();";
        if ($container !== null && self::isBracedNamespace($source, $container)) {
            $edits[] = [$container->getEndFilePos(), 0, $sentinel . "\n", 1, 0, 0];
        } else {
            $edits[] = [strlen($source), 0, (self::endsOutsidePhp($source) ? '<?php ' : '') . $sentinel, 1, 0, 0];
        }

        $plain = self::applyEdits($source, $edits);
        $magic = null;
        // Magic comments turned off (Settings): they stay ordinary comments, nothing is added.
        if ($magicComments && MagicComments::mentioned($source)) {
            [$plain, $magic] = self::instrument($source, $statements, $parser, $edits, $plain, $returned);
        }
        // Last: the edits above never touch the opening tag, so their offsets stay valid.
        if ($applyStrictTypes) {
            $plain = self::withStrictTypes($plain);
        }

        return [self::evalReady($plain), strlen($prefix), $hasResult, null, $magic];
    }

    /**
     * Adds the magic comments' probes to the compiled source. The instrumented source must
     * parse and keep every line where it was; otherwise the snippet runs without probes.
     *
     * @param \RunletVendor\PhpParser\Node\Stmt[] $statements
     * @param \RunletVendor\PhpParser\Parser $parser
     * @param array<int, array<int, mixed>> $edits
     * @return array{0: string, 1: array{probes: array<int, array{line: int, kind: string, comment: string}>, rejected: array<int, array{line: int, comment: string, reason: string}>, notice?: string}|null}
     */
    private static function instrument(string $source, array $statements, $parser, array $edits, string $plain, ?\RunletVendor\PhpParser\Node\Stmt\Expression $returned): array
    {
        try {
            $plan = MagicComments::plan($source, $statements, $parser, $returned);
        } catch (\Throwable $error) {
            return [$plain, ['probes' => [], 'rejected' => [], 'notice' => 'Runlet could not read the magic comments in this snippet (' . $error->getMessage() . '), so it runs without them.']];
        }
        if ($plan['probes'] === [] && $plan['rejected'] === []) {
            return [$plain, null];
        }
        $magic = ['probes' => $plan['probes'], 'rejected' => $plan['rejected']];
        if ($plan['probes'] === []) {
            return [$plain, $magic];
        }
        $problem = null;
        try {
            $instrumented = self::applyEdits($source, array_merge($edits, $plan['edits']));
            if (substr_count($instrumented, "\n") !== substr_count($plain, "\n")) {
                $problem = 'the lines moved';
            } else {
                $parser->parse($instrumented);
            }
        } catch (\Throwable $error) {
            $problem = $error->getMessage();
        }
        if ($problem !== null || !isset($instrumented)) {
            // Never run differently because of a probe: drop them all and say so.
            foreach ($plan['probes'] as $probe) {
                $magic['rejected'][] = ['line' => $probe['line'], 'comment' => $probe['comment'], 'reason' => 'Runlet could not add this probe to the snippet.', 'label' => 'not added'];
            }
            usort($magic['rejected'], static function (array $a, array $b): int {
                return $a['line'] <=> $b['line'];
            });
            $magic['probes'] = [];
            $magic['notice'] = 'Runlet could not add the magic comments\' probes to this snippet (' . $problem . '), so it runs without them.';

            return [$plain, $magic];
        }

        return [$instrumented, $magic];
    }

    /**
     * Applies insertions and replacements, back to front so earlier offsets stay valid.
     * Edits at one offset are joined in (group, key1, key2) order: closing parts first, then
     * replacements, inserted statements, `return `, and opening calls (outermost first).
     *
     * @param array<int, array<int, mixed>> $edits [offset, deleteLength, text, group, key1, key2]
     */
    private static function applyEdits(string $source, array $edits): string
    {
        $byOffset = [];
        $deletions = [];
        foreach ($edits as $edit) {
            $byOffset[(int) $edit[0]][] = $edit;
            if ($edit[1] > 0) {
                $deletions[] = [(int) $edit[0], (int) $edit[0] + (int) $edit[1]];
            }
        }
        foreach ($deletions as [$from, $to]) {
            foreach (array_keys($byOffset) as $offset) {
                if ($offset > $from && $offset < $to) {
                    throw new \RuntimeException('overlapping edits at offset ' . $offset);
                }
            }
        }
        krsort($byOffset);
        foreach ($byOffset as $offset => $group) {
            usort($group, static function (array $a, array $b): int {
                return [$a[3], $a[4], $a[5]] <=> [$b[3], $b[4], $b[5]];
            });
            $text = '';
            $delete = 0;
            foreach ($group as $edit) {
                $text .= $edit[2];
                $delete += (int) $edit[1];
            }
            $source = substr($source, 0, $offset) . $text . substr($source, $offset + $delete);
        }

        return $source;
    }

    /**
     * The last statement that is not a Nop (comments after the last statement).
     *
     * @param \RunletVendor\PhpParser\Node\Stmt[] $list
     */
    private static function lastStatement(array $list): ?\RunletVendor\PhpParser\Node\Stmt
    {
        for ($i = count($list) - 1; $i >= 0; $i--) {
            if (!$list[$i] instanceof \RunletVendor\PhpParser\Node\Stmt\Nop) {
                return $list[$i];
            }
        }

        return null;
    }

    /**
     * Whether the snippet has its own `declare(strict_types=…)` (either value), which
     * always wins over the setting.
     */
    public static function declaresStrictTypes(string $source): bool
    {
        if (!function_exists('token_get_all')) {
            return preg_match('/\bdeclare\s*\(\s*strict_types\s*=/i', $source) === 1;
        }
        $tokens = token_get_all($source);
        $count = count($tokens);
        for ($i = 0; $i < $count; $i++) {
            if (!is_array($tokens[$i]) || $tokens[$i][0] !== T_DECLARE) {
                continue;
            }
            $sawParenthesis = false;
            for ($j = $i + 1; $j < $count; $j++) {
                $token = $tokens[$j];
                if (is_array($token) && in_array($token[0], [T_WHITESPACE, T_COMMENT, T_DOC_COMMENT], true)) {
                    continue;
                }
                if (!$sawParenthesis) {
                    if ($token !== '(') {
                        break;
                    }
                    $sawParenthesis = true;
                    continue;
                }
                if (is_array($token) && $token[0] === T_STRING && strtolower($token[1]) === 'strict_types') {
                    return true;
                }
                break;
            }
        }

        return false;
    }

    /**
     * Makes `declare(strict_types=1);` the first statement on the opening tag's line, so
     * no line number changes. Whitespace before a snippet's own `<?php` (inline output,
     * which PHP does not allow before the declaration) moves after the declaration.
     */
    private static function withStrictTypes(string $source): string
    {
        if (preg_match('/^(\s*)<\?php(?=\s|$)/', $source, $match)) {
            return '<?php ' . self::STRICT_TYPES . $match[1] . substr($source, strlen($match[0]));
        }
        if (preg_match('/^\s*<\?=/', $source)) {
            return '<?php ' . self::STRICT_TYPES . ' ?>' . $source;
        }

        return $source;
    }

    /**
     * eval() starts in PHP mode. Strip a leading open tag (keeping its trailing
     * whitespace so line numbers are unchanged); otherwise switch to HTML mode first.
     */
    public static function evalReady(string $source): string
    {
        if (preg_match('/^<\?php(?=\s)/', $source)) {
            $rest = substr($source, 5);

            return $rest[0] === ' ' ? substr($rest, 1) : $rest;
        }

        return '?>' . $source;
    }

    private static function isBracedNamespace(string $source, \RunletVendor\PhpParser\Node\Stmt\Namespace_ $namespace): bool
    {
        $end = $namespace->getEndFilePos();

        return $end >= 0 && isset($source[$end]) && $source[$end] === '}';
    }

    private static function endsOutsidePhp(string $source): bool
    {
        $tokens = token_get_all($source);
        for ($i = count($tokens) - 1; $i >= 0; $i--) {
            $token = $tokens[$i];
            if (is_array($token)) {
                if ($token[0] === T_WHITESPACE || $token[0] === T_COMMENT || $token[0] === T_DOC_COMMENT) {
                    continue;
                }

                return $token[0] === T_INLINE_HTML || $token[0] === T_CLOSE_TAG;
            }

            return false;
        }

        return false;
    }

    private static function column(string $source, \RunletVendor\PhpParser\Error $error): int
    {
        if (!$error->hasColumnInfo()) {
            return 0;
        }

        return $error->getStartColumn($source);
    }
}

/** An error raised by a project driver (.runlet/*Driver.php), with the driver that raised it. */
final class DriverFailure extends \RuntimeException
{
    /** @var string */
    public $driverFile;
    /** @var string|null */
    public $driverClass;

    public function __construct(string $context, string $driverFile, ?string $driverClass, \Throwable $previous)
    {
        parent::__construct($context . ': ' . $previous->getMessage(), 0, $previous);
        $this->driverFile = $driverFile;
        $this->driverClass = $driverClass;
    }
}

final class SnippetParseError extends \Exception
{
    /** @var int */
    public $snippetLine;
    /** @var int */
    public $snippetColumn;

    public function __construct(string $message, int $line, int $column, int $prefixLength)
    {
        parent::__construct($message);
        $this->snippetLine = max(1, $line);
        $this->snippetColumn = ($line <= 1 && $column > 0) ? max(1, $column - $prefixLength) : $column;
    }
}

final class Runner
{
    /** @var \Runlet\Driver|null The driver being booted (exit diagnostics). */
    private static $bootingDriver;
    /** @var string The project path being booted (exit diagnostics). */
    private static $bootingPath = '';

    /** @var array<string, mixed> */
    private static $request = [];
    /** @var string[]|null Import CSV's batches of rows (#152): data of the request, never code. */
    private static $sqlBatches = null;
    /** @var float */
    private static $startedAt = 0.0;
    /** The run's id from the request (#207: MongoDB tags its operations with it). */
    private static $runId = '';
    /** @var string */
    private static $state = 'starting';
    /** @var bool */
    private static $ddCalled = false;
    /** @var bool */
    private static $finished = false;
    /** @var ValueNormalizer|null */
    private static $normalizer;
    /** @var int */
    private static $prefixLength = 0;
    /** @var int */
    private static $dumpCount = 0;
    /** @var array<string, mixed> Driver variables imported into the snippet scope. */
    private static $variables = [];
    /** @var array{context: string, file: string, class: string|null}|null The project driver code running now. */
    private static $driverContext;
    /** @var \Runlet\Inspector|null The run inspector (snippet runs only). */
    private static $inspector;
    /** @var \Runlet\Driver|null The driver that booted the project. */
    private static $driver;
    /** @var array{label: string|null, file: string|null, class: string|null} How errors from the booted driver are attributed. */
    private static $driverOrigin = ['label' => null, 'file' => null, 'class' => null];
    /** @var bool Whether returned and dumped objects get HTML previews. */
    private static $previews = false;
    /** @var bool Set while a preview renders, so dumps inside the view get none. */
    private static $previewing = false;
    /** @var int */
    private static $maxBodyBytes = 2097152;
    /** @var int The line of the snippet's eval() in this file: its code is "…(<line>) : eval()'d code". */
    private static $evalLine = 0;
    /** @var array<string, mixed>|null Profile Run options (`request.profile`), else null. */
    private static $profileOptions;
    /** @var Profiler|null The snippet's profiler during a Profile Run. */
    private static $profiler;

    /** Explicit `bootstrap` request values mapped to built-in drivers. */
    private const BUILTIN_DRIVERS = [
        'laravel' => \Runlet\Drivers\LaravelDriver::class,
        'lumen' => \Runlet\Drivers\LaravelDriver::class,
        'laravel-zero' => \Runlet\Drivers\LaravelDriver::class,
        'wordpress' => \Runlet\Drivers\WordPressDriver::class,
        'symfony' => \Runlet\Drivers\SymfonyDriver::class,
        'composer' => \Runlet\Drivers\ComposerDriver::class,
        'plain' => \Runlet\Drivers\PlainDriver::class,
    ];

    /** Built-in auto-detection order; the first whose canBootstrap() is true boots the project. */
    private const DETECTION_ORDER = [
        \Runlet\Drivers\LaravelDriver::class,
        \Runlet\Drivers\WordPressDriver::class,
        \Runlet\Drivers\SymfonyDriver::class,
        \Runlet\Drivers\ComposerDriver::class,
        \Runlet\Drivers\PlainDriver::class,
    ];

    public static function main(string $encodedRequest): void
    {
        self::$startedAt = microtime(true);
        $decoded = base64_decode($encodedRequest, true);
        $request = $decoded === false ? null : json_decode($decoded, true);
        $decoded = null;
        self::$runId = is_array($request) && is_string($request['runId'] ?? null) ? $request['runId'] : '';
        if (is_array($request) && is_array($request['sqlConnection'] ?? null)) {
            // A saved database connection (#138): its password is in this request. From here
            // on no exception records function arguments, this function's argument no longer
            // holds the request, and no project code runs (plain bootstrap, no hints).
            ini_set('zend.exception_ignore_args', '1');
            $encodedRequest = '';
            if (($request['sqlConnection']['driver'] ?? '') === 'redis') {
                // #190: a saved Redis connection opens with Runlet's own RESP client.
                RedisConnect::configure($request['sqlConnection']);
            } elseif (($request['sqlConnection']['driver'] ?? '') === 'mongodb') {
                MongoTab::configure($request['sqlConnection']);
            } else {
                SqlConnect::configure($request['sqlConnection']);
            }
            unset($request['sqlConnection'], $request['hints'], $request['inspector'], $request['profile']);
            $request['mode'] = 'run';
            $request['bootstrap'] = 'plain';
            $request['magicComments'] = false;
        }
        // "run" (default) runs `code`; "commands" boots the project the same way and lists
        // its commands (driver commands() plus Composer scripts) instead; "panels" reports
        // its App Info sections (#19, Panels.php).
        $mode = is_array($request) && in_array($request['mode'] ?? 'run', ['commands', 'panels'], true) ? (string) $request['mode'] : 'run';
        if (!is_array($request) || !isset($request['nonce']) || ($mode === 'run' && !isset($request['code']))) {
            fwrite(fopen('php://stderr', 'wb'), "Runlet runner: invalid request\n");
            exit(70);
        }
        // #152: Import CSV's rows travel in the request apart from the code (so the snippet
        // compiler never parses them); SqlCsv takes them once.
        if (isset($request['sqlBatches']) && is_array($request['sqlBatches'])) {
            self::$sqlBatches = $request['sqlBatches'];
        }
        unset($request['sqlBatches']);
        self::$request = $request;
        Channel::open((string) $request['nonce']);
        $limits = is_array($request['limits'] ?? null) ? $request['limits'] : [];
        self::$normalizer = new ValueNormalizer($limits);
        SnippetMessages::configure($limits);
        self::$maxBodyBytes = (int) ($limits['maxBodyBytes'] ?? self::$maxBodyBytes);
        if ($mode === 'run') {
            self::createInspector(is_array($request['inspector'] ?? null) ? $request['inspector'] : [], $limits);
            self::$profileOptions = is_array($request['profile'] ?? null) ? $request['profile'] : null;
        }

        register_shutdown_function([self::class, 'shutdown']);

        $cwd = getcwd();
        $projectPath = $cwd === false ? '.' : $cwd;
        $requested = strtolower((string) ($request['bootstrap'] ?? 'auto'));
        if ($requested !== 'custom' && !isset(self::BUILTIN_DRIVERS[$requested])) {
            $requested = 'auto';
        }

        // Emitted before any project code loads, so the app learns the PID (for Stop) even
        // if a driver hangs. The framework here is preliminary: "custom" while project
        // drivers are pending; `bootstrapped` reports the driver that actually booted.
        Channel::emit('started', [
            'pid' => getmypid(),
            'phpVersion' => PHP_VERSION,
            'phpBinary' => PHP_BINARY,
            'sapi' => PHP_SAPI,
            'workingDirectory' => $cwd,
            'framework' => self::preliminaryFramework($projectPath, $requested),
            'user' => function_exists('posix_geteuid') ? posix_geteuid() : null,
            'profilers' => (object) Profiler::loaded(),
        ]);

        if (self::$profileOptions !== null && ($reason = Profiler::unavailableReason()) !== null) {
            // Profile Run on a PHP without Excimer: nothing of the project or the snippet runs.
            Channel::emit('error', ['stage' => 'launch', 'className' => 'ProfilerUnavailable', 'message' => $reason]);
            self::finish('error');

            return;
        }

        if ($mode === 'commands') {
            // Read from composer.json before any project code runs, so the scripts are listed
            // even when the application cannot boot.
            Channel::emit('commands', ['origin' => 'composer', 'source' => 'Composer', 'commands' => self::composerScripts($projectPath)]);
        }

        self::$state = 'bootstrap';
        $bootstrapStarted = microtime(true);
        try {
            $booted = self::bootstrap($projectPath, $requested);
        } catch (DriverFailure $failure) {
            $previous = $failure->getPrevious() ?? $failure;
            self::emitThrowable('bootstrap', $previous, array_filter([
                'message' => self::cleanMessage($failure->getMessage()),
                'driverFile' => $failure->driverFile,
                'driverClass' => $failure->driverClass,
            ]));
            self::finish('error');

            return;
        } catch (\Throwable $error) {
            self::emitThrowable('bootstrap', $error);
            self::finish('error');

            return;
        }
        if ($mode === 'run') {
            self::installDumpHandler();
        }

        $types = [];
        foreach (self::$variables as $name => $value) {
            $types[$name] = self::typeName($value);
        }
        $bootstrapped = [
            'framework' => $booted['framework'],
            'frameworkVersion' => $booted['version'],
            'driverName' => $booted['name'],
            // Always a JSON object (never []), name => class or type, for completion.
            'variables' => (object) $types,
            'bootstrapMs' => (int) round((microtime(true) - $bootstrapStarted) * 1000),
        ];
        if ($booted['file'] !== null) {
            $bootstrapped['driverFile'] = $booted['file'];
        }
        if ($booted['environment'] !== null) {
            $bootstrapped['environment'] = $booted['environment'];
        }
        self::log('runner', 'Booted ' . $booted['name'] . ($booted['version'] !== null ? ' ' . $booted['version'] : '') . ($booted['environment'] !== null ? ' (environment: ' . $booted['environment'] . ')' : '') . ' in ' . $bootstrapped['bootstrapMs'] . ' ms', $types === [] ? null : 'variables: $' . implode(', $', array_keys($types)));
        Channel::emit('bootstrapped', $bootstrapped);
        self::$driver = $booted['driver'];
        self::$driverOrigin = ['label' => $booted['label'], 'file' => $booted['file'], 'class' => $booted['class']];
        if ($mode === 'run') {
            self::inspect($booted);
        }

        if ($mode === 'commands') {
            self::listDriverCommands($booted);

            return;
        }
        if ($mode === 'panels') {
            self::reportPanels($booted, $projectPath);

            return;
        }

        self::$state = 'parse';
        try {
            $compiled = SnippetCompiler::compile((string) $request['code'], ($request['strictTypes'] ?? false) === true, ($request['magicComments'] ?? true) !== false);
            [$evalCode, $prefixLength, $hasResult, $notice] = $compiled;
            $magic = $compiled[4] ?? null;
        } catch (SnippetParseError $error) {
            Channel::emit('error', [
                'stage' => 'parse',
                'className' => 'ParseError',
                'message' => $error->getMessage(),
                'snippetLine' => $error->snippetLine,
                'snippetColumn' => $error->snippetColumn,
                'inSnippet' => true,
            ]);
            self::finish('error');

            return;
        }
        self::$prefixLength = $prefixLength;
        if ($notice !== null) {
            Channel::emit('notice', ['message' => $notice]);
        }
        if ($magic !== null) {
            self::installProbes($magic, $limits);
        }

        self::$state = 'execute';
        $executeStarted = microtime(true);
        if (self::$profileOptions !== null) {
            self::$profiler = Profiler::start(self::$profileOptions, $projectPath);
        }
        Probe::begin();
        try {
            $value = self::evaluate($evalCode);
        } catch (\Throwable $error) {
            self::stopProfiler();
            self::emitThrowable($error instanceof \ParseError ? 'parse' : 'execute', $error);
            self::finish('error', $executeStarted);

            return;
        }
        self::stopProfiler();

        if ($value instanceof NoResult) {
            Channel::emit('result', ['hasValue' => false]);
        } else {
            $payload = ['hasValue' => true, 'value' => self::normalize($value)];
            $preview = self::preview($value);
            if ($preview !== null) {
                $payload['preview'] = $preview;
            }
            Channel::emit('result', $payload);
        }
        self::finish('completed', $executeStarted);
    }

    /**
     * Reports the snippet's magic comments (`probes`: what each shows, and why the others
     * show nothing) and arms the probes. Comments Runlet cannot show get one notice.
     *
     * @param array{probes: array<int, array{line: int, kind: string, comment: string}>, rejected: array<int, array{line: int, comment: string, reason: string, label: string}>, notice?: string} $magic
     * @param array<string, mixed> $limits
     */
    private static function installProbes(array $magic, array $limits): void
    {
        $probes = [];
        foreach ($magic['probes'] as $id => $probe) {
            $probes[] = ['id' => $id, 'line' => $probe['line'], 'kind' => $probe['kind'], 'comment' => $probe['comment']];
        }
        Channel::emit('probes', ['probes' => $probes, 'rejected' => $magic['rejected']]);
        if (isset($magic['notice'])) {
            Channel::emit('notice', ['message' => $magic['notice']]);
        } elseif ($magic['rejected'] !== []) {
            $parts = [];
            foreach (array_slice($magic['rejected'], 0, 5) as $rejected) {
                $parts[] = 'line ' . $rejected['line'] . ' (' . $rejected['comment'] . '): ' . $rejected['reason'];
            }
            $more = count($magic['rejected']) - count($parts);
            $count = count($magic['rejected']);
            Channel::emit('notice', ['message' => 'Runlet can\'t show ' . ($count === 1 ? 'a magic comment' : $count . ' magic comments') . ', and the code runs as written. '
                . implode(' ', $parts) . ($more > 0 ? ' (' . $more . ' more)' : '')]);
        }
        Probe::install($magic['probes'], $limits);
    }

    /**
     * The run inspector, created before bootstrap so drivers can prepare for it (WordPress
     * turns on SAVEQUERIES). Its values use tighter limits than results and dumps.
     *
     * @param array<string, mixed> $options
     * @param array<string, mixed> $limits
     */
    private static function createInspector(array $options, array $limits): void
    {
        self::$previews = ($options['previews'] ?? false) === true;
        $normalizer = new ValueNormalizer([
            'maxDepth' => min(6, (int) ($limits['maxDepth'] ?? 8)),
            'maxChildren' => 100,
            'maxStringBytes' => 16384,
            'maxNodes' => 5000,
            'maxValueBytes' => 524288,
        ]);
        self::$inspector = new \Runlet\Inspector(
            $options + array_intersect_key($limits, array_flip(['maxQueries', 'maxRecords', 'maxRecordBytes', 'maxBodyBytes'])),
            static function (string $type, array $payload): void {
                Channel::emit($type, $payload);
            },
            static function ($value) use ($normalizer): array {
                try {
                    return $normalizer->normalize($value);
                } catch (\Throwable $error) {
                    return ['id' => 0, 'type' => 'unknown', 'scalar' => 'Runlet could not inspect this value: ' . $error->getMessage()];
                }
            }
        );
        \Runlet\Inspector::setCurrent(self::$inspector);
    }

    /**
     * Calls the driver's inspect() hook (when the inspector is on), then reports the
     * inspector's sections. A failing hook is a notice; the run continues.
     *
     * @param array{framework: string, version: string|null, name: string, file: string|null, driver: \Runlet\Driver, label: string|null, class: string|null} $booted
     */
    private static function inspect(array $booted): void
    {
        $inspector = self::$inspector;
        if ($inspector === null || !$inspector->isEnabled()) {
            return;
        }
        $driver = $booted['driver'];
        try {
            self::callDriver($booted['label'], $booted['file'], $booted['class'], 'inspect()', static function () use ($driver, $inspector): void {
                $driver->inspect($inspector);
            });
        } catch (\Throwable $error) {
            $message = $error instanceof DriverFailure ? $error->getMessage() : $booted['name'] . ' failed in inspect(): ' . $error->getMessage();
            Channel::emit('notice', ['message' => self::cleanMessage($message) . ' The run continues, but the inspector may miss queries, mail, or logs.']);
        }
        $inspector->ready($booted['name']);
    }

    /**
     * The driver's HTML preview of a returned or dumped object, bounded, or null.
     *
     * @param mixed $value
     * @return array<string, mixed>|null
     */
    private static function preview($value): ?array
    {
        if (!self::$previews || self::$previewing || self::$driver === null || !is_object($value)) {
            return null;
        }
        $driver = self::$driver;
        self::$previewing = true;
        try {
            $preview = $driver->preview($value);
        } catch (\Throwable $error) {
            $preview = ['title' => get_class($value), 'error' => self::cleanMessage($error->getMessage())];
        } finally {
            self::$previewing = false;
        }
        if (!is_array($preview) || (!isset($preview['html']) && !isset($preview['error']))) {
            return null;
        }
        $result = [];
        $limits = ['kind' => 30, 'title' => 300, 'subject' => 1000, 'error' => 4000, 'html' => self::$maxBodyBytes, 'text' => self::$maxBodyBytes];
        foreach ($limits as $key => $limit) {
            if (!isset($preview[$key]) || !is_scalar($preview[$key])) {
                continue;
            }
            $text = (string) $preview[$key];
            [$text, $omitted] = \Runlet\Inspector::clip($key === 'title' ? \Runlet\Inspector::className($text) : $text, $limit);
            $result[$key] = $text;
            if ($omitted > 0 && ($key === 'html' || $key === 'text')) {
                $result[$key . 'OmittedBytes'] = $omitted;
            }
        }

        return $result;
    }

    /** @return mixed */
    private static function evaluate(string $__runletCode)
    {
        // Evaluated in its own function scope: snippet variables never leak into the runner.
        // Driver variables come first; EXTR_SKIP and the name checks in collectVariables()
        // keep them from replacing $__runletCode.
        extract(self::$variables, EXTR_SKIP);
        self::$evalLine = __LINE__ + 2;

        return eval($__runletCode);
    }

    /** @return array<string, mixed> */
    private static function normalize($value): array
    {
        if (self::$normalizer === null) {
            return ['id' => 0, 'type' => 'unknown'];
        }
        try {
            return self::$normalizer->normalize($value);
        } catch (\Throwable $error) {
            return ['id' => 0, 'type' => 'unknown', 'scalar' => 'Runlet could not inspect this value: ' . $error->getMessage()];
        }
    }

    /**
     * The framework reported in `started`, from file checks only (no project code runs).
     * `bootstrap` request values: auto (default), custom, or a built-in driver id.
     */
    private static function preliminaryFramework(string $projectPath, string $requested): string
    {
        if (isset(self::BUILTIN_DRIVERS[$requested])) {
            $class = self::BUILTIN_DRIVERS[$requested];

            return self::frameworkId(new $class(), $projectPath, false);
        }
        if ($requested === 'custom' || self::projectDriverFiles($projectPath) !== []) {
            return 'custom';
        }

        return self::frameworkId(self::detectBuiltinDriver($projectPath), $projectPath, false);
    }

    /**
     * Picks and runs a driver: project drivers in .runlet/ first (auto or custom), then the
     * built-in detection order. Also collects the driver's snippet variables.
     *
     * @return array{framework: string, version: string|null, name: string, environment: string|null, file: string|null, driver: \Runlet\Driver, label: string|null, class: string|null}
     */
    private static function bootstrap(string $projectPath, string $requested): array
    {
        $driver = null;
        $file = null;
        if (isset(self::BUILTIN_DRIVERS[$requested])) {
            $class = self::BUILTIN_DRIVERS[$requested];
            $driver = new $class();
        } else {
            $driver = $requested === 'auto' ? self::rememberedBuiltinDriver($projectPath) : null;
            if ($driver === null) {
                [$driver, $file] = self::discoverProjectDriver($projectPath);
            }
            if ($driver === null && $requested === 'custom') {
                throw new \RuntimeException('No Runlet project driver can bootstrap ' . $projectPath . '. Add a class extending Runlet\Driver in .runlet/<Name>Driver.php whose canBootstrap() returns true.');
            }
            if ($driver === null) {
                $driver = self::detectBuiltinDriver($projectPath);
            }
        }

        $class = $file === null ? null : get_class($driver);
        $file = $file === null ? null : self::relativeDriverPath($projectPath, $file);
        $label = $file === null ? null : $class . ' (' . $file . ')';
        $builtinKey = $file === null ? array_search(get_class($driver), self::BUILTIN_DRIVERS, true) : false;
        $stamp = self::runletDirectoryStamp($projectPath);
        $recalled = self::recalled('driver') === 'builtin:' . $builtinKey . '@' . $stamp;
        self::log('runner', 'Driver: ' . ($label ?? get_class($driver)), ($recalled ? 'remembered for this session (no .runlet folder changes)' : ($requested === 'auto' ? 'auto-detected' : 'requested: ' . $requested)) . ' in ' . $projectPath);
        if ($requested === 'auto' && is_string($builtinKey)) {
            self::remember('driver', 'builtin:' . $builtinKey . '@' . $stamp);
        }
        self::$bootingDriver = $driver;
        self::$bootingPath = $projectPath;
        if ((self::$request['mode'] ?? 'run') === 'commands') {
            // Before bootstrap(): host commands are declarations, listed even when boot fails.
            self::emitHostCommands($driver, $label, $file, $class);
            // #20: so are the driver's log paths, for the log viewer.
            self::emitLogPaths($driver, $label, $file, $class);
        }
        self::callDriver($label, $file, $class, 'bootstrap()', static function () use ($driver, $projectPath): void {
            $driver->bootstrap($projectPath);
        });
        self::$variables = self::callDriver($label, $file, $class, 'variables()', static function () use ($driver): array {
            return self::collectVariables($driver->variables());
        });
        $version = self::callDriver($label, $file, $class, 'version()', static function () use ($driver): ?string {
            return $driver->version();
        });
        $name = self::callDriver($label, $file, $class, 'name()', static function () use ($driver): string {
            return $driver->name();
        });

        return [
            'framework' => self::frameworkId($driver, $projectPath, $file !== null),
            'version' => $version,
            'name' => $name,
            'environment' => self::driverEnvironment($driver, $label),
            'file' => $file,
            'driver' => $driver,
            'label' => $label,
            'class' => $class,
        ];
    }

    /**
     * The application's environment name from the driver's environment() (#12), for the
     * `bootstrapped` event: without control characters, trimmed, at most 64 characters; null
     * when there is none. It is informational, so a driver whose environment() throws only
     * gets a Run Log line and the run continues.
     */
    private static function driverEnvironment(\Runlet\Driver $driver, ?string $label): ?string
    {
        try {
            $environment = $driver->environment();
        } catch (\Throwable $error) {
            self::log('runner', ($label ?? get_class($driver)) . ': environment() failed; the environment is not reported', get_class($error) . ': ' . self::cleanMessage($error->getMessage()));

            return null;
        }
        // Invalid UTF-8 makes preg_replace() return null.
        $environment = is_string($environment) ? preg_replace('/\p{Cc}+/u', '', $environment) : null;
        if (!is_string($environment) || !preg_match('/^.{1,64}/us', trim($environment), $match)) {
            return null;
        }

        return rtrim($match[0]);
    }

    /**
     * A value the app remembered for this session (the request's `hints`, sent back from an
     * earlier run's `remember` events). Callers check it is still valid before using it.
     */
    public static function recalled(string $key): ?string
    {
        $hints = self::$request['hints'] ?? null;

        return is_array($hints) && isset($hints[$key]) && is_string($hints[$key]) ? $hints[$key] : null;
    }

    /** Asks the app to remember a value for this target until it quits (see recalled()). */
    public static function remember(string $key, string $value): void
    {
        if (self::recalled($key) !== $value) {
            Channel::emit('remember', ['key' => $key, 'value' => $value]);
        }
    }

    /** The remembered built-in driver, when no .runlet driver was added or changed since and it still accepts the project. */
    private static function rememberedBuiltinDriver(string $projectPath): ?\Runlet\Driver
    {
        $hint = self::recalled('driver');
        if ($hint === null || !preg_match('/^builtin:([a-z]+)@(.+)$/', $hint, $match) || $match[2] !== self::runletDirectoryStamp($projectPath)
            || !isset(self::BUILTIN_DRIVERS[$match[1]])) {
            return null;
        }
        $class = self::BUILTIN_DRIVERS[$match[1]];
        $driver = new $class();

        return $driver->canBootstrap($projectPath) ? $driver : null;
    }

    /** Changes when project drivers are added, removed, or edited in .runlet/. */
    private static function runletDirectoryStamp(string $projectPath): string
    {
        $directory = $projectPath . '/.runlet';
        if (!is_dir($directory)) {
            return 'none';
        }
        $stamp = (string) @filemtime($directory);
        foreach (glob($directory . '/*Driver.php') ?: [] as $file) {
            $stamp .= ':' . @filemtime($file);
        }

        return $stamp;
    }

    /** Emits one Run Log line (Run ▸ Show Run Log in the app). */
    public static function log(string $source, string $message, ?string $detail = null): void
    {
        Channel::emit('log', array_filter(['source' => $source, 'message' => $message, 'detail' => $detail], static function ($value): bool {
            return $value !== null;
        }));
    }

    /**
     * What explains an exit() during bootstrap: the driver's own hint (e.g. WordPress's
     * redirect) and the project file loaded last, which is usually where exit() was called
     * from (a plugin, a config file, a bootstrap script). Also logged.
     */
    private static function bootstrapExitHint(): string
    {
        $parts = [];
        $driver = self::$bootingDriver;
        if ($driver !== null && method_exists($driver, 'bootstrapExitHint')) {
            try {
                $hint = $driver->bootstrapExitHint();
                if (is_string($hint) && $hint !== '') {
                    $parts[] = $hint;
                }
            } catch (\Throwable $ignored) {
            }
        }
        $files = array_values(array_filter(get_included_files(), static function (string $file): bool {
            return $file !== '' && $file[0] === '/' && strpos($file, 'eval()') === false;
        }));
        $last = end($files);
        if (is_string($last) && $last !== '') {
            $root = rtrim(self::$bootingPath, '/') . '/';
            $shown = self::$bootingPath !== '' && strpos($last, $root) === 0 ? substr($last, strlen($root)) : $last;
            $parts[] = 'The last file loaded was ' . $shown . ' (' . count($files) . ' files in all).';
            self::log('bootstrap', 'exit() during bootstrap; last file loaded: ' . $shown, implode("\n", array_slice(array_map(static function (string $file) use ($root): string {
                return strpos($file, $root) === 0 ? substr($file, strlen($root)) : $file;
            }, $files), -8)));
        }

        return implode(' ', $parts);
    }

    /** Most commands one `commands` event lists, and the longest description kept. */
    private const MAX_COMMANDS = 5000;
    private const MAX_DESCRIPTION = 500;

    /**
     * Commands mode, after bootstrap: emits the driver's commands() and finishes.
     *
     * @param array{framework: string, version: string|null, name: string, file: string|null, driver: \Runlet\Driver, label: string|null, class: string|null} $booted
     */
    private static function listDriverCommands(array $booted): void
    {
        self::$state = 'commands';
        $driver = $booted['driver'];
        try {
            $commands = self::callDriver($booted['label'], $booted['file'], $booted['class'], 'commands()', static function () use ($driver): array {
                return $driver->commands();
            });
        } catch (DriverFailure $failure) {
            $previous = $failure->getPrevious() ?? $failure;
            self::emitThrowable('execute', $previous, array_filter([
                'message' => self::cleanMessage($failure->getMessage()),
                'driverFile' => $failure->driverFile,
                'driverClass' => $failure->driverClass,
            ]));
            self::finish('error');

            return;
        } catch (\Throwable $error) {
            self::emitThrowable('execute', $error, ['message' => $booted['name'] . ' could not list its commands: ' . self::cleanMessage($error->getMessage())]);
            self::finish('error');

            return;
        }

        $payload = [
            'origin' => 'driver',
            'source' => $booted['name'],
            'framework' => $booted['framework'],
            'commands' => self::normalizeCommands($commands, $booted['name']),
        ];
        if ($booted['file'] !== null) {
            $payload['driverFile'] = $booted['file'];
        }
        Channel::emit('commands', $payload);
        self::finish('completed');
    }

    /**
     * Panels mode (App Info, #19), after bootstrap: emits the built-in sections, then the
     * driver's panels(), and finishes. A failing panels() is the driver event's `error`; the
     * built-ins were sent already.
     *
     * @param array{framework: string, version: string|null, name: string, file: string|null, driver: \Runlet\Driver, label: string|null, class: string|null} $booted
     */
    private static function reportPanels(array $booted, string $projectPath): void
    {
        self::$state = 'panels';
        $driver = $booted['driver'];
        try {
            Channel::emit('panels', AppInfo::builtin($driver, $projectPath, $booted['name']));
        } catch (\Throwable $error) {
            Channel::emit('panels', ['origin' => 'builtin', 'source' => $booted['name'], 'sections' => [], 'error' => 'Runlet could not read the App Info: ' . self::cleanMessage($error->getMessage())]);
        }
        try {
            $payload = AppInfo::driver(self::callDriver($booted['label'], $booted['file'], $booted['class'], 'panels()', static function () use ($driver) {
                return $driver->panels();
            }), $booted['name']);
        } catch (\Throwable $error) {
            $payload = AppInfo::driver([], $booted['name']);
            $payload['error'] = self::cleanMessage($error instanceof DriverFailure ? $error->getMessage() : $booted['name'] . ' failed in panels(): ' . $error->getMessage());
        }
        if ($booted['file'] !== null) {
            $payload['driverFile'] = $booted['file'];
        }
        Channel::emit('panels', $payload);
        self::finish('completed');
    }

    /**
     * Commands mode, before bootstrap: emits the driver's hostCommands() as a `hostCommands`
     * event (static commands and command sources; empty lists when it declares none, so the
     * app knows the declaration is current). A failing hostCommands() is a notice, never a
     * reason to stop listing the driver's own commands.
     */
    private static function emitHostCommands(\Runlet\Driver $driver, ?string $label, ?string $file, ?string $class): void
    {
        $context = $label ?? get_class($driver);
        try {
            $entries = self::callDriver($label, $file, $class, 'hostCommands()', static function () use ($driver): array {
                return $driver->hostCommands();
            });
        } catch (\Throwable $error) {
            $previous = $error instanceof DriverFailure ? ($error->getPrevious() ?? $error) : $error;
            Channel::emit('notice', ['message' => $context . ': hostCommands() failed, so its host commands are not listed: ' . self::cleanMessage($previous->getMessage())]);

            return;
        }
        $commands = [];
        $sources = [];
        $skipped = [];
        foreach ($entries as $key => $entry) {
            $name = is_array($entry) && isset($entry['name']) && is_scalar($entry['name']) ? (string) $entry['name'] : (is_string($key) ? $key : '');
            $list = is_array($entry) && isset($entry['list']) && is_string($entry['list']) ? trim($entry['list']) : '';
            $console = is_array($entry) && isset($entry['console']) && is_string($entry['console']) ? trim($entry['console']) : '';
            if ($name !== '' && ($list !== '' || $console !== '')) {
                if (count($sources) < 20) {
                    $description = isset($entry['description']) && is_scalar($entry['description']) ? trim((string) $entry['description']) : '';
                    $sources[] = [
                        'name' => $name,
                        'format' => $list !== '' ? 'runlet' : 'symfony',
                        'list' => $list !== '' ? $list : $console . ' list --format=json',
                        'console' => $list !== '' ? null : $console,
                        'description' => $description === '' ? null : self::shorten($description, self::MAX_DESCRIPTION),
                    ];
                }
                continue;
            }
            if (is_string($entry) || (is_array($entry) && isset($entry['command']))) {
                $commands[$key] = $entry;
                continue;
            }
            $skipped[] = $name === '' ? '#' . $key : $name;
        }
        if ($skipped !== []) {
            Channel::emit('notice', ['message' => $context . ' returned host commands without a command, list, or console, which Runlet skipped: ' . implode(', ', array_slice($skipped, 0, 20)) . '.']);
        }
        Channel::emit('hostCommands', [
            'commands' => self::normalizeCommands($commands, $context),
            'sources' => $sources,
        ]);
    }

    /**
     * Commands mode, before bootstrap (#20): emits the driver's logPaths() as a `logPaths`
     * event (at most 50 non-empty strings of at most 1,024 characters; an empty list when it
     * declares none). A failing logPaths() is a notice; the commands are still listed.
     */
    private static function emitLogPaths(\Runlet\Driver $driver, ?string $label, ?string $file, ?string $class): void
    {
        if (!method_exists($driver, 'logPaths')) {
            return;
        }
        $context = $label ?? get_class($driver);
        try {
            $declared = self::callDriver($label, $file, $class, 'logPaths()', static function () use ($driver): array {
                return $driver->logPaths();
            });
        } catch (\Throwable $error) {
            $previous = $error instanceof DriverFailure ? ($error->getPrevious() ?? $error) : $error;
            Channel::emit('notice', ['message' => $context . ': logPaths() failed, so the log viewer lists only the logs it finds by itself: ' . self::cleanMessage($previous->getMessage())]);

            return;
        }
        $paths = [];
        foreach ($declared as $path) {
            if (!is_string($path) || ($path = trim($path)) === '' || strlen($path) > 1024 || in_array($path, $paths, true)) {
                continue;
            }
            $paths[] = $path;
            if (count($paths) >= 50) {
                break;
            }
        }
        Channel::emit('logPaths', ['paths' => $paths]);
    }

    /**
     * Validates commands() output: name-keyed entries or lists of entries with a `name`;
     * a string value is the command line. Invalid entries are skipped with a notice.
     *
     * @param array<mixed> $commands
     * @return array<int, array{name: string, command: string, description: string|null, group: string|null, needsInput?: bool}>
     */
    private static function normalizeCommands(array $commands, string $driverName): array
    {
        $result = [];
        $seen = [];
        $skipped = [];
        foreach ($commands as $key => $entry) {
            if (is_string($entry)) {
                $entry = ['command' => $entry];
            }
            $name = is_array($entry) && isset($entry['name']) && is_scalar($entry['name']) ? (string) $entry['name'] : (is_string($key) ? $key : '');
            $command = is_array($entry) && isset($entry['command']) && is_string($entry['command']) ? trim($entry['command']) : '';
            if ($name === '' || $command === '') {
                $skipped[] = $name === '' ? '#' . $key : $name;
                continue;
            }
            if (isset($seen[$name]) || count($result) >= self::MAX_COMMANDS) {
                continue;
            }
            $seen[$name] = true;
            $description = isset($entry['description']) && is_scalar($entry['description']) ? trim((string) $entry['description']) : '';
            $group = isset($entry['group']) && is_scalar($entry['group']) ? trim((string) $entry['group']) : '';
            $normalized = [
                'name' => $name,
                'command' => $command,
                'description' => $description === '' ? null : self::shorten($description, self::MAX_DESCRIPTION),
                'group' => $group === '' ? null : $group,
            ];
            if (is_array($entry) && ($entry['needsInput'] ?? false) === true) {
                $normalized['needsInput'] = true;
            }
            $result[] = $normalized;
        }
        if ($skipped !== []) {
            Channel::emit('notice', ['message' => $driverName . ' returned commands without a name or command line, which Runlet skipped: ' . implode(', ', array_slice($skipped, 0, 20)) . '.']);
        }

        return $result;
    }

    /** Composer's own event names: `scripts` entries Composer runs as hooks, not commands. */
    private const COMPOSER_EVENTS = [
        'pre-install-cmd', 'post-install-cmd', 'pre-update-cmd', 'post-update-cmd', 'pre-status-cmd', 'post-status-cmd',
        'pre-archive-cmd', 'post-archive-cmd', 'pre-autoload-dump', 'post-autoload-dump', 'post-root-package-install',
        'post-create-project-cmd', 'pre-operations-exec', 'pre-package-install', 'post-package-install',
        'pre-package-update', 'post-package-update', 'pre-package-uninstall', 'post-package-uninstall', 'init', 'command',
        'pre-file-download', 'post-file-download', 'pre-command-run', 'pre-pool-create',
    ];

    /**
     * Scripts from composer.json in the working directory, as `composer run-script <name>`.
     * Pure file read: no project code runs.
     *
     * @return array<int, array{name: string, command: string, description: string|null, group: string}>
     */
    private static function composerScripts(string $projectPath): array
    {
        $manifest = @file_get_contents($projectPath . '/composer.json');
        $composer = is_string($manifest) ? json_decode($manifest, true) : null;
        if (!is_array($composer) || !isset($composer['scripts']) || !is_array($composer['scripts'])) {
            return [];
        }
        $descriptions = isset($composer['scripts-descriptions']) && is_array($composer['scripts-descriptions']) ? $composer['scripts-descriptions'] : [];
        $result = [];
        foreach ($composer['scripts'] as $name => $script) {
            $name = (string) $name;
            if ($name === '' || in_array($name, self::COMPOSER_EVENTS, true)) {
                continue;
            }
            $description = isset($descriptions[$name]) && is_string($descriptions[$name]) ? trim($descriptions[$name]) : '';
            if ($description === '') {
                $steps = is_array($script) ? $script : [$script];
                $parts = [];
                foreach ($steps as $stepKey => $step) {
                    // Symfony Flex "auto-scripts" map commands to their runner: list the commands.
                    $parts[] = is_string($stepKey) ? $stepKey : (is_scalar($step) ? (string) $step : '');
                }
                $parts = array_values(array_filter($parts, 'strlen'));
                $description = count($parts) > 1 ? $parts[0] . ' (+' . (count($parts) - 1) . ' more)' : ($parts[0] ?? '');
            }
            $argument = preg_match('/^[A-Za-z0-9:._-]+$/', $name) ? $name : escapeshellarg($name);
            $result[] = [
                'name' => $name,
                'command' => 'composer run-script ' . $argument,
                'description' => $description === '' ? null : self::shorten($description, self::MAX_DESCRIPTION),
                'group' => 'composer',
            ];
        }

        return $result;
    }

    private static function shorten(string $text, int $limit): string
    {
        if (strlen($text) <= $limit) {
            return $text;
        }
        $cut = substr($text, 0, $limit);
        // Never end inside a multibyte UTF-8 sequence.
        while ($cut !== '' && preg_match('//u', $cut) !== 1) {
            $cut = substr($cut, 0, -1);
        }

        return $cut . '…';
    }

    private static function detectBuiltinDriver(string $projectPath): \Runlet\Driver
    {
        foreach (self::DETECTION_ORDER as $class) {
            $driver = new $class();
            if ($driver->canBootstrap($projectPath)) {
                return $driver;
            }
        }

        return new \Runlet\Drivers\PlainDriver();
    }

    private static function frameworkId(\Runlet\Driver $driver, string $projectPath, bool $isProjectDriver): string
    {
        if ($isProjectDriver) {
            return 'custom:' . get_class($driver);
        }
        if ($driver instanceof \Runlet\Drivers\LaravelDriver) {
            return $driver->flavor($projectPath);
        }
        if ($driver instanceof \Runlet\Drivers\WordPressDriver) {
            return 'wordpress';
        }
        if ($driver instanceof \Runlet\Drivers\SymfonyDriver) {
            return 'symfony';
        }
        if ($driver instanceof \Runlet\Drivers\ComposerDriver) {
            return 'composer';
        }

        return 'plain';
    }

    /**
     * Project driver files: <project>/.runlet/*Driver.php, sorted. Read straight from disk,
     * so a globally git-ignored .runlet/ folder works.
     *
     * @return string[]
     */
    private static function projectDriverFiles(string $projectPath): array
    {
        $directory = $projectPath . '/.runlet';
        $entries = is_dir($directory) ? @scandir($directory) : false;
        if (!is_array($entries)) {
            return [];
        }
        $files = [];
        foreach ($entries as $entry) {
            if (substr($entry, -10) === 'Driver.php' && is_file($directory . '/' . $entry)) {
                $files[] = $directory . '/' . $entry;
            }
        }
        sort($files, SORT_STRING);

        return $files;
    }

    /**
     * Loads every project driver file (after the project's Composer autoloader, when it
     * exists) and returns the first concrete Runlet\Driver declared in .runlet/ whose
     * canBootstrap() accepts the project.
     *
     * @return array{0: \Runlet\Driver|null, 1: string|null}
     */
    private static function discoverProjectDriver(string $projectPath): array
    {
        $files = self::projectDriverFiles($projectPath);
        if ($files === []) {
            return [null, null];
        }
        // Drivers may use project classes without loading Composer themselves. Loading it
        // again later (e.g. from the app's own bootstrap file) is harmless: Composer's
        // generated autoloader returns the already registered loader.
        $autoload = $projectPath . '/vendor/autoload.php';
        if (is_file($autoload)) {
            require_once $autoload;
        }

        $directory = $projectPath . '/.runlet';
        $realDirectory = realpath($directory);
        // A driver may extend another driver in .runlet/ regardless of file order.
        $siblingLoader = static function (string $class) use ($directory): void {
            $short = substr((string) strrchr('\\' . $class, '\\'), 1);
            if (substr($short, -6) === 'Driver' && is_file($directory . '/' . $short . '.php')) {
                self::requireFile($directory . '/' . $short . '.php');
            }
        };

        $candidates = [];
        spl_autoload_register($siblingLoader);
        try {
            foreach ($files as $file) {
                $before = get_declared_classes();
                $relative = self::relativeDriverPath($projectPath, $file);
                $context = 'Runlet driver ' . $relative . ' could not be loaded';
                self::$driverContext = ['context' => $context, 'file' => $relative, 'class' => null];
                try {
                    self::requireFile($file);
                } catch (\Throwable $error) {
                    throw new DriverFailure($context, $relative, null, $error);
                }
                foreach (array_diff(get_declared_classes(), $before) as $class) {
                    $reflection = new \ReflectionClass($class);
                    $declaredIn = $reflection->getFileName();
                    if ($reflection->isAbstract() || !$reflection->isSubclassOf(\Runlet\Driver::class)
                        || !is_string($declaredIn) || realpath(dirname($declaredIn)) !== $realDirectory) {
                        continue;
                    }
                    $candidates[$class] = $declaredIn;
                }
            }
        } finally {
            spl_autoload_unregister($siblingLoader);
            self::$driverContext = null;
        }

        foreach ($candidates as $class => $file) {
            $relative = self::relativeDriverPath($projectPath, $file);
            $driver = self::callDriver($class . ' (' . $relative . ')', $relative, $class, 'canBootstrap()', static function () use ($class, $projectPath): ?\Runlet\Driver {
                $driver = (new \ReflectionClass($class))->newInstance();

                return $driver->canBootstrap($projectPath) ? $driver : null;
            });
            if ($driver !== null) {
                return [$driver, $file];
            }
        }

        return [null, null];
    }

    /**
     * Runs one driver call. For project drivers ($label set), errors are wrapped so the
     * report names the driver, and fatal errors are attributed to it by shutdown().
     *
     * @return mixed
     */
    private static function callDriver(?string $label, ?string $file, ?string $class, string $method, \Closure $call)
    {
        if ($label === null || $file === null) {
            return $call();
        }
        $context = 'Runlet driver ' . $label . ' failed in ' . $method;
        self::$driverContext = ['context' => $context, 'file' => $file, 'class' => $class];
        try {
            return $call();
        } catch (\Throwable $error) {
            throw new DriverFailure($context, $file, $class, $error);
        } finally {
            self::$driverContext = null;
        }
    }

    /**
     * Import CSV's batches of rows (#152), handed over once: the caller then holds the only
     * reference and can free each batch as it goes.
     *
     * @return string[]
     */
    public static function takeSqlBatches(): array
    {
        $batches = self::$sqlBatches ?? [];
        self::$sqlBatches = null;

        return $batches;
    }

    /** The run's id, as Runlet sent it (#207); empty when it sent none. */
    public static function runId(): string
    {
        return self::$runId;
    }

    /** The driver that booted the project (SQL tabs, #35); null before bootstrap. */
    public static function bootedDriver(): ?\Runlet\Driver
    {
        return self::$driver;
    }

    /**
     * Calls the booted driver: a project driver's errors (and fatal errors) name its file
     * and method, as during bootstrap.
     *
     * @return mixed
     */
    public static function callBootedDriver(string $method, \Closure $call)
    {
        $origin = self::$driverOrigin;

        return self::callDriver($origin['label'], $origin['file'], $origin['class'], $method, $call);
    }

    private static function requireFile(string $__runletFile): void
    {
        require_once $__runletFile;
    }

    private static function relativeDriverPath(string $projectPath, string $file): string
    {
        $prefix = rtrim($projectPath, '/') . '/';

        return strpos($file, $prefix) === 0 ? substr($file, strlen($prefix)) : $file;
    }

    /**
     * Keeps variables with valid, non-reserved names.
     *
     * @param array<mixed> $variables
     * @return array<string, mixed>
     */
    private static function collectVariables(array $variables): array
    {
        $accepted = [];
        $ignored = [];
        foreach ($variables as $name => $value) {
            $name = (string) $name;
            if (!preg_match('/^[A-Za-z_\x80-\xff][A-Za-z0-9_\x80-\xff]*$/', $name) || $name === 'this' || $name === 'GLOBALS' || strpos($name, '__runlet') === 0) {
                $ignored[] = $name;
                continue;
            }
            $accepted[$name] = $value;
        }
        if ($ignored !== []) {
            Channel::emit('notice', ['message' => 'Runlet ignored driver variables with names that cannot be snippet variables: ' . implode(', ', $ignored) . '.']);
        }

        return $accepted;
    }

    /** @param mixed $value */
    private static function typeName($value): string
    {
        if (is_object($value)) {
            $class = get_class($value);
            // Anonymous classes are named "class@anonymous<NUL>/path:line$0".
            $nul = strpos($class, "\0");

            return $nul === false ? $class : substr($class, 0, $nul);
        }
        $types = ['integer' => 'int', 'double' => 'float', 'boolean' => 'bool', 'NULL' => 'null', 'resource (closed)' => 'resource'];
        $type = gettype($value);

        return $types[$type] ?? $type;
    }

    private static function installDumpHandler(): void
    {
        $handler = static function ($value, $label = null): void {
            self::emitDump($value, $label);
        };

        // The active global dump() may come from the project, or from something loaded
        // earlier such as a php.ini auto_prepend_file with a namespace-scoped var-dumper.
        // Hook every VarDumper class that the active dump()/dd() actually call.
        $candidates = ['Symfony\Component\VarDumper\VarDumper'];
        foreach (['dump', 'dd'] as $function) {
            if (function_exists($function)) {
                $candidates = array_merge($candidates, self::varDumperClassesUsedBy($function, 0));
            }
        }
        $installed = false;
        foreach (array_unique($candidates) as $class) {
            if (class_exists($class) && method_exists($class, 'setHandler')) {
                $class::setHandler($handler);
                $installed = true;
            }
        }
        if ($installed) {
            return;
        }

        if (!function_exists('dump') && !function_exists('dd')) {
            eval('function dump(...$vars) { foreach ($vars as $v) { \RunletRunner\Runner::emitDump($v, null); } return $vars[0] ?? null; }'
                . 'function dd(...$vars) { foreach ($vars as $v) { \RunletRunner\Runner::emitDump($v, null); } exit(1); }');
        }
    }

    /**
     * Finds VarDumper classes referenced by the file defining $function, following
     * php-scoper style aliases (`function dump() { return \\Prefix\\dump(...); }`).
     *
     * @return string[]
     */
    private static function varDumperClassesUsedBy(string $function, int $depth): array
    {
        try {
            $reflection = new \ReflectionFunction($function);
        } catch (\Throwable $error) {
            return [];
        }
        $file = $reflection->getFileName();
        $lines = is_string($file) ? @file($file) : false;
        if (!is_array($lines)) {
            return [];
        }
        $classes = [];
        if (preg_match_all('/([A-Za-z0-9_\\\\]*Symfony\\\\Component\\\\VarDumper\\\\VarDumper)\b/', implode('', $lines), $matches)) {
            foreach ($matches[1] as $class) {
                $classes[] = ltrim($class, '\\');
            }
        }
        $start = max(0, (int) $reflection->getStartLine() - 1);
        $body = implode('', array_slice($lines, $start, max(1, (int) $reflection->getEndLine() - $start)));
        if ($depth < 3 && preg_match_all('/\\\\?([A-Za-z_][A-Za-z0-9_]*(?:\\\\[A-Za-z_][A-Za-z0-9_]*)+)\s*\(/', $body, $calls)) {
            foreach ($calls[1] as $target) {
                if (strcasecmp($target, $function) !== 0 && function_exists($target)) {
                    $classes = array_merge($classes, self::varDumperClassesUsedBy($target, $depth + 1));
                }
            }
        }

        return $classes;
    }

    /** @param mixed $value */
    public static function emitDump($value, $label = null): void
    {
        $origin = 'dump';
        $snippetFrame = null;
        $callerFrame = null;
        $laravelBenchmark = false;
        foreach (debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS) as $frame) {
            $function = $frame['function'] ?? '';
            $class = $frame['class'] ?? '';
            $short = substr((string) strrchr('\\' . $function, '\\'), 1);
            if ($short === 'dd' && $class === '') {
                $origin = 'dd';
                self::$ddCalled = true;
            }
            if ($function === 'dd' && $class === 'Illuminate\\Support\\Benchmark') {
                $laravelBenchmark = true;
            }
            if ($callerFrame === null && ($short === 'dump' || $short === 'dd') && $class === '') {
                $callerFrame = $frame;
            }
            if ($snippetFrame === null && isset($frame['file']) && self::isSnippetFile($frame['file'])) {
                $snippetFrame = $frame;
            }
        }
        $frame = $snippetFrame ?? $callerFrame;
        if ($laravelBenchmark) {
            self::recordLaravelBenchmark($value);
        }

        self::$dumpCount++;
        $payload = ['index' => self::$dumpCount, 'origin' => $origin, 'value' => self::normalize($value)];
        if ($label !== null && $label !== '') {
            $payload['label'] = (string) $label;
        }
        $preview = self::preview($value);
        if ($preview !== null) {
            $payload['preview'] = $preview;
        }
        if ($frame !== null) {
            $payload += self::location($frame['file'] ?? null, $frame['line'] ?? null);
        }
        Channel::emit('dump', $payload);
    }

    /**
     * Laravel's Benchmark::dd() dumped its averages: also record them as a benchmark card,
     * with the iteration count from Benchmark::dd()'s arguments.
     *
     * @param mixed $value
     */
    private static function recordLaravelBenchmark($value): void
    {
        try {
            foreach (debug_backtrace(0) as $frame) {
                if (($frame['class'] ?? '') === 'Illuminate\\Support\\Benchmark' && ($frame['function'] ?? '') === 'dd') {
                    \Runlet\Benchmark::recordLaravelDump($value, is_array($frame['args'] ?? null) ? $frame['args'] : []);

                    return;
                }
            }
        } catch (\Throwable $error) {
            // The dump itself is still shown.
        }
    }

    /** Stops the Profile Run's sampling (the record is sent when the run finishes). */
    private static function stopProfiler(): void
    {
        if (self::$profiler !== null) {
            try {
                self::$profiler->stop();
            } catch (\Throwable $error) {
                Channel::emit('notice', ['message' => 'Runlet could not stop the profiler: ' . $error->getMessage()]);
                self::$profiler = null;
            }
        }
    }

    /** Sends the Profile Run's flame-graph data, before the inspector finishes. */
    private static function emitProfile(): void
    {
        $profiler = self::$profiler;
        self::$profiler = null;
        if ($profiler === null || self::$inspector === null) {
            return;
        }
        try {
            self::$inspector->measurement(Profiler::SECTION, 'profile', 'Profile', $profiler->record(), []);
        } catch (\Throwable $error) {
            Channel::emit('notice', ['message' => 'Runlet could not report the profile: ' . $error->getMessage()]);
        }
    }

    /** @return array<string, mixed> */
    private static function location(?string $file, ?int $line): array
    {
        if ($file === null) {
            return [];
        }
        if (self::isSnippetFile($file)) {
            return ['inSnippet' => true, 'snippetLine' => (int) $line];
        }

        return ['inSnippet' => false, 'file' => $file, 'line' => $line];
    }

    private static function cleanMessage(string $message): string
    {
        return (string) preg_replace("/(?:Standard input code|\\S+)\\(\\d+\\) : eval\\(\\)'d code/", 'snippet', $message);
    }

    /**
     * Whether a backtrace file is the snippet. Other code the runner evaluates (such as the
     * DBAL 4 inspector middleware) is "eval()'d code" too, but from another line.
     */
    public static function isSnippetFile(string $file): bool
    {
        $suffix = self::$evalLine > 0 ? '(' . self::$evalLine . ") : eval()'d code" : "eval()'d code";

        return substr($file, -strlen($suffix)) === $suffix;
    }

    /** @param array<string, mixed> $overrides */
    private static function emitThrowable(string $stage, \Throwable $error, array $overrides = []): void
    {
        $details = self::describeThrowable($error);
        $payload = $overrides + [
            'stage' => $stage,
            'className' => $details['className'],
            'message' => $details['message'],
            'code' => is_int($error->getCode()) ? $error->getCode() : (string) $error->getCode(),
        ];
        unset($details['className'], $details['message']);
        Channel::emit('error', $payload + $details);
    }

    /**
     * @internal $error's class, message, where it was thrown (and the snippet line that led
     * there), its stack trace without the runner's frames, and its cause: what error events
     * carry, and \Runlet\error()'s card for a Throwable (#196).
     *
     * @return array<string, mixed>
     */
    public static function describeThrowable(\Throwable $error): array
    {
        $payload = [
            'className' => get_class($error),
            'message' => self::cleanMessage($error->getMessage()),
        ] + self::location($error->getFile(), $error->getLine());

        if (!($payload['inSnippet'] ?? false)) {
            foreach ($error->getTrace() as $frame) {
                if (isset($frame['file']) && self::isSnippetFile($frame['file'])) {
                    $payload['snippetLine'] = (int) ($frame['line'] ?? 0);
                    break;
                }
            }
        }

        $frames = [];
        foreach (array_slice(self::userTrace($error->getTrace()), 0, 40) as $frame) {
            $item = ['function' => ($frame['class'] ?? '') . ($frame['type'] ?? '') . ($frame['function'] ?? '')];
            $item += self::location($frame['file'] ?? null, $frame['line'] ?? null);
            $frames[] = $item;
        }
        $payload['trace'] = $frames;

        $previous = $error->getPrevious();
        if ($previous !== null) {
            $payload['previous'] = ['className' => get_class($previous), 'message' => $previous->getMessage()];
        }

        return $payload;
    }

    /**
     * Drops the runner's own frames (eval() and everything below it).
     *
     * @param array<int, array<string, mixed>> $trace
     * @return array<int, array<string, mixed>>
     */
    private static function userTrace(array $trace): array
    {
        $result = [];
        foreach ($trace as $frame) {
            if (($frame['function'] ?? '') === 'eval' || strpos((string) ($frame['class'] ?? ''), 'RunletRunner\\') === 0) {
                break;
            }
            $result[] = $frame;
        }

        return $result;
    }

    private static function finish(string $reason, ?float $executeStarted = null): void
    {
        if (self::$finished) {
            return;
        }
        self::$finished = true;
        self::$state = 'finished';
        Probe::finish();
        self::emitProfile();
        if (self::$inspector !== null) {
            self::$inspector->finish();
        }
        SnippetMessages::finish();
        $payload = [
            'reason' => $reason,
            'elapsedMs' => (int) round((microtime(true) - self::$startedAt) * 1000),
            'peakMemory' => \Runlet\Benchmark::realPeakMemory(),
        ];
        if ($executeStarted !== null) {
            $payload['executeMs'] = (int) round((microtime(true) - $executeStarted) * 1000);
        }
        Channel::emit('runnerFinished', $payload);
    }

    public static function shutdown(): void
    {
        if (self::$finished) {
            return;
        }
        $error = error_get_last();
        $fatalTypes = E_ERROR | E_PARSE | E_CORE_ERROR | E_COMPILE_ERROR | E_USER_ERROR | E_RECOVERABLE_ERROR;
        $driver = self::$driverContext;
        $driverFields = $driver === null ? [] : array_filter(['driverFile' => $driver['file'], 'driverClass' => $driver['class']]);
        if ($error !== null && ($error['type'] & $fatalTypes) !== 0) {
            $stage = in_array(self::$state, ['execute', 'commands', 'panels'], true) ? 'execute' : (self::$state === 'parse' ? 'parse' : 'bootstrap');
            $message = self::cleanMessage($error['message']);
            Channel::emit('error', [
                'stage' => $stage,
                'className' => 'FatalError',
                'message' => $driver === null ? $message : $driver['context'] . ': ' . $message,
                'fatal' => true,
            ] + $driverFields + self::location($error['file'], $error['line']));
            self::finish('fatal');

            return;
        }

        if (self::$state === 'bootstrap') {
            // exit()/die() while booting the application: nothing would explain the empty run.
            $message = ($driver === null ? 'The application' : $driver['context'] . ': the driver') . ' called exit() while Runlet was bootstrapping it.';
            $hint = self::bootstrapExitHint();
            Channel::emit('error', [
                'stage' => 'bootstrap',
                'className' => 'Exit',
                'message' => $hint === '' ? $message : $message . ' ' . $hint,
            ] + $driverFields);
            self::finish('error');

            return;
        }

        if (self::$state === 'commands' || self::$state === 'panels') {
            Channel::emit('error', [
                'stage' => 'execute',
                'className' => 'Exit',
                'message' => ($driver === null ? 'The application' : $driver['context'] . ': the driver') . ' called exit() while Runlet was ' . (self::$state === 'panels' ? 'reading its App Info.' : 'listing its commands.'),
            ] + $driverFields);
            self::finish('error');

            return;
        }

        self::finish(self::$ddCalled ? 'dd' : 'exit');
    }
}
}

/*
 * Snippet messages (#196): \Runlet\notice(), \Runlet\warning(), and \Runlet\error() (and the
 * same methods on \Runlet\Inspector) put notice, warning, and non-fatal error cards in Runlet's
 * output, with the line that called them. They are output, not inspector records: they show
 * whether the run inspector is on or off, and none of them ends the run or marks it failed.
 * Declared by the runner after Runner.php. See docs/snippet-api.md.
 *
 * Each card is a `notice` event with `level`, `user: true`, the caller's location, and an
 * optional `context` value and `exception`. Older app builds read only `message`.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

final class SnippetMessages
{
    /** Cards per run; the rest are counted in one notice when the run finishes. */
    public const MAX_MESSAGES = 200;
    /** Bytes of one card's message. */
    public const MAX_MESSAGE_BYTES = 16384;
    /** Bytes of all cards together (messages, contexts, traces); later cards are left out. */
    public const MAX_TOTAL_BYTES = 8388608;

    /** @var int */
    private static $shown = 0;
    /** @var int */
    private static $omitted = 0;
    /** @var int */
    private static $bytes = 0;
    /** @var array<string, int> */
    private static $limits = [];
    /** @var ValueNormalizer|null */
    private static $normalizer;
    /** @var bool */
    private static $finished = false;

    /**
     * The run's value limits (`request.limits`). Contexts use tighter ones, like the run
     * inspector's values.
     *
     * @param array<string, mixed> $limits
     */
    public static function configure(array $limits): void
    {
        self::$limits = ['maxDepth' => min(6, (int) ($limits['maxDepth'] ?? 8))];
        self::$normalizer = null;
    }

    /**
     * Shows one card. Never throws: a message Runlet cannot show is dropped.
     *
     * @param string $level notice, warning, or error
     * @param mixed $message a string, or (for errors) a Throwable
     * @param mixed $context
     */
    public static function emit(string $level, $message, $context = []): void
    {
        try {
            if (self::$finished) {
                return;
            }
            if (self::$shown >= self::MAX_MESSAGES) {
                self::$omitted++;

                return;
            }
            $payload = ['level' => in_array($level, ['notice', 'warning', 'error'], true) ? $level : 'notice', 'user' => true];
            if ($message instanceof \Throwable) {
                $details = Runner::describeThrowable($message);
                $text = (string) $details['message'];
                unset($details['message']);
                $payload['exception'] = $details;
            } else {
                $text = self::text($message);
            }
            [$text, $omittedBytes] = \Runlet\Inspector::clip($text, self::MAX_MESSAGE_BYTES);
            $payload = ['message' => $text] + $payload;
            if ($omittedBytes > 0) {
                $payload['omittedBytes'] = $omittedBytes;
            }
            $payload += \Runlet\Inspector::callerLocation();
            if ($context !== [] && $context !== null) {
                $payload['context'] = self::normalize($context);
            }
            $size = strlen((string) json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR));
            if (self::$bytes + $size > self::MAX_TOTAL_BYTES) {
                self::$omitted++;

                return;
            }
            self::$bytes += $size;
            self::$shown++;
            Channel::emit('notice', $payload);
        } catch (\Throwable $error) {
            // Showing a message must never break the snippet.
        }
    }

    /** Reports the cards the limits left out, once, when the run finishes. */
    public static function finish(): void
    {
        if (self::$finished) {
            return;
        }
        self::$finished = true;
        if (self::$omitted > 0) {
            Channel::emit('notice', ['message' => 'Runlet left out ' . self::$omitted . ' more ' . (self::$omitted === 1 ? 'card' : 'cards')
                . ' from \\Runlet\\notice(), warning(), and error(): a run shows at most ' . self::MAX_MESSAGES . ' of them (' . (int) (self::MAX_TOTAL_BYTES / 1048576) . ' MB in all).']);
        }
    }

    /**
     * A message that is not a string, as text: without calling the snippet's code, except
     * __toString() on a Stringable object.
     *
     * @param mixed $message
     */
    private static function text($message): string
    {
        if (is_string($message)) {
            return $message;
        }
        if ($message === null) {
            return '';
        }
        if (is_bool($message)) {
            return $message ? 'true' : 'false';
        }
        if (is_int($message)) {
            return (string) $message;
        }
        if (is_float($message)) {
            return ValueNormalizer::floatString($message);
        }
        if (is_object($message) && method_exists($message, '__toString')) {
            try {
                return (string) $message;
            } catch (\Throwable $error) {
                return \Runlet\Inspector::className(get_class($message));
            }
        }
        if (is_object($message)) {
            return \Runlet\Inspector::className(get_class($message));
        }
        if (is_array($message)) {
            return 'array(' . count($message) . ')';
        }

        return gettype($message);
    }

    /**
     * @param mixed $value
     * @return array<string, mixed>
     */
    private static function normalize($value): array
    {
        if (self::$normalizer === null) {
            self::$normalizer = new ValueNormalizer([
                'maxDepth' => self::$limits['maxDepth'] ?? 6,
                'maxChildren' => 100,
                'maxStringBytes' => 16384,
                'maxNodes' => 5000,
                'maxValueBytes' => 524288,
            ]);
        }
        try {
            return self::$normalizer->normalize($value);
        } catch (\Throwable $error) {
            return ['id' => 0, 'type' => 'unknown', 'scalar' => 'Runlet could not inspect this value: ' . $error->getMessage()];
        }
    }
}
}

namespace Runlet {

/**
 * Shows a notice card in Runlet's output, with the line that called it, like Runlet's own
 * notices. The run goes on. Works whether or not the run inspector is on.
 *
 *     \Runlet\notice('Imported 120 rows', ['skipped' => 3]);
 *
 * @param string $message the card's text (at most 16 KB is shown)
 * @param array<mixed> $context shown under the message as an expandable value, bounded like dumps
 */
function notice(string $message, array $context = []): void
{
    \RunletRunner\SnippetMessages::emit('notice', $message, $context);
}

/**
 * Shows a warning card in Runlet's output, with the line that called it. The run goes on.
 * Works whether or not the run inspector is on.
 *
 *     \Runlet\warning('Cache is cold', ['store' => 'redis']);
 *
 * @param string $message the card's text (at most 16 KB is shown)
 * @param array<mixed> $context shown under the message as an expandable value, bounded like dumps
 */
function warning(string $message, array $context = []): void
{
    \RunletRunner\SnippetMessages::emit('warning', $message, $context);
}

/**
 * Shows an error card in Runlet's output, with the line that called it, without ending the
 * run: the run goes on, and it isn't marked failed. Pass a caught Throwable to show its class,
 * message, where it was thrown, and its stack trace, like an uncaught error's card. Works
 * whether or not the run inspector is on.
 *
 *     try {
 *         $client->sync();
 *     } catch (\Throwable $e) {
 *         \Runlet\error($e, ['client' => $client->id]);
 *     }
 *
 * @param string|\Throwable $message the card's text (at most 16 KB is shown), or a Throwable
 * @param array<mixed> $context shown under the message as an expandable value, bounded like dumps
 */
function error($message, array $context = []): void
{
    \RunletRunner\SnippetMessages::emit('error', $message, $context);
}
}

/*
 * SQL tabs (#35): runs one statement from an SQL tab and reports it as an `sql` event. The
 * app generates the snippet that calls SqlTab::run() (Packages/RunletKit/Sources/RunletCore/
 * SQLTabs.swift); that code never holds credentials.
 *
 * Where the connection comes from, in order:
 *  0. a saved connection (#138), when the run carries one (SqlConnect.php): the user saved
 *     its definition for the target and its password in the Keychain; the request brings
 *     them on stdin, and the run booted no project code. A read-only one (#139) refuses
 *     writing and session-changing statements before connecting, and runs the rest in a
 *     read-only session;
 *  1. the booted driver's sqlConnection(): a project driver's own, or the built-in Laravel,
 *     Symfony (Doctrine), or WordPress (its PDO from wp-config.php, else $wpdb, #208:
 *     WordPressDatabase.php) driver's. The application's own connections need no
 *     credentials from Runlet;
 *  2. an Eloquent connection resolver or WordPress's $wpdb that the application set up;
 *  3. otherwise an SqlUnavailable error that says so.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

/** The project has no database connection SQL tabs can use. */
final class SqlUnavailable extends \RuntimeException
{
}

/** The chosen connection could not be opened (an unknown name, a driver error, …). */
final class SqlConnectionFailed extends \RuntimeException
{
}

/**
 * A read-only saved connection (#139) refused a statement before anything was sent. The app
 * refuses it first; this is the runner's own check.
 */
final class SqlReadOnlyRefused extends \RuntimeException
{
}

/**
 * Bound parameters (#145): a statement with placeholders can't be bound on this connection (a
 * callable has no binding API, MySQL refuses a name used twice), so nothing ran. Runlet never
 * writes values into the SQL instead.
 */
final class SqlParametersRefused extends \RuntimeException
{
}

/**
 * Load Next (#146): the next page couldn't run (the connection's driver changed, or the
 * database refused the row limit Runlet added). Nothing was appended.
 */
final class SqlPageFailed extends \RuntimeException
{
}

/**
 * Run All Statements (#129): a statement failed, so the run stopped. The message says which
 * statement, what the transaction did, and which statements did not run.
 */
final class SqlStatementFailed extends \RuntimeException
{
}

final class SqlTab
{
    /** Columns kept per row; later columns are left out and counted. */
    private const MAX_COLUMNS = 200;
    /** Bytes kept of each text cell. */
    private const MAX_CELL_BYTES = 8192;
    /** Bytes of cells per result; rows past it are left out. */
    private const MAX_RESULT_BYTES = 8388608;
    /** Bytes of a statement's text echoed back with its result (Run All). */
    private const MAX_STATEMENT_ECHO_BYTES = 2000;
    /** Built-in drivers and how the tab names their connection's origin. */
    private const BUILTIN_SOURCES = [
        'Runlet\Drivers\LaravelDriver' => 'Laravel DB::connection()',
        'Runlet\Drivers\SymfonyDriver' => 'Symfony Doctrine registry',
        'Runlet\Drivers\WordPressDriver' => 'WordPress $wpdb',
    ];

    /**
     * Runs `$sql` on the named (or default) connection and emits its `sql` event. With
     * `$schema`, it then reads the connection's tables and columns for completion (#128), as
     * an `sqlSchema` event that never fails the run.
     *
     * `$params` (#145) are the statement's bound values, each `name` (without `:`) or 1-based
     * `position`, a `type` (`str`, `int`, `decimal`, `bool`, `null`), and its `value`; they
     * are bound with PDOStatement::bindValue and never become part of the SQL.
     *
     * @param array<int, array<string, mixed>> $params
     */
    public static function run(string $sql, ?string $connection, int $maxRows, bool $schema = false, array $params = []): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        $maxRows = max(1, $maxRows);
        self::refuseOnReadOnly([['sql' => $sql, 'line' => 0]]);
        $names = self::connectionNames();
        [$source, $origin] = self::resolve($connection, $names);
        self::refuseUnbindable($source, $origin, [['sql' => $sql, 'line' => 0, 'params' => $params]]);
        SqlCancel::report($source, $connection); // #144: Stop can cancel the statement on the server.
        $started = hrtime(true);
        $common = ['source' => $origin, 'maxRows' => $maxRows] + self::connectionFields($connection);
        if (!$source instanceof \PDO) {
            $result = self::runCallable($source, $sql, $maxRows);
            $result['readNs'] = hrtime(true);
            $results = [$result];
        } else {
            // #154: every result set (a stored procedure's, a batch's), under one row and byte cap.
            $read = [];
            try {
                $results = self::runPdoSets($source, $sql, $maxRows, $params, $read);
            } catch (\Throwable $error) {
                // A later set failed: the sets read before it still show ("Result 1", …).
                self::emitResults($read, false, $common, $started, $names);
                throw $error;
            }
        }
        self::emitResults($results, true, $common, $started, $names);
        if ($schema) {
            self::emitSchema($connection, $source, $origin, $results[0]['driver'] ?? null);
        }

        return NoResult::instance();
    }

    /**
     * Emits a statement's results as `sql` events (#154): one for a single result, as before;
     * several labelled `resultSet` (index, and count when `$complete`) when the statement
     * returned more than one, or a later one failed after these were read. Each result's
     * `elapsedMs` runs from the statement's start to the end of reading it.
     *
     * @param array<int, array<string, mixed>> $results
     * @param array<string, mixed> $common Fields every result gets (source, maxRows, connection, statement).
     * @param string[] $names The connection names, sent with the first result.
     */
    private static function emitResults(array $results, bool $complete, array $common, int $started, array $names): void
    {
        $count = count($results);
        foreach (array_values($results) as $index => $result) {
            $result['elapsedMs'] = round(((int) ($result['readNs'] ?? hrtime(true)) - $started) / 1e6, 3);
            unset($result['readNs']);
            $result += $common;
            if ($index === 0 && $names !== []) {
                $result['connections'] = $names;
            }
            if ($count > 1 || !$complete) {
                $result['resultSet'] = $complete ? ['index' => $index + 1, 'count' => $count] : ['index' => $index + 1];
            }
            Channel::emit('sql', $result);
        }
    }

    /**
     * Load Next (#146): one page of a statement whose result the row cap cut, as an `sql`
     * event. The app builds `$sql` (SQLPaging in RunletCore): the statement as written, or with
     * a row limit added to its end (`$added`, e.g. `LIMIT 1001 OFFSET 1000`, written for PDO
     * driver `$driver`, which the connection must still be). `$skip` rows are fetched and
     * discarded first when the database doesn't skip them itself. `$params` are the first
     * run's bound values (#145). A read-only saved connection (#139) refuses as for a run.
     *
     * @param array<int, array<string, mixed>> $params
     */
    public static function page(string $sql, ?string $connection, int $maxRows, int $skip, ?string $driver, array $params = [], ?string $added = null): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        $maxRows = max(1, $maxRows);
        $skip = max(0, $skip);
        self::refuseOnReadOnly([['sql' => $sql, 'line' => 0]]);
        $names = self::connectionNames();
        [$source, $origin] = self::resolve($connection, $names);
        if ($driver !== null) {
            $actual = $source instanceof \PDO ? self::pdoDriverName($source) : null;
            if (self::dialect($actual) !== self::dialect($driver)) {
                throw new SqlPageFailed('The connection is ' . ($actual === null ? 'no longer a PDO connection' : 'a ' . $actual . ' connection now') . ', and Load Next wrote the next page for ' . $driver . '. Run the statement again.');
            }
        }
        self::refuseUnbindable($source, $origin, [['sql' => $sql, 'line' => 0, 'params' => $params]]);
        SqlCancel::report($source, $connection); // #144
        $started = hrtime(true);
        try {
            $result = $source instanceof \PDO ? self::runPdo($source, $sql, $maxRows, $params, $skip) : self::runCallable($source, $sql, $maxRows, $skip);
        } catch (DriverFailure $failure) {
            throw $failure;
        } catch (SqlParametersRefused $refused) {
            throw $refused;
        } catch (\Throwable $error) {
            if ($added === null) {
                throw $error;
            }
            throw new SqlPageFailed($error->getMessage() . "\n\nLoad Next added \u{201C}" . $added . "\u{201D} to the end of the statement. If the database can't take that, add LIMIT and OFFSET to the statement yourself.", 0, $error);
        }
        if (!isset($result['columns'])) {
            throw new SqlPageFailed('The statement returned no rows this time (' . (int) ($result['affectedRows'] ?? 0) . ' affected), so there is no next page.');
        }
        $result['elapsedMs'] = round((hrtime(true) - $started) / 1e6, 3);
        $result['source'] = $origin;
        $result['maxRows'] = $maxRows;
        $result += self::connectionFields($connection);
        Channel::emit('sql', $result);

        return NoResult::instance();
    }

    /**
     * Export Query to CSV and Import CSV (#152, SqlCsv.php): the run's connection for `$sql`,
     * after the refusals a run makes first (a read-only connection's, #139; values that can't
     * be bound, #145).
     *
     * @param array<int, array<string, mixed>> $params
     * @return array{0: \PDO|callable, 1: string, 2: ?string, 3: array<string, mixed>} The connection, where it came from, its PDO driver, and a result's `connection` fields.
     */
    public static function openFor(string $sql, ?string $connection, array $params = []): array
    {
        self::refuseOnReadOnly([['sql' => $sql, 'line' => 0]]);
        [$source, $origin] = self::resolve($connection, self::connectionNames());
        self::refuseUnbindable($source, $origin, [['sql' => $sql, 'line' => 0, 'params' => $params]]);

        return [$source, $origin, $source instanceof \PDO ? self::pdoDriverName($source) : null, self::connectionFields($connection)];
    }

    /**
     * Bound values (#145) for SqlCsv's statements (#152), in run()'s shape.
     *
     * @param array<int, array<string, mixed>> $params
     */
    public static function bindValues(\PDOStatement $statement, array $params): void
    {
        self::bind($statement, $params);
    }

    /** sqlsrv and dblib are both SQL Server; sqlite2 is SQLite. */
    private static function dialect(?string $driver): ?string
    {
        switch ($driver) {
            case 'dblib':
                return 'sqlsrv';
            case 'sqlite2':
                return 'sqlite';
            default:
                return $driver;
        }
    }

    /**
     * Test Connection (#138): opens the run's saved connection and emits an `sqlTest` event
     * (server version, current database and user, round trip). No statement of the user's.
     */
    public static function test(): NoResult
    {
        if (!SqlConnect::isConfigured()) {
            throw new SqlUnavailable('Test Connection needs a saved connection, and this run has none.');
        }
        Channel::emit('sqlTest', SqlConnect::test());

        return NoResult::instance();
    }

    /**
     * Stop (#144): cancels the running statement of session `$session` (reported by the run's
     * `sqlSession` event) on the same connection, opened again in this second runner, and
     * emits an `sqlCancel` event. `$statement` must be the dialect's own cancel statement
     * (SqlCancel::statement()); `$server` is the run's server fingerprint. Runlet's statement,
     * not the user's: read-only connections (#139) allow it.
     */
    public static function cancel(string $dialect, int $session, string $statement, ?string $connection, string $server = ''): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        [$source, $origin] = self::resolve($connection, []);
        Channel::emit('sqlCancel', SqlCancel::cancel($source, $origin, $dialect, $session, $statement, $server));

        return NoResult::instance();
    }

    /**
     * Explain Statement (#147): the plan of `$sql` on the tab's connection, as an `sqlPlan`
     * event. Plain Explain never runs the statement; `$analyze` runs it, guarded (SqlExplain).
     * `$params` are bound values (#145), in run()'s shape.
     *
     * @param array<int, array<string, mixed>> $params
     */
    public static function explain(string $sql, ?string $connection, bool $analyze, array $params = []): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        SqlExplain::refuseEarly($sql, $analyze);
        $names = self::connectionNames();
        [$source, $origin] = self::resolve($connection, $names);
        self::refuseUnbindable($source, $origin, [['sql' => $sql, 'line' => 0, 'params' => $params]]);
        SqlCancel::report($source, $connection); // #144
        $driverName = $source instanceof \PDO ? self::pdoDriverName($source) : (WordPressDatabase::isWpdb($origin) ? 'mysql' : null);
        $bind = static function (\PDOStatement $statement) use ($params): void {
            self::bind($statement, $params);
        };
        $started = hrtime(true);
        $plan = SqlExplain::explain($source, $origin, $driverName, $sql, $analyze, $bind);
        $plan['elapsedMs'] = round((hrtime(true) - $started) / 1e6, 3);
        $plan['source'] = $origin;
        $plan += self::connectionFields($connection);
        if ($names !== []) {
            $plan['connections'] = $names;
        }
        Channel::emit('sqlPlan', $plan);

        return NoResult::instance();
    }

    /**
     * The `connection` of a result: the tab's application connection name (null for the
     * default), or a saved connection's name with `saved` (#138).
     *
     * @return array<string, mixed>
     */
    private static function connectionFields(?string $connection): array
    {
        return SqlConnect::isConfigured() ? ['connection' => SqlConnect::name(), 'saved' => true] : ['connection' => $connection];
    }

    /**
     * Schema (#128): emits the connection's tables and columns as an `sqlSchema` event. Only
     * names and types are read, never rows. Loading the schema is explicit (the SQL bar's
     * Load Schema) or follows a statement that ran.
     */
    public static function schema(?string $connection): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        [$source, $origin] = self::resolve($connection, self::connectionNames());
        self::emitSchema($connection, $source, $origin, $source instanceof \PDO ? self::pdoDriverName($source) : null, true);

        return NoResult::instance();
    }

    /**
     * Show Definition (#148): emits the definition (DDL) of one table or view as an
     * `sqlDefinition` event (SqlDefinition). Only the catalog is read; nothing is created,
     * changed, or run, and the app shows the DDL in a read-only sheet.
     */
    public static function definition(string $table, ?string $connection): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        [$source, $origin] = self::resolve($connection, self::connectionNames());
        $driverName = $source instanceof \PDO ? self::pdoDriverName($source) : null;
        $started = hrtime(true);
        try {
            $read = SqlDefinition::read($source, $origin, $driverName, $table);
        } catch (DriverFailure | SqlUnavailable | SqlDefinitionNotFound $refused) {
            throw $refused;
        } catch (\Throwable $error) {
            throw new SqlConnectionFailed('Runlet could not read the definition of ' . $table . ': ' . $error->getMessage(), 0, $error);
        }
        $payload = ['driver' => $driverName ?? ($read['dialect'] ?? null), 'source' => $origin] + self::connectionFields($connection) + $read;
        unset($payload['dialect']);
        $payload['elapsedMs'] = round((hrtime(true) - $started) / 1e6, 3);
        Channel::emit('sqlDefinition', array_filter($payload, static function ($value): bool {
            return $value !== null;
        }));

        return NoResult::instance();
    }

    /**
     * The Database pane's Server section (#150): emits the server's overview, sizes, and
     * sessions (`$parts`, all when empty) on the tab's connection as an `sqlServer` event
     * (SqlServerInfo). Only the catalog and the server's status are read, never table rows.
     *
     * @param string[] $parts
     */
    public static function server(array $parts, ?string $connection): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        [$source, $origin] = self::resolve($connection, self::connectionNames());
        $driverName = $source instanceof \PDO ? self::pdoDriverName($source) : null;
        $started = hrtime(true);
        try {
            $read = SqlServerInfo::read($source, $origin, $driverName, $parts);
        } catch (DriverFailure | SqlUnavailable $refused) {
            throw $refused;
        } catch (\Throwable $error) {
            throw new SqlConnectionFailed('Runlet could not read the server details: ' . $error->getMessage(), 0, $error);
        }
        $payload = ['driver' => $driverName, 'source' => $origin] + self::connectionFields($connection) + $read;
        unset($payload['dialect']);
        $payload['elapsedMs'] = round((hrtime(true) - $started) / 1e6, 3);
        Channel::emit('sqlServer', array_filter($payload, static function ($value): bool {
            return $value !== null;
        }));

        return NoResult::instance();
    }

    /**
     * The Server section's Cancel Query or Kill Session (#150), confirmed in the app: sends
     * `$statement` (SqlServerInfo::statement()) for `$session` on the same connection, opened
     * again in this runner, and emits an `sqlServerAction` event. `$server` is the list's server
     * fingerprint, `$listedBy` the session the list was read with (refused, like this runner's
     * own), and `$user`/`$started` what the list showed for the session. Runlet's statement,
     * not the user's: read-only connections (#139) allow it.
     */
    public static function serverAction(string $action, string $dialect, int $session, string $statement, ?string $connection, string $server, int $listedBy, string $user = '', string $started = ''): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        [$source, $origin] = self::resolve($connection, []);
        $driverName = $source instanceof \PDO ? self::pdoDriverName($source) : null;
        Channel::emit('sqlServerAction', SqlServerInfo::act($source, $origin, $driverName, $action, $dialect, $session, $statement, $server, $listedBy, $user, $started));

        return NoResult::instance();
    }

    /**
     * Browse Table (#151): one page of a table, read with the SELECT the app wrote (quoted names
     * from the schema, filter values in `$params`, bound), as an `sql` event. `$driver` is the
     * PDO driver it was written for (null for a callable connection, read without bound
     * values). The SELECT asks for one row more than `$pageSize`, so `truncated` says whether
     * another page follows (SqlTable).
     *
     * @param array<int, array<string, mixed>> $params
     */
    public static function browse(string $sql, ?string $connection, int $pageSize, ?string $driver, array $params = []): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        $pageSize = max(1, $pageSize);
        $names = self::connectionNames();
        [$source, $origin] = self::resolve($connection, $names);
        SqlTable::checkBrowse($sql, $source instanceof \PDO ? self::pdoDriverName($source) : null, $driver);
        self::refuseUnbindable($source, $origin, [['sql' => $sql, 'line' => 0, 'params' => $params]]);
        SqlCancel::report($source, $connection); // #144
        $started = hrtime(true);
        $result = $source instanceof \PDO ? self::runPdo($source, $sql, $pageSize, $params) : self::runCallable($source, $sql, $pageSize);
        $result['elapsedMs'] = round((hrtime(true) - $started) / 1e6, 3);
        $result['source'] = $origin;
        $result['maxRows'] = $pageSize;
        $result += self::connectionFields($connection);
        Channel::emit('sql', $result);

        return NoResult::instance();
    }

    /**
     * Apply in Browse Table (#151): the changes the user reviewed (UPDATE, INSERT, and DELETE
     * statements the app wrote, each with its bound `params`), in one transaction where each
     * must affect exactly one row (SqlTable::apply()). Emits an `sql` event per change and a
     * notice once committed; otherwise everything is rolled back and the error says which
     * change and why. A read-only saved connection (#139) refuses before connecting, and a
     * callable connection, which can't bind values, is refused.
     *
     * @param array<int, array<string, mixed>> $statements
     */
    public static function applyEdits(array $statements, ?string $connection, ?string $driver): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        $statements = array_values($statements);
        SqlTable::checkEdits($statements);
        self::refuseOnReadOnly($statements);
        [$source, $origin] = self::resolve($connection, []);
        if (!$source instanceof \PDO) {
            throw new SqlTableRefused('Browse Table changes rows only through a PDO connection, which binds values, and this connection (' . $origin . ') runs statements through a callable. Nothing ran.');
        }
        $driverName = self::pdoDriverName($source);
        SqlTable::checkDialect($driverName, $driver, 'Review Changes');
        SqlCancel::report($source, $connection, true); // #144
        $bind = static function (\PDOStatement $statement, array $params): void {
            self::bind($statement, $params);
        };
        foreach (SqlTable::apply($source, $driverName, $statements, $bind) as $result) {
            Channel::emit('sql', $result + ['source' => $origin] + self::connectionFields($connection));
        }
        Channel::emit('notice', ['message' => SqlTable::committed(count($statements))]);

        return NoResult::instance();
    }

    /**
     * @param \PDO|callable $source
     */
    private static function emitSchema(?string $connection, $source, string $origin, ?string $driverName, bool $throw = false): void
    {
        $started = hrtime(true);
        $payload = ['driver' => $driverName, 'source' => $origin] + self::connectionFields($connection);
        try {
            $read = SqlSchema::read($connection, $source, $origin, $driverName);
            $payload = array_merge($payload, $read);
        } catch (DriverFailure $failure) {
            if ($throw) {
                throw $failure;
            }
            $payload['error'] = $failure->getMessage();
        } catch (\Throwable $error) {
            if ($throw) {
                throw new SqlConnectionFailed('Runlet could not read the schema: ' . $error->getMessage(), 0, $error);
            }
            $payload['error'] = 'Runlet could not read the schema: ' . $error->getMessage();
        }
        $payload['elapsedMs'] = round((hrtime(true) - $started) / 1e6, 3);
        Channel::emit('sqlSchema', array_filter($payload, static function ($value): bool {
            return $value !== null;
        }));
    }

    /**
     * Run All Statements (#129): runs `$statements` in order on one connection and emits an
     * `sql` event per statement (with `statement`: index, count, line, and text). Stops at the
     * first error. With `$transaction`, the run is one transaction: committed after the last
     * statement, rolled back when one fails. MySQL and MariaDB commit some statements at once
     * (CREATE, ALTER, DROP, … flagged `implicitCommit` by the app): Runlet says so before
     * running and opens a new transaction after each of them, so a later failure rolls back
     * only what came after.
     *
     * With `$schema`, the connection's tables and columns follow when every statement ran (#128).
     * A statement's `params` are its bound values (#145, see run()).
     *
     * @param array<int, array{sql: string, line: int, implicitCommit?: bool, params?: array<int, array<string, mixed>>}> $statements
     */
    public static function runAll(array $statements, ?string $connection, int $maxRows, bool $transaction, bool $schema = false): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        $maxRows = max(1, $maxRows);
        $statements = array_values($statements);
        $count = count($statements);
        if ($count === 0) {
            throw new \InvalidArgumentException('There are no statements to run.');
        }
        self::refuseOnReadOnly($statements);
        $names = self::connectionNames();
        [$source, $origin] = self::resolve($connection, $names);
        $driverName = $source instanceof \PDO ? self::pdoDriverName($source) : (WordPressDatabase::isWpdb($origin) ? 'mysql' : null);
        // #145: a statement whose values can't be bound refuses the whole script, before anything runs.
        self::refuseUnbindable($source, $origin, $statements);
        SqlCancel::report($source, $connection, $transaction); // #144
        $commitsAtOnce = $transaction && in_array($driverName, ['mysql', 'oci'], true);
        if ($commitsAtOnce) {
            $flagged = [];
            foreach ($statements as $index => $statement) {
                if (!empty($statement['implicitCommit'])) {
                    $flagged[] = ($index + 1) . ' (line ' . (int) $statement['line'] . ')';
                }
            }
            if ($flagged !== []) {
                Channel::emit('notice', ['message' => ($driverName === 'oci' ? 'Oracle' : 'MySQL') . ' commits ' . (count($flagged) === 1 ? 'statement ' : 'statements ') . self::listing($flagged)
                    . ' at once, with everything before ' . (count($flagged) === 1 ? 'it' : 'them') . ', even in a transaction. If a later statement fails, only the statements after the last of them are rolled back.']);
            }
        }
        if ($transaction) {
            try {
                self::begin($source);
            } catch (DriverFailure $failure) {
                throw $failure;
            } catch (\Throwable $error) {
                throw new SqlConnectionFailed('Runlet could not start a transaction on this connection: ' . $error->getMessage() . ' Nothing ran. To run the statements without one, turn off "In a Transaction" in the SQL bar.', 0, $error);
            }
        }
        $committedThrough = 0;
        foreach ($statements as $index => $statement) {
            $sql = (string) $statement['sql'];
            $line = (int) $statement['line'];
            $started = hrtime(true);
            $common = ['source' => $origin, 'maxRows' => $maxRows] + self::connectionFields($connection)
                + ['statement' => ['index' => $index + 1, 'count' => $count, 'line' => $line, 'text' => self::echoed($sql)]];
            $read = [];
            try {
                if ($index > 0) {
                    // #139: whatever the statement before did, the next one runs read-only.
                    SqlConnect::enforceReadOnly();
                }
                $params = isset($statement['params']) && is_array($statement['params']) ? $statement['params'] : [];
                if ($source instanceof \PDO) {
                    $results = self::runPdoSets($source, $sql, $maxRows, $params, $read); // #154
                } else {
                    $results = [self::runCallable($source, $sql, $maxRows) + ['readNs' => hrtime(true)]];
                }
            } catch (DriverFailure $failure) {
                throw $failure;
            } catch (\Throwable $error) {
                // #154: the result sets read before a later one failed still show.
                self::emitResults($read, false, $common, $started, $index === 0 ? $names : []);
                $notes = [];
                if ($transaction) {
                    $notes[] = self::rollBack($source, $index, $committedThrough);
                }
                if ($index + 1 < $count) {
                    $notes[] = ($index + 2 === $count ? 'Statement ' . $count . ' did' : 'Statements ' . ($index + 2) . '–' . $count . ' did') . ' not run.';
                }
                throw new SqlStatementFailed('Statement ' . ($index + 1) . ' of ' . $count . ' (line ' . $line . '): ' . $error->getMessage() . "\n\n" . implode(' ', $notes), 0, $error);
            }
            self::emitResults($results, true, $common, $started, $index === 0 ? $names : []);
            if ($commitsAtOnce && !empty($statement['implicitCommit'])) {
                // The database ended the transaction; the rest of the run gets a new one.
                $committedThrough = $index + 1;
                self::endImplicitlyCommitted($source);
                self::begin($source);
            }
        }
        if ($transaction) {
            try {
                self::commit($source);
            } catch (DriverFailure $failure) {
                throw $failure;
            } catch (\Throwable $error) {
                throw new SqlStatementFailed('All ' . $count . ' statements ran, but Runlet could not commit the transaction: ' . $error->getMessage() . ' The database has probably rolled it back.', 0, $error);
            }
            Channel::emit('notice', ['message' => 'Committed the transaction: ' . ($count === 1 ? 'the statement ran' : 'all ' . $count . ' statements ran') . '.']);
        }
        if ($schema) {
            self::emitSchema($connection, $source, $origin, $driverName);
        }

        return NoResult::instance();
    }

    /**
     * Read-only saved connections (#139): refuses the whole run, before the connection is
     * opened, when any statement would write or make the session writable again.
     *
     * @param array<int, array{sql: string, line: int}> $statements
     */
    private static function refuseOnReadOnly(array $statements): void
    {
        if (!SqlConnect::isConfigured() || !SqlConnect::isReadOnly()) {
            return;
        }
        $count = count($statements);
        foreach (array_values($statements) as $index => $statement) {
            $why = SqlReadOnly::refusal((string) $statement['sql'], SqlConnect::driverName());
            if ($why === null) {
                continue;
            }
            $name = '"' . SqlConnect::name() . '"';
            throw new SqlReadOnlyRefused($count === 1
                ? 'Runlet refused this statement on the read-only connection ' . $name . ': it ' . $why . '. Nothing ran.'
                : 'Statement ' . ($index + 1) . ' of ' . $count . ' (line ' . (int) $statement['line'] . ') ' . $why . ', so Runlet ran none of the script on the read-only connection ' . $name . '. Nothing ran.');
        }
    }

    /**
     * Bound parameters (#145): refuses the run, before anything runs, when a statement has
     * values this connection can't bind. A callable connection (WordPress's $wpdb, Doctrine
     * without PDO, a driver's callable) has no binding API, and Runlet never writes values
     * into the SQL instead. MySQL's native prepares (which Runlet uses, so a second statement
     * can't slip through) refuse a name used more than once.
     *
     * @param \PDO|callable $source
     * @param array<int, array<string, mixed>> $statements
     */
    private static function refuseUnbindable($source, string $origin, array $statements): void
    {
        $count = count($statements);
        $driverName = $source instanceof \PDO ? self::pdoDriverName($source) : null;
        foreach (array_values($statements) as $index => $statement) {
            $params = isset($statement['params']) && is_array($statement['params']) ? $statement['params'] : [];
            if ($params === []) {
                continue;
            }
            $which = $count === 1 ? 'This statement has' : 'Statement ' . ($index + 1) . ' of ' . $count . ' (line ' . (int) $statement['line'] . ') has';
            if (!$source instanceof \PDO) {
                throw new SqlParametersRefused(WordPressDatabase::isWpdb($origin)
                    ? $which . ' placeholders, and this connection (' . $origin . ') runs statements through WordPress\'s $wpdb, without bound values. Runlet never writes values into the SQL, so nothing ran. Use $wpdb->prepare() in a PHP tab, or write the values into the statement yourself.'
                    : $which . ' placeholders, and this connection (' . $origin . ') runs statements through a callable, which can\'t bind values. Runlet never writes values into the SQL, so nothing ran. Return a PDO from the driver\'s sqlConnection() to bind values, run the query from a PHP tab, or write the values into the statement yourself.');
            }
            if ($driverName !== 'mysql') {
                continue;
            }
            foreach ($params as $param) {
                $uses = (int) ($param['uses'] ?? 1);
                if (isset($param['name']) && $uses > 1) {
                    throw new SqlParametersRefused($which . ' :' . $param['name'] . ' ' . $uses . ' times. MySQL and MariaDB can\'t bind one name in several places when the statement is prepared natively, as Runlet prepares it. Give each place its own name (:' . $param['name'] . ', :' . $param['name'] . '_2), or use ? placeholders. Nothing ran.');
                }
            }
        }
    }

    /**
     * Bound parameters (#145): each value with its PDO type. Text and decimals are PARAM_STR
     * (PDO has no decimal type, so a DECIMAL column keeps every digit), integers PARAM_INT,
     * booleans PARAM_BOOL, and NULL PARAM_NULL.
     *
     * @param array<int, array<string, mixed>> $params
     */
    private static function bind(\PDOStatement $statement, array $params): void
    {
        foreach ($params as $param) {
            $value = $param['value'] ?? null;
            switch ((string) ($param['type'] ?? 'str')) {
                case 'int':
                    $type = \PDO::PARAM_INT;
                    $value = (int) $value;
                    break;
                case 'bool':
                    $type = \PDO::PARAM_BOOL;
                    $value = (bool) $value;
                    break;
                case 'null':
                    $type = \PDO::PARAM_NULL;
                    $value = null;
                    break;
                default:
                    $type = \PDO::PARAM_STR;
                    $value = (string) $value;
            }
            $placeholder = isset($param['name']) ? ':' . $param['name'] : '?' . (int) ($param['position'] ?? 0);
            try {
                $bound = $statement->bindValue(isset($param['name']) ? ':' . $param['name'] : (int) ($param['position'] ?? 0), $value, $type);
            } catch (\PDOException $error) {
                throw new SqlParametersRefused('Runlet could not bind ' . $placeholder . ': ' . $error->getMessage() . ' PDO may read the statement differently than Runlet (a placeholder inside a string, a comment, or a quoted name).', 0, $error);
            }
            if ($bound === false) {
                throw new SqlParametersRefused('Runlet could not bind ' . $placeholder . '. PDO may read the statement differently than Runlet (a placeholder inside a string, a comment, or a quoted name).');
            }
        }
    }

    /** @param callable|\PDO $source */
    private static function begin($source): void
    {
        if ($source instanceof \PDO) {
            $source->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
            $source->beginTransaction();

            return;
        }
        $source('BEGIN');
    }

    /** @param callable|\PDO $source */
    private static function commit($source): void
    {
        if ($source instanceof \PDO) {
            if ($source->inTransaction()) {
                $source->commit();
            }

            return;
        }
        $source('COMMIT');
    }

    /**
     * After a statement the database committed at once: PHP 8 already sees no transaction;
     * PHP 7.4 still thinks one is open, and COMMIT ends it without changing anything.
     *
     * @param callable|\PDO $source
     */
    private static function endImplicitlyCommitted($source): void
    {
        try {
            if ($source instanceof \PDO) {
                if ($source->inTransaction()) {
                    $source->commit();
                }
            } else {
                // MySQL ignores a COMMIT without a transaction; elsewhere (WordPress on
                // SQLite, …) it commits here, as MySQL did.
                $source('COMMIT');
            }
        } catch (\Throwable $error) {
            // Nothing was open any more.
        }
    }

    /**
     * Rolls back after statement `$failed` (0-based) failed and says what that undid.
     *
     * @param callable|\PDO $source
     */
    private static function rollBack($source, int $failed, int $committedThrough): string
    {
        try {
            if ($source instanceof \PDO) {
                if ($source->inTransaction()) {
                    $source->rollBack();
                }
            } else {
                $source('ROLLBACK');
            }
        } catch (\Throwable $error) {
            return 'Runlet could not roll back the transaction: ' . $error->getMessage() . ($failed > 0 ? ' Check what ' . ($failed === 1 ? 'statement 1' : 'statements 1–' . $failed) . ' changed.' : '');
        }
        $first = $committedThrough + 1;
        $undone = $failed < $first ? 'Rolled back the transaction.' : 'Rolled back the transaction: ' . ($failed === $first ? 'statement ' . $first . ' was' : 'statements ' . $first . '–' . $failed . ' were') . ' undone.';
        if ($committedThrough > 0) {
            $undone .= ' ' . ($committedThrough === 1 ? 'Statement 1 stays' : 'Statements 1–' . $committedThrough . ' stay') . ': the database committed ' . ($committedThrough === 1 ? 'it' : 'them') . ' at statement ' . $committedThrough . '.';
        }

        return $undone;
    }

    /** @param string[] $items "1, 2 and 3" */
    private static function listing(array $items): string
    {
        if (count($items) < 2) {
            return implode('', $items);
        }

        return implode(', ', array_slice($items, 0, -1)) . ' and ' . $items[count($items) - 1];
    }

    /** A statement's text for its result card, cut at a UTF-8 boundary. */
    private static function echoed(string $sql): string
    {
        $sql = trim($sql);
        if (strlen($sql) <= self::MAX_STATEMENT_ECHO_BYTES) {
            return $sql;
        }
        $cut = substr($sql, 0, self::MAX_STATEMENT_ECHO_BYTES);
        while ($cut !== '' && preg_match('//u', $cut) !== 1) {
            $cut = substr($cut, 0, -1);
        }

        return $cut . '…';
    }

    private static function pdoDriverName(\PDO $pdo): ?string
    {
        try {
            return (string) $pdo->getAttribute(\PDO::ATTR_DRIVER_NAME);
        } catch (\Throwable $error) {
            return null;
        }
    }

    /**
     * The connection to use and where it came from.
     *
     * @param string[] $names
     * @return array{0: \PDO|callable, 1: string}
     */
    private static function resolve(?string $connection, array $names): array
    {
        if (SqlConnect::isConfigured()) {
            // A saved connection (#138): opened here, in a process that booted no project code.
            return [SqlConnect::pdo(), SqlConnect::origin()];
        }
        $driver = Runner::bootedDriver();
        $known = $names === [] ? '' : ' Connections: ' . implode(', ', $names) . '.';
        try {
            if ($driver !== null) {
                $source = Runner::callBootedDriver('sqlConnection()', static function () use ($driver, $connection) {
                    return $driver->sqlConnection($connection);
                });
                if ($source !== null) {
                    $declaring = (new \ReflectionMethod($driver, 'sqlConnection'))->getDeclaringClass()->getName();
                    if (!$source instanceof \PDO && !is_callable($source)) {
                        throw new \UnexpectedValueException($declaring . '::sqlConnection() returned ' . (is_object($source) ? get_class($source) : gettype($source)) . '; return a PDO, a callable, or null.');
                    }

                    if ($declaring === 'Runlet\Drivers\WordPressDriver') {
                        // #208: "WordPress (PDO from wp-config)" or "WordPress ($wpdb, because …)".
                        return [$source, WordPressDatabase::origin() ?? self::BUILTIN_SOURCES[$declaring]];
                    }

                    return [$source, self::BUILTIN_SOURCES[$declaring] ?? $declaring . '::sqlConnection()'];
                }
            }
            $detected = self::detect($connection);
        } catch (DriverFailure $failure) {
            throw $failure;
        } catch (\Throwable $error) {
            $what = $connection === null ? 'the default connection' : 'the "' . $connection . '" connection';
            throw new SqlConnectionFailed('Runlet could not open ' . $what . ': ' . $error->getMessage() . $known, 0, $error);
        }
        if ($detected !== null) {
            return $detected;
        }
        $name = $driver === null ? 'none' : $driver->name();
        throw new SqlUnavailable('This project has no database connection that SQL tabs can use. Its driver (' . $name . ') provides none, and the application set up no Eloquent connection or WordPress $wpdb. '
            . 'To run SQL here, save a connection for this target (New Connection… in the SQL bar\'s connection menu; its password goes to the Keychain), or return one from sqlConnection() in a project driver (.runlet/<Name>Driver.php; see "SQL connections" in the drivers guide).');
    }

    /**
     * A connection the application set up without its driver saying so: Eloquent's
     * connection resolver (Laravel, or illuminate/database through Capsule) or $wpdb. Only
     * classes that are already loaded count; nothing is autoloaded to find out.
     *
     * @return array{0: \PDO|callable, 1: string}|null
     */
    private static function detect(?string $connection): ?array
    {
        $model = 'Illuminate\Database\Eloquent\Model';
        if (class_exists($model, false) && method_exists($model, 'getConnectionResolver')) {
            $resolver = $model::getConnectionResolver();
            if (is_object($resolver)) {
                return [\Runlet\SqlConnections::eloquent($resolver, $connection), 'Eloquent connection resolver'];
            }
        }
        $wpdb = $GLOBALS['wpdb'] ?? null;
        if (is_object($wpdb) && class_exists('wpdb', false) && $wpdb instanceof \wpdb) {
            if ($connection !== null) {
                throw new \InvalidArgumentException('WordPress has one database connection ($wpdb), not "' . $connection . '".');
            }

            return [\Runlet\SqlConnections::wpdb($wpdb), 'WordPress $wpdb'];
        }

        return null;
    }

    /** @return string[] The driver's connection names (default first), cleaned; [] when it lists none. */
    private static function connectionNames(): array
    {
        $driver = Runner::bootedDriver();
        if ($driver === null || SqlConnect::isConfigured()) {
            return [];
        }
        try {
            $names = Runner::callBootedDriver('sqlConnections()', static function () use ($driver): array {
                return $driver->sqlConnections();
            });
        } catch (\Throwable $error) {
            Channel::emit('notice', ['message' => 'The connection list is unavailable: ' . $error->getMessage()]);

            return [];
        }
        $clean = [];
        foreach ($names as $name) {
            if ((is_string($name) || is_int($name)) && (string) $name !== '' && strlen((string) $name) <= 200 && !in_array((string) $name, $clean, true)) {
                $clean[] = (string) $name;
            }
        }

        return array_slice($clean, 0, 100);
    }

    /**
     * @param array<int, array<string, mixed>> $params Bound values (#145).
     * @param int $skip Rows to fetch and discard first (Load Next, #146).
     * @return array<string, mixed>
     */
    private static function runPdo(\PDO $pdo, string $sql, int $maxRows, array $params = [], int $skip = 0): array
    {
        $read = [];
        $results = self::runPdoSets($pdo, $sql, $maxRows, $params, $read, $skip, false);
        unset($results[0]['readNs']);

        return $results[0];
    }

    /**
     * Runs `$sql` and reads its result sets (#154): after the first, the next ones while the
     * driver has more (`PDOStatement::nextRowset()`: MySQL and MariaDB procedures, SQL Server
     * batches; SQLite and PostgreSQL return one). The row cap and the result size cap apply to
     * all of them together. A set without columns reports its affected rows. A last set that
     * has no columns and changed nothing, after others, is MySQL's status of the CALL itself
     * and is left out. `$read` holds the sets read so far, for the caller to show when a later
     * one fails.
     *
     * @param array<int, array<string, mixed>> $params Bound values (#145).
     * @param array<int, array<string, mixed>> $read
     * @param int $skip Rows of the first set to fetch and discard first (Load Next, #146).
     * @param bool $everySet false reads only the first set (Load Next pages single results).
     * @return array<int, array<string, mixed>> Each with `readNs` (hrtime when it was read).
     */
    private static function runPdoSets(\PDO $pdo, string $sql, int $maxRows, array $params, array &$read, int $skip = 0, bool $everySet = true): array
    {
        $driverName = self::pdoDriverName($pdo);
        $restore = [\PDO::ATTR_ERRMODE => $pdo->getAttribute(\PDO::ATTR_ERRMODE)];
        $pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        $attributes = [];
        if ($driverName === 'mysql' || $params !== []) {
            // Native prepares, so MySQL refuses several statements in one run, and bound values
            // (#145) go to the database apart from the SQL rather than being quoted into it by
            // PDO (drivers without the setting, such as SQLite, always bind natively).
            $attributes[\PDO::ATTR_EMULATE_PREPARES] = false;
        }
        if ($driverName === 'mysql') {
            // Unbuffered, so a large result is not held in memory beyond the rows Runlet keeps.
            $buffered = defined('Pdo\Mysql::ATTR_USE_BUFFERED_QUERY') ? constant('Pdo\Mysql::ATTR_USE_BUFFERED_QUERY') : (defined('PDO::MYSQL_ATTR_USE_BUFFERED_QUERY') ? constant('PDO::MYSQL_ATTR_USE_BUFFERED_QUERY') : null);
            if ($buffered !== null) {
                $attributes[(int) $buffered] = false;
            }
        }
        foreach ($attributes as $attribute => $value) {
            try {
                $previous = $pdo->getAttribute($attribute);
                if ($pdo->setAttribute($attribute, $value)) {
                    $restore[$attribute] = $previous;
                }
            } catch (\Throwable $error) {
                // The attribute isn't supported here: keep the connection's setting.
            }
        }
        try {
            $statement = $pdo->prepare($sql);
            self::bind($statement, $params);
            $statement->execute();
            $budget = ['rows' => $maxRows, 'bytes' => 0];
            do {
                $set = self::readSet($statement, $driverName, $budget, $read === [] ? $skip : 0, $read !== []);
                $set['readNs'] = hrtime(true);
                $read[] = $set;
            } while ($everySet && self::nextRowset($statement, $driverName));
            if (isset($set['columns'])) {
                $statement->closeCursor();
            }
            $last = $read[count($read) - 1];
            if (count($read) > 1 && !isset($last['columns']) && (int) ($last['affectedRows'] ?? 0) === 0) {
                array_pop($read);
            }

            return $read;
        } finally {
            foreach ($restore as $attribute => $value) {
                try {
                    $pdo->setAttribute($attribute, $value);
                } catch (\Throwable $error) {
                    // Best effort: the run ends right after this anyway.
                }
            }
        }
    }

    /**
     * One result set of `$statement`: its columns and rows within `$budget` (rows left, bytes
     * used by the sets before it), or the rows it affected.
     *
     * @param array{rows: int, bytes: int} $budget
     * @return array<string, mixed>
     */
    private static function readSet(\PDOStatement $statement, ?string $driverName, array &$budget, int $skip, bool $later): array
    {
        $count = $statement->columnCount();
        if ($count > 0 && $later) {
            // After a set with columns, MySQL keeps reporting its column count for a set that
            // has none (a procedure's UPDATE, or the CALL's own status); such a set has no meta.
            try {
                $meta = $statement->getColumnMeta(0);
            } catch (\Throwable $error) {
                $meta = false;
            }
            if (!is_array($meta)) {
                $count = 0;
            }
        }
        if ($count <= 0) {
            return ['driver' => $driverName, 'affectedRows' => $statement->rowCount()];
        }
        $columns = [];
        for ($index = 0; $index < min($count, self::MAX_COLUMNS); $index++) {
            $meta = false;
            try {
                $meta = $statement->getColumnMeta($index);
            } catch (\Throwable $error) {
                $meta = false;
            }
            $columns[] = is_array($meta) && isset($meta['name']) && $meta['name'] !== '' ? (string) $meta['name'] : 'column ' . ($index + 1);
        }
        $rows = [];
        $bytes = 0;
        $truncation = null;
        while ($skip > 0 && $statement->fetch(\PDO::FETCH_NUM) !== false) {
            $skip--;
        }
        while (($row = $statement->fetch(\PDO::FETCH_NUM)) !== false) {
            if (count($rows) >= $budget['rows']) {
                $truncation = 'rows';
                break;
            }
            if ($budget['bytes'] + $bytes >= self::MAX_RESULT_BYTES) {
                $truncation = 'bytes';
                break;
            }
            $cells = [];
            foreach (array_slice($row, 0, count($columns)) as $value) {
                $cells[] = self::cell($value, $bytes);
            }
            $rows[] = $cells;
        }
        $budget['rows'] = max(0, $budget['rows'] - count($rows));
        $budget['bytes'] += $bytes;

        return array_filter([
            'driver' => $driverName,
            'columns' => $columns,
            'rows' => $rows,
            'truncated' => $truncation !== null ? true : null,
            'truncation' => $truncation,
            'omittedColumns' => $count > count($columns) ? $count - count($columns) : null,
            'bytes' => $bytes,
        ], static function ($value): bool {
            return $value !== null;
        });
    }

    /**
     * Moves to the statement's next result set (#154). SQLite and PostgreSQL have one, and
     * keep today's behaviour (nothing is asked); a driver without multiple result sets
     * (SQLSTATE IM001) has no more. A later statement of a procedure that failed throws.
     */
    private static function nextRowset(\PDOStatement $statement, ?string $driverName): bool
    {
        if ($driverName === null || in_array($driverName, ['sqlite', 'sqlite2', 'pgsql'], true)) {
            return false;
        }
        try {
            return $statement->nextRowset();
        } catch (\PDOException $error) {
            if ((string) $error->getCode() === 'IM001') {
                return false;
            }
            throw $error;
        }
    }

    /**
     * @param int $skip Rows to pass over first (Load Next, #146).
     * @return array<string, mixed>
     */
    private static function runCallable(callable $run, string $sql, int $maxRows, int $skip = 0): array
    {
        $returned = $run($sql);
        if (is_int($returned)) {
            return ['affectedRows' => $returned];
        }
        if (!is_iterable($returned)) {
            throw new \UnexpectedValueException('The SQL connection callable returned ' . (is_object($returned) ? get_class($returned) : gettype($returned)) . '; return the rows (an iterable of arrays or objects) or the number of affected rows (an int).');
        }
        $columns = [];
        $positions = [];
        $omitted = [];
        $records = [];
        $bytes = 0;
        $truncation = null;
        foreach ($returned as $row) {
            if ($skip > 0) {
                $skip--;
                continue;
            }
            if (count($records) >= $maxRows) {
                $truncation = 'rows';
                break;
            }
            if ($bytes >= self::MAX_RESULT_BYTES) {
                $truncation = 'bytes';
                break;
            }
            $fields = is_object($row) ? get_object_vars($row) : (is_array($row) ? $row : ['value' => $row]);
            $cells = [];
            foreach ($fields as $key => $value) {
                $key = (string) $key;
                if (!isset($positions[$key])) {
                    if (count($columns) >= self::MAX_COLUMNS) {
                        $omitted[$key] = true;
                        continue;
                    }
                    $positions[$key] = count($columns);
                    $columns[] = $key;
                }
                $cells[$positions[$key]] = self::cell($value, $bytes);
            }
            $records[] = $cells;
        }
        $rows = [];
        foreach ($records as $cells) {
            $row = [];
            for ($index = 0; $index < count($columns); $index++) {
                $row[] = array_key_exists($index, $cells) ? $cells[$index] : null;
            }
            $rows[] = $row;
        }

        return array_filter([
            'columns' => $columns,
            'rows' => $rows,
            'truncated' => $truncation !== null ? true : null,
            'truncation' => $truncation,
            'omittedColumns' => $omitted === [] ? null : count($omitted),
            'bytes' => $bytes,
        ], static function ($value): bool {
            return $value !== null;
        });
    }

    /**
     * One cell as JSON: null, a bool, a number, or text; an object for text Runlet shortened
     * (`text`, `omittedBytes`; -1 when the full size is unknown) or bytes that aren't UTF-8
     * (`binary` byte count, `hex` of the first 32 bytes).
     *
     * @param mixed $value
     * @return mixed
     */
    private static function cell($value, int &$bytes)
    {
        if ($value === null || is_bool($value) || is_int($value)) {
            $bytes += 8;

            return $value;
        }
        if (is_float($value)) {
            $bytes += 16;

            return is_finite($value) ? $value : (string) $value;
        }
        $unknownLength = false;
        if (is_resource($value)) {
            // Large objects (PostgreSQL bytea, Oracle LOBs) arrive as streams.
            $read = @stream_get_contents($value, self::MAX_CELL_BYTES + 1);
            $value = $read === false ? '' : $read;
            $unknownLength = strlen($value) > self::MAX_CELL_BYTES;
        } elseif ($value instanceof \DateTimeInterface) {
            $value = $value->format('Y-m-d H:i:s.uP');
        } elseif (is_object($value)) {
            $value = method_exists($value, '__toString') ? (string) $value : get_class($value);
        } elseif (is_array($value)) {
            $encoded = json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR);
            $value = $encoded === false ? 'array' : $encoded;
        }
        $string = (string) $value;
        $length = strlen($string);
        if (preg_match('//u', $string) !== 1) {
            $bytes += 80;

            return ['binary' => $unknownLength ? -1 : $length, 'hex' => strtoupper(bin2hex(substr($string, 0, 32)))];
        }
        if ($length > self::MAX_CELL_BYTES) {
            $cut = substr($string, 0, self::MAX_CELL_BYTES);
            while ($cut !== '' && preg_match('//u', $cut) !== 1) {
                $cut = substr($cut, 0, -1);
            }
            $bytes += strlen($cut);

            return ['text' => $cut, 'omittedBytes' => $unknownLength ? -1 : $length - strlen($cut)];
        }
        $bytes += $length;

        return $string;
    }
}
}

namespace RunletRunner {

final class MongoTab
{
    private static $definition;
    private static $password;

    public static function configure(array $definition): void
    {
        self::$password = (string) ($definition['password'] ?? '');
        Channel::addSecret(self::$password);
        unset($definition['password']);
        self::$definition = $definition;
    }

    private static function connect(?string $name): array
    {
        if (!extension_loaded('mongodb')) {
            throw new \RuntimeException('MongoDB needs ext-mongodb. Choose Connect from this Mac with a PHP that has it, or install ext-mongodb on the target.');
        }
        if (self::$definition === null) {
            $driver = Runner::bootedDriver();
            if ($driver !== null && method_exists($driver, 'mongoConnection')) {
                $connection = Runner::callBootedDriver('mongoConnection()', static function () use ($driver, $name) { return $driver->mongoConnection($name); });
                if (is_array($connection) && ($connection['manager'] ?? null) instanceof \MongoDB\Driver\Manager && is_string($connection['database'] ?? null)) {
                    return [$connection['manager'], $connection['database']];
                }
            }
            if (class_exists('Illuminate\Support\Facades\DB')) {
                $connection = \Illuminate\Support\Facades\DB::connection($name ?? 'mongodb');
                // laravel-mongodb 5.2 and later: getClient() (getMongoClient() is deprecated there, #207).
                $client = method_exists($connection, 'getClient') ? $connection->getClient() : null;
                if ($client === null && method_exists($connection, 'getMongoClient')) { $client = $connection->getMongoClient(); }
                if (is_object($client) && method_exists($client, 'getManager')) {
                    return [$client->getManager(), $connection->getDatabaseName()];
                }
            }
            throw new \RuntimeException('Choose a saved MongoDB connection, a Laravel MongoDB connection, or a project driver mongoConnection() hook.');
        }
        $definition = self::$definition;
        [$uri, $options] = self::clientOptions($definition, (string) self::$password);
        try {
            $manager = new \MongoDB\Driver\Manager($uri, $options);
        } finally {
            self::$password = null;
            unset($options['password']);
        }
        return [$manager, (string) ($definition['database'] ?? '')];
    }

    /**
     * The URI and options for a saved definition (#191, #207), without connecting: host and port
     * (or `mongodb+srv://` with the host only; the driver looks up the SRV and TXT records when
     * it connects), SCRAM with the password or X.509 with the client certificate (against
     * `$external`), replica set, read preference, a tunnel's direct connection, and TLS: the CA
     * file, the client certificate and key (combined into a private temporary file when they're
     * two), and Verify CA (`tlsAllowInvalidHostnames`). The driver always checks the CA.
     */
    public static function clientOptions(array $definition, string $password): array
    {
        $mongo = $definition['mongo'] ?? [];
        $host = (string) ($definition['host'] ?? '');
        if (!preg_match('/^[A-Za-z0-9._:\[\]-]+$/D', $host)) { throw new \RuntimeException('Invalid MongoDB host.'); }
        $srv = ($mongo['srv'] ?? false) === true;
        $tunnel = $definition['tunnel'] ?? null;
        if ($srv && $tunnel !== null) { throw new \RuntimeException('SRV cannot use an SSH tunnel.'); }
        $port = (int) ($definition['port'] ?? 27017);
        if ($port < 1 || $port > 65535) { throw new \RuntimeException('Invalid MongoDB port.'); }
        if ($tunnel !== null) { $host = '127.0.0.1'; $port = (int) $tunnel['port']; }
        if (strpos($host, ':') !== false && $host[0] !== '[') { $host = '[' . $host . ']'; }
        $uri = ($srv ? 'mongodb+srv://' : 'mongodb://') . $host . ($srv ? '' : ':' . $port);
        $timeout = max(1, min(300, (int) ($definition['timeout'] ?? 10))) * 1000;
        $options = ['connectTimeoutMS' => $timeout, 'serverSelectionTimeoutMS' => $timeout, 'socketTimeoutMS' => 30000, 'appname' => 'Runlet'];
        $mechanism = (string) ($mongo['authMechanism'] ?? '');
        if (!in_array($mechanism, ['', 'SCRAM-SHA-1', 'SCRAM-SHA-256', 'MONGODB-X509'], true)) { throw new \RuntimeException('Unsupported MongoDB authentication mechanism.'); }
        if ($mechanism === 'MONGODB-X509') {
            // #207: the client certificate authenticates; the user name, when given, is its subject.
            $options['authMechanism'] = 'MONGODB-X509';
            $options['authSource'] = '$external';
            if (($definition['user'] ?? '') !== '') { $options['username'] = $definition['user']; }
        } elseif (($definition['user'] ?? '') !== '') {
            $options['username'] = $definition['user'];
            $options['password'] = $password;
            $options['authSource'] = $mongo['authDatabase'] ?? 'admin';
            if ($mechanism !== '') { $options['authMechanism'] = $mechanism; }
        }
        foreach (['replicaSet', 'readPreference'] as $key) {
            if (($mongo[$key] ?? '') !== '') { $options[$key] = $mongo[$key]; }
        }
        if ($tunnel !== null) { $options['directConnection'] = true; }
        $tls = $definition['tls'] ?? null;
        if (isset($tls['mode'])) {
            if (!in_array($tls['mode'], ['disable', 'verify-ca', 'verify-full'], true)) { throw new \RuntimeException('Unsupported MongoDB TLS mode.'); }
            $options['tls'] = $tls['mode'] !== 'disable';
            if ($tls['mode'] === 'verify-ca') { $options['tlsAllowInvalidHostnames'] = true; }
            if ($options['tls']) {
                foreach (['ca' => 'CA file', 'cert' => 'client certificate', 'key' => 'client key'] as $key => $label) {
                    $path = $tls[$key] ?? null;
                    if (is_string($path) && $path !== '' && !is_readable($path)) { throw new \RuntimeException('The TLS ' . $label . ' isn\'t readable where the connection opens: ' . $path); }
                }
                if (($tls['ca'] ?? '') !== '') { $options['tlsCAFile'] = $tls['ca']; }
                $cert = (string) ($tls['cert'] ?? '');
                $key = (string) ($tls['key'] ?? '');
                if ($key !== '' && $cert === '') { throw new \RuntimeException('A TLS client key needs its client certificate.'); }
                if ($cert !== '') { $options['tlsCertificateKeyFile'] = $key === '' || $key === $cert ? $cert : self::combinedPEM($cert, $key); }
            }
        }
        if ($mechanism === 'MONGODB-X509' && !isset($options['tlsCertificateKeyFile'])) { throw new \RuntimeException('X.509 authentication needs TLS with a client certificate.'); }
        return [$uri, $options];
    }

    /**
     * The driver reads one PEM with the certificate and its key: a private (0600) temporary copy
     * of both, removed when the runner ends. The driver reads it whenever it opens a connection.
     */
    private static function combinedPEM(string $cert, string $key): string
    {
        $path = tempnam(sys_get_temp_dir(), 'runlet-mongo-');
        if ($path === false) { throw new \RuntimeException('Runlet couldn\'t combine the TLS client certificate and key: no writable temporary folder. Use one PEM with both as the client certificate.'); }
        chmod($path, 0600);
        register_shutdown_function(static function () use ($path): void { @unlink($path); });
        $contents = @file_get_contents($cert);
        $private = @file_get_contents($key);
        if ($contents === false || $private === false || file_put_contents($path, rtrim($contents) . "\n" . rtrim($private) . "\n") === false) {
            throw new \RuntimeException('Runlet couldn\'t combine the TLS client certificate and key. Use one PEM with both as the client certificate.');
        }
        return $path;
    }

    public static function validate(string $json): array
    {
        if (strlen($json) > 1048576) { throw new \RuntimeException('MongoDB query exceeds 1 MiB.'); }
        $query = json_decode($json);
        if (!$query instanceof \stdClass) { throw new \RuntimeException('Enter one MongoDB JSON query object.'); }
        $fields = [
            'find' => ['filter', 'projection', 'sort', 'skip', 'limit', 'explain'],
            'findOne' => ['filter', 'projection', 'sort'],
            'aggregate' => ['pipeline', 'explain'], 'countDocuments' => ['filter'],
            'distinct' => ['filter', 'field'], 'getIndexes' => [],
            'insertOne' => ['documents'], 'insertMany' => ['documents'],
            'updateOne' => ['filter', 'update'], 'updateMany' => ['filter', 'update'],
            'replaceOne' => ['filter', 'replacement'], 'deleteOne' => ['filter'],
            'deleteMany' => ['filter'], 'drop' => [], 'createIndex' => ['keys', 'unique'],
            'listDatabases' => [], 'listCollections' => [], 'sampleSchema' => [],
            'dropDatabase' => ['database'],
        ];
        $operation = $query->operation ?? '';
        if (!is_string($operation) || !isset($fields[$operation])) { throw new \RuntimeException('Unsupported MongoDB operation.'); }
        if (array_diff(array_keys(get_object_vars($query)), array_merge($operation === 'dropDatabase' ? ['operation'] : ['collection', 'operation'], $fields[$operation]))) { throw new \RuntimeException('Unknown fields for this MongoDB operation.'); }
        if ($operation === 'dropDatabase') {
            // #207: the query names the database; run() checks it is the connection's.
            $name = $query->database ?? '';
            if (!is_string($name) || $name === '' || strlen($name) > 63 || preg_match('/[\/\\\\. "$*<>:|?\x00]/', $name) || in_array(strtolower($name), ['admin', 'local', 'config'], true)) { throw new \RuntimeException('dropDatabase names the connection\'s database (admin, local and config can\'t be dropped).'); }
            $query->collection = '';
        } else {
            $collection = $query->collection ?? '';
            if (!is_string($collection) || $collection === '' || strlen($collection) > 120 || strpos($collection, "\0") !== false || strpos($collection, 'system.') === 0) { throw new \RuntimeException('Invalid collection name.'); }
        }
        foreach (['filter', 'projection', 'sort', 'update', 'replacement', 'keys'] as $key) {
            if (property_exists($query, $key) && !$query->$key instanceof \stdClass) { throw new \RuntimeException($key . ' must be an object.'); }
        }
        foreach (['skip', 'limit'] as $key) {
            if (property_exists($query, $key) && (!is_int($query->$key) || $query->$key < 0 || $query->$key > 1000000)) { throw new \RuntimeException($key . ' must be an integer from 0 to 1000000.'); }
        }
        foreach (['explain', 'unique'] as $key) {
            if (property_exists($query, $key) && !is_bool($query->$key)) { throw new \RuntimeException($key . ' must be boolean.'); }
        }
        if ($operation === 'aggregate') {
            if (!isset($query->pipeline) || !is_array($query->pipeline)) { throw new \RuntimeException('aggregate requires a pipeline array.'); }
            foreach ($query->pipeline as $stage) {
                if (!$stage instanceof \stdClass || count(get_object_vars($stage)) !== 1) { throw new \RuntimeException('Each pipeline stage must be a single-key object.'); }
            }
        }
        if ($operation === 'distinct' && (!isset($query->field) || !is_string($query->field) || $query->field === '')) { throw new \RuntimeException('distinct requires field.'); }
        if (strpos($operation, 'insert') === 0) {
            if (!isset($query->documents) || !is_array($query->documents) || count($query->documents) < 1 || count($query->documents) > 1000 || ($operation === 'insertOne' && count($query->documents) !== 1)) { throw new \RuntimeException('Insert requires documents.'); }
            foreach ($query->documents as $document) { if (!$document instanceof \stdClass) { throw new \RuntimeException('Each document must be an object.'); } }
        }
        foreach (['updateOne' => 'update', 'updateMany' => 'update', 'replaceOne' => 'replacement', 'createIndex' => 'keys'] as $method => $key) {
            if ($operation === $method && (!isset($query->$key) || ($key !== 'replacement' && count(get_object_vars($query->$key)) === 0))) { throw new \RuntimeException($operation . ' requires ' . $key . '.'); }
        }
        if (self::hasKey($query, ['$where', '$function', '$accumulator', '$code'])) { throw new \RuntimeException('Server-side JavaScript is not supported.'); }
        $read = in_array($operation, ['find', 'findOne', 'aggregate', 'countDocuments', 'distinct', 'getIndexes', 'listDatabases', 'listCollections', 'sampleSchema'], true) && !self::hasKey($query->pipeline ?? [], ['$out', '$merge']);
        $destructive = $operation === 'drop' || $operation === 'dropDatabase' || (in_array($operation, ['deleteMany', 'updateMany'], true) && count(get_object_vars($query->filter ?? new \stdClass())) === 0);
        if (($query->explain ?? false) && !$read) { throw new \RuntimeException('Explain is available only for reads.'); }
        return [$query, $read, $destructive];
    }

    private static function hasKey($value, array $keys): bool
    {
        if (!is_array($value) && !is_object($value)) { return false; }
        foreach ($value as $key => $child) {
            if (in_array($key, $keys, true) || self::hasKey($child, $keys)) { return true; }
        }
        return false;
    }

    public static function run(array $request): NoResult
    {
        ini_set('zend.exception_ignore_args', '1');
        [$query, $read, $destructive] = self::validate((string) ($request['query'] ?? ''));
        if ((self::$definition['readOnly'] ?? false) && !$read) { throw new \RuntimeException('Read-only MongoDB connection refused ' . $query->operation . '. Nothing ran.'); }
        if ($destructive && ($request['confirmed'] ?? false) !== true) { throw new \RuntimeException('Confirm MongoDB ' . $query->operation . ' before running.'); }
        try {
            [$manager, $database] = self::connect($request['connection'] ?? null);
            if ($database === '') { throw new \RuntimeException('Choose a database in the connection settings.'); }
            if ($query->operation === 'dropDatabase' && $query->database !== $database) {
                throw new \RuntimeException('dropDatabase names “' . $query->database . '”, but the connection\'s database is “' . $database . '”. Nothing ran.');
            }
            $query = class_exists('MongoDB\BSON\Document')
                ? \MongoDB\BSON\Document::fromJSON(json_encode($query))->toPHP()
                : \MongoDB\BSON\toPHP(\MongoDB\BSON\fromJSON(json_encode($query)));
            $size = max(1, min(1000, (int) ($request['pageSize'] ?? 100)));
            $offset = max(0, min(1000000, (int) ($request['offset'] ?? 0)));
            // #207: the operation runs on one selected server (the read preference's for reads, the
            // primary for writes), tagged with the run's id, so Stop can find it there and kill it.
            $server = $manager->selectServer($read ? $manager->getReadPreference() : new \MongoDB\Driver\ReadPreference('primary'));
            $tag = self::tag($server);
            if ($tag !== null) { self::reportSession($server, $tag, $request['connection'] ?? null); }
            $started = microtime(true);
            $documents = self::execute($server, $database, $query, $size, $offset, $tag);
            $rows = [];
            $bytes = 0;
            $cut = false;
            foreach ($documents as $document) {
                $json = class_exists('MongoDB\BSON\Document')
                    ? \MongoDB\BSON\Document::fromPHP((object) $document)->toCanonicalExtendedJSON()
                    : \MongoDB\BSON\toCanonicalExtendedJSON(\MongoDB\BSON\fromPHP((object) $document));
                $bytes += strlen($json);
                if (count($rows) >= $size || $bytes > 4194304) { $cut = true; break; }
                $rows[] = self::clean(json_decode($json, true));
            }
            self::emit($rows, $query->operation, (microtime(true) - $started) * 1000, $request['connection'] ?? null);
            if ($cut) { Channel::emit('notice', ['message' => 'MongoDB output reached its document or 4 MiB size limit. Narrow the filter or projection to see the omitted data.']); }
        } catch (\Throwable $error) {
            // Runlet's own messages (a plain RuntimeException) say what to do; driver errors are replaced.
            if (!extension_loaded('mongodb') || get_class($error) === \RuntimeException::class) { throw $error; }
            throw new \RuntimeException('MongoDB ' . $query->operation . ' failed. Check the connection, permissions, and query shape. Driver code: ' . (int) $error->getCode());
        }
        return NoResult::instance();
    }

    /** Runs the operation on `$server` (#207), its commands carrying `comment: $tag` when there is one. */
    private static function execute(\MongoDB\Driver\Server $server, string $database, $query, int $size, int $offset, ?string $tag)
    {
        $manager = $server;
        $operation = $query->operation;
        $collection = $query->collection;
        $filter = $query->filter ?? new \stdClass();
        $comment = $tag === null ? [] : ['comment' => $tag];
        if ($operation === 'listDatabases') {
            $result = $manager->executeReadCommand('admin', new \MongoDB\Driver\Command(['listDatabases' => 1, 'nameOnly' => true, 'authorizedDatabases' => true] + $comment))->toArray();
            return array_slice($result[0]->databases ?? [], 0, $size);
        }
        if ($operation === 'listCollections') {
            $cursor = $manager->executeReadCommand($database, new \MongoDB\Driver\Command(['listCollections' => 1, 'nameOnly' => true, 'authorizedCollections' => true, 'cursor' => ['batchSize' => 100]] + $comment));
            $collections = [];
            foreach ($cursor as $item) {
                if (count($collections) >= 100) { break; }
                $count = null;
                try {
                    $stats = $manager->executeReadCommand($database, new \MongoDB\Driver\Command(['collStats' => $item->name, 'maxTimeMS' => 5000] + $comment))->toArray();
                    $count = $stats[0]->count ?? null;
                } catch (\Throwable $ignored) {}
                $collections[] = (object) ['name' => $item->name, 'type' => $item->type ?? 'collection', 'estimatedCount' => $count];
            }
            return $collections;
        }
        if ($operation === 'sampleSchema') {
            $cursor = $manager->executeReadCommand($database, new \MongoDB\Driver\Command(['aggregate' => $collection, 'pipeline' => [['$sample' => ['size' => 50]]], 'cursor' => new \stdClass(), 'maxTimeMS' => 10000] + $comment));
            $fields = [];
            foreach ($cursor as $document) {
                foreach ($document as $name => $value) {
                    $fields[$name][self::typeName($value)] = true;
                }
            }
            $rows = [];
            foreach ($fields as $name => $types) { $rows[] = (object) ['field' => $name, 'types' => implode(', ', array_keys($types))]; }
            return array_slice($rows, 0, 200);
        }
        if ($operation === 'find' || $operation === 'findOne') {
            $limit = $operation === 'findOne' ? 1 : min($size, max(0, ($query->limit ?? 1000000) - $offset));
            if ($limit === 0) { return []; }
            $options = ['limit' => $limit, 'skip' => ($query->skip ?? 0) + $offset, 'maxTimeMS' => 25000];
            foreach (['projection', 'sort'] as $key) { if (isset($query->$key)) { $options[$key] = $query->$key; } }
            // #228: the tag goes with the projection and sort, not instead of them.
            $tagged = $options + $comment;
            if (!($query->explain ?? false)) { return $manager->executeQuery($database . '.' . $collection, new \MongoDB\Driver\Query($filter, $tagged)); }
            $command = ['explain' => ['find' => $collection, 'filter' => $filter] + $options, 'verbosity' => 'queryPlanner'] + $comment;
        } elseif ($operation === 'aggregate' || $operation === 'countDocuments') {
            $pipeline = $operation === 'countDocuments' ? [(object) ['$match' => $filter], (object) ['$count' => 'count']] : $query->pipeline;
            if (!self::hasKey($pipeline, ['$out', '$merge'])) {
                if ($offset > 0) { $pipeline[] = (object) ['$skip' => $offset]; }
                $pipeline[] = (object) ['$limit' => $size];
            }
            $command = ['aggregate' => $collection, 'pipeline' => $pipeline, 'cursor' => new \stdClass(), 'maxTimeMS' => 25000];
            $command = ($query->explain ?? false) ? ['explain' => $command, 'verbosity' => 'queryPlanner'] + $comment : $command + $comment;
        } elseif ($operation === 'distinct') {
            $result = $manager->executeReadCommand($database, new \MongoDB\Driver\Command(['distinct' => $collection, 'key' => $query->field, 'query' => $filter, 'maxTimeMS' => 25000] + $comment))->toArray();
            return array_map(static function ($value) { return (object) ['value' => $value]; }, array_slice($result[0]->values ?? [], $offset, $size));
        } elseif ($operation === 'getIndexes') {
            $command = ['listIndexes' => $collection, 'cursor' => new \stdClass()] + $comment;
        } elseif ($operation === 'dropDatabase') {
            $manager->executeWriteCommand($database, new \MongoDB\Driver\Command(['dropDatabase' => 1] + $comment));
            return [(object) ['dropped' => $database]];
        } elseif ($operation === 'drop') {
            return $manager->executeWriteCommand($database, new \MongoDB\Driver\Command(['drop' => $collection] + $comment));
        } elseif ($operation === 'createIndex') {
            $command = ['createIndexes' => $collection, 'indexes' => [['key' => $query->keys, 'name' => 'runlet_' . substr(hash('sha256', json_encode($query->keys)), 0, 12), 'unique' => $query->unique ?? false]]] + $comment;
            return $manager->executeWriteCommand($database, new \MongoDB\Driver\Command($command));
        } else {
            $bulk = new \MongoDB\Driver\BulkWrite($comment !== [] && version_compare((string) phpversion('mongodb'), '1.14.0', '>=') ? $comment : []);
            if (strpos($operation, 'insert') === 0) {
                foreach ($query->documents as $document) { $bulk->insert($document); }
            } elseif (strpos($operation, 'delete') === 0) {
                $bulk->delete($filter, ['limit' => $operation === 'deleteOne' ? 1 : 0]);
            } else {
                $bulk->update($filter, $query->update ?? $query->replacement, ['multi' => $operation === 'updateMany', 'upsert' => false]);
            }
            $result = $manager->executeBulkWrite($database . '.' . $collection, $bulk);
            return [(object) ['inserted' => $result->getInsertedCount(), 'matched' => $result->getMatchedCount(), 'modified' => $result->getModifiedCount(), 'deleted' => $result->getDeletedCount()]];
        }
        if (self::hasKey($query->pipeline ?? [], ['$out', '$merge'])) { return $manager->executeReadWriteCommand($database, new \MongoDB\Driver\Command($command)); }
        return $manager->executeReadCommand($database, new \MongoDB\Driver\Command($command));
    }

    private static function clean($value)
    {
        if (is_string($value)) { return Channel::scrub(preg_replace('~(mongodb(?:\+srv)?://)[^\s/"<>]*@~i', '$1[redacted]@', $value)); }
        if (is_array($value)) {
            $clean = [];
            foreach ($value as $key => $child) { $clean[is_string($key) ? self::clean($key) : $key] = self::clean($child); }
            return $clean;
        }
        return $value;
    }

    /**
     * A sampled value's BSON type, short (#207): ObjectId, UTCDateTime, Decimal128, Binary,
     * Timestamp, Regex, … for the extension's classes; object, array, string, int, double,
     * bool and null for the others.
     */
    public static function typeName($value): string
    {
        if (is_object($value)) {
            if ($value instanceof \stdClass || $value instanceof \MongoDB\BSON\Document) { return 'object'; }
            if ($value instanceof \MongoDB\BSON\PackedArray) { return 'array'; }
            $class = get_class($value);
            $slash = strrpos($class, '\\');
            return $slash === false ? $class : substr($class, $slash + 1);
        }
        switch (gettype($value)) {
            case 'integer': return 'int';
            case 'double': return 'double';
            case 'boolean': return 'bool';
            case 'NULL': return 'null';
            case 'array': return 'array';
            default: return 'string';
        }
    }

    /**
     * A table cell for a value of canonical Extended JSON (#207), as the tree's type tags say:
     * ObjectId("…"), a date as Runlet shows SQL dates (2026-01-01 00:00:00.000+00:00, UTC),
     * Decimal128 and doubles as their exact text, 32- and 64-bit integers as numbers, binary as
     * BinData(subtype, "base64") or UUID("…"). Documents and arrays read like mongosh:
     * { status: "paid", placed: ISODate("2026-01-01T00:00:00.000Z") }.
     */
    public static function cell($value)
    {
        if (!is_array($value)) { return $value; }
        $special = self::special($value, false);
        return $special !== null ? $special : self::shell($value);
    }

    /** mongosh-like text of a document, an array, or a value inside them. */
    private static function shell($value): string
    {
        if (!is_array($value)) { return (string) json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR); }
        $special = self::special($value, true);
        if ($special !== null) { return (string) $special; }
        if ($value === []) { return '{}'; }
        $parts = [];
        if (array_keys($value) === range(0, count($value) - 1)) {
            foreach ($value as $child) { $parts[] = self::shell($child); }
            return '[' . implode(', ', $parts) . ']';
        }
        foreach ($value as $key => $child) {
            $key = (string) $key;
            $parts[] = (preg_match('/^[A-Za-z_$][A-Za-z0-9_$]*$/D', $key) ? $key : json_encode($key, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)) . ': ' . self::shell($child);
        }
        return '{ ' . implode(', ', $parts) . ' }';
    }

    /** A BSON type in canonical Extended JSON, as text (int for integers in a cell); null for others. */
    private static function special(array $value, bool $nested)
    {
        $keys = array_keys($value);
        if (count($keys) !== 1 || !is_string($keys[0]) || $keys[0] === '' || $keys[0][0] !== '$') { return null; }
        $inner = $value[$keys[0]];
        switch ($keys[0]) {
            case '$oid':
                return is_string($inner) ? 'ObjectId("' . $inner . '")' : null;
            case '$date':
                $ms = is_array($inner) && isset($inner['$numberLong']) ? $inner['$numberLong'] : $inner;
                if (is_string($ms) && preg_match('/^-?\d{1,19}$/D', $ms)) { $ms = (int) $ms; }
                if (!is_int($ms)) { return is_string($inner) ? $inner : null; }
                $seconds = intdiv($ms, 1000);
                $millis = $ms % 1000;
                if ($millis < 0) { $millis += 1000; $seconds--; }
                $date = (new \DateTimeImmutable('@' . $seconds))->setTimezone(new \DateTimeZone('UTC'));
                return $nested
                    ? 'ISODate("' . $date->format('Y-m-d\TH:i:s') . sprintf('.%03d', $millis) . 'Z")'
                    : $date->format('Y-m-d H:i:s') . sprintf('.%03d', $millis) . '+00:00';
            case '$numberInt':
            case '$numberLong':
                if (!is_string($inner) || !preg_match('/^-?\d{1,19}$/D', $inner)) { return null; }
                return $nested ? $inner : (int) $inner;
            case '$numberDouble':
                return is_string($inner) ? $inner : null;
            case '$numberDecimal':
                return is_string($inner) ? ($nested ? 'Decimal128("' . $inner . '")' : $inner) : null;
            case '$binary':
                if (!is_array($inner) || !isset($inner['base64'], $inner['subType'])) { return null; }
                $bytes = base64_decode((string) $inner['base64'], true);
                if (in_array($inner['subType'], ['03', '04'], true) && $bytes !== false && strlen($bytes) === 16) {
                    $hex = bin2hex($bytes);
                    return 'UUID("' . substr($hex, 0, 8) . '-' . substr($hex, 8, 4) . '-' . substr($hex, 12, 4) . '-' . substr($hex, 16, 4) . '-' . substr($hex, 20) . '")';
                }
                $subtype = hexdec((string) $inner['subType']);
                if (strlen((string) $inner['base64']) > 88) { return 'BinData(' . $subtype . ', ' . number_format($bytes === false ? 0 : strlen($bytes)) . ' bytes)'; }
                return 'BinData(' . $subtype . ', "' . $inner['base64'] . '")';
            case '$timestamp':
                return is_array($inner) && isset($inner['t'], $inner['i']) ? 'Timestamp({ t: ' . (int) $inner['t'] . ', i: ' . (int) $inner['i'] . ' })' : null;
            case '$regularExpression':
                return is_array($inner) && isset($inner['pattern']) ? '/' . $inner['pattern'] . '/' . ($inner['options'] ?? '') : null;
            case '$minKey':
                return 'MinKey';
            case '$maxKey':
                return 'MaxKey';
            case '$symbol':
                return is_string($inner) ? $inner : null;
            case '$undefined':
                return 'undefined';
        }
        return null;
    }

    private static function emit(array $documents, string $operation, float $elapsed, ?string $connection): void
    {
        $columns = [];
        foreach ($documents as $document) { foreach (array_keys($document) as $key) { $columns[$key] = true; } }
        $columns = array_slice(array_keys($columns), 0, 200);
        $rows = [];
        foreach ($documents as $document) {
            $row = [];
            foreach ($columns as $column) {
                $row[] = self::cell($document[$column] ?? null);
            }
            $rows[] = $row;
        }
        Channel::emit('sql', ['columns' => $columns, 'rows' => $rows, 'rowCount' => count($rows), 'driver' => 'mongodb', 'connection' => self::$definition['name'] ?? $connection, 'saved' => self::$definition !== null, 'source' => 'MongoDB ' . $operation, 'elapsedMs' => $elapsed, 'truncated' => false]);
        Runner::emitDump($documents, 'MongoDB documents · Extended JSON');
    }

    // MARK: Stop cancels on the server (#207), like SQL tabs (#144)

    /**
     * The tag the run's operations carry as their `comment`: `runlet:<run id>`. MongoDB 4.4 and
     * later accept `comment` on every command; older servers get no tag (Stop ends the runner only).
     */
    private static function tag(\MongoDB\Driver\Server $server): ?string
    {
        $runId = strtolower(Runner::runId());
        if (!preg_match('/^[0-9a-f-]{36}$/D', $runId) || (int) ($server->getInfo()['maxWireVersion'] ?? 0) < 9) { return null; }
        return 'runlet:' . $runId;
    }

    /**
     * What identifies the server process an operation runs on: its `topologyVersion.processId`
     * (MongoDB 4.4 and later, unique per process), or its host and port. Hashed, like SQL's (#144).
     */
    private static function fingerprint(\MongoDB\Driver\Server $server): string
    {
        $info = $server->getInfo();
        $topology = $info['topologyVersion'] ?? null;
        $process = is_array($topology) ? ($topology['processId'] ?? null) : (is_object($topology) ? ($topology->processId ?? null) : null);
        $id = $process instanceof \MongoDB\BSON\ObjectId ? 'process:' . (string) $process : 'address:' . $server->getHost() . ':' . $server->getPort();
        return substr(hash('sha256', 'mongodb|' . $id), 0, 16);
    }

    /** The `sqlSession` event (#144, #180): the tag and the server, never credentials. */
    private static function reportSession(\MongoDB\Driver\Server $server, string $tag, ?string $connection): void
    {
        Channel::emit('sqlSession', array_filter([
            'driver' => 'mongodb',
            'id' => 0,
            'tag' => $tag,
            'connection' => self::$definition === null ? $connection : null,
            'saved' => self::$definition === null ? null : true,
            'server' => self::fingerprint($server),
        ], static function ($value): bool {
            return $value !== null;
        }));
    }

    /** The connection's server with `$fingerprint`, after the driver discovered them; null when none has it. */
    private static function serverWithFingerprint(\MongoDB\Driver\Manager $manager, string $fingerprint): ?\MongoDB\Driver\Server
    {
        $manager->selectServer(new \MongoDB\Driver\ReadPreference('primaryPreferred'));
        foreach ($manager->getServers() as $server) {
            if (self::fingerprint($server) === $fingerprint) { return $server; }
        }
        return null;
    }

    /** The users this connection is authenticated as, as `user@db` (empty without authentication). */
    private static function authenticatedUsers(\MongoDB\Driver\Server $server): array
    {
        $status = $server->executeCommand('admin', new \MongoDB\Driver\Command(['connectionStatus' => 1]))->toArray()[0] ?? null;
        $users = [];
        foreach (($status->authInfo->authenticatedUsers ?? []) as $user) { $users[] = $user->user . '@' . $user->db; }
        sort($users);
        return $users;
    }

    /** An operation's effective users, as `user@db`, sorted. */
    private static function operationUsers($op): array
    {
        $users = [];
        foreach (($op->effectiveUsers ?? []) as $user) { $users[] = $user->user . '@' . $user->db; }
        sort($users);
        return $users;
    }

    /** This user's operations on `$server` that carry `$tag` (a getMore carries it in its originating command). */
    private static function taggedOperations(\MongoDB\Driver\Server $server, string $tag): array
    {
        $result = $server->executeCommand('admin', new \MongoDB\Driver\Command([
            'currentOp' => 1, '$ownOps' => true,
            '$or' => [['command.comment' => $tag], ['originatingCommand.comment' => $tag]],
        ]))->toArray()[0] ?? null;
        return is_object($result) && is_array($result->inprog ?? null) ? $result->inprog : [];
    }

    /**
     * Stop's second runner (#207): opens the same connection, checks it reached the server the run
     * reported (`$fingerprint`), finds this user's operations tagged `$tag` with `currentOp`,
     * refuses another user's, sends `killOp` for each, and watches them end. Emits `sqlCancel`.
     */
    public static function cancel(string $tag, ?string $connection, string $fingerprint): NoResult
    {
        $started = hrtime(true);
        $report = static function (string $outcome, array $fields = []) use ($started): NoResult {
            Channel::emit('sqlCancel', array_filter([
                'outcome' => $outcome, 'driver' => 'mongodb', 'session' => 0,
                'statement' => $fields['statement'] ?? 'killOp',
                'detail' => $fields['detail'] ?? null,
                'state' => $fields['state'] ?? null,
                'verified' => $fields['verified'] ?? null,
                'elapsedMs' => round((hrtime(true) - $started) / 1e6, 3),
            ], static function ($value): bool {
                return $value !== null;
            }));
            return NoResult::instance();
        };
        if (!preg_match('/^runlet:[0-9a-f-]{36}$/D', $tag)) { return $report('refused', ['detail' => 'Runlet kills only operations it tagged itself']); }
        if (!extension_loaded('mongodb')) { return $report('failed', ['detail' => 'this PHP has no ext-mongodb']); }
        try {
            [$manager] = self::connect($connection);
            $server = self::serverWithFingerprint($manager, $fingerprint);
            if ($server === null) {
                return $report('refused', ['detail' => 'the second connection reached another MongoDB server than the run (a list of hosts, a failover, or a load balancer?), so Runlet sent nothing there']);
            }
            $users = self::authenticatedUsers($server);
            $operations = self::taggedOperations($server, $tag);
            if ($operations === []) { return $report('idle'); }
            $ids = [];
            foreach ($operations as $operation) {
                if (self::operationUsers($operation) !== $users) {
                    return $report('refused', ['detail' => 'operation ' . self::opText($operation->opid ?? '?') . ' runs as another MongoDB user']);
                }
                $ids[] = $operation->opid;
            }
            foreach ($ids as $id) {
                $server->executeCommand('admin', new \MongoDB\Driver\Command(['killOp' => 1, 'op' => $id]));
            }
            $statement = 'killOp ' . implode(', ', array_map([self::class, 'opText'], $ids));
            $deadline = hrtime(true) + 2000 * 1000000;
            do {
                usleep(100000);
                $left = self::taggedOperations($server, $tag);
                if ($left === []) { return $report('cancelled', ['statement' => $statement, 'verified' => true]); }
            } while (hrtime(true) < $deadline);
            return $report('stillRunning', ['statement' => $statement, 'state' => ($left[0]->desc ?? null)]);
        } catch (\Throwable $error) {
            return $report($error->getCode() === 13 ? 'refused' : 'failed', ['detail' => $error->getCode() === 13 ? 'this MongoDB user may not list or kill the operation (code 13)' : 'MongoDB answered with code ' . (int) $error->getCode()]);
        }
    }

    /** An opid as text: 4711, or "shard01:4711" on mongos. */
    private static function opText($id): string
    {
        return is_int($id) ? (string) $id : (is_string($id) ? $id : (string) json_encode($id));
    }

    // MARK: The Database pane's Server section (#207), like SQL's (#150) and Redis's

    /**
     * Reads the server the tab's reads go to: a `serverStatus` summary (version, uptime,
     * connections, memory, replica set state) and `currentOp`'s operations, tagged with the
     * panel's own comment so the list can name its own operation. Emits `mongoServer`. Changes
     * nothing; a part the user may not read reports why.
     */
    public static function server(?string $connection): NoResult
    {
        ini_set('zend.exception_ignore_args', '1');
        try {
            [$manager] = self::connect($connection);
            $server = $manager->selectServer($manager->getReadPreference());
        } catch (\Throwable $error) {
            if (!extension_loaded('mongodb') || $error instanceof \RuntimeException && !$error instanceof \MongoDB\Driver\Exception\Exception) { throw $error; }
            throw new \RuntimeException('MongoDB connection failed. Check the host, authentication and TLS settings. Driver code: ' . (int) $error->getCode());
        }
        $own = 'runlet:' . strtolower(Runner::runId()) . ':panel';
        $report = ['server' => self::fingerprint($server), 'host' => $server->getHost() . ':' . $server->getPort(), 'listedBy' => $own, 'errors' => []];
        $info = $server->getInfo();
        $report['replica'] = array_filter([
            'setName' => is_string($info['setName'] ?? null) ? $info['setName'] : null,
            'state' => isset($info['setName']) ? (($info['isWritablePrimary'] ?? $info['ismaster'] ?? false) ? 'PRIMARY' : (($info['secondary'] ?? false) ? 'SECONDARY' : (($info['arbiterOnly'] ?? false) ? 'ARBITER' : 'OTHER'))) : null,
            'primary' => is_string($info['primary'] ?? null) ? $info['primary'] : null,
            'me' => is_string($info['me'] ?? null) ? $info['me'] : null,
            'mongos' => ($info['msg'] ?? '') === 'isdbgrid' ? true : null,
        ], static function ($value): bool { return $value !== null; });
        try {
            $status = $server->executeCommand('admin', new \MongoDB\Driver\Command(['serverStatus' => 1, 'repl' => 1, 'metrics' => 0, 'locks' => 0, 'wiredTiger' => 0, 'tcmalloc' => 0]))->toArray()[0];
            $report['status'] = array_filter([
                'version' => is_string($status->version ?? null) ? $status->version : null,
                'process' => is_string($status->process ?? null) ? $status->process : null,
                'host' => is_string($status->host ?? null) ? $status->host : null,
                'uptime' => isset($status->uptime) ? (int) $status->uptime : null,
                'connections' => isset($status->connections) ? array_filter(['current' => (int) ($status->connections->current ?? 0), 'available' => (int) ($status->connections->available ?? 0), 'totalCreated' => (int) ($status->connections->totalCreated ?? 0)], static function ($value) { return true; }) : null,
                'memory' => isset($status->mem) ? ['residentMB' => (int) ($status->mem->resident ?? 0), 'virtualMB' => (int) ($status->mem->virtual ?? 0)] : null,
                'storageEngine' => is_string($status->storageEngine->name ?? null) ? $status->storageEngine->name : null,
                'replicaState' => isset($status->repl->setName) ? (($status->repl->isWritablePrimary ?? $status->repl->ismaster ?? false) ? 'PRIMARY' : (($status->repl->secondary ?? false) ? 'SECONDARY' : 'OTHER')) : null,
                'opcounters' => isset($status->opcounters) ? array_map('intval', (array) $status->opcounters) : null,
            ], static function ($value): bool { return $value !== null; });
        } catch (\Throwable $error) {
            $report['errors']['serverStatus'] = self::panelError($error);
        }
        try {
            [$inprog, $report['ownOnly']] = self::currentOperations($server, [], $own);
            $operations = [];
            foreach ($inprog as $op) {
                if (count($operations) >= 200) { break; }
                $comment = is_string($op->command->comment ?? null) ? $op->command->comment : null;
                $operations[] = array_filter([
                    'opid' => self::opText($op->opid ?? ''),
                    'numeric' => is_int($op->opid ?? null) ? true : null,
                    'op' => is_string($op->op ?? null) ? $op->op : null,
                    'ns' => is_string($op->ns ?? null) && $op->ns !== '' ? $op->ns : null,
                    'desc' => is_string($op->desc ?? null) ? $op->desc : null,
                    'client' => is_string($op->client ?? null) ? $op->client : (is_string($op->client_s ?? null) ? $op->client_s : null),
                    'appName' => is_string($op->appName ?? null) ? self::clean($op->appName) : null,
                    'users' => self::operationUsers($op) ?: null,
                    'active' => isset($op->active) ? (bool) $op->active : null,
                    'micros' => isset($op->microsecs_running) ? (int) $op->microsecs_running : null,
                    'waitingForLock' => !empty($op->waitingForLock) ? true : null,
                    'comment' => $comment === null ? null : self::clean($comment),
                    'command' => isset($op->command) ? self::commandSummary($op->command) : null,
                    'own' => $comment === $own ? true : null,
                ], static function ($value): bool { return $value !== null; });
            }
            $report['operations'] = $operations;
        } catch (\Throwable $error) {
            $report['errors']['currentOp'] = self::panelError($error);
        }
        foreach (['errors', 'replica', 'status'] as $key) {
            if (($report[$key] ?? null) === []) { unset($report[$key]); }
        }
        if (isset($report['status']['opcounters']) && $report['status']['opcounters'] === []) { unset($report['status']['opcounters']); }
        Channel::emit('mongoServer', $report);
        return NoResult::instance();
    }

    /**
     * `$currentOp` (active operations, at most 200) matching `$match`, as the panel lists them:
     * every user's, or only this user's when it lacks the inprog privilege (then the second
     * value is true). The aggregate carries `$comment`, so the list can name the panel's own.
     */
    private static function currentOperations(\MongoDB\Driver\Server $server, array $match, ?string $comment): array
    {
        foreach ([true, false] as $allUsers) {
            $pipeline = [['$currentOp' => ['allUsers' => $allUsers, 'idleConnections' => false]]];
            if ($match !== []) { $pipeline[] = ['$match' => $match]; }
            $pipeline[] = ['$limit' => 200];
            try {
                $cursor = $server->executeReadCommand('admin', new \MongoDB\Driver\Command(['aggregate' => 1, 'pipeline' => $pipeline, 'cursor' => new \stdClass()] + ($comment === null ? [] : ['comment' => $comment])));
                return [$cursor->toArray(), !$allUsers];
            } catch (\MongoDB\Driver\Exception\Exception $denied) {
                // Without the inprog privilege, a user may list (and kill) only their own operations.
                if ($denied->getCode() !== 13 || !$allUsers) { throw $denied; }
            }
        }
        return [[], true];
    }

    /** "find shop.orders { filter: { status: "paid" }, limit: 50 }": the command, shortened, without session fields. */
    private static function commandSummary($command): string
    {
        $fields = [];
        foreach ((array) $command as $key => $value) {
            if ($key === 'lsid' || $key === 'comment' || (is_string($key) && $key !== '' && $key[0] === '$')) { continue; }
            $fields[$key] = $value;
        }
        $json = json_encode($fields, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR);
        $text = self::clean(is_string($json) ? $json : '');
        return strlen($text) > 400 ? substr($text, 0, 400) . '…' : $text;
    }

    private static function panelError(\Throwable $error): string
    {
        $code = (int) $error->getCode();
        return $code === 13 ? 'This MongoDB user isn\'t allowed to read it (code 13, Unauthorized).' : 'MongoDB refused it (code ' . $code . ').';
    }

    /**
     * Kill Op, confirmed in the app (#207): refuses another server (`$fingerprint`), the panel's
     * own operation and this runner's, and an operation that isn't the one listed any more (its
     * namespace or kind changed, or it's gone); then `killOp`. Emits `mongoKill`.
     */
    public static function killOp($opid, string $fingerprint, string $listedBy, string $ns, string $op, ?string $connection): NoResult
    {
        $report = static function (string $outcome, string $detail) use ($opid): NoResult {
            Channel::emit('mongoKill', ['opid' => self::opText($opid), 'outcome' => $outcome, 'detail' => $detail]);
            return NoResult::instance();
        };
        $text = self::opText($opid);
        try {
            [$manager] = self::connect($connection);
            $server = self::serverWithFingerprint($manager, $fingerprint);
            if ($server === null) {
                return $report('refused', 'This connection reached another MongoDB server than the one the list came from, so Runlet killed nothing. Read the operations again.');
            }
            $current = self::currentOperations($server, ['opid' => $opid], null)[0][0] ?? null;
            if ($current === null) { return $report('gone', 'Operation ' . $text . ' isn\'t running any more.'); }
            $comment = is_string($current->command->comment ?? null) ? $current->command->comment : '';
            if ($comment === $listedBy || strpos($comment, 'runlet:' . strtolower(Runner::runId())) === 0) {
                return $report('refused', 'Operation ' . $text . ' is Runlet\'s own, so it wasn\'t killed.');
            }
            if ((string) ($current->ns ?? '') !== $ns || (string) ($current->op ?? '') !== $op) {
                return $report('refused', 'Operation ' . $text . ' is now ' . (string) ($current->op ?? '?') . ' on ' . ((string) ($current->ns ?? '') ?: 'no namespace') . ', not the one listed, so Runlet killed nothing. Read the operations again.');
            }
            $server->executeCommand('admin', new \MongoDB\Driver\Command(['killOp' => 1, 'op' => $opid]));
            return $report('killed', 'Killed operation ' . $text . ' (killOp). It ends at its next interruption point.');
        } catch (\Throwable $error) {
            if ($error instanceof \RuntimeException && !$error instanceof \MongoDB\Driver\Exception\Exception) { return $report('failed', $error->getMessage()); }
            return $report('failed', (int) $error->getCode() === 13 ? 'This MongoDB user may not kill operation ' . $text . ' (code 13, Unauthorized).' : 'MongoDB refused killOp (code ' . (int) $error->getCode() . ').');
        }
    }

    public static function test(): NoResult
    {
        try {
            [$manager, $database] = self::connect(null);
            $manager->executeCommand('admin', new \MongoDB\Driver\Command(['ping' => 1]));
            Channel::emit('sqlTest', ['driver' => 'mongodb', 'serverVersion' => 'MongoDB', 'database' => $database, 'elapsedMs' => 0]);
        } catch (\Throwable $error) {
            if (!extension_loaded('mongodb')) { throw $error; }
            throw new \RuntimeException('MongoDB connection test failed. Check the host, authentication and TLS settings.');
        }
        return NoResult::instance();
    }
}
}

/*
 * Saved database connections (#138): a connection the user saved for a target, opened in
 * the target's own PHP (local PHP, `docker exec`, SSH), or from this Mac (#142: Runlet's PHP
 * or the default PHP, in an empty folder of Runlet's; `place` is "mac"), which is also where
 * connections of all targets open. The app sends its definition and
 * password in the runner request, which reaches PHP only on stdin; Runner::main() hands the
 * definition to SqlConnect::configure() and drops it from the request before anything else
 * runs, and the run boots no project code (the `plain` bootstrap).
 *
 * The password:
 *  - is never a function argument: connect() reads it from a private property, and the
 *    run sets zend.exception_ignore_args, so no exception trace carries it;
 *  - is forgotten once the connection is open (Channel keeps what it needs to scrub);
 *  - never leaves in an event: Channel::emit() replaces it (and its URL-encoded forms)
 *    with ••• in every message, and PDO's errors are rethrown with their message only.
 *
 * Read-only connections (#139): connect() makes the session read-only before anything else
 * runs (MySQL/MariaDB: SET SESSION TRANSACTION READ ONLY; PostgreSQL: SET SESSION
 * CHARACTERISTICS AS TRANSACTION READ ONLY; SQLite: the file opened read-only, and PRAGMA
 * query_only), checks that the database took it, and SqlTab sends the setting again before
 * each statement. SqlReadOnly refuses statements that would write or undo it, before the
 * connection is even opened; the app refuses them first.
 *
 * Connection options (#140): a Unix socket, a charset, TLS (a mode and the CA, client
 * certificate, and key files, which are paths where this PHP runs; Runlet never reads them),
 * extra DSN options, and init statements; SQL Server (pdo_sqlsrv, else pdo_dblib) and a
 * custom PDO DSN. No option carries a password: keys that look like one are refused here
 * too. Init statements run after the read-only setting (so the database refuses writes in
 * them), and the setting is sent and checked again after them.
 *
 * SSH tunnels (#143): `tunnel` carries the local port of a forward on an SSH profile's shared
 * connection, opened from this Mac. PHP connects to 127.0.0.1 on that port; the host stays the
 * server's name, so PostgreSQL gets it as `host` (for TLS verify-full) with
 * `hostaddr=127.0.0.1`. MySQL and SQL Server connect to 127.0.0.1 and check a certificate
 * against that address.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

final class SqlConnect
{
    private const DRIVERS = ['mysql', 'pgsql', 'sqlite', 'sqlsrv', 'custom'];
    private const READ_ONLY_DRIVERS = ['mysql', 'pgsql', 'sqlite'];
    private const TLS_MODES = ['disable', 'prefer', 'require', 'verify-ca', 'verify-full'];
    /** DSN keys each driver sets from its own fields, so extra options can't. */
    private const MANAGED_OPTIONS = [
        'pgsql' => ['host', 'port', 'dbname', 'user', 'sslmode', 'sslrootcert', 'sslcert', 'sslkey', 'client_encoding', 'connect_timeout'],
        'sqlsrv' => ['server', 'database', 'uid', 'encrypt', 'trustservercertificate', 'logintimeout'],
    ];
    private const MAX_INIT_STATEMENTS = 20;

    /**
     * @var array{id: string, name: string, driver: string, host: string, port: int|null, database: string, user: string, timeout: int, summary: string, readOnly: bool, socket: string, charset: string, tls: array{mode: string, ca: string, cert: string, key: string}, init: string[], options: array<int, array{0: string, 1: string}>, dsn: string, place: string, tunnel: array{port: int, via: string}}|null
     */
    private static $definition;
    /** @var string|null The password, until the connection is open. */
    private static $password;
    /** @var \PDO|null */
    private static $pdo;
    /** @var string|null The PDO driver that opened the connection (`dblib` for SQL Server through FreeTDS). */
    private static $pdoDriver;
    /** @var float|null */
    private static $connectMs;

    /**
     * Takes the saved connection from the runner request. Called by Runner::main() before
     * the bootstrap; the caller removes it from the request.
     *
     * @param array<string, mixed> $connection
     */
    public static function configure(array $connection): void
    {
        $password = isset($connection['password']) && is_string($connection['password']) ? $connection['password'] : null;
        unset($connection['password']);
        $tls = is_array($connection['tls'] ?? null) ? $connection['tls'] : [];
        $init = [];
        foreach (is_array($connection['init'] ?? null) ? $connection['init'] : [] as $statement) {
            if (is_string($statement) && trim($statement) !== '') {
                $init[] = $statement;
            }
        }
        $tunnel = is_array($connection['tunnel'] ?? null) ? $connection['tunnel'] : [];
        $options = [];
        foreach (is_array($connection['options'] ?? null) ? $connection['options'] : [] as $option) {
            if (is_array($option) && isset($option[0], $option[1]) && is_string($option[0]) && is_string($option[1])) {
                $options[] = [$option[0], $option[1]];
            }
        }
        self::$definition = [
            'id' => (string) ($connection['id'] ?? ''),
            'name' => (string) ($connection['name'] ?? ''),
            'driver' => (string) ($connection['driver'] ?? ''),
            'host' => (string) ($connection['host'] ?? ''),
            'port' => isset($connection['port']) ? (int) $connection['port'] : null,
            'database' => (string) ($connection['database'] ?? ''),
            'user' => (string) ($connection['user'] ?? ''),
            'timeout' => max(1, min(300, (int) ($connection['timeout'] ?? 10))),
            'summary' => (string) ($connection['summary'] ?? ''),
            'readOnly' => ($connection['readOnly'] ?? false) === true,
            'socket' => (string) ($connection['socket'] ?? ''),
            'charset' => (string) ($connection['charset'] ?? ''),
            'tls' => [
                'mode' => (string) ($tls['mode'] ?? ''),
                'ca' => (string) ($tls['ca'] ?? ''),
                'cert' => (string) ($tls['cert'] ?? ''),
                'key' => (string) ($tls['key'] ?? ''),
            ],
            'init' => $init,
            'options' => $options,
            'dsn' => (string) ($connection['dsn'] ?? ''),
            // #142: "mac" when this PHP runs on the user's Mac for the connection.
            'place' => ($connection['place'] ?? '') === 'mac' ? 'mac' : 'target',
            // #143: the local forward's port (0: no tunnel) and the SSH profile's name.
            'tunnel' => [
                'port' => max(0, min(65535, (int) ($tunnel['port'] ?? 0))),
                'via' => (string) ($tunnel['via'] ?? ''),
            ],
        ];
        self::$password = $password;
        if ($password !== null && $password !== '') {
            Channel::addSecret($password);
        }
    }

    public static function isConfigured(): bool
    {
        return self::$definition !== null;
    }

    /** The saved connection's name. */
    public static function name(): string
    {
        return self::$definition['name'] ?? '';
    }

    /** The saved connection is read-only (#139). */
    public static function isReadOnly(): bool
    {
        return (self::$definition['readOnly'] ?? false) === true;
    }

    /**
     * Where results say they came from: `saved connection "Reporting" (pgsql, db:5432/reports)`,
     * with `, read-only session` for a read-only one (#139).
     */
    public static function origin(): string
    {
        $definition = self::$definition ?? [];
        $summary = (string) ($definition['summary'] ?? '');

        return 'saved connection "' . ($definition['name'] ?? '') . '"' . ($summary === '' ? '' : ' (' . $summary . ')') . (self::isReadOnly() ? ', read-only session' : '');
    }

    /** Whether this PHP opens the connection from the user's Mac (#142) rather than on the target. */
    public static function onThisMac(): bool
    {
        return (self::$definition['place'] ?? '') === 'mac';
    }

    /** "This Mac's PHP 8.5.8" or "This target's PHP 8.4.1", for messages. */
    private static function whosePhp(): string
    {
        return (self::onThisMac() ? 'This Mac\'s PHP ' : 'This target\'s PHP ') . PHP_VERSION;
    }

    /** "this Mac" or "this target", for messages. */
    private static function here(): string
    {
        return self::onThisMac() ? 'this Mac' : 'this target';
    }

    /** What to do about a missing driver from this Mac (#142): Runlet's PHP has them. */
    private static function macDriverHint(string $driver): string
    {
        if (!self::onThisMac()) {
            return '';
        }

        return in_array($driver, ['mysql', 'pgsql', 'sqlite'], true)
            ? ' Download Runlet\'s PHP in Settings ▸ PHP: it has pdo_mysql, pdo_pgsql, and pdo_sqlite, and Runlet uses it for connections from this Mac.'
            : ' Runlet\'s PHP doesn\'t have it either: install the driver in this Mac\'s default PHP (Settings ▸ PHP), or open the connection from the target.';
    }

    /** The saved connection's driver (`mysql`, `pgsql`, `sqlite`, `sqlsrv`, or `custom`). */
    public static function driverName(): ?string
    {
        return self::$definition['driver'] ?? null;
    }

    /** The open connection; opens it on first use. */
    public static function pdo(): \PDO
    {
        if (self::$pdo === null) {
            $started = hrtime(true);
            try {
                self::$pdo = self::connect();
            } finally {
                // Opened or not, this process never needs the password again.
                self::$password = null;
            }
            self::$connectMs = round((hrtime(true) - $started) / 1e6, 3);
        }

        return self::$pdo;
    }

    /**
     * Test Connection: opens the connection and reports the server's version, the current
     * database and user, one round trip, and whether TLS is in use (#140). Runs only Runlet's
     * own fixed queries, after the connection's init statements.
     *
     * @return array<string, mixed>
     */
    public static function test(): array
    {
        $pdo = self::pdo();
        $driver = self::$pdoDriver ?? (string) self::driverName();
        $version = null;
        try {
            $version = (string) $pdo->getAttribute(\PDO::ATTR_SERVER_VERSION);
        } catch (\Throwable $error) {
            $version = null;
        }
        $started = hrtime(true);
        $pdo->query('SELECT 1')->fetchAll();
        $roundTrip = round((hrtime(true) - $started) / 1e6, 3);
        $database = null;
        $user = null;
        try {
            if ($driver === 'mysql') {
                $row = $pdo->query('SELECT DATABASE(), CURRENT_USER()')->fetch(\PDO::FETCH_NUM);
                [$database, $user] = is_array($row) ? $row : [null, null];
            } elseif ($driver === 'pgsql') {
                $row = $pdo->query('SELECT current_database(), current_user')->fetch(\PDO::FETCH_NUM);
                [$database, $user] = is_array($row) ? $row : [null, null];
            } elseif ($driver === 'sqlsrv' || $driver === 'dblib') {
                $row = $pdo->query('SELECT DB_NAME(), SUSER_SNAME()')->fetch(\PDO::FETCH_NUM);
                [$database, $user] = is_array($row) ? $row : [null, null];
            } elseif ($driver === 'sqlite' && self::driverName() === 'sqlite') {
                $path = (string) (self::$definition['database'] ?? '');
                $real = $path === ':memory:' ? false : realpath($path);
                $database = $real === false ? $path : $real;
            }
        } catch (\Throwable $error) {
            // Version and round trip are enough; the names are a courtesy.
        }
        $definition = self::$definition ?? [];

        return array_filter([
            'driver' => self::driverName() === 'custom' ? $driver : self::driverName(),
            // SQL Server opened through pdo_dblib (FreeTDS) rather than pdo_sqlsrv.
            'pdoDriver' => $driver === 'dblib' ? 'dblib' : null,
            'serverVersion' => $version,
            'database' => $database === null ? null : (string) $database,
            'user' => $user === null ? null : (string) $user,
            'connectMs' => self::$connectMs,
            'roundTripMs' => $roundTrip,
            'phpVersion' => PHP_VERSION,
            // connect() checked that the database took the read-only setting.
            'readOnly' => self::isReadOnly() ? true : null,
            'initStatements' => ($definition['init'] ?? []) === [] ? null : count($definition['init']),
            // #142: Test Connection reports the PHP's drivers.
            'pdoDrivers' => array_values(\PDO::getAvailableDrivers()),
        ] + self::tlsInfo($pdo, $driver), static function ($value): bool {
            return $value !== null;
        });
    }

    /**
     * Whether the open connection is encrypted, as the server reports it: `tls` (bool),
     * `tlsVersion`, `tlsCipher`. Empty when the driver can't tell.
     *
     * @return array<string, mixed>
     */
    private static function tlsInfo(\PDO $pdo, string $driver): array
    {
        try {
            if ($driver === 'mysql') {
                $status = $pdo->query("SHOW SESSION STATUS WHERE Variable_name IN ('Ssl_version', 'Ssl_cipher')")->fetchAll(\PDO::FETCH_KEY_PAIR);
                $cipher = (string) ($status['Ssl_cipher'] ?? '');

                return ['tls' => $cipher !== '', 'tlsVersion' => $cipher === '' ? null : (string) ($status['Ssl_version'] ?? ''), 'tlsCipher' => $cipher === '' ? null : $cipher];
            }
            if ($driver === 'pgsql') {
                $row = $pdo->query('SELECT ssl, version, cipher FROM pg_stat_ssl WHERE pid = pg_backend_pid()')->fetch(\PDO::FETCH_NUM);
                if (!is_array($row)) {
                    return [];
                }
                $on = in_array(strtolower(var_export($row[0], true)), ['true', "'t'", "'1'", '1'], true);

                return ['tls' => $on, 'tlsVersion' => $on ? (string) $row[1] : null, 'tlsCipher' => $on ? (string) $row[2] : null];
            }
            if ($driver === 'sqlsrv' || $driver === 'dblib') {
                $value = $pdo->query('SELECT encrypt_option FROM sys.dm_exec_connections WHERE session_id = @@SPID')->fetchColumn();

                return $value === false ? [] : ['tls' => strtoupper((string) $value) === 'TRUE'];
            }
        } catch (\Throwable $error) {
            // The user may not see the view (SQL Server needs VIEW SERVER STATE).
        }

        return [];
    }

    /**
     * How the connection will be opened: the PDO DSN, the PDO attributes (by constant name),
     * and the PDO driver. Never the password (PDO gets it as its own argument). Throws
     * SqlConnectionFailed when the definition can't be expressed or this PHP lacks the
     * driver. `$available` defaults to this PHP's PDO drivers.
     *
     * @param string[]|null $available
     * @return array{dsn: string, attributes: array<string, array{0: int, 1: mixed}>, pdoDriver: string}
     */
    public static function plan(?array $available = null): array
    {
        $definition = self::$definition;
        if ($definition === null) {
            throw new SqlConnectionFailed('No saved connection was sent with this run.');
        }
        $name = '"' . $definition['name'] . '"';
        $driver = $definition['driver'];
        if (!in_array($driver, self::DRIVERS, true)) {
            throw new SqlConnectionFailed('The saved connection ' . $name . ' uses the ' . $driver . ' driver, which this Runlet doesn\'t support.');
        }
        if ($available === null) {
            if (!class_exists('PDO', false)) {
                throw new SqlConnectionFailed(self::whosePhp() . ' has no PDO extension, so it can\'t open the saved connection ' . $name . '.' . self::macDriverHint((string) $driver));
            }
            $available = \PDO::getAvailableDrivers();
        }
        $has = 'It has: ' . ($available === [] ? 'none' : implode(', ', $available)) . '.';
        if ($definition['readOnly'] && !in_array($driver, self::READ_ONLY_DRIVERS, true)) {
            throw new SqlConnectionFailed('Runlet can\'t make the session of the saved connection ' . $name . ' read-only (' . ($driver === 'custom' ? 'a custom DSN' : 'SQL Server') . ' has no read-only session it can enforce), so nothing ran.');
        }
        $tls = $definition['tls'];
        if ($tls['mode'] !== '' && !in_array($tls['mode'], self::TLS_MODES, true)) {
            throw new SqlConnectionFailed('The saved connection ' . $name . ' asks for the TLS mode "' . $tls['mode'] . '", which this Runlet doesn\'t know.');
        }
        self::checkOptions($driver, $definition['options']);
        if ($definition['tunnel']['port'] > 0) {
            self::checkTunnel($definition);
        }
        $timeout = $definition['timeout'];
        $attributes = ['PDO::ATTR_TIMEOUT' => [\PDO::ATTR_TIMEOUT, $timeout]];

        switch ($driver) {
            case 'sqlite':
                self::requireDriver('sqlite', $available, $has);
                $database = $definition['database'];
                if ($database === '' || strpos($database, "\0") !== false) {
                    throw new SqlConnectionFailed('The saved connection has no SQLite file.');
                }
                if ($database !== ':memory:' && !is_file($database)) {
                    throw new SqlConnectionFailed('The SQLite file ' . $database . ' doesn\'t exist on ' . self::here() . (substr($database, 0, 1) === '/' ? '' : ' (a relative path starts in ' . (getcwd() ?: 'the project directory') . ')') . '. Runlet opens existing files only.');
                }
                if ($definition['readOnly']) {
                    // #139: SQLite opens the file read-only (PHP 7.3+), so no statement can write to it.
                    $flags = self::constant(['Pdo\Sqlite::ATTR_OPEN_FLAGS', 'PDO::SQLITE_ATTR_OPEN_FLAGS']);
                    $readOnly = self::constant(['Pdo\Sqlite::OPEN_READONLY', 'PDO::SQLITE_OPEN_READONLY']);
                    if ($flags !== null && $readOnly !== null) {
                        $attributes[$flags[0]] = [$flags[1], $readOnly[1]];
                    }
                }

                return ['dsn' => 'sqlite:' . $database, 'attributes' => $attributes, 'pdoDriver' => 'sqlite'];

            case 'mysql':
                self::requireDriver('mysql', $available, $has);
                $dsn = 'mysql:' . self::address($definition, false) . self::databasePart($definition, ';dbname=', false);
                $charset = $definition['charset'] === '' ? 'utf8mb4' : $definition['charset'];
                self::checkCharset($charset);
                $dsn .= ';charset=' . $charset;

                return ['dsn' => $dsn, 'attributes' => $attributes + self::mysqlTls($definition), 'pdoDriver' => 'mysql'];

            case 'pgsql':
                self::requireDriver('pgsql', $available, $has);
                $dsn = 'pgsql:' . self::address($definition, true) . self::databasePart($definition, ';dbname=', true);
                if ($tls['mode'] !== '') {
                    $dsn .= ';sslmode=' . $tls['mode'];
                    if ($tls['mode'] !== 'disable') {
                        foreach (['ca' => 'sslrootcert', 'cert' => 'sslcert', 'key' => 'sslkey'] as $field => $keyword) {
                            if ($tls[$field] !== '') {
                                $dsn .= ';' . $keyword . '=' . self::libpqQuote(self::checkPath($tls[$field], self::fileLabel($field)));
                            }
                        }
                    }
                }
                if ($definition['charset'] !== '') {
                    $dsn .= ';client_encoding=' . self::libpqQuote(self::checkCharset($definition['charset']));
                }
                foreach ($definition['options'] as [$key, $value]) {
                    $dsn .= ';' . $key . '=' . self::libpqQuote($value);
                }

                return ['dsn' => $dsn, 'attributes' => $attributes, 'pdoDriver' => 'pgsql'];

            case 'sqlsrv':
                // Microsoft's pdo_sqlsrv, else pdo_dblib (FreeTDS).
                $pdoDriver = in_array('sqlsrv', $available, true) ? 'sqlsrv' : (in_array('dblib', $available, true) ? 'dblib' : null);
                if ($pdoDriver === null) {
                    throw new SqlConnectionFailed(self::whosePhp() . ' has neither pdo_sqlsrv nor pdo_dblib, which SQL Server needs. ' . $has . self::macDriverHint('sqlsrv'));
                }
                $host = self::checkHost($definition['host']);
                $port = (int) ($definition['port'] ?? 1433);
                if ($definition['tunnel']['port'] > 0) {
                    // #143: the SSH tunnel's local end.
                    $host = '127.0.0.1';
                    $port = $definition['tunnel']['port'];
                }
                if ($pdoDriver === 'dblib') {
                    if ($tls['mode'] !== '') {
                        throw new SqlConnectionFailed((self::onThisMac() ? 'This Mac\'s PHP' : 'This target\'s PHP') . ' opens SQL Server with pdo_dblib (FreeTDS), which takes TLS settings from freetds.conf ("encryption"), not from Runlet. Set the connection\'s TLS to "Driver default", or install pdo_sqlsrv. Nothing ran.');
                    }
                    $dsn = 'dblib:host=' . $host . ':' . $port . self::databasePart($definition, ';dbname=', false, true) . ';charset=UTF-8';
                    foreach ($definition['options'] as [$key, $value]) {
                        $dsn .= ';' . $key . '=' . $value;
                    }

                    return ['dsn' => $dsn, 'attributes' => $attributes, 'pdoDriver' => 'dblib'];
                }
                // pdo_sqlsrv rejects PDO::ATTR_TIMEOUT; its DSN has LoginTimeout.
                $dsn = 'sqlsrv:Server=' . $host . ',' . $port . self::databasePart($definition, ';Database=', false, true) . ';LoginTimeout=' . $timeout;
                if ($tls['mode'] === 'disable') {
                    $dsn .= ';Encrypt=no';
                } elseif ($tls['mode'] === 'require') {
                    $dsn .= ';Encrypt=yes;TrustServerCertificate=yes';
                } elseif ($tls['mode'] === 'verify-full') {
                    $dsn .= ';Encrypt=yes;TrustServerCertificate=no';
                } elseif ($tls['mode'] !== '') {
                    throw new SqlConnectionFailed('SQL Server\'s driver can\'t express the TLS mode ' . $tls['mode'] . ' (it checks the host name whenever it checks the certificate, and it can\'t fall back). Choose disable, require, or verify-full.');
                }
                foreach ($definition['options'] as [$key, $value]) {
                    $dsn .= ';' . $key . '=' . $value;
                }

                return ['dsn' => $dsn, 'attributes' => [], 'pdoDriver' => 'sqlsrv'];

            default: // custom
                $dsn = $definition['dsn'];
                $problem = self::customDsnProblem($dsn);
                if ($problem !== null) {
                    throw new SqlConnectionFailed('The saved connection ' . $name . '\'s DSN ' . $problem);
                }
                $prefix = strtolower(substr($dsn, 0, (int) strpos($dsn, ':')));
                if (!in_array($prefix, $available, true)) {
                    throw new SqlConnectionFailed(self::whosePhp() . ' has no pdo_' . $prefix . ' driver for the DSN. ' . $has . self::macDriverHint($prefix));
                }

                return ['dsn' => $dsn, 'attributes' => $prefix === 'sqlsrv' ? [] : $attributes, 'pdoDriver' => $prefix];
        }
    }

    /**
     * Why a custom DSN can't be used, or null: it must start with a PDO driver prefix, and it
     * can't carry a password (or point PDO at a file or URL that holds the DSN).
     */
    public static function customDsnProblem(string $dsn): ?string
    {
        if (trim($dsn) === '') {
            return 'is empty.';
        }
        if (preg_match('/[\x00-\x1f\x7f]/', $dsn) === 1) {
            return 'can\'t contain line breaks or control characters.';
        }
        if (preg_match('/^[A-Za-z][A-Za-z0-9_]*:/', $dsn) !== 1) {
            return 'must start with a PDO driver name and a colon, such as oci: or odbc:.';
        }
        if (stripos($dsn, 'uri:') === 0) {
            return 'can\'t be a uri: DSN (Runlet doesn\'t let PDO read the DSN from a file or URL). Paste the DSN itself.';
        }
        if (preg_match('/(^|[;:\s])\s*(password|passwd|pwd|sslpassword)\s*=/i', $dsn) === 1 || preg_match('#://[^/@\s;]*:[^/@\s;]*@#', $dsn) === 1) {
            return 'contains a password. Runlet keeps passwords only in the Keychain: put it in the Password field.';
        }

        return null;
    }

    /**
     * MySQL's TLS attributes (#140). mysqlnd encrypts only when one of the SSL attributes is
     * set, and then checks the certificate and the host name together unless
     * MYSQL_ATTR_SSL_VERIFY_SERVER_CERT is false; so it has disable, require, and verify-full,
     * and no prefer or verify-ca. connect() checks Ssl_cipher afterwards.
     *
     * @param array<string, mixed> $definition
     * @return array<string, array{0: int, 1: mixed}>
     */
    private static function mysqlTls(array $definition): array
    {
        $tls = $definition['tls'];
        $mode = $tls['mode'];
        if ($mode === '' || $mode === 'disable') {
            return [];
        }
        if ($mode === 'prefer' || $mode === 'verify-ca') {
            throw new SqlConnectionFailed('MySQL\'s PDO driver can\'t express the TLS mode ' . $mode . ': it either requires TLS or doesn\'t use it, and it checks the host name whenever it checks the certificate. Choose disable, require, or verify-full.');
        }
        $attributes = [];
        $set = static function (string $suffix, $value) use (&$attributes): void {
            $constant = self::constant(['Pdo\Mysql::ATTR_' . $suffix, 'PDO::MYSQL_ATTR_' . $suffix]);
            if ($constant === null) {
                throw new SqlConnectionFailed(self::whosePhp() . ' has no PDO::MYSQL_ATTR_' . $suffix . ', so it can\'t open this connection with TLS (it needs PHP 7.1.4 or later with mysqlnd).');
            }
            $attributes[$constant[0]] = [$constant[1], $value];
        };
        if ($tls['ca'] !== '') {
            $set('SSL_CA', self::checkPath($tls['ca'], 'CA file'));
        } elseif ($mode === 'require') {
            // An empty CA turns TLS on; nothing is verified, so nothing is loaded.
            $set('SSL_CA', '');
        } else {
            // verify-full without a CA file: this PHP's OpenSSL default certificates.
            [$file, $directory] = self::systemCertificates();
            if ($file !== null) {
                $set('SSL_CA', $file);
            } elseif ($directory !== null) {
                $set('SSL_CAPATH', $directory);
            } else {
                throw new SqlConnectionFailed('Verifying the server needs a CA file, and this target\'s PHP has no default one (openssl.cafile). Set the connection\'s CA file. Nothing ran.');
            }
        }
        if ($tls['cert'] !== '') {
            $set('SSL_CERT', self::checkPath($tls['cert'], 'client certificate'));
        }
        if ($tls['key'] !== '') {
            $set('SSL_KEY', self::checkPath($tls['key'], 'client key'));
        }
        $set('SSL_VERIFY_SERVER_CERT', $mode === 'verify-full');

        return $attributes;
    }

    /**
     * This PHP's default CA file and directory (openssl.cafile/capath, else OpenSSL's
     * defaults), when they exist.
     *
     * @return array{0: string|null, 1: string|null}
     */
    private static function systemCertificates(): array
    {
        if (!function_exists('openssl_get_cert_locations')) {
            return [null, null];
        }
        $locations = openssl_get_cert_locations();
        $file = null;
        foreach ([(string) ($locations['ini_cafile'] ?? ''), (string) ($locations['default_cert_file'] ?? '')] as $candidate) {
            if ($candidate !== '' && is_file($candidate)) {
                $file = $candidate;
                break;
            }
        }
        $directory = null;
        foreach ([(string) ($locations['ini_capath'] ?? ''), (string) ($locations['default_cert_dir'] ?? '')] as $candidate) {
            if ($candidate !== '' && is_dir($candidate)) {
                $directory = $candidate;
                break;
            }
        }

        return [$file, $directory];
    }

    /**
     * `host=…;port=…`, or the Unix socket (MySQL `unix_socket=`; PostgreSQL `host=` with the
     * socket's directory, and the port that names the socket file).
     *
     * @param array<string, mixed> $definition
     */
    private static function address(array $definition, bool $pgsql): string
    {
        $socket = (string) $definition['socket'];
        $port = (int) ($definition['port'] ?? ($pgsql ? 5432 : 3306));
        if ($socket !== '') {
            self::checkPath($socket, 'socket', false);

            return $pgsql ? 'host=' . self::libpqQuote($socket) . ';port=' . $port : 'unix_socket=' . $socket;
        }
        $host = self::checkHost((string) $definition['host']);
        $tunnel = (int) ($definition['tunnel']['port'] ?? 0);
        if ($tunnel > 0) {
            // #143: connect to the SSH tunnel's local end. libpq still gets the server's name
            // as host, for TLS verification (verify-full) and its messages.
            return $pgsql
                ? 'host=' . trim($host, '[]') . ';hostaddr=127.0.0.1;port=' . $tunnel
                : 'host=127.0.0.1;port=' . $tunnel;
        }

        // libpq takes a bracket-less IPv6 address.
        return 'host=' . ($pgsql ? trim($host, '[]') : $host) . ';port=' . $port;
    }

    /**
     * #143: a connection through an SSH tunnel forwards a host and port, so it can't use a
     * socket, an SQLite file, or a custom DSN, and no option may send libpq elsewhere.
     *
     * @param array<string, mixed> $definition
     */
    private static function checkTunnel(array $definition): void
    {
        $name = '"' . $definition['name'] . '"';
        if (!in_array($definition['driver'], ['mysql', 'pgsql', 'sqlsrv'], true)) {
            throw new SqlConnectionFailed('The saved connection ' . $name . ' can\'t go through an SSH tunnel: a tunnel forwards a host and port. Nothing ran.');
        }
        if ((string) $definition['socket'] !== '') {
            throw new SqlConnectionFailed('The saved connection ' . $name . ' goes through an SSH tunnel, which forwards a host and port, not a Unix socket. Nothing ran.');
        }
        foreach ($definition['options'] as [$key, $value]) {
            if (strtolower($key) === 'hostaddr') {
                throw new SqlConnectionFailed('The saved connection ' . $name . ' goes through an SSH tunnel, so its "' . $key . '" option is set by the tunnel (127.0.0.1). Remove the option. Nothing ran.');
            }
        }
    }

    /** @param array<string, mixed> $definition */
    private static function databasePart(array $definition, string $prefix, bool $quote, bool $braces = false): string
    {
        $database = (string) $definition['database'];
        if ($database === '') {
            return '';
        }
        if (preg_match('/[;\'"\\\\\x00-\x1f]/', $database) === 1 || ($braces && strpbrk($database, '{}') !== false)) {
            throw new SqlConnectionFailed('The saved connection\'s database name can\'t contain ";", quotes' . ($braces ? ', braces' : '') . ', or control characters.');
        }

        return $prefix . ($quote ? "'" . $database . "'" : $database);
    }

    private static function checkHost(string $host): string
    {
        if ($host === '' || preg_match('/^[A-Za-z0-9._:%\[\]-]+$/', $host) !== 1 || $host[0] === '-') {
            throw new SqlConnectionFailed('The saved connection\'s host "' . $host . '" isn\'t a host name or IP address.');
        }

        return $host;
    }

    private static function checkCharset(string $charset): string
    {
        if (preg_match('/^[A-Za-z0-9_-]{1,40}$/', $charset) !== 1) {
            throw new SqlConnectionFailed('The saved connection\'s charset "' . $charset . '" isn\'t a character set name.');
        }

        return $charset;
    }

    /**
     * A path where this PHP runs (a socket, a CA file, a client certificate or key): absolute,
     * and nothing that could end or quote a DSN value. Files must exist and be readable; Runlet
     * doesn't open them, the driver does.
     */
    private static function checkPath(string $path, string $what, bool $file = true): string
    {
        if ($path === '' || $path[0] !== '/' || preg_match('/[;\'"\\\\\x00-\x1f]/', $path) === 1) {
            throw new SqlConnectionFailed('The ' . $what . ' "' . $path . '" must be an absolute path without ";", quotes, backslashes, or control characters.');
        }
        if ($file && !is_readable($path)) {
            throw new SqlConnectionFailed('The ' . $what . ' ' . $path . ' doesn\'t exist on ' . self::here() . ', or its PHP can\'t read it. Nothing ran.');
        }

        return $path;
    }

    private static function fileLabel(string $field): string
    {
        return $field === 'ca' ? 'CA file' : ($field === 'cert' ? 'client certificate' : 'client key');
    }

    /** A libpq connection value in single quotes (pdo_pgsql turns every ";" into a space). */
    private static function libpqQuote(string $value): string
    {
        return "'" . str_replace(['\\', "'"], ['\\\\', "\\'"], $value) . "'";
    }

    /**
     * Extra DSN options (#140): PostgreSQL's libpq keywords and SQL Server's DSN keywords.
     * Refused: other drivers, keys that look like a password, keys Runlet sets from the
     * connection's fields, and values that could end the DSN entry.
     *
     * @param array<int, array{0: string, 1: string}> $options
     */
    private static function checkOptions(string $driver, array $options): void
    {
        if ($options === []) {
            return;
        }
        if (!isset(self::MANAGED_OPTIONS[$driver])) {
            throw new SqlConnectionFailed('The ' . $driver . ' driver takes no extra DSN options.');
        }
        foreach ($options as [$key, $value]) {
            if (preg_match('/^[A-Za-z][A-Za-z0-9_]{0,63}$/', $key) !== 1) {
                throw new SqlConnectionFailed('The DSN option "' . $key . '" isn\'t a keyword.');
            }
            if (preg_match('/pass|pwd/i', $key) === 1) {
                throw new SqlConnectionFailed('The DSN option "' . $key . '" looks like a password. Runlet keeps passwords only in the Keychain: put it in the Password field.');
            }
            if (in_array(strtolower($key), self::MANAGED_OPTIONS[$driver], true)) {
                throw new SqlConnectionFailed('The DSN option "' . $key . '" is set from the connection\'s own fields.');
            }
            if (preg_match($driver === 'sqlsrv' ? '/[;{}\x00-\x1f]/' : '/[;\x00-\x1f]/', $value) === 1) {
                throw new SqlConnectionFailed('The value of the DSN option "' . $key . '" can\'t contain ";"' . ($driver === 'sqlsrv' ? ', braces,' : '') . ' or control characters.');
            }
        }
    }

    /** @param string[] $available */
    private static function requireDriver(string $driver, array $available, string $has): void
    {
        if (!in_array($driver, $available, true)) {
            throw new SqlConnectionFailed(self::whosePhp() . ' has no pdo_' . $driver . ' driver. ' . $has . self::macDriverHint($driver));
        }
    }

    /**
     * Opens the connection. It takes no arguments, so neither the password nor the DSN is
     * ever in a stack frame; PDO's exception is replaced by one with its message only.
     */
    private static function connect(): \PDO
    {
        $definition = self::$definition;
        if ($definition === null) {
            throw new SqlConnectionFailed('No saved connection was sent with this run.');
        }
        $name = '"' . $definition['name'] . '"';
        $plan = self::plan();
        // Init statements are checked before anything is sent.
        $count = count($definition['init']);
        if ($count > self::MAX_INIT_STATEMENTS) {
            throw new SqlConnectionFailed('The saved connection ' . $name . ' has ' . $count . ' init statements; Runlet runs at most ' . self::MAX_INIT_STATEMENTS . '. Nothing ran.');
        }
        foreach ($definition['init'] as $index => $statement) {
            $why = SqlReadOnly::initRefusal($statement, $definition['driver'], $definition['readOnly']);
            if ($why !== null) {
                throw new SqlConnectionFailed('Init statement ' . ($index + 1) . ' of the saved connection ' . $name . ' ' . $why . ', so Runlet didn\'t connect. Nothing ran.');
            }
        }
        $options = [\PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION];
        foreach ($plan['attributes'] as [$key, $value]) {
            $options[$key] = $value;
        }
        $warnings = [];
        set_error_handler(static function (int $severity, string $message) use (&$warnings): bool {
            $warnings[] = $message;

            return true;
        });
        $message = '';
        $pdo = null;
        try {
            $pdo = new \PDO($plan['dsn'], $definition['user'] === '' ? null : $definition['user'], self::$password, $options);
        } catch (\Throwable $error) {
            $message = $error->getMessage();
        } finally {
            restore_error_handler();
        }
        if ($pdo === null) {
            if ($message === '' && $warnings !== []) {
                $message = implode(' ', $warnings);
            }
            // #143: through a tunnel, the SSH server opens the TCP connection to the database.
            $hint = $definition['tunnel']['port'] > 0
                ? ' The SSH server of "' . $definition['tunnel']['via'] . '" connects to the database for the tunnel, so the host and port are as that server sees them; check it can reach them.'
                : '';
            // Thrown outside the catch, with no previous exception: nothing of PDO's trace stays.
            throw new SqlConnectionFailed(Channel::scrub('Runlet could not open the saved connection ' . $name . ' (' . $definition['summary'] . '): ' . $message . $hint));
        }
        self::$pdoDriver = $plan['pdoDriver'];
        $where = $name . ' (' . $definition['summary'] . ')';
        if ($plan['pdoDriver'] === 'mysql' && in_array($definition['tls']['mode'], ['require', 'verify-full'], true)) {
            // #140: refuse to go on unencrypted, whatever mysqlnd did.
            $cipher = '';
            try {
                $row = $pdo->query("SHOW SESSION STATUS LIKE 'Ssl_cipher'")->fetch(\PDO::FETCH_NUM);
                $cipher = is_array($row) ? (string) ($row[1] ?? '') : '';
            } catch (\Throwable $error) {
                $cipher = '';
            }
            if ($cipher === '') {
                $pdo = null;
                throw new SqlConnectionFailed('The saved connection ' . $where . ' asks for TLS (' . $definition['tls']['mode'] . '), but the server didn\'t encrypt the session, so nothing ran.');
            }
        }
        if ($definition['readOnly']) {
            $problem = self::makeReadOnly($pdo, $definition['driver'], true);
            if ($problem !== null) {
                $pdo = null;
                throw new SqlConnectionFailed(Channel::scrub('Runlet could not make the session of the read-only connection ' . $where . ' read-only, so nothing ran: ' . $problem));
            }
        }
        foreach ($definition['init'] as $index => $statement) {
            try {
                $result = $pdo->query($statement);
                if ($result !== false) {
                    $result->closeCursor();
                }
            } catch (\Throwable $error) {
                $pdo = null;
                throw new SqlConnectionFailed(Channel::scrub('Init statement ' . ($index + 1) . ' of the saved connection ' . $where . ' failed, so nothing of yours ran: ' . $error->getMessage()));
            }
        }
        if ($definition['readOnly'] && $definition['init'] !== []) {
            // Whatever the init statements did, the session is read-only again, and checked.
            $problem = self::makeReadOnly($pdo, $definition['driver'], true);
            if ($problem !== null) {
                $pdo = null;
                throw new SqlConnectionFailed(Channel::scrub('After its init statements, the session of the read-only connection ' . $where . ' isn\'t read-only, so nothing ran: ' . $problem));
            }
        }

        return $pdo;
    }

    /**
     * Read-only connections (#139): sends the driver's read-only setting again. SqlTab calls
     * it before each statement, so a statement that slipped past the refusals can't leave the
     * session writable for the next one. A failure stops the run.
     */
    public static function enforceReadOnly(): void
    {
        if (!self::isReadOnly() || self::$pdo === null) {
            return;
        }
        $problem = self::makeReadOnly(self::$pdo, (string) self::driverName(), false);
        if ($problem !== null) {
            throw new SqlConnectionFailed('Runlet could not keep the session of the read-only connection "' . self::name() . '" read-only, so it stopped: ' . $problem);
        }
    }

    /**
     * Sends the driver's read-only setting; with `$verify`, asks the database whether it took
     * it. Returns what went wrong, or null.
     */
    private static function makeReadOnly(\PDO $pdo, string $driver, bool $verify): ?string
    {
        $statements = [
            'mysql' => ['SET SESSION TRANSACTION READ ONLY', ['SELECT @@session.transaction_read_only', 'SELECT @@session.tx_read_only']],
            'pgsql' => ['SET SESSION CHARACTERISTICS AS TRANSACTION READ ONLY', ['SHOW default_transaction_read_only']],
            'sqlite' => ['PRAGMA query_only = ON', ['PRAGMA query_only']],
        ];
        if (!isset($statements[$driver])) {
            return 'the ' . $driver . ' driver has no read-only session.';
        }
        [$set, $checks] = $statements[$driver];
        try {
            $pdo->exec($set);
        } catch (\Throwable $error) {
            return $set . ' failed: ' . $error->getMessage() . ($driver === 'mysql' ? ' (MySQL 5.6.5 and MariaDB 10.0 or later have read-only sessions.)' : '');
        }
        if (!$verify) {
            return null;
        }
        $last = '';
        foreach ($checks as $check) {
            try {
                $statement = $pdo->query($check);
                $value = $statement === false ? false : $statement->fetchColumn();
                if ($statement !== false) {
                    $statement->closeCursor();
                }
            } catch (\Throwable $error) {
                // MySQL before 5.7.20 and MariaDB before 11.1 call it tx_read_only.
                $last = $error->getMessage();
                continue;
            }
            if (in_array(strtolower((string) $value), ['1', 'on', 'true'], true)) {
                return null;
            }

            return 'the database says the session is not read-only (' . $check . ' = ' . var_export($value, true) . ').';
        }

        return 'Runlet could not check it: ' . $last;
    }

    /**
     * The first defined class or PDO constant, as [name, value] (PHP 8.4 moved driver
     * constants to Pdo\Mysql and Pdo\Sqlite, and later deprecates the PDO:: ones). Also
     * WordPress's PDO connection's TLS attributes (#208).
     *
     * @param string[] $names
     * @return array{0: string, 1: int}|null
     */
    public static function constant(array $names): ?array
    {
        foreach ($names as $name) {
            if (defined($name)) {
                return [$name, (int) constant($name)];
            }
        }

        return null;
    }
}

/**
 * Read-only connections (#139): which statements the runner refuses to send, again after the
 * app (SQLReadOnly.swift holds the same rules). Refused: statements that would make the
 * session writable again (SET … TRANSACTION READ WRITE, SET transaction_read_only,
 * SET default_transaction_read_only, SET SESSION CHARACTERISTICS, BEGIN/START TRANSACTION
 * … READ WRITE, RESET ALL, DISCARD ALL, PRAGMA query_only, set_config()), anything that
 * doesn't start with a reading keyword (or plain transaction control), reads with a writing
 * keyword inside (a writable CTE, SELECT … INTO, FOR UPDATE, EXPLAIN ANALYZE of a write),
 * and a second statement after a `;`. The statement is read as each database could read it:
 * with and without backslash escapes, MySQL's executable comments opened, and `#` as a
 * comment (MySQL) or an operator (PostgreSQL, SQLite).
 */
final class SqlReadOnly
{
    private const READING = ['SELECT', 'SHOW', 'DESCRIBE', 'DESC', 'EXPLAIN', 'VALUES', 'TABLE', 'WITH', 'PRAGMA'];
    private const TRANSACTION = ['BEGIN', 'START', 'COMMIT', 'ROLLBACK', 'END', 'SAVEPOINT', 'RELEASE', 'ABORT'];
    private const SETTINGS = ['TRANSACTION_READ_ONLY', 'TX_READ_ONLY', 'DEFAULT_TRANSACTION_READ_ONLY', 'QUERY_ONLY'];
    private const EMBEDDED = ['INSERT', 'UPDATE', 'DELETE', 'MERGE', 'INTO', 'CREATE', 'DROP', 'ALTER', 'TRUNCATE'];
    private const WRITING = [
        'INSERT', 'UPDATE', 'DELETE', 'REPLACE', 'MERGE', 'UPSERT', 'CREATE', 'ALTER', 'DROP', 'TRUNCATE', 'RENAME',
        'GRANT', 'REVOKE', 'COMMENT', 'LOCK', 'UNLOCK', 'CALL', 'EXEC', 'EXECUTE', 'DO', 'COPY', 'LOAD', 'IMPORT',
        'VACUUM', 'REINDEX', 'CLUSTER', 'REFRESH', 'ATTACH', 'DETACH', 'OPTIMIZE', 'REPAIR', 'ANALYZE', 'FLUSH',
        'PURGE', 'KILL', 'HANDLER', 'SET', 'RESET', 'SECURITY', 'INSTALL', 'UNINSTALL', 'SHUTDOWN',
    ];
    private const PRAGMA_READS = ['TABLE_INFO', 'TABLE_XINFO', 'TABLE_LIST', 'INDEX_INFO', 'INDEX_XINFO', 'INDEX_LIST', 'FOREIGN_KEY_LIST', 'FOREIGN_KEY_CHECK', 'INTEGRITY_CHECK', 'QUICK_CHECK'];

    /**
     * Why `$sql` isn't sent on a read-only connection ("can change data or the schema
     * (INSERT)"), or null when it may run.
     */
    public static function refusal(string $sql, ?string $driver): ?string
    {
        foreach (self::readings($sql, $driver) as [$text, $escapes, $hashComments]) {
            $refusal = self::check(self::tokens($text, $escapes, $hashComments));
            if ($refusal !== null) {
                return $refusal;
            }
        }

        return null;
    }

    /**
     * Init statements (#140): why a saved connection's init statement can't run, or null.
     * Every connection refuses an empty one, several statements in one, and transaction
     * control (an init statement can't leave a transaction open, nor commit one). A read-only
     * connection also refuses what `refusal()` refuses, except session settings (`SET
     * search_path …`, `SET time_zone …`) that leave it read-only and change nothing
     * server-wide; the runner sends them after the read-only setting and checks the setting
     * again afterwards.
     */
    public static function initRefusal(string $sql, ?string $driver, bool $readOnly): ?string
    {
        foreach (self::readings($sql, $driver) as [$text, $escapes, $hashComments]) {
            $refusal = self::checkInit(self::tokens($text, $escapes, $hashComments), $readOnly);
            if ($refusal !== null) {
                return $refusal;
            }
        }

        return null;
    }

    /**
     * The ways `$driver` could read `$sql`: [text, backslash escapes, `#` comments].
     *
     * @return array<int, array{0: string, 1: bool, 2: bool}>
     */
    private static function readings(string $sql, ?string $driver): array
    {
        $backslash = strpos($sql, '\\') !== false;
        $readings = [];
        if ($driver === null || $driver === 'mysql') {
            $readings[] = [$sql, false, true];
            if ($backslash) {
                $readings[] = [$sql, true, true];
            }
            if (preg_match('~/\*M?!~', $sql) === 1) {
                $opened = (string) preg_replace('~/\*M?![0-9]*~', ' ', $sql);
                $readings[] = [$opened, false, true];
                $readings[] = [$opened, true, true];
            }
        }
        if ($driver !== 'mysql') {
            $readings[] = [$sql, false, false];
            if ($backslash && $driver !== 'sqlite') {
                $readings[] = [$sql, true, false];
            }
        }

        return $readings;
    }

    /** @param array<int, array{0: string, 1: string}> $tokens */
    private static function checkInit(array $tokens, bool $readOnly): ?string
    {
        if ($tokens === []) {
            return 'has no statement';
        }
        $semicolon = false;
        foreach ($tokens as [$kind]) {
            if ($kind === ';') {
                $semicolon = true;
            } elseif ($semicolon) {
                return 'holds several statements (give each its own line)';
            }
        }
        $words = [];
        foreach ($tokens as [$kind, $text]) {
            if ($kind === 'w') {
                $words[] = ltrim($text, '@');
            }
        }
        $first = $words[0] ?? '';
        $second = $words[1] ?? '';
        if (in_array($first, self::TRANSACTION, true) && ($first !== 'START' || $second === 'TRANSACTION')) {
            return 'begins or ends a transaction (' . ($first === 'START' ? 'START TRANSACTION' : $first) . '), which an init statement can\'t do';
        }
        if (!$readOnly) {
            return null;
        }
        if ($first === 'SET') {
            foreach ($words as $word) {
                if (in_array($word, ['GLOBAL', 'PERSIST', 'PERSIST_ONLY', 'PASSWORD'], true)) {
                    return 'changes a server-wide setting or an account (SET … ' . $word . ')';
                }
            }
            if ($second === 'DEFAULT' && ($words[2] ?? '') === 'ROLE') {
                return 'changes an account (SET DEFAULT ROLE)';
            }
        }

        return self::check($tokens, true);
    }

    /**
     * @param array<int, array{0: string, 1: string}> $tokens
     * @param bool $sessionSettings Allow SET of settings that keep the session read-only (init statements).
     */
    private static function check(array $tokens, bool $sessionSettings = false): ?string
    {
        if ($tokens === []) {
            return null;
        }
        $semicolon = false;
        foreach ($tokens as [$kind]) {
            if ($kind === ';') {
                $semicolon = true;
            } elseif ($semicolon) {
                return 'holds several statements, and Runlet sends one at a time';
            }
        }
        // Words, and names that include quoted ones (`transaction_read_only`) for the settings.
        $words = [];
        $names = [];
        foreach ($tokens as [$kind, $text]) {
            if ($kind === 'w') {
                $words[] = $text;
                $names[] = ltrim($text, '@');
            } elseif ($kind === 'q') {
                $names[] = $text;
            }
        }
        if ($words === []) {
            return 'is one Runlet can\'t classify, so it can\'t tell whether it changes data';
        }
        $first = $words[0];
        $second = $words[1] ?? '';
        $change = static function (string $phrase): string {
            return 'would make the read-only session writable again (' . $phrase . ')';
        };
        if (in_array('SET_CONFIG', $names, true)) {
            return $change('set_config()');
        }
        foreach ($names as $name) {
            if (in_array($name, self::SETTINGS, true) && in_array($first, ['SET', 'RESET', 'PRAGMA', 'ALTER'], true)) {
                return $change($first . ' ' . strtolower($name));
            }
        }
        $readWrite = false;
        for ($index = 0; $index + 1 < count($tokens); $index++) {
            if ($tokens[$index][0] === 'w' && $tokens[$index][1] === 'READ' && $tokens[$index + 1][0] === 'w' && $tokens[$index + 1][1] === 'WRITE') {
                $readWrite = true;
            }
        }
        if ($first === 'SET' && (in_array('CHARACTERISTICS', $names, true) || $readWrite)) {
            return $change('SET … TRANSACTION READ WRITE');
        }
        if (in_array($first, ['BEGIN', 'START'], true) && $readWrite) {
            return $change($first . ' … READ WRITE');
        }
        if (in_array($first, ['RESET', 'DISCARD'], true) && $second === 'ALL') {
            return $change($first . ' ALL');
        }
        if (in_array($first, self::TRANSACTION, true) && ($first !== 'START' || $second === 'TRANSACTION')) {
            return null;
        }
        if ($first === 'SET' && $sessionSettings) {
            return null;
        }
        if (in_array($first, ['SET', 'RESET'], true)) {
            return 'changes the session\'s settings (' . $first . '), which could make it writable again';
        }
        if (in_array($first, self::WRITING, true)) {
            return 'can change data or the schema (' . $first . ')';
        }
        if (!in_array($first, self::READING, true)) {
            return 'starts with ' . $first . ', and Runlet can\'t tell whether it changes data';
        }
        if ($first === 'PRAGMA') {
            foreach ($tokens as $index => [$kind, $text]) {
                if ($kind === 'p' && $text === '=') {
                    return 'can change data or the schema (PRAGMA … =)';
                }
                if ($kind === 'p' && $text === '(') {
                    $name = '';
                    for ($before = $index - 1; $before >= 0; $before--) {
                        if ($tokens[$before][0] === 'w') {
                            $name = $tokens[$before][1];
                            break;
                        }
                    }

                    return in_array($name, self::PRAGMA_READS, true) ? null : 'can change data or the schema (PRAGMA … (…))';
                }
            }

            return null;
        }
        if ($first === 'EXPLAIN') {
            if (!in_array('ANALYZE', array_slice($words, 1, 3), true)) {
                return null;
            }
            foreach (array_slice($words, 1) as $name) {
                if (in_array($name, self::EMBEDDED, true) && $name !== 'INTO') {
                    return 'can change data or the schema (EXPLAIN ANALYZE … ' . $name . ')';
                }
            }

            return null;
        }
        foreach (array_slice($words, 1) as $position => $name) {
            if (in_array($name, self::EMBEDDED, true)) {
                $previous = $words[$position] ?? '';
                if ($name === 'UPDATE' && in_array($previous, ['FOR', 'KEY'], true)) {
                    return 'can change data or the schema (FOR UPDATE, which locks rows)';
                }

                return 'can change data or the schema (' . ($name === 'INTO' ? $first . ' … INTO' : $name) . ')';
            }
        }

        return null;
    }

    /**
     * The statement's tokens without comments: [kind, text], kind w (word, upper case), q
     * (quoted name, upper case), s (string), n (number), p (punctuation), or ;.
     *
     * @return array<int, array{0: string, 1: string}>
     */
    private static function tokens(string $sql, bool $escapes, bool $hashComments): array
    {
        $tokens = [];
        $length = strlen($sql);
        $i = 0;
        while ($i < $length) {
            $c = $sql[$i];
            $next = $i + 1 < $length ? $sql[$i + 1] : '';
            if (strpos(" \t\r\n\f", $c) !== false) {
                $i++;
                continue;
            }
            if (($c === '-' && $next === '-') || ($hashComments && $c === '#' && $next !== '>' && $next !== '-')) {
                $end = strpos($sql, "\n", $i);
                $i = $end === false ? $length : $end;
                continue;
            }
            if ($c === '/' && $next === '*') {
                $end = strpos($sql, '*/', $i + 2);
                $i = $end === false ? $length : $end + 2;
                continue;
            }
            if ($c === "'" || $c === '"' || $c === '`') {
                $j = $i + 1;
                while ($j < $length) {
                    if ($escapes && $c === "'" && $sql[$j] === '\\') {
                        $j += 2;
                        continue;
                    }
                    if ($sql[$j] === $c) {
                        if ($j + 1 < $length && $sql[$j + 1] === $c) {
                            $j += 2;
                            continue;
                        }
                        break;
                    }
                    $j++;
                }
                $tokens[] = [$c === "'" ? 's' : 'q', strtoupper(substr($sql, $i + 1, max(0, min($j, $length) - $i - 1)))];
                $i = $j + 1;
                continue;
            }
            if ($c === '$' && preg_match('/\G\$([A-Za-z_\x80-\xff][A-Za-z0-9_\x80-\xff]*)?\$/', $sql, $match, 0, $i) === 1) {
                // A dollar-quoted body: $$…$$ or $tag$…$tag$.
                $end = strpos($sql, $match[0], $i + strlen($match[0]));
                $i = $end === false ? $length : $end + strlen($match[0]);
                $tokens[] = ['s', ''];
                continue;
            }
            if (preg_match('/\G[0-9]+[0-9A-Za-z.]*|\G\.[0-9][0-9A-Za-z.]*/', $sql, $match, 0, $i) === 1) {
                $tokens[] = ['n', $match[0]];
                $i += strlen($match[0]);
                continue;
            }
            if (preg_match('/\G[A-Za-z_\x80-\xff@][A-Za-z0-9_$@\x80-\xff]*/', $sql, $match, 0, $i) === 1) {
                $tokens[] = ['w', strtoupper($match[0])];
                $i += strlen($match[0]);
                continue;
            }
            $tokens[] = [$c === ';' ? ';' : 'p', $c];
            $i++;
        }

        return $tokens;
    }
}
}

/*
 * WordPress's own PDO connection for SQL tabs (#208). WordPressDriver::sqlConnection() asks
 * for it when an SQL feature needs the connection, never while WordPress boots. It is opened
 * with the application's own settings, read in the target's PHP after WordPress loaded, as
 * Laravel's connection uses its .env: Runlet never asks for, sees, or stores them.
 *
 *  - MySQL and MariaDB (`$wpdb` is WordPress's own wpdb, or Query Monitor's QM_DB, which only
 *    times queries): pdo_mysql with DB_HOST (every form wpdb::parse_db_host() reads: host,
 *    host:port, host:/socket, :/socket, [IPv6]:port), DB_NAME, DB_USER, DB_PASSWORD, and the
 *    charset and collation $wpdb uses. MYSQL_CLIENT_FLAGS with MYSQLI_CLIENT_SSL, and the
 *    MYSQL_SSL_CA / _CAPATH / _CERT / _KEY / _CIPHER constants hosts set, turn on TLS (checked
 *    after connecting). The session's sql_mode loses the modes wpdb removes.
 *  - The SQLite Database Integration drop-in: pdo_sqlite on its file (FQDB, else DB_DIR and
 *    DB_FILE), with foreign keys on, as the drop-in opens it. Statements are SQLite's there.
 *
 * Otherwise SQL tabs keep running statements through $wpdb (SqlConnections::wpdb()), and the
 * origin says why: RUNLET_WPDB_ONLY is set, a db.php drop-in Runlet doesn't recognise (HyperDB,
 * LudicrousDB, a custom one, a multisite's separate databases), $wpdb connected with other
 * settings than the constants, a missing PDO driver, or a connection that failed.
 *
 * The password is read from DB_PASSWORD inside connect(), which takes no arguments, with
 * zend.exception_ignore_args on; PDO's errors are rethrown as their message only, scrubbed,
 * and Channel replaces the password in every error, notice, and log event from then on.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

/** The WordPress PDO connection can't be opened; the message is the reason (scrubbed). */
final class WordPressPdoUnavailable extends \RuntimeException
{
}

final class WordPressDatabase
{
    /** Where results say a PDO connection came from. */
    public const PDO_ORIGIN = 'WordPress (PDO from wp-config)';
    /** Where results say a statement ran when the tab chose the `wpdb` connection. */
    public const WPDB_ORIGIN = 'WordPress $wpdb';
    /** $wpdb classes that connect with wpdb's own db_connect(), from wp-config's constants. */
    private const MYSQL_CLASSES = ['wpdb', 'QM_DB'];
    /** wpdb::$incompatible_modes: the SQL modes wpdb removes from its session. */
    private const INCOMPATIBLE_MODES = ['NO_ZERO_DATE', 'ONLY_FULL_GROUP_BY', 'STRICT_TRANS_TABLES', 'STRICT_ALL_TABLES', 'TRADITIONAL', 'ANSI'];
    /** mysqli's client flags (MYSQLI_CLIENT_*), for PHP without mysqli. */
    private const CLIENT_COMPRESS = 32;
    private const CLIENT_SSL_DONT_VERIFY = 64;
    private const CLIENT_SSL = 2048;
    private const CLIENT_SSL_VERIFY = 1073741824;
    /** The TLS constants hosts define, by the PDO attribute they become. */
    private const TLS_CONSTANTS = ['SSL_CA' => 'MYSQL_SSL_CA', 'SSL_CAPATH' => 'MYSQL_SSL_CAPATH', 'SSL_CERT' => 'MYSQL_SSL_CERT', 'SSL_KEY' => 'MYSQL_SSL_KEY', 'SSL_CIPHER' => 'MYSQL_SSL_CIPHER'];
    /** Well-known db.php drop-ins Runlet leaves to $wpdb, by their class. */
    private const KNOWN_DROPINS = ['hyperdb' => 'HyperDB', 'ludicrousdb' => 'LudicrousDB', 'm_wpdb' => 'Multi-DB', 'shardb' => 'SharDB'];
    /** Characters kept of PDO's message in the origin. */
    private const MAX_REASON_BYTES = 200;

    /** @var array{pdo: \PDO|null, origin: string}|null This process's connection, opened once. */
    private static $opened;
    /** @var string|null Where the last connection() came from. */
    private static $lastOrigin;
    /** @var array<string, mixed>|null The plan connect() opens; never holds the password. */
    private static $plan;

    /**
     * SQL tabs' connection for WordPress: this process's PDO, opened on first use, or $wpdb's
     * callable when PDO isn't possible (origin() says why). `$wpdbOnly` (the tab chose the
     * `wpdb` connection) always returns the callable and opens nothing.
     *
     * @param object $wpdb
     * @return \PDO|callable
     */
    public static function connection($wpdb, bool $wpdbOnly = false)
    {
        if ($wpdbOnly) {
            self::$lastOrigin = self::WPDB_ORIGIN;

            return \Runlet\SqlConnections::wpdb($wpdb);
        }
        if (self::$opened === null) {
            self::$opened = self::open($wpdb);
        }
        self::$lastOrigin = self::$opened['origin'];

        return self::$opened['pdo'] ?? \Runlet\SqlConnections::wpdb($wpdb);
    }

    /** "WordPress (PDO from wp-config)" or "WordPress ($wpdb, because …)"; null before connection(). */
    public static function origin(): ?string
    {
        return self::$lastOrigin;
    }

    /** Whether `$origin` is a connection through $wpdb's callable (which speaks MySQL). */
    public static function isWpdb(string $origin): bool
    {
        return $origin === self::WPDB_ORIGIN || strpos($origin, 'WordPress ($wpdb') === 0;
    }

    /** @return array{pdo: \PDO|null, origin: string} */
    private static function open($wpdb): array
    {
        $plan = self::plan(self::environment($wpdb));
        if (isset($plan['fallback'])) {
            return self::fallback((string) $plan['fallback']);
        }
        if ($plan['driver'] === 'mysql' && defined('DB_PASSWORD')) {
            // Errors, notices, and log lines never carry it (results are the database's data).
            Channel::addSecret((string) constant('DB_PASSWORD'), false);
        }
        self::$plan = $plan;
        try {
            $pdo = self::connect();
            $details = self::configure($pdo, $plan);
        } catch (WordPressPdoUnavailable $unavailable) {
            return self::fallback($unavailable->getMessage());
        } catch (\Throwable $error) {
            return self::fallback(Channel::scrub('PDO couldn\'t set the session up as $wpdb does: ' . $error->getMessage()));
        } finally {
            self::$plan = null;
        }
        Runner::log('sql', 'WordPress: PDO connection from wp-config.php (' . $plan['summary'] . ')', $details === [] ? null : implode("\n", $details));

        return ['pdo' => $pdo, 'origin' => self::PDO_ORIGIN];
    }

    /** @return array{pdo: null, origin: string} */
    private static function fallback(string $reason): array
    {
        $reason = Channel::scrub($reason);
        if (strlen($reason) > self::MAX_REASON_BYTES) {
            $cut = function_exists('mb_strcut') ? mb_strcut($reason, 0, self::MAX_REASON_BYTES, 'UTF-8') : substr($reason, 0, self::MAX_REASON_BYTES);
            $reason = rtrim($cut) . '…';
        }
        Runner::log('sql', 'WordPress: statements run through $wpdb, because ' . $reason, 'Browse Table edits, bound values, Import CSV, Explain, the server panel, and cancelling on the server need a PDO connection.'
            . (strpos($reason, 'RUNLET_WPDB_ONLY') === 0 ? ' Remove RUNLET_WPDB_ONLY to let Runlet open one from wp-config.php.' : ' Define RUNLET_WPDB_ONLY in wp-config.php to use $wpdb without trying PDO, or save a connection for this target.'));

        return ['pdo' => null, 'origin' => 'WordPress ($wpdb, because ' . $reason . ')'];
    }

    /**
     * What plan() reads, from the running WordPress: `class` ($wpdb's), `dropIn` (the db.php
     * drop-in's path, or null), `multisite`, `wpdbOnly` (RUNLET_WPDB_ONLY), `engine`
     * (DB_ENGINE), `sqliteFile` (FQDB, else DB_DIR/WP_CONTENT_DIR and DB_FILE), the `name`,
     * `user`, and `host` constants (null when not text), `charset` and `collate` ($wpdb's, else
     * DB_CHARSET / DB_COLLATE), `flags` (MYSQL_CLIENT_FLAGS), `tls` (the MYSQL_SSL_* constants),
     * `wpdb` ($wpdb's own dbname, dbhost, and dbuser, when it has them), and `defaultSocket` /
     * `defaultPort` (mysqli's defaults). Never the password.
     *
     * @param object $wpdb
     * @return array<string, mixed>
     */
    public static function environment($wpdb): array
    {
        $text = static function (string $name): ?string {
            if (!defined($name)) {
                return null;
            }
            $value = constant($name);

            return is_string($value) || is_int($value) ? (string) $value : null;
        };
        $contentDir = defined('WP_CONTENT_DIR') ? rtrim((string) WP_CONTENT_DIR, '/') : (defined('ABSPATH') ? rtrim((string) ABSPATH, '/') . '/wp-content' : null);
        $dropIn = $contentDir !== null && is_file($contentDir . '/db.php') ? $contentDir . '/db.php' : null;
        $sqliteFile = $text('FQDB');
        if ($sqliteFile === null) {
            $directory = $text('DB_DIR');
            $directory = $directory !== null ? rtrim($directory, '/') . '/' : ($contentDir !== null ? $contentDir . '/database/' : null);
            $sqliteFile = $directory === null ? null : $directory . ($text('DB_FILE') ?? '.ht.sqlite');
        }
        $tls = [];
        foreach (self::TLS_CONSTANTS as $constant) {
            $value = $text($constant);
            if ($value !== null && $value !== '') {
                $tls[$constant] = $value;
            }
        }
        $own = [];
        foreach (['dbname' => 'name', 'dbhost' => 'host', 'dbuser' => 'user'] as $property => $key) {
            $value = self::property($wpdb, $property);
            if (is_string($value)) {
                $own[$key] = $value;
            }
        }
        $charset = self::property($wpdb, 'charset');
        $collate = self::property($wpdb, 'collate');
        $flags = defined('MYSQL_CLIENT_FLAGS') ? constant('MYSQL_CLIENT_FLAGS') : 0;

        return [
            'class' => get_class($wpdb),
            'dropIn' => $dropIn,
            'multisite' => function_exists('is_multisite') && \is_multisite(),
            'wpdbOnly' => defined('RUNLET_WPDB_ONLY') && (bool) constant('RUNLET_WPDB_ONLY'),
            'engine' => $text('DB_ENGINE'),
            'sqliteFile' => $sqliteFile,
            'name' => $text('DB_NAME'),
            'user' => $text('DB_USER'),
            'host' => $text('DB_HOST'),
            'charset' => is_string($charset) && $charset !== '' ? $charset : ($text('DB_CHARSET') ?? ''),
            'collate' => is_string($collate) && $collate !== '' ? $collate : ($text('DB_COLLATE') ?? ''),
            'flags' => is_int($flags) ? $flags : (int) $flags,
            'tls' => $tls,
            'wpdb' => $own,
            'defaultSocket' => (string) ini_get('mysqli.default_socket'),
            'defaultPort' => (int) ini_get('mysqli.default_port'),
        ];
    }

    /** A property of $wpdb, also a protected one (wpdb's dbname, dbhost, …), without running its code; null when it has none. */
    private static function property($object, string $name)
    {
        try {
            $reflection = new \ReflectionObject($object);
            if (!$reflection->hasProperty($name)) {
                return null;
            }
            $property = $reflection->getProperty($name);
            $property->setAccessible(true);

            return $property->isInitialized($object) ? $property->getValue($object) : null;
        } catch (\Throwable $error) {
            return null;
        }
    }

    /**
     * How the connection opens: `driver`, `dsn`, `user`, `attributes` (by constant name, as
     * SqlConnect::plan()), `tls`, `charset`, `collate`, and a `summary` for messages, or
     * `fallback` with the reason $wpdb is kept. `$environment` is environment()'s shape;
     * `$available` defaults to this PHP's PDO drivers. Opens nothing.
     *
     * @param array<string, mixed> $environment
     * @param string[]|null $available
     * @return array<string, mixed>
     */
    public static function plan(array $environment, ?array $available = null): array
    {
        if (!empty($environment['wpdbOnly'])) {
            return ['fallback' => 'RUNLET_WPDB_ONLY is set'];
        }
        if ($available === null) {
            $available = class_exists('PDO', false) ? \PDO::getAvailableDrivers() : [];
        }
        $class = (string) ($environment['class'] ?? '');
        $mysqlClass = in_array(strtolower($class), array_map('strtolower', self::MYSQL_CLASSES), true);
        if (stripos($class, 'sqlite') !== false || (!$mysqlClass && strtolower((string) ($environment['engine'] ?? '')) === 'sqlite')) {
            return self::sqlitePlan($environment, $available);
        }
        if (!$mysqlClass) {
            $known = self::KNOWN_DROPINS[strtolower($class)] ?? $class;
            $by = ($environment['dropIn'] ?? null) !== null ? 'the db.php drop-in replaces wpdb with ' . $known : '$wpdb is ' . $known . ', not wpdb';

            return ['fallback' => $by . ', which Runlet doesn\'t open itself' . (!empty($environment['multisite']) ? ' (a multisite\'s databases can be split)' : '')];
        }
        $name = $environment['name'] ?? null;
        $user = $environment['user'] ?? null;
        $host = $environment['host'] ?? null;
        if (!is_string($name) || $name === '' || !is_string($user) || !is_string($host)) {
            return ['fallback' => 'wp-config.php doesn\'t define DB_NAME, DB_USER, and DB_HOST as text'];
        }
        $own = is_array($environment['wpdb'] ?? null) ? $environment['wpdb'] : [];
        foreach (['name' => 'DB_NAME', 'host' => 'DB_HOST', 'user' => 'DB_USER'] as $key => $constant) {
            if (isset($own[$key]) && $own[$key] !== $environment[$key]) {
                return ['fallback' => '$wpdb connected with another ' . $constant . ' than wp-config.php defines'];
            }
        }
        if (!in_array('mysql', $available, true)) {
            return ['fallback' => 'this PHP has no pdo_mysql (it has ' . ($available === [] ? 'no PDO drivers' : 'pdo_' . implode(', pdo_', $available)) . ')'];
        }
        $parsed = self::parseHost($host);
        if ($parsed === null) {
            return ['fallback' => 'DB_HOST "' . $host . '" isn\'t a host, port, or socket Runlet can read'];
        }
        [$address, $port, $socket, $ipv6] = $parsed;
        if ($address !== '' && preg_match('/^[A-Za-z0-9._%:-]+$/', $address) !== 1) {
            return ['fallback' => 'DB_HOST "' . $host . '" isn\'t a host, port, or socket Runlet can read'];
        }
        if (preg_match('/[;\x00-\x1f]/', $name) === 1) {
            return ['fallback' => 'DB_NAME contains ";" or control characters, which a PDO DSN can\'t hold'];
        }
        // mysqli (and so $wpdb) talks to "localhost" over a Unix socket: DB_HOST's, else mysqli's default.
        $local = $address === '' || strtolower($address) === 'localhost';
        if ($local) {
            $socket = $socket ?? (($environment['defaultSocket'] ?? '') !== '' ? (string) $environment['defaultSocket'] : null);
            if ($socket !== null && preg_match('/[;\x00-\x1f]/', $socket) === 1) {
                return ['fallback' => 'the socket path in DB_HOST contains ";" or control characters'];
            }
            $dsn = 'mysql:host=localhost' . ($socket !== null ? ';unix_socket=' . $socket : '');
            $where = 'localhost' . ($socket !== null ? ' (' . $socket . ')' : '');
        } else {
            $port = $port ?? ((int) ($environment['defaultPort'] ?? 0) > 0 ? (int) $environment['defaultPort'] : 3306);
            $address = $ipv6 ? '[' . $address . ']' : $address;
            $dsn = 'mysql:host=' . $address . ';port=' . $port;
            $where = $address . ':' . $port;
        }
        $dsn .= ';dbname=' . $name;
        $charset = (string) ($environment['charset'] ?? '');
        $collate = (string) ($environment['collate'] ?? '');
        if ($charset !== '') {
            if (preg_match('/^[A-Za-z0-9_]{1,40}$/', $charset) !== 1) {
                return ['fallback' => 'the charset "' . $charset . '" isn\'t a character set name'];
            }
            $dsn .= ';charset=' . $charset;
        }
        if ($collate !== '' && preg_match('/^[A-Za-z0-9_]{1,64}$/', $collate) !== 1) {
            return ['fallback' => 'the collation "' . $collate . '" isn\'t a collation name'];
        }
        $attributes = ['PDO::ATTR_TIMEOUT' => [\PDO::ATTR_TIMEOUT, 10]];
        $flags = (int) ($environment['flags'] ?? 0);
        $tlsConstants = is_array($environment['tls'] ?? null) ? $environment['tls'] : [];
        $tls = ($flags & self::CLIENT_SSL) !== 0 || $tlsConstants !== [];
        if ($tls) {
            $verify = ($flags & self::CLIENT_SSL_VERIFY) !== 0
                ? true
                // mysqlnd checks the server's certificate when it has a CA to check it with.
                : (($flags & self::CLIENT_SSL_DONT_VERIFY) !== 0 ? false : isset($tlsConstants['MYSQL_SSL_CA']) || isset($tlsConstants['MYSQL_SSL_CAPATH']));
            $set = ['SSL_CA' => ''];
            foreach (self::TLS_CONSTANTS as $suffix => $constant) {
                if (isset($tlsConstants[$constant])) {
                    $value = (string) $tlsConstants[$constant];
                    if ($suffix !== 'SSL_CIPHER' && ($value[0] !== '/' || !is_readable($value))) {
                        return ['fallback' => $constant . ' (' . $value . ') isn\'t a file this PHP can read'];
                    }
                    $set[$suffix] = $value;
                }
            }
            if (isset($set['SSL_CAPATH']) && !isset($tlsConstants['MYSQL_SSL_CA'])) {
                unset($set['SSL_CA']);
            }
            $set['SSL_VERIFY_SERVER_CERT'] = $verify;
            foreach ($set as $suffix => $value) {
                $constant = SqlConnect::constant(['Pdo\Mysql::ATTR_' . $suffix, 'PDO::MYSQL_ATTR_' . $suffix]);
                if ($constant === null) {
                    return ['fallback' => 'wp-config.php asks for TLS, and this PHP\'s pdo_mysql has no PDO::MYSQL_ATTR_' . $suffix];
                }
                $attributes[$constant[0]] = [$constant[1], $value];
            }
        }
        if (($flags & self::CLIENT_COMPRESS) !== 0) {
            $compress = SqlConnect::constant(['Pdo\Mysql::ATTR_COMPRESS', 'PDO::MYSQL_ATTR_COMPRESS']);
            if ($compress !== null) {
                $attributes[$compress[0]] = [$compress[1], true];
            }
        }

        return [
            'driver' => 'mysql',
            'dsn' => $dsn,
            'user' => $user,
            'attributes' => $attributes,
            'tls' => $tls,
            'charset' => $charset,
            'collate' => $collate,
            'summary' => 'mysql, ' . $where . '/' . $name . ($tls ? ', TLS' : ''),
        ];
    }

    /**
     * @param array<string, mixed> $environment
     * @param string[] $available
     * @return array<string, mixed>
     */
    private static function sqlitePlan(array $environment, array $available): array
    {
        if (!in_array('sqlite', $available, true)) {
            return ['fallback' => 'the SQLite drop-in needs pdo_sqlite, and this PHP has ' . ($available === [] ? 'no PDO drivers' : 'pdo_' . implode(', pdo_', $available))];
        }
        $file = $environment['sqliteFile'] ?? null;
        if (!is_string($file) || $file === '' || !is_file($file)) {
            return ['fallback' => 'the SQLite drop-in\'s database file' . (is_string($file) && $file !== '' ? ' (' . $file . ')' : '') . ' wasn\'t found (FQDB, or DB_DIR and DB_FILE)'];
        }

        return [
            'driver' => 'sqlite',
            'dsn' => 'sqlite:' . $file,
            'user' => null,
            'attributes' => ['PDO::ATTR_TIMEOUT' => [\PDO::ATTR_TIMEOUT, 10]],
            'tls' => false,
            'charset' => '',
            'collate' => '',
            'summary' => 'sqlite, ' . $file,
        ];
    }

    /**
     * wpdb::parse_db_host(): DB_HOST as [host, port, socket, isIPv6]. "host", "host:port",
     * "host:/path/to.sock", ":/path/to.sock", "[::1]", "[::1]:3306" (and a bare IPv6 address).
     * Null when wpdb couldn't read it either.
     *
     * @return array{0: string, 1: int|null, 2: string|null, 3: bool}|null
     */
    public static function parseHost(string $host): ?array
    {
        $socket = null;
        $position = strpos($host, ':/');
        if ($position !== false) {
            $socket = substr($host, $position + 1);
            $host = substr($host, 0, $position);
        }
        $ipv6 = substr_count($host, ':') > 1;
        $pattern = $ipv6 ? '#^(?:\[)?(?P<host>[0-9a-fA-F:]+)(?:\]:(?P<port>[\d]+))?#' : '#^(?P<host>[^:/]*)(?::(?P<port>[\d]+))?#';
        if (preg_match($pattern, $host, $matches) !== 1) {
            return null;
        }
        $port = !empty($matches['port']) ? abs((int) $matches['port']) : null;

        return [!empty($matches['host']) ? $matches['host'] : '', $port === 0 ? null : $port, $socket, $ipv6];
    }

    /**
     * Opens self::$plan. It takes no arguments, so neither the password nor the DSN is in a
     * stack frame; PDO's exception is replaced by one with its (scrubbed) message only.
     */
    private static function connect(): \PDO
    {
        $plan = self::$plan;
        if ($plan === null) {
            throw new WordPressPdoUnavailable('no connection was planned');
        }
        $options = [\PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION];
        foreach ($plan['attributes'] as [$key, $value]) {
            $options[$key] = $value;
        }
        $ignoreArgs = ini_get('zend.exception_ignore_args');
        ini_set('zend.exception_ignore_args', '1');
        $warnings = [];
        set_error_handler(static function (int $severity, string $message) use (&$warnings): bool {
            $warnings[] = $message;

            return true;
        });
        $message = '';
        $pdo = null;
        try {
            $pdo = $plan['driver'] === 'sqlite'
                ? new \PDO($plan['dsn'], null, null, $options)
                : new \PDO($plan['dsn'], $plan['user'], defined('DB_PASSWORD') ? (string) constant('DB_PASSWORD') : '', $options);
        } catch (\Throwable $error) {
            $message = $error->getMessage();
        } finally {
            restore_error_handler();
            if ($ignoreArgs !== false) {
                ini_set('zend.exception_ignore_args', $ignoreArgs);
            }
        }
        if ($pdo === null) {
            if ($message === '' && $warnings !== []) {
                $message = implode(' ', $warnings);
            }
            // Thrown outside the catch, with no previous exception: nothing of PDO's trace stays.
            throw new WordPressPdoUnavailable(Channel::scrub('PDO couldn\'t connect: ' . $message));
        }

        return $pdo;
    }

    /**
     * The session as $wpdb has it: MySQL's TLS checked, SET NAMES with the collation, and the
     * sql_mode without wpdb's incompatible modes; SQLite's foreign keys on. Returns what it set,
     * for the Run Log.
     *
     * @param array<string, mixed> $plan
     * @return string[]
     */
    private static function configure(\PDO $pdo, array $plan): array
    {
        if ($plan['driver'] === 'sqlite') {
            $pdo->exec('PRAGMA foreign_keys = ON');

            return ['foreign keys on, as the SQLite drop-in opens the file'];
        }
        $details = [];
        if ($plan['tls']) {
            $row = $pdo->query("SHOW SESSION STATUS LIKE 'Ssl_cipher'")->fetch(\PDO::FETCH_NUM);
            $cipher = is_array($row) ? (string) ($row[1] ?? '') : '';
            if ($cipher === '') {
                throw new WordPressPdoUnavailable('wp-config.php asks for TLS, and the server didn\'t encrypt the PDO session');
            }
            $details[] = 'TLS: ' . $cipher;
        }
        if ($plan['charset'] !== '' && $plan['collate'] !== '') {
            $pdo->exec("SET NAMES '" . $plan['charset'] . "' COLLATE '" . $plan['collate'] . "'");
        }
        if ($plan['charset'] !== '') {
            $details[] = 'charset ' . $plan['charset'] . ($plan['collate'] !== '' ? ', collation ' . $plan['collate'] : '');
        }
        $current = $pdo->query('SELECT @@SESSION.sql_mode')->fetchColumn();
        if (is_string($current) && $current !== '') {
            $incompatible = self::INCOMPATIBLE_MODES;
            if (function_exists('apply_filters')) {
                $incompatible = (array) \apply_filters('incompatible_sql_modes', $incompatible);
            }
            $modes = array_values(array_filter(explode(',', $current), static function (string $mode) use ($incompatible): bool {
                return !in_array(strtoupper($mode), $incompatible, true);
            }));
            $statement = $pdo->prepare('SET SESSION sql_mode = ?');
            $statement->execute([implode(',', $modes)]);
            $details[] = 'sql_mode ' . ($modes === [] ? '(empty)' : implode(',', $modes)) . ', without the modes wpdb removes';
        }

        return $details;
    }
}
}

/*
 * SQL tabs' schema (#128, #21): the tables and columns of a connection for completion and the
 * schema explorer, with their kind (table or view), approximate row counts, column details
 * (nullable, default, primary key, foreign key), and indexes. Only the database's catalog is
 * read, never rows. SqlTab resolves the connection and emits the `sqlSchema` event.
 *
 * Per database, one catalog query for the columns (a detailed one, else the plain one from
 * #128), then one for indexes and one for foreign keys. Those two are extras: when one fails,
 * the schema still has its tables and columns, and a note says what is missing.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

final class SqlSchema
{
    /** Tables and columns reported at most, and the longest name kept. */
    public const MAX_TABLES = 2000;
    public const MAX_COLUMNS = 50000;
    /** Index columns reported at most (all tables together). */
    public const MAX_INDEX_COLUMNS = 20000;
    public const MAX_NAME_BYTES = 200;
    /** Bytes of a column default kept. */
    private const MAX_DEFAULT_BYTES = 200;

    /**
     * The driver's sqlSchema(), else the connection's own catalog.
     *
     * @param \PDO|callable $source
     * @return array<string, mixed> `tables`, `how`, and `truncated`/`notes` when they apply
     */
    public static function read(?string $connection, $source, string $origin, ?string $driverName): array
    {
        $driver = Runner::bootedDriver();
        if ($driver !== null) {
            $declared = Runner::callBootedDriver('sqlSchema()', static function () use ($driver, $connection) {
                return $driver->sqlSchema($connection);
            });
            if (is_array($declared)) {
                $declaring = (new \ReflectionMethod($driver, 'sqlSchema'))->getDeclaringClass()->getName();

                return self::declared($declared) + ['how' => $declaring . '::sqlSchema()'];
            }
        }
        $dialects = self::dialects($source, $origin, $driverName);
        if ($dialects === []) {
            throw new \RuntimeException('Runlet doesn\'t know how to list the tables of ' . ($driverName ?? 'this') . ' connections. Return them from sqlSchema() in a project driver.');
        }
        $failure = null;
        foreach ($dialects as $dialect) {
            $queries = self::queries($dialect);
            $rows = null;
            foreach ([$queries['columns'], $queries['plainColumns']] as $sql) {
                try {
                    $rows = self::fetch($source, $sql, self::MAX_COLUMNS + 1);
                    break;
                } catch (\Throwable $error) {
                    $failure = $failure ?? $error;
                }
            }
            if ($rows === null) {
                continue;
            }
            $builder = new SchemaBuilder();
            $builder->addColumns($rows);
            foreach (['indexes' => 'Indexes', 'foreignKeys' => 'Foreign keys'] as $kind => $label) {
                if (!isset($queries[$kind])) {
                    continue;
                }
                try {
                    $extra = self::fetch($source, $queries[$kind], self::MAX_INDEX_COLUMNS + 1);
                    $kind === 'indexes' ? $builder->addIndexes($extra) : $builder->addForeignKeys($extra);
                } catch (\Throwable $error) {
                    $builder->note($label . ' could not be read: ' . $error->getMessage());
                }
            }

            return $builder->result() + ['how' => $queries['how']];
        }
        throw new \RuntimeException(($failure !== null ? $failure->getMessage() : 'no tables') . ' Return the schema from sqlSchema() in a project driver if this connection can\'t list its tables.');
    }

    /**
     * The catalogs to try: the PDO driver's, or for a callable (its dialect unknown) each in
     * turn ($wpdb is MySQL).
     *
     * @param \PDO|callable $source
     * @return string[]
     */
    private static function dialects($source, string $origin, ?string $driverName): array
    {
        switch ($driverName) {
            case 'sqlite':
            case 'mysql':
            case 'pgsql':
                return [$driverName];
            case 'sqlsrv':
            case 'dblib':
                return ['sqlsrv'];
        }
        if ($source instanceof \PDO) {
            return [];
        }

        return WordPressDatabase::isWpdb($origin) ? ['mysql', 'sqlite'] : ['mysql', 'pgsql', 'sqlite'];
    }

    /**
     * One dialect's catalog queries. Columns rows: table, column, type, nullable, default,
     * primary key, kind (`table` or `view`), approximate rows. Index rows: table, index,
     * unique, primary, column. Foreign key rows: table, column, referenced table, referenced
     * column, and the constraint they belong to (#153: a composite key's columns share it).
     * Columns have distinct names: callables may return associative rows.
     *
     * @return array<string, string>
     */
    private static function queries(string $dialect): array
    {
        switch ($dialect) {
            case 'sqlite':
                return [
                    'how' => 'sqlite_master',
                    'columns' => <<<'SQL'
                        SELECT m.name AS table_name, p.name AS column_name, p.type AS data_type,
                            CASE WHEN p."notnull" = 0 AND p.pk = 0 THEN 1 ELSE 0 END AS nullable, p.dflt_value AS column_default,
                            CASE WHEN p.pk > 0 THEN 1 ELSE 0 END AS primary_key, m.type AS table_kind, NULL AS approx_rows
                        FROM sqlite_master m JOIN pragma_table_info(m.name) p
                        WHERE m.type IN ('table', 'view') AND m.name NOT LIKE 'sqlite\_%' ESCAPE '\'
                        ORDER BY m.name, p.cid
                        SQL,
                    'plainColumns' => <<<'SQL'
                        SELECT m.name AS table_name, p.name AS column_name, p.type AS data_type
                        FROM sqlite_master m JOIN pragma_table_info(m.name) p
                        WHERE m.type IN ('table', 'view') AND m.name NOT LIKE 'sqlite\_%' ESCAPE '\'
                        ORDER BY m.name, p.cid
                        SQL,
                    'indexes' => <<<'SQL'
                        SELECT m.name AS table_name, il.name AS index_name, il."unique" AS is_unique,
                            CASE WHEN il.origin = 'pk' THEN 1 ELSE 0 END AS is_primary, ii.name AS column_name
                        FROM sqlite_master m JOIN pragma_index_list(m.name) il JOIN pragma_index_info(il.name) ii
                        WHERE m.type = 'table' AND m.name NOT LIKE 'sqlite\_%' ESCAPE '\'
                        ORDER BY m.name, il.name, ii.seqno
                        SQL,
                    'foreignKeys' => <<<'SQL'
                        SELECT m.name AS table_name, fk."from" AS column_name, fk."table" AS referenced_table, fk."to" AS referenced_column,
                            fk.id AS constraint_name
                        FROM sqlite_master m JOIN pragma_foreign_key_list(m.name) fk
                        WHERE m.type = 'table'
                        ORDER BY m.name, fk.id, fk.seq
                        SQL,
                ];
            case 'mysql':
                return [
                    'how' => 'information_schema',
                    'columns' => <<<'SQL'
                        SELECT c.TABLE_NAME AS table_name, c.COLUMN_NAME AS column_name, c.DATA_TYPE AS data_type,
                            CASE WHEN c.IS_NULLABLE = 'YES' THEN 1 ELSE 0 END AS nullable, c.COLUMN_DEFAULT AS column_default,
                            CASE WHEN c.COLUMN_KEY = 'PRI' THEN 1 ELSE 0 END AS primary_key,
                            CASE WHEN t.TABLE_TYPE = 'VIEW' THEN 'view' ELSE 'table' END AS table_kind, t.TABLE_ROWS AS approx_rows
                        FROM information_schema.COLUMNS c
                        JOIN information_schema.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
                        WHERE c.TABLE_SCHEMA = DATABASE()
                        ORDER BY c.TABLE_NAME, c.ORDINAL_POSITION
                        SQL,
                    'plainColumns' => <<<'SQL'
                        SELECT TABLE_NAME AS table_name, COLUMN_NAME AS column_name, DATA_TYPE AS data_type
                        FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() ORDER BY TABLE_NAME, ORDINAL_POSITION
                        SQL,
                    'indexes' => <<<'SQL'
                        SELECT TABLE_NAME AS table_name, INDEX_NAME AS index_name, CASE WHEN NON_UNIQUE = 0 THEN 1 ELSE 0 END AS is_unique,
                            CASE WHEN INDEX_NAME = 'PRIMARY' THEN 1 ELSE 0 END AS is_primary, COLUMN_NAME AS column_name
                        FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE()
                        ORDER BY TABLE_NAME, INDEX_NAME, SEQ_IN_INDEX
                        SQL,
                    'foreignKeys' => <<<'SQL'
                        SELECT TABLE_NAME AS table_name, COLUMN_NAME AS column_name,
                            CASE WHEN REFERENCED_TABLE_SCHEMA = DATABASE() THEN REFERENCED_TABLE_NAME ELSE CONCAT(REFERENCED_TABLE_SCHEMA, '.', REFERENCED_TABLE_NAME) END AS referenced_table,
                            REFERENCED_COLUMN_NAME AS referenced_column, CONSTRAINT_NAME AS constraint_name
                        FROM information_schema.KEY_COLUMN_USAGE
                        WHERE TABLE_SCHEMA = DATABASE() AND REFERENCED_TABLE_NAME IS NOT NULL
                        ORDER BY TABLE_NAME, CONSTRAINT_NAME, ORDINAL_POSITION
                        SQL,
                ];
            case 'pgsql':
                return [
                    'how' => 'information_schema',
                    'columns' => <<<'SQL'
                        SELECT CASE WHEN c.table_schema = current_schema() THEN c.table_name ELSE c.table_schema || '.' || c.table_name END AS table_name,
                            c.column_name AS column_name, c.data_type AS data_type,
                            CASE WHEN c.is_nullable = 'YES' THEN 1 ELSE 0 END AS nullable, c.column_default AS column_default,
                            CASE WHEN EXISTS (
                                SELECT 1 FROM pg_catalog.pg_constraint pc
                                JOIN pg_catalog.pg_class pt ON pt.oid = pc.conrelid
                                JOIN pg_catalog.pg_namespace pn ON pn.oid = pt.relnamespace
                                JOIN pg_catalog.pg_attribute pa ON pa.attrelid = pc.conrelid AND pa.attnum = ANY (pc.conkey)
                                WHERE pc.contype = 'p' AND pn.nspname = c.table_schema AND pt.relname = c.table_name AND pa.attname = c.column_name
                            ) THEN 1 ELSE 0 END AS primary_key,
                            CASE WHEN t.table_type = 'VIEW' THEN 'view' ELSE 'table' END AS table_kind,
                            (SELECT CASE WHEN cl.reltuples < 0 THEN NULL ELSE cl.reltuples::bigint END
                                FROM pg_catalog.pg_class cl JOIN pg_catalog.pg_namespace n ON n.oid = cl.relnamespace
                                WHERE n.nspname = c.table_schema AND cl.relname = c.table_name) AS approx_rows
                        FROM information_schema.columns c
                        JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name
                        WHERE c.table_schema = ANY (current_schemas(false))
                        ORDER BY 1, c.ordinal_position
                        SQL,
                    'plainColumns' => <<<'SQL'
                        SELECT CASE WHEN c.table_schema = current_schema() THEN c.table_name ELSE c.table_schema || '.' || c.table_name END AS table_name,
                            c.column_name AS column_name, c.data_type AS data_type
                        FROM information_schema.columns c WHERE c.table_schema = ANY (current_schemas(false)) ORDER BY 1, c.ordinal_position
                        SQL,
                    'indexes' => <<<'SQL'
                        SELECT CASE WHEN n.nspname = current_schema() THEN t.relname ELSE n.nspname || '.' || t.relname END AS table_name,
                            i.relname AS index_name, CASE WHEN ix.indisunique THEN 1 ELSE 0 END AS is_unique,
                            CASE WHEN ix.indisprimary THEN 1 ELSE 0 END AS is_primary, a.attname AS column_name
                        FROM pg_catalog.pg_index ix
                        JOIN pg_catalog.pg_class t ON t.oid = ix.indrelid
                        JOIN pg_catalog.pg_class i ON i.oid = ix.indexrelid
                        JOIN pg_catalog.pg_namespace n ON n.oid = t.relnamespace
                        CROSS JOIN LATERAL unnest(ix.indkey) WITH ORDINALITY AS k(attnum, ord)
                        LEFT JOIN pg_catalog.pg_attribute a ON a.attrelid = t.oid AND a.attnum = k.attnum
                        WHERE n.nspname = ANY (current_schemas(false))
                        ORDER BY 1, 2, k.ord
                        SQL,
                    'foreignKeys' => <<<'SQL'
                        SELECT CASE WHEN n.nspname = current_schema() THEN t.relname ELSE n.nspname || '.' || t.relname END AS table_name,
                            a.attname AS column_name,
                            CASE WHEN rn.nspname = current_schema() THEN rt.relname ELSE rn.nspname || '.' || rt.relname END AS referenced_table,
                            ra.attname AS referenced_column, c.conname AS constraint_name
                        FROM pg_catalog.pg_constraint c
                        JOIN pg_catalog.pg_class t ON t.oid = c.conrelid
                        JOIN pg_catalog.pg_namespace n ON n.oid = t.relnamespace
                        JOIN pg_catalog.pg_class rt ON rt.oid = c.confrelid
                        JOIN pg_catalog.pg_namespace rn ON rn.oid = rt.relnamespace
                        CROSS JOIN LATERAL unnest(c.conkey, c.confkey) WITH ORDINALITY AS k(col, refcol, ord)
                        JOIN pg_catalog.pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.col
                        JOIN pg_catalog.pg_attribute ra ON ra.attrelid = c.confrelid AND ra.attnum = k.refcol
                        WHERE c.contype = 'f' AND n.nspname = ANY (current_schemas(false))
                        ORDER BY 1, c.conname, k.ord
                        SQL,
                ];
            default: // sqlsrv: columns with their details; indexes and foreign keys are not read.
                return [
                    'how' => 'INFORMATION_SCHEMA',
                    'columns' => <<<'SQL'
                        SELECT CASE WHEN c.TABLE_SCHEMA = SCHEMA_NAME() THEN c.TABLE_NAME ELSE c.TABLE_SCHEMA + '.' + c.TABLE_NAME END AS table_name,
                            c.COLUMN_NAME AS column_name, c.DATA_TYPE AS data_type,
                            CASE WHEN c.IS_NULLABLE = 'YES' THEN 1 ELSE 0 END AS nullable, c.COLUMN_DEFAULT AS column_default,
                            CASE WHEN EXISTS (
                                SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
                                JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE k ON k.CONSTRAINT_NAME = tc.CONSTRAINT_NAME AND k.CONSTRAINT_SCHEMA = tc.CONSTRAINT_SCHEMA
                                WHERE tc.CONSTRAINT_TYPE = 'PRIMARY KEY' AND tc.TABLE_SCHEMA = c.TABLE_SCHEMA AND tc.TABLE_NAME = c.TABLE_NAME AND k.COLUMN_NAME = c.COLUMN_NAME
                            ) THEN 1 ELSE 0 END AS primary_key,
                            CASE WHEN t.TABLE_TYPE = 'VIEW' THEN 'view' ELSE 'table' END AS table_kind, NULL AS approx_rows
                        FROM INFORMATION_SCHEMA.COLUMNS c
                        JOIN INFORMATION_SCHEMA.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
                        ORDER BY 1, c.ORDINAL_POSITION
                        SQL,
                    'plainColumns' => <<<'SQL'
                        SELECT CASE WHEN TABLE_SCHEMA = SCHEMA_NAME() THEN TABLE_NAME ELSE TABLE_SCHEMA + '.' + TABLE_NAME END AS table_name,
                            COLUMN_NAME AS column_name, DATA_TYPE AS data_type
                        FROM INFORMATION_SCHEMA.COLUMNS ORDER BY 1, ORDINAL_POSITION
                        SQL,
                ];
        }
    }

    /**
     * Rows of a catalog query as lists of values, at most `$limit`.
     *
     * @param \PDO|callable $source
     * @return array<int, array<int, mixed>>
     */
    private static function fetch($source, string $sql, int $limit): array
    {
        $rows = [];
        if ($source instanceof \PDO) {
            $source->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
            $statement = $source->query($sql);
            while (($row = $statement->fetch(\PDO::FETCH_NUM)) !== false) {
                $rows[] = $row;
                if (count($rows) >= $limit) {
                    break;
                }
            }
            $statement->closeCursor();

            return $rows;
        }
        $returned = $source($sql);
        if (!is_iterable($returned)) {
            throw new \UnexpectedValueException('the connection returned no rows for the catalog query');
        }
        foreach ($returned as $row) {
            $rows[] = array_values(is_object($row) ? get_object_vars($row) : (array) $row);
            if (count($rows) >= $limit) {
                break;
            }
        }

        return $rows;
    }

    /**
     * A driver's own schema: `table => [column => type]` or `table => [column, …]` (#128), or
     * per table `['columns' => [column => type or details], 'indexes' => [...], 'rows' => n,
     * 'kind' => 'view']` (#21). Column details: `type`, `nullable`, `default`, `primaryKey`,
     * `references` (`table.column`). Indexes: `name`, `columns`, `unique`, `primary`.
     *
     * @param array<mixed> $declared
     * @return array<string, mixed>
     */
    private static function declared(array $declared): array
    {
        $builder = new SchemaBuilder();
        $columnRows = [];
        $indexRows = [];
        $foreignKeys = [];
        foreach ($declared as $table => $spec) {
            $table = (string) $table;
            $detailed = is_array($spec) && isset($spec['columns']) && is_array($spec['columns']);
            $columns = $detailed ? $spec['columns'] : (is_array($spec) ? $spec : []);
            $kind = $detailed && ($spec['kind'] ?? null) === 'view' ? 'view' : 'table';
            $rows = $detailed && isset($spec['rows']) && is_numeric($spec['rows']) ? (int) $spec['rows'] : null;
            if ($columns === []) {
                $columnRows[] = [$table, null, null, null, null, null, $kind, $rows];
            }
            foreach ($columns as $key => $value) {
                if (is_int($key)) {
                    $columnRows[] = [$table, is_scalar($value) ? (string) $value : null, null, null, null, null, $kind, $rows];
                    continue;
                }
                if (!is_array($value)) {
                    $columnRows[] = [$table, (string) $key, is_scalar($value) ? (string) $value : null, null, null, null, $kind, $rows];
                    continue;
                }
                $columnRows[] = [
                    $table, (string) $key, isset($value['type']) && is_scalar($value['type']) ? (string) $value['type'] : null,
                    array_key_exists('nullable', $value) ? ($value['nullable'] ? 1 : 0) : null,
                    array_key_exists('default', $value) && is_scalar($value['default']) ? (string) $value['default'] : null,
                    !empty($value['primaryKey']) ? 1 : 0, $kind, $rows,
                ];
                if (isset($value['references']) && is_string($value['references']) && strpos($value['references'], '.') !== false) {
                    $at = (int) strrpos($value['references'], '.');
                    $foreignKeys[] = [$table, (string) $key, substr($value['references'], 0, $at), substr($value['references'], $at + 1)];
                }
            }
            foreach ($detailed && isset($spec['indexes']) && is_array($spec['indexes']) ? $spec['indexes'] : [] as $index) {
                if (!is_array($index) || !isset($index['name'], $index['columns']) || !is_array($index['columns'])) {
                    continue;
                }
                foreach ($index['columns'] as $column) {
                    $indexRows[] = [$table, (string) $index['name'], !empty($index['unique']) ? 1 : 0, !empty($index['primary']) ? 1 : 0, is_scalar($column) ? (string) $column : null];
                }
            }
        }
        $builder->addColumns($columnRows);
        $builder->addIndexes($indexRows);
        $builder->addForeignKeys($foreignKeys);

        return $builder->result();
    }

    /** A clean UTF-8 name within the limit, or null. */
    public static function name($value): ?string
    {
        if (!is_scalar($value)) {
            return null;
        }
        $name = (string) $value;

        return $name === '' || strlen($name) > self::MAX_NAME_BYTES || preg_match('//u', $name) !== 1 ? null : $name;
    }

    /** A column default as text, cut at a UTF-8 boundary; null when there is none. */
    public static function defaultValue($value): ?string
    {
        if ($value === null || !is_scalar($value)) {
            return null;
        }
        $text = (string) $value;
        if (preg_match('//u', $text) !== 1) {
            return null;
        }
        if (strlen($text) > self::MAX_DEFAULT_BYTES) {
            $text = substr($text, 0, self::MAX_DEFAULT_BYTES);
            while ($text !== '' && preg_match('//u', $text) !== 1) {
                $text = substr($text, 0, -1);
            }
            $text .= '…';
        }

        return $text;
    }

    /** 1, '1', true, 't', 'YES' → true; 0, '0', false, 'f', 'NO' → false; else null. */
    public static function flag($value): ?bool
    {
        if ($value === null) {
            return null;
        }
        if (is_bool($value)) {
            return $value;
        }
        $text = strtolower(trim((string) $value));
        if (in_array($text, ['1', 't', 'true', 'yes'], true)) {
            return true;
        }

        return in_array($text, ['0', 'f', 'false', 'no'], true) ? false : null;
    }
}

/** Builds the bounded `tables` list of an `sqlSchema` event from catalog rows. */
final class SchemaBuilder
{
    /** @var array<string, array<string, mixed>> */
    private $tables = [];
    /** @var array<string, array<string, int>> column positions per table */
    private $positions = [];
    private $columns = 0;
    private $indexColumns = 0;
    private $truncated = false;
    /** @var string[] */
    private $notes = [];

    /** @param array<int, array<int, mixed>> $rows table, column, type[, nullable, default, primary key, kind, rows] */
    public function addColumns(array $rows): void
    {
        foreach ($rows as $row) {
            $table = SqlSchema::name($row[0] ?? null);
            if ($table === null) {
                continue;
            }
            if (!isset($this->tables[$table])) {
                if (count($this->tables) >= SqlSchema::MAX_TABLES) {
                    $this->truncated = true;
                    continue;
                }
                $this->tables[$table] = ['name' => $table, 'columns' => []];
                $this->positions[$table] = [];
            }
            if (($row[6] ?? null) === 'view') {
                $this->tables[$table]['kind'] = 'view';
            }
            if (isset($row[7]) && is_numeric($row[7]) && (int) $row[7] >= 0) {
                $this->tables[$table]['rows'] = (int) $row[7];
            }
            $column = SqlSchema::name($row[1] ?? null);
            if ($column === null || isset($this->positions[$table][$column])) {
                continue;
            }
            if ($this->columns >= SqlSchema::MAX_COLUMNS) {
                $this->truncated = true;
                continue;
            }
            $entry = ['name' => $column];
            $type = isset($row[2]) && is_scalar($row[2]) ? strtolower(trim((string) $row[2])) : '';
            if ($type !== '' && strlen($type) <= 64 && preg_match('//u', $type) === 1) {
                $entry['type'] = $type;
            }
            $nullable = SqlSchema::flag($row[3] ?? null);
            if ($nullable !== null) {
                $entry['nullable'] = $nullable;
            }
            $default = SqlSchema::defaultValue($row[4] ?? null);
            if ($default !== null) {
                $entry['default'] = $default;
            }
            if (SqlSchema::flag($row[5] ?? null) === true) {
                $entry['primaryKey'] = true;
            }
            $this->positions[$table][$column] = count($this->tables[$table]['columns']);
            $this->tables[$table]['columns'][] = $entry;
            $this->columns++;
        }
    }

    /** @param array<int, array<int, mixed>> $rows table, index, unique, primary, column */
    public function addIndexes(array $rows): void
    {
        $order = [];
        foreach ($rows as $row) {
            $table = SqlSchema::name($row[0] ?? null);
            $index = SqlSchema::name($row[1] ?? null);
            $column = SqlSchema::name($row[4] ?? null);
            if ($table === null || $index === null || !isset($this->tables[$table])) {
                continue;
            }
            if ($this->indexColumns >= SqlSchema::MAX_INDEX_COLUMNS) {
                $this->truncated = true;
                break;
            }
            if (!isset($order[$table][$index])) {
                $order[$table][$index] = count($this->tables[$table]['indexes'] ?? []);
                $entry = ['name' => $index, 'columns' => []];
                if (SqlSchema::flag($row[2] ?? null) === true) {
                    $entry['unique'] = true;
                }
                if (SqlSchema::flag($row[3] ?? null) === true) {
                    $entry['primary'] = true;
                }
                $this->tables[$table]['indexes'][] = $entry;
            }
            if ($column !== null) {
                $this->tables[$table]['indexes'][$order[$table][$index]]['columns'][] = $column;
                $this->indexColumns++;
            }
        }
    }

    /**
     * Each column's `references`, and (#153) when the catalog names the constraint, the table's
     * `foreignKeys`: one entry per constraint with its columns in order, so a composite key is
     * one relation. `referencedColumns` is left out when the catalog doesn't name them (SQLite's
     * `REFERENCES customers`: the referenced table's primary key).
     *
     * @param array<int, array<int, mixed>> $rows table, column, referenced table, referenced column[, constraint]
     */
    public function addForeignKeys(array $rows): void
    {
        $order = [];
        foreach ($rows as $row) {
            $table = SqlSchema::name($row[0] ?? null);
            $column = SqlSchema::name($row[1] ?? null);
            $referenced = SqlSchema::name($row[2] ?? null);
            if ($table === null || $column === null || $referenced === null || !isset($this->positions[$table][$column])) {
                continue;
            }
            $target = SqlSchema::name($row[3] ?? null);
            $this->tables[$table]['columns'][$this->positions[$table][$column]]['references'] = $target === null ? $referenced : $referenced . '.' . $target;
            $constraint = SqlSchema::name($row[4] ?? null);
            if ($constraint === null) {
                continue;
            }
            $key = $constraint . "\x1F" . $referenced;
            if (!isset($order[$table][$key])) {
                $order[$table][$key] = count($this->tables[$table]['foreignKeys'] ?? []);
                $this->tables[$table]['foreignKeys'][] = ['name' => $constraint, 'columns' => [], 'references' => $referenced, 'referencedColumns' => []];
            }
            $at = $order[$table][$key];
            $this->tables[$table]['foreignKeys'][$at]['columns'][] = $column;
            if ($target === null || !isset($this->tables[$table]['foreignKeys'][$at]['referencedColumns'])) {
                unset($this->tables[$table]['foreignKeys'][$at]['referencedColumns']);
            } else {
                $this->tables[$table]['foreignKeys'][$at]['referencedColumns'][] = $target;
            }
        }
    }

    public function note(string $note): void
    {
        $this->notes[] = $note;
    }

    /** @return array<string, mixed> */
    public function result(): array
    {
        $result = ['tables' => array_values($this->tables)];
        if ($this->truncated) {
            $result['truncated'] = true;
        }
        if ($this->notes !== []) {
            $result['notes'] = $this->notes;
        }

        return $result;
    }
}
}

/*
 * Explain Statement in SQL tabs (#147). SqlTab::explain() resolves the tab's connection (the
 * application's, or a saved one) and hands it here with the statement. Runlet puts the
 * database's own EXPLAIN in front of the statement and sends that alone; the app reads the
 * answer into a plan tree (Packages/RunletKit/Sources/RunletCore/SQLPlan.swift).
 *
 *  - Explain (plan only) never runs the statement: MySQL and MariaDB `EXPLAIN FORMAT=JSON`,
 *    PostgreSQL `EXPLAIN (FORMAT JSON)`, SQLite `EXPLAIN QUERY PLAN`.
 *  - Explain Analyze runs it: MariaDB `ANALYZE FORMAT=JSON`, MySQL 8.0.18+ `EXPLAIN ANALYZE`
 *    (a text tree), PostgreSQL `EXPLAIN (ANALYZE, FORMAT JSON)` in a transaction that is
 *    always rolled back. A statement that can write (or that Runlet can't classify) is refused
 *    on MySQL and MariaDB, where DDL and non-transactional tables can't be rolled back, and on
 *    read-only saved connections (#139). SQLite has no EXPLAIN ANALYZE.
 *  - SQL Server, other PDO drivers, and callables whose database Runlet doesn't know are
 *    refused with a message. WordPress's $wpdb is MySQL.
 *
 * The statement is prepared natively (no emulation), so the database refuses a second
 * statement after a `;` instead of running it. Bound values (#145) are bound by SqlTab, as
 * for run(), which also refuses them on callables.
 *
 * The run inspector's Explain tab (#4, #170) runs its EXPLAIN itself, through the captured
 * connection, and hands the rows to Runlet\explainPlan() (at the end of this file), which
 * reads them into the same `sqlPlan` event (SqlExplain::fromRows()).
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

/** Explain Statement can't explain on this connection, or refused Explain Analyze. Nothing ran. */
final class SqlExplainRefused extends \RuntimeException
{
}

final class SqlExplain
{
    /** Bytes of the database's own output kept. */
    private const MAX_RAW_BYTES = 4194304;
    /** SQLite's EXPLAIN QUERY PLAN rows kept. */
    private const MAX_ROWS = 10000;

    /**
     * Refusals that need no connection: a statement that is already an EXPLAIN, and Explain
     * Analyze of a write on a read-only saved connection.
     */
    public static function refuseEarly(string $sql, bool $analyze): void
    {
        $first = self::firstWord($sql);
        if (in_array($first, ['EXPLAIN', 'DESCRIBE', 'DESC', 'ANALYZE'], true)) {
            throw new SqlExplainRefused('This statement already starts with ' . $first . '. Explain Statement adds the database\'s own EXPLAIN: remove ' . $first . ', or run the statement as written. Nothing ran.');
        }
        if ($analyze && SqlConnect::isConfigured() && SqlConnect::isReadOnly()) {
            $why = SqlReadOnly::refusal($sql, SqlConnect::driverName());
            if ($why !== null) {
                throw new SqlReadOnlyRefused('Explain Analyze runs the statement, and Runlet refused it on the read-only connection "' . SqlConnect::name() . '": it ' . $why . '. Explain Statement (without Analyze) shows its plan without running it. Nothing ran.');
            }
        }
    }

    /**
     * Explains `$sql` on `$source` and returns the `sqlPlan` event's payload (without the
     * connection fields SqlTab adds).
     *
     * @param \PDO|callable $source
     * @param callable(\PDOStatement): void|null $bind Binds the statement's values (#145).
     * @return array<string, mixed>
     */
    public static function explain($source, string $origin, ?string $driverName, string $sql, bool $analyze, ?callable $bind = null): array
    {
        $serverVersion = $source instanceof \PDO ? self::serverVersion($source) : null;
        $dialect = self::dialect($source, $origin, $driverName, $serverVersion);
        if ($analyze) {
            self::refuseAnalyze($dialect, $sql);
        }
        [$prefix, $format] = self::prefix($dialect, $analyze);
        $explained = $prefix . ' ' . self::withoutTrailingSemicolon($sql);
        $payload = [
            'driver' => $dialect === 'mariadb' ? 'mysql' : $dialect,
            'dialect' => $dialect,
            'format' => $format,
            'analyze' => $analyze,
            'explained' => $prefix,
            'serverVersion' => $serverVersion,
        ];
        $rolledBack = false;
        if ($source instanceof \PDO) {
            $transaction = $analyze && $dialect === 'pgsql';
            if ($transaction) {
                // PostgreSQL: Explain Analyze runs the statement in a transaction that is always
                // rolled back, so a write it makes doesn't stay.
                $source->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
                $source->beginTransaction();
            }
            try {
                $rows = self::fetchPdo($source, $dialect, $explained, $bind);
            } catch (\PDOException $error) {
                if (($dialect === 'mysql' || $dialect === 'mariadb') && SqlConnect::isConfigured() && SqlConnect::isReadOnly() && strpos($error->getMessage(), '1792') !== false) {
                    // #139: MySQL and MariaDB won't even explain a write in a read-only session.
                    throw new SqlExplainRefused(($dialect === 'mariadb' ? 'MariaDB' : 'MySQL') . ' refuses to explain a statement that writes in a read-only session (error 1792), although EXPLAIN wouldn\'t run it. Explain it on a connection that isn\'t read-only, or explain the SELECT that finds the same rows. Nothing ran.', 0, $error);
                }
                throw $error;
            } finally {
                if ($transaction) {
                    try {
                        if ($source->inTransaction()) {
                            $source->rollBack();
                        }
                        $rolledBack = true;
                    } catch (\Throwable $error) {
                        // The connection is gone with the run; nothing was committed.
                        $rolledBack = true;
                    }
                }
            }
        } else {
            $rows = self::fetchCallable($source, $explained);
        }
        if ($dialect === 'sqlite') {
            $payload['rows'] = self::planRows($rows);
        } else {
            $payload += self::raw(self::rawText($rows, $dialect));
        }
        if ($rolledBack) {
            $payload['rolledBack'] = true;
        }

        return self::withoutNulls($payload);
    }

    /**
     * The run inspector's Explain tab (#170): `Runlet\explainPlan()` hands over the EXPLAIN
     * rows the tab's own code fetched, and this returns them as the `sqlPlan` event's payload,
     * or null when they aren't a plan Runlet reads (MySQL's tabular EXPLAIN, PostgreSQL's text
     * plan, a database it doesn't know), which the tab then shows as rows. It sends nothing
     * to the database: the dialect and server version come from the connection object.
     *
     * @param mixed $rows
     * @param mixed $connection a PDO, an Illuminate or Doctrine DBAL connection, $wpdb, a
     *        dialect name (`mysql`, `mariadb`, `pgsql`, `sqlite`), or null to tell by the rows
     * @return array<string, mixed>|null
     */
    public static function fromRows($rows, $connection, ?string $connectionName): ?array
    {
        $rows = self::rowList($rows);
        if ($rows === null || $rows === []) {
            return null;
        }
        [$dialect, $serverVersion, $source, $name] = self::describe($connection);
        $first = $rows[0];
        if ($dialect === null) {
            // Each database names its EXPLAIN's column: SQLite `detail`, PostgreSQL
            // `QUERY PLAN`, MySQL and MariaDB `EXPLAIN`.
            $dialect = array_key_exists('detail', $first) ? 'sqlite' : (array_key_exists('QUERY PLAN', $first) ? 'pgsql' : (array_key_exists('EXPLAIN', $first) ? 'mysql' : null));
            if ($dialect === null) {
                return null;
            }
        }
        $payload = [
            'driver' => $dialect === 'mariadb' ? 'mysql' : $dialect,
            'dialect' => $dialect,
            'analyze' => false,
            'serverVersion' => $serverVersion,
            'connection' => $connectionName ?? $name,
            'source' => $source,
        ];
        if ($dialect === 'sqlite') {
            if (!array_key_exists('detail', $first)) {
                return null;
            }
            $payload['format'] = 'rows';
            $payload['explained'] = 'EXPLAIN QUERY PLAN';
            $payload['rows'] = self::planRows($rows);

            return self::withoutNulls($payload);
        }
        if (count($first) !== 1) {
            return null;
        }
        $raw = ltrim(self::rawText($rows, $dialect));
        if ($dialect === 'pgsql') {
            if ($raw === '' || ($raw[0] !== '[' && $raw[0] !== '{')) {
                return null;
            }
            $payload['format'] = 'json';
            $payload['explained'] = 'EXPLAIN (FORMAT JSON)';
            // The parser reads the actual figures of an ANALYZE the user wrote in.
            $payload['analyze'] = strpos($raw, '"Execution Time"') !== false;
        } elseif ($raw !== '' && $raw[0] === '{') {
            $payload['format'] = 'json';
            $payload['explained'] = 'EXPLAIN FORMAT=JSON';
            $payload['analyze'] = $dialect === 'mariadb' && strpos($raw, '"r_loops"') !== false;
        } elseif (strncmp($raw, '->', 2) === 0) {
            // MySQL's EXPLAIN FORMAT=TREE, or the EXPLAIN ANALYZE the user wrote in.
            $payload['format'] = 'tree';
            $payload['analyze'] = strpos($raw, '(actual time=') !== false;
            $payload['explained'] = $payload['analyze'] ? 'EXPLAIN ANALYZE' : 'EXPLAIN FORMAT=TREE';
        } else {
            return null;
        }
        $payload += self::raw($raw);

        return self::withoutNulls($payload);
    }

    /**
     * The database's output, at most MAX_RAW_BYTES of it, as valid UTF-8.
     *
     * @return array<string, mixed>
     */
    private static function raw(string $raw): array
    {
        $payload = [];
        if (strlen($raw) > self::MAX_RAW_BYTES) {
            $raw = substr($raw, 0, self::MAX_RAW_BYTES);
            $payload['rawTruncated'] = true;
        }
        if (preg_match('//u', $raw) !== 1) {
            $raw = (string) preg_replace('/[\x80-\xFF]/', '?', $raw);
        }
        $payload['raw'] = $raw;

        return $payload;
    }

    /**
     * @param array<string, mixed> $payload
     * @return array<string, mixed>
     */
    private static function withoutNulls(array $payload): array
    {
        return array_filter($payload, static function ($value): bool {
            return $value !== null;
        });
    }

    /**
     * Rows as returned by Laravel (objects), Doctrine, $wpdb, or PDO (arrays), or a
     * collection of them; null when `$rows` isn't a list of rows.
     *
     * @param mixed $rows
     * @return array<int, array<string, mixed>>|null
     */
    private static function rowList($rows): ?array
    {
        if (is_object($rows) && !$rows instanceof \Traversable && method_exists($rows, 'all')) {
            $rows = $rows->all();
        }
        if ($rows instanceof \Traversable) {
            $rows = iterator_to_array($rows, false);
        }
        if (!is_array($rows)) {
            return null;
        }
        $list = [];
        foreach (array_slice(array_values($rows), 0, self::MAX_ROWS) as $row) {
            if (is_object($row)) {
                $row = get_object_vars($row);
            }
            if (!is_array($row) || $row === []) {
                return null;
            }
            $list[] = $row;
        }

        return $list;
    }

    /**
     * The dialect, server version, origin, and connection name of what the tab passed as
     * its connection. Nothing is sent to the database.
     *
     * @param mixed $connection
     * @return array{0: string|null, 1: string|null, 2: string|null, 3: string|null}
     */
    private static function describe($connection): array
    {
        if (is_string($connection)) {
            $names = ['mysql' => 'mysql', 'mariadb' => 'mariadb', 'pgsql' => 'pgsql', 'postgres' => 'pgsql', 'postgresql' => 'pgsql', 'sqlite' => 'sqlite', 'sqlite3' => 'sqlite'];

            return [$names[strtolower($connection)] ?? null, null, null, null];
        }
        if ($connection instanceof \PDO) {
            $version = self::serverVersion($connection);

            return [self::knownDialect(self::pdoDriver($connection), $version), $version, 'PDO', null];
        }
        if (!is_object($connection)) {
            return [null, null, null, null];
        }
        try {
            if (is_a($connection, 'Illuminate\Database\Connection')) {
                $pdo = method_exists($connection, 'getReadPdo') ? $connection->getReadPdo() : $connection->getPdo();
                $version = $pdo instanceof \PDO ? self::serverVersion($pdo) : null;
                $driver = method_exists($connection, 'getDriverName') ? (string) $connection->getDriverName() : ($pdo instanceof \PDO ? self::pdoDriver($pdo) : null);

                return [self::knownDialect($driver, $version), $version, 'Illuminate database connection', method_exists($connection, 'getName') ? $connection->getName() : null];
            }
            if (is_a($connection, 'Doctrine\DBAL\Connection')) {
                $native = \Runlet\SqlConnections::doctrine($connection);
                $version = $native instanceof \PDO ? self::serverVersion($native) : null;
                $platform = strtolower(get_class($connection->getDatabasePlatform()));
                $driver = strpos($platform, 'mariadb') !== false ? 'mariadb' : (strpos($platform, 'mysql') !== false ? 'mysql' : (strpos($platform, 'postgre') !== false ? 'pgsql' : (strpos($platform, 'sqlite') !== false ? 'sqlite' : null)));

                return [self::knownDialect($driver, $version), $version, 'Doctrine DBAL', null];
            }
            if (is_a($connection, 'wpdb')) {
                if (is_a($connection, 'WP_SQLite_DB')) {
                    return [null, null, 'WordPress $wpdb', null];
                }
                $version = method_exists($connection, 'db_server_info') ? $connection->db_server_info() : null;
                $version = is_string($version) && $version !== '' ? $version : null;

                return [self::knownDialect('mysql', $version), $version, 'WordPress $wpdb', null];
            }
        } catch (\Throwable $error) {
            // A connection that can't say: the rows tell the database.
        }

        return [null, null, null, null];
    }

    /** `mysql` (or `mariadb` by its server version), `pgsql`, `sqlite`; null for others. */
    private static function knownDialect(?string $driver, ?string $serverVersion): ?string
    {
        switch ($driver) {
            case 'mysql':
            case 'mariadb':
                return $driver === 'mariadb' || ($serverVersion !== null && stripos($serverVersion, 'mariadb') !== false) ? 'mariadb' : 'mysql';
            case 'pgsql':
            case 'sqlite':
                return $driver;
            default:
                return null;
        }
    }

    private static function pdoDriver(\PDO $pdo): ?string
    {
        try {
            return (string) $pdo->getAttribute(\PDO::ATTR_DRIVER_NAME);
        } catch (\Throwable $error) {
            return null;
        }
    }

    /**
     * The database's EXPLAIN dialect: from the PDO driver (MariaDB by its server version), or
     * $wpdb's MySQL. Anything else is refused here.
     *
     * @param \PDO|callable $source
     */
    private static function dialect($source, string $origin, ?string $driverName, ?string $serverVersion): string
    {
        switch ($driverName) {
            case 'mysql':
                if ($serverVersion === null && !$source instanceof \PDO) {
                    $serverVersion = self::callableVersion($source);
                }

                return $serverVersion !== null && stripos($serverVersion, 'mariadb') !== false ? 'mariadb' : 'mysql';
            case 'pgsql':
            case 'sqlite':
                return $driverName;
            case 'sqlsrv':
            case 'dblib':
                throw new SqlExplainRefused('Explain Statement doesn\'t support SQL Server yet (its plans come from SET SHOWPLAN_XML). Nothing ran.');
            case null:
                throw new SqlExplainRefused('Explain Statement needs to know the database, and this connection (' . $origin . ') runs statements through a callable. Return a PDO from the driver\'s sqlConnection(), or write EXPLAIN in the tab yourself and run it. Nothing ran.');
            default:
                throw new SqlExplainRefused('Explain Statement supports MySQL, MariaDB, PostgreSQL, and SQLite; this connection uses the ' . $driverName . ' driver. Write EXPLAIN in the tab yourself and run it. Nothing ran.');
        }
    }

    /** Explain Analyze runs the statement; refuses what can't be undone. */
    private static function refuseAnalyze(string $dialect, string $sql): void
    {
        if ($dialect === 'sqlite') {
            throw new SqlExplainRefused('SQLite has no EXPLAIN ANALYZE. Explain Statement shows SQLite\'s query plan without running the statement. Nothing ran.');
        }
        if ($dialect !== 'mysql' && $dialect !== 'mariadb') {
            return;
        }
        $why = SqlReadOnly::refusal($sql, 'mysql');
        if ($why !== null) {
            throw new SqlExplainRefused('Explain Analyze runs the statement, and Runlet runs only reading statements that way on ' . ($dialect === 'mariadb' ? 'MariaDB' : 'MySQL') . ': this one ' . $why
                . '. MySQL and MariaDB commit DDL at once and can\'t roll back non-transactional tables, so Runlet can\'t undo it. Explain Statement (without Analyze) shows its plan without running it. Nothing ran.');
        }
    }

    /** @return array{0: string, 1: string} The EXPLAIN to put first, and the output's format. */
    private static function prefix(string $dialect, bool $analyze): array
    {
        switch ($dialect) {
            case 'pgsql':
                return [$analyze ? 'EXPLAIN (ANALYZE, FORMAT JSON)' : 'EXPLAIN (FORMAT JSON)', 'json'];
            case 'sqlite':
                return ['EXPLAIN QUERY PLAN', 'rows'];
            case 'mariadb':
                return [$analyze ? 'ANALYZE FORMAT=JSON' : 'EXPLAIN FORMAT=JSON', 'json'];
            default:
                return [$analyze ? 'EXPLAIN ANALYZE' : 'EXPLAIN FORMAT=JSON', $analyze ? 'tree' : 'json'];
        }
    }

    /**
     * Runs the EXPLAIN with native prepares (MySQL and PostgreSQL then refuse a second
     * statement; SQLite compiles only the first) and returns its rows with column names.
     *
     * @param callable(\PDOStatement): void|null $bind
     * @return array<int, array<string, mixed>>
     */
    private static function fetchPdo(\PDO $pdo, string $dialect, string $sql, ?callable $bind): array
    {
        $restore = [\PDO::ATTR_ERRMODE => $pdo->getAttribute(\PDO::ATTR_ERRMODE)];
        $pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        if ($dialect !== 'sqlite') {
            try {
                $previous = $pdo->getAttribute(\PDO::ATTR_EMULATE_PREPARES);
                if ($pdo->setAttribute(\PDO::ATTR_EMULATE_PREPARES, false)) {
                    $restore[\PDO::ATTR_EMULATE_PREPARES] = $previous;
                }
            } catch (\Throwable $error) {
                // The driver has no such setting: it prepares natively.
            }
        }
        try {
            $statement = $pdo->prepare($sql);
            if ($bind !== null) {
                $bind($statement);
            }
            $statement->execute();
            $rows = $statement->fetchAll(\PDO::FETCH_ASSOC);
            $statement->closeCursor();

            return is_array($rows) ? $rows : [];
        } finally {
            foreach ($restore as $attribute => $value) {
                try {
                    $pdo->setAttribute($attribute, $value);
                } catch (\Throwable $error) {
                    // Best effort: the run ends right after this.
                }
            }
        }
    }

    /**
     * @param callable $run
     * @return array<int, array<string, mixed>>
     */
    private static function fetchCallable(callable $run, string $sql): array
    {
        $returned = $run($sql);
        if (!is_iterable($returned)) {
            throw new \UnexpectedValueException('The SQL connection callable returned no rows for the EXPLAIN.');
        }
        $rows = [];
        foreach ($returned as $row) {
            $rows[] = is_object($row) ? get_object_vars($row) : (is_array($row) ? $row : ['value' => $row]);
            if (count($rows) >= self::MAX_ROWS) {
                break;
            }
        }

        return $rows;
    }

    /**
     * The JSON (or MySQL's tree) from the first row's first column; several rows (an older
     * MySQL's tabular EXPLAIN, a callable's) are joined.
     *
     * @param array<int, array<string, mixed>> $rows
     */
    private static function rawText(array $rows, string $dialect): string
    {
        if ($rows === []) {
            throw new \UnexpectedValueException('The database returned no plan.');
        }
        $parts = [];
        foreach ($rows as $row) {
            $value = reset($row);
            if (is_resource($value)) {
                $value = (string) stream_get_contents($value);
            }
            $parts[] = is_scalar($value) ? (string) $value : (string) json_encode($value);
        }

        return implode("\n", $parts);
    }

    /**
     * SQLite's EXPLAIN QUERY PLAN rows as `[id, parent, detail]` (SQLite before 3.24 has no
     * `parent`; its rows stay flat).
     *
     * @param array<int, array<string, mixed>> $rows
     * @return array<int, array{0: int, 1: int, 2: string}>
     */
    private static function planRows(array $rows): array
    {
        $plan = [];
        foreach (array_slice($rows, 0, self::MAX_ROWS) as $index => $row) {
            $detail = $row['detail'] ?? end($row);
            $plan[] = [
                isset($row['id']) ? (int) $row['id'] : $index + 1,
                isset($row['parent']) ? (int) $row['parent'] : 0,
                is_scalar($detail) ? (string) $detail : '',
            ];
        }

        return $plan;
    }

    private static function serverVersion(\PDO $pdo): ?string
    {
        try {
            $version = $pdo->getAttribute(\PDO::ATTR_SERVER_VERSION);
        } catch (\Throwable $error) {
            return null;
        }

        return is_string($version) && $version !== '' ? $version : null;
    }

    /** $wpdb's server version, to tell MariaDB from MySQL. */
    private static function callableVersion(callable $run): ?string
    {
        try {
            foreach ($run('SELECT VERSION() AS version') as $row) {
                $fields = is_object($row) ? get_object_vars($row) : (array) $row;
                $value = reset($fields);

                return is_string($value) ? $value : null;
            }
        } catch (\Throwable $error) {
            return null;
        }

        return null;
    }

    /** The statement's first word, upper-cased, after comments and blank space. */
    private static function firstWord(string $sql): string
    {
        $text = (string) preg_replace('~^(\s+|--[^\n]*(\n|$)|#[^\n]*(\n|$)|/\*.*?\*/)+~s', '', $sql);

        return preg_match('/^([A-Za-z_]+)/', $text, $match) === 1 ? strtoupper($match[1]) : '';
    }

    /** `SELECT 1;` → `SELECT 1`: the EXPLAIN goes in front of one statement. */
    private static function withoutTrailingSemicolon(string $sql): string
    {
        return (string) preg_replace('/;\s*$/', '', rtrim($sql));
    }
}
}

namespace Runlet {

/**
 * Shows EXPLAIN rows as Runlet's plan card (#170): the plan as a tree with full scans
 * highlighted, and the database's own output under Raw, as Explain Statement in SQL tabs
 * does (#147). The run inspector's Explain tab ends with it:
 *
 *     $connection = DB::connection('mysql');
 *     $plan = $connection->select('EXPLAIN FORMAT=JSON select * from users where email = ?', ['ada@example.com']);
 *     return \Runlet\explainPlan($plan, $connection);
 *
 * Pass the rows of `EXPLAIN FORMAT=JSON` (MySQL, MariaDB), `EXPLAIN (FORMAT JSON)`
 * (PostgreSQL), or `EXPLAIN QUERY PLAN` (SQLite), and the connection they came from: a PDO,
 * an Illuminate or Doctrine DBAL connection, $wpdb, or the database's name (`mysql`,
 * `mariadb`, `pgsql`, `sqlite`). The connection tells MariaDB from MySQL; nothing is sent to
 * the database.
 *
 * @param mixed $rows the EXPLAIN's rows, as objects or arrays
 * @param mixed $connection the connection, or the database's name; null tells by the rows
 * @param string|null $connectionName the name the card shows for the connection
 * @return mixed nothing to show when Runlet shows the plan; otherwise (a tabular MySQL
 *         EXPLAIN, PostgreSQL's text plan, an unknown database) the rows as they are
 */
function explainPlan($rows, $connection = null, ?string $connectionName = null)
{
    $plan = \RunletRunner\SqlExplain::fromRows($rows, $connection, $connectionName);
    if ($plan === null) {
        return $rows;
    }
    \RunletRunner\Channel::emit('sqlPlan', $plan);

    return \RunletRunner\NoResult::instance();
}
}

/*
 * Show Definition (#148): the definition (DDL) of one table or view, read from the database's
 * catalog for the schema explorer, which shows it in a read-only sheet. Only the
 * catalog is read, never rows, and nothing is created or changed. SqlTab resolves the
 * connection and emits the `sqlDefinition` event.
 *
 * Per database:
 *  - MySQL and MariaDB: SHOW CREATE TABLE / SHOW CREATE VIEW, plus SHOW CREATE TRIGGER for
 *    the table's triggers;
 *  - SQLite: the object's own `sql` in sqlite_master, plus its indexes and triggers;
 *  - PostgreSQL, which has no SHOW CREATE: a CREATE TABLE reconstructed from pg_catalog
 *    (columns with types, defaults, identity, collation, NOT NULL), pg_get_constraintdef(),
 *    pg_get_indexdef(), pg_get_triggerdef(), comments, and the enum types its columns use;
 *    pg_get_viewdef() for views. The event says it is reconstructed.
 * SQL Server and other drivers are not supported. A callable connection (whose database Runlet
 * doesn't know) is tried as MySQL, PostgreSQL, then SQLite, like the schema; when a project
 * driver's sqlSchema() describes it instead of a catalog, there is no definition to read.
 *
 * Names are bound as parameters on PDO; a callable can't bind, so they are written as quoted
 * literals for its dialect. Identifiers in SHOW statements are quoted.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

/** The table or view isn't in this catalog (the dialect was right, the name wasn't). */
final class SqlDefinitionNotFound extends \RuntimeException
{
}

final class SqlDefinition
{
    /** Bytes of DDL reported at most. */
    public const MAX_BYTES = 2097152;
    /** Triggers and indexes read at most per table. */
    public const MAX_TRIGGERS = 100;
    public const MAX_INDEXES = 500;
    /** Columns of one table read at most (PostgreSQL). */
    public const MAX_COLUMNS = 5000;

    /**
     * The definition of `$table`, a name as the schema explorer lists it.
     *
     * @param \PDO|callable $source
     * @return array<string, mixed> `table`, `dialect`, `kind`, `how`, `sql`, and `reconstructed`, `server`, `notes` when they apply
     */
    public static function read($source, string $origin, ?string $driverName, string $table): array
    {
        if ($table === '' || strlen($table) > SqlSchema::MAX_NAME_BYTES || preg_match('//u', $table) !== 1) {
            throw new \InvalidArgumentException('Show Definition needs the name of a table or view.');
        }
        $dialects = self::dialects($source, $origin, $driverName);
        $failure = null;
        foreach ($dialects as $dialect) {
            try {
                switch ($dialect) {
                    case 'mysql':
                        $result = self::mysql($source, $table);
                        break;
                    case 'pgsql':
                        $result = self::pgsql($source, $table);
                        break;
                    default:
                        $result = self::sqlite($source, $table);
                }
            } catch (SqlDefinitionNotFound $missing) {
                throw $missing;
            } catch (DriverFailure $driverFailure) {
                throw $driverFailure;
            } catch (\Throwable $error) {
                $failure = $failure ?? $error;
                continue;
            }
            $server = $source instanceof \PDO ? self::server($source, $dialect) : null;
            if ($server !== null) {
                $result['server'] = $server;
            }
            $result['sql'] = self::bounded($result['sql'], $result);

            return ['table' => $table, 'dialect' => $dialect] + $result;
        }
        throw new \RuntimeException($failure !== null ? $failure->getMessage() : 'no catalog answered');
    }

    /**
     * The catalogs to try: the PDO driver's, or for a callable each in turn ($wpdb is MySQL).
     *
     * @param \PDO|callable $source
     * @return string[]
     */
    private static function dialects($source, string $origin, ?string $driverName): array
    {
        switch ($driverName) {
            case 'mysql':
            case 'pgsql':
            case 'sqlite':
                return [$driverName];
            case 'sqlsrv':
            case 'dblib':
                throw new SqlUnavailable('Runlet doesn\'t show SQL Server definitions yet. Use your database tool, or sp_helptext and the sys catalog views, to read this one.');
        }
        if ($source instanceof \PDO) {
            throw new SqlUnavailable('Runlet can\'t show definitions on ' . ($driverName ?? 'this') . ' connections: it reads them on MySQL, MariaDB, PostgreSQL, and SQLite.');
        }
        $driver = Runner::bootedDriver();
        if ($driver !== null && (new \ReflectionMethod($driver, 'sqlSchema'))->getDeclaringClass()->getName() !== 'Runlet\Driver') {
            throw new SqlUnavailable('Runlet can\'t show a definition here: this connection is a callable from ' . $origin . ', so Runlet doesn\'t know its database, and the project driver\'s sqlSchema() lists its tables without a catalog to read definitions from.');
        }

        return WordPressDatabase::isWpdb($origin) ? ['mysql', 'sqlite'] : ['mysql', 'pgsql', 'sqlite'];
    }

    /**
     * MySQL and MariaDB: SHOW CREATE TABLE (or VIEW), then the table's triggers.
     *
     * @param \PDO|callable $source
     * @return array<string, mixed>
     */
    private static function mysql($source, string $table): array
    {
        $found = self::rows($source, 'mysql', 'SELECT TABLE_TYPE AS table_type FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :name', ['name' => $table], 1);
        if ($found === []) {
            throw new SqlDefinitionNotFound('There is no table or view named ' . $table . ' in this database. Reload the schema if it was renamed or dropped.');
        }
        $isView = strtoupper((string) self::value($found[0], 'table_type')) === 'VIEW';
        $quoted = self::backticks($table);
        $rows = self::rows($source, 'mysql', ($isView ? 'SHOW CREATE VIEW ' : 'SHOW CREATE TABLE ') . $quoted, [], 1);
        $definition = $rows === [] ? null : (self::value($rows[0], $isView ? 'Create View' : 'Create Table') ?? self::value($rows[0], 1));
        if (!is_string($definition) || trim($definition) === '') {
            throw new \RuntimeException('SHOW CREATE ' . ($isView ? 'VIEW' : 'TABLE') . ' returned no definition.');
        }
        $statements = [self::statement($definition)];
        $notes = [];
        if (!$isView) {
            try {
                $names = self::rows($source, 'mysql', 'SELECT TRIGGER_NAME AS trigger_name FROM information_schema.TRIGGERS WHERE EVENT_OBJECT_SCHEMA = DATABASE() AND EVENT_OBJECT_TABLE = :name ORDER BY ACTION_TIMING, EVENT_MANIPULATION, ACTION_ORDER', ['name' => $table], self::MAX_TRIGGERS);
                foreach ($names as $row) {
                    $name = self::value($row, 'trigger_name');
                    if (!is_string($name) || $name === '') {
                        continue;
                    }
                    $trigger = self::rows($source, 'mysql', 'SHOW CREATE TRIGGER ' . self::backticks($name), [], 1);
                    $text = $trigger === [] ? null : (self::value($trigger[0], 'SQL Original Statement') ?? self::value($trigger[0], 2));
                    if (is_string($text) && trim($text) !== '') {
                        $statements[] = self::statement($text);
                    }
                }
            } catch (DriverFailure $driverFailure) {
                throw $driverFailure;
            } catch (\Throwable $error) {
                $notes[] = 'Triggers could not be read: ' . $error->getMessage();
            }
        }

        return self::result($isView ? 'view' : 'table', $isView ? 'SHOW CREATE VIEW' : 'SHOW CREATE TABLE', $statements, $notes);
    }

    /**
     * SQLite: the object's own CREATE statement, then its indexes and triggers, as written.
     * Indexes SQLite made for PRIMARY KEY and UNIQUE have no SQL of their own.
     *
     * @param \PDO|callable $source
     * @return array<string, mixed>
     */
    private static function sqlite($source, string $table): array
    {
        $found = self::rows($source, 'sqlite', 'SELECT type AS object_type, name AS object_name, sql AS object_sql FROM sqlite_master WHERE name = :name COLLATE NOCASE AND type IN (\'table\', \'view\')', ['name' => $table], 1);
        if ($found === []) {
            throw new SqlDefinitionNotFound('There is no table or view named ' . $table . ' in this database. Reload the schema if it was renamed or dropped.');
        }
        $type = (string) self::value($found[0], 'object_type');
        $sql = self::value($found[0], 'object_sql');
        if (!is_string($sql) || trim($sql) === '') {
            throw new \RuntimeException('sqlite_master has no SQL for ' . $table . '.');
        }
        $statements = [self::statement($sql)];
        $notes = [];
        try {
            $related = self::rows($source, 'sqlite', 'SELECT type AS object_type, sql AS object_sql FROM sqlite_master WHERE tbl_name = :name COLLATE NOCASE AND type IN (\'index\', \'trigger\') AND sql IS NOT NULL ORDER BY CASE type WHEN \'index\' THEN 0 ELSE 1 END, name', ['name' => (string) self::value($found[0], 'object_name')], self::MAX_INDEXES + self::MAX_TRIGGERS);
            foreach ($related as $row) {
                $text = self::value($row, 'object_sql');
                if (is_string($text) && trim($text) !== '') {
                    $statements[] = self::statement($text);
                }
            }
        } catch (DriverFailure $failure) {
            throw $failure;
        } catch (\Throwable $error) {
            $notes[] = 'Indexes and triggers could not be read: ' . $error->getMessage();
        }

        return self::result($type === 'view' ? 'view' : 'table', 'sqlite_master', $statements, $notes);
    }

    /**
     * PostgreSQL: the relation's catalog rows, then the reconstruction (postgres()). The name
     * is the explorer's: bare in the current schema, else `schema.table` in the search path.
     *
     * @param \PDO|callable $source
     * @return array<string, mixed>
     */
    private static function pgsql($source, string $table): array
    {
        $found = self::rows($source, 'pgsql', <<<'SQL'
            SELECT c.oid AS oid, c.relkind AS relkind, c.relpersistence AS relpersistence, c.relispartition AS relispartition,
                quote_ident(n.nspname) || '.' || quote_ident(c.relname) AS qualified,
                array_to_string(c.reloptions, ', ') AS options,
                CASE WHEN c.relkind = 'p' THEN pg_get_partkeydef(c.oid) END AS partition_key,
                CASE WHEN c.relispartition THEN pg_get_expr(c.relpartbound, c.oid) END AS partition_bound,
                obj_description(c.oid, 'pg_class') AS comment,
                CASE WHEN c.relkind IN ('v', 'm') THEN pg_get_viewdef(c.oid, true) END AS view_definition
            FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
            WHERE c.relkind IN ('r', 'p', 'v', 'm', 'f') AND n.nspname = ANY (current_schemas(false))
                AND ((n.nspname = current_schema() AND c.relname = :name) OR n.nspname || '.' || c.relname = :qualified)
            ORDER BY CASE WHEN n.nspname = current_schema() THEN 0 ELSE 1 END
            SQL, ['name' => $table, 'qualified' => $table], 1);
        if ($found === []) {
            throw new SqlDefinitionNotFound('There is no table or view named ' . $table . ' in the search path. Reload the schema if it was renamed or dropped.');
        }
        $relation = self::assoc($found[0]);
        $oid = (int) $relation['oid'];
        $catalog = ['relation' => $relation, 'columns' => [], 'constraints' => [], 'indexes' => [], 'triggers' => [], 'enums' => [], 'parents' => []];
        $catalog['columns'] = self::rows($source, 'pgsql', <<<'SQL'
            SELECT quote_ident(a.attname) AS name, format_type(a.atttypid, a.atttypmod) AS type, a.attnotnull AS not_null,
                pg_get_expr(d.adbin, d.adrelid) AS default_value, a.attidentity AS identity, a.attgenerated AS generated,
                CASE WHEN a.attcollation <> t.typcollation AND a.attcollation <> 0 THEN quote_ident(cn.nspname) || '.' || quote_ident(co.collname) END AS collation,
                col_description(a.attrelid, a.attnum) AS comment
            FROM pg_catalog.pg_attribute a
            JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
            LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
            LEFT JOIN pg_catalog.pg_collation co ON co.oid = a.attcollation
            LEFT JOIN pg_catalog.pg_namespace cn ON cn.oid = co.collnamespace
            WHERE a.attrelid = :oid AND a.attnum > 0 AND NOT a.attisdropped
            ORDER BY a.attnum
            SQL, ['oid' => $oid], self::MAX_COLUMNS);
        $notes = [];
        $extras = [
            'constraints' => ['Constraints', <<<'SQL'
                SELECT quote_ident(conname) AS name, contype AS type, pg_get_constraintdef(oid, true) AS definition
                FROM pg_catalog.pg_constraint WHERE conrelid = :oid AND contype IN ('p', 'u', 'c', 'f', 'x')
                ORDER BY CASE contype WHEN 'p' THEN 0 WHEN 'u' THEN 1 WHEN 'c' THEN 2 WHEN 'x' THEN 3 ELSE 4 END, conname
                SQL],
            'indexes' => ['Indexes', <<<'SQL'
                SELECT pg_get_indexdef(ix.indexrelid) AS definition
                FROM pg_catalog.pg_index ix JOIN pg_catalog.pg_class i ON i.oid = ix.indexrelid
                WHERE ix.indrelid = :oid AND NOT EXISTS (
                    SELECT 1 FROM pg_catalog.pg_constraint k WHERE k.conindid = ix.indexrelid AND k.conrelid = ix.indrelid AND k.contype IN ('p', 'u', 'x'))
                ORDER BY i.relname
                SQL],
            'triggers' => ['Triggers', 'SELECT pg_get_triggerdef(oid, true) AS definition FROM pg_catalog.pg_trigger WHERE tgrelid = :oid AND NOT tgisinternal ORDER BY tgname'],
            'enums' => ['Enum types', <<<'SQL'
                SELECT format_type(t.oid, NULL) AS name, json_agg(e.enumlabel ORDER BY e.enumsortorder)::text AS labels
                FROM pg_catalog.pg_type t JOIN pg_catalog.pg_enum e ON e.enumtypid = t.oid
                WHERE t.oid IN (SELECT atttypid FROM pg_catalog.pg_attribute WHERE attrelid = :oid AND attnum > 0 AND NOT attisdropped)
                GROUP BY t.oid ORDER BY 1
                SQL],
            'parents' => ['Parent tables', <<<'SQL'
                SELECT quote_ident(n.nspname) || '.' || quote_ident(p.relname) AS name
                FROM pg_catalog.pg_inherits i JOIN pg_catalog.pg_class p ON p.oid = i.inhparent JOIN pg_catalog.pg_namespace n ON n.oid = p.relnamespace
                WHERE i.inhrelid = :oid ORDER BY i.inhseqno
                SQL],
        ];
        $isView = in_array($relation['relkind'], ['v', 'm'], true);
        foreach ($extras as $key => [$label, $sql]) {
            if ($isView && in_array($key, ['constraints', 'enums', 'parents'], true)) {
                continue;
            }
            try {
                $catalog[$key] = self::rows($source, 'pgsql', $sql, ['oid' => $oid], self::MAX_INDEXES);
            } catch (DriverFailure $driverFailure) {
                throw $driverFailure;
            } catch (\Throwable $error) {
                $notes[] = $label . ' could not be read: ' . $error->getMessage();
            }
        }
        $built = self::postgres($catalog);
        $built['notes'] = array_merge($built['notes'] ?? [], $notes);
        if ($built['notes'] === []) {
            unset($built['notes']);
        }

        return $built;
    }

    /**
     * Reconstructs PostgreSQL DDL from catalog rows (associative arrays or objects), so it can
     * be checked from recorded rows: `relation` (relkind, relpersistence, relispartition,
     * qualified, options, partition_key, partition_bound, comment, view_definition), `columns`
     * (name, type, not_null, default_value, identity, generated, collation, comment),
     * `constraints` (name, type, definition), `indexes` and `triggers` (definition), `enums`
     * (name, labels as a JSON array), `parents` (name). Names arrive quoted (quote_ident()).
     *
     * @param array<string, mixed> $catalog
     * @return array<string, mixed> `kind`, `how`, `sql`, `reconstructed`, and `notes`
     */
    public static function postgres(array $catalog): array
    {
        $relation = self::assoc($catalog['relation'] ?? []);
        $name = (string) ($relation['qualified'] ?? '');
        $relkind = (string) ($relation['relkind'] ?? 'r');
        $options = isset($relation['options']) && is_string($relation['options']) && $relation['options'] !== '' ? ' WITH (' . $relation['options'] . ')' : '';
        $statements = [];
        $notes = [];
        $kind = 'table';
        if ($relkind === 'v' || $relkind === 'm') {
            $kind = $relkind === 'm' ? 'materialized view' : 'view';
            $definition = rtrim(trim((string) ($relation['view_definition'] ?? '')), ';');
            $statements[] = ($relkind === 'm' ? 'CREATE MATERIALIZED VIEW ' : 'CREATE OR REPLACE VIEW ') . $name . $options . " AS\n" . $definition . ';';
        } else {
            if ($relkind === 'p') {
                $kind = 'partitioned table';
            } elseif ($relkind === 'f') {
                $kind = 'foreign table';
                $notes[] = 'A foreign table: its server and options are left out.';
            }
            $enums = [];
            foreach ($catalog['enums'] ?? [] as $row) {
                $row = self::assoc($row);
                $labels = json_decode((string) ($row['labels'] ?? '[]'), true);
                if (!is_array($labels) || !isset($row['name'])) {
                    continue;
                }
                $enums[] = 'CREATE TYPE ' . $row['name'] . ' AS ENUM (' . implode(', ', array_map([self::class, 'pgLiteral'], array_map('strval', $labels))) . ');';
            }
            if ($enums !== []) {
                $statements[] = "-- Enum types its columns use (defined on their own, not by this table):\n" . implode("\n", $enums);
            }
            $lines = [];
            foreach ($catalog['columns'] ?? [] as $row) {
                $row = self::assoc($row);
                $line = '    ' . $row['name'] . ' ' . $row['type'];
                if (isset($row['collation']) && is_string($row['collation']) && $row['collation'] !== '') {
                    $line .= ' COLLATE ' . $row['collation'];
                }
                $default = isset($row['default_value']) && is_string($row['default_value']) && $row['default_value'] !== '' ? $row['default_value'] : null;
                $generated = (string) ($row['generated'] ?? '');
                $identity = (string) ($row['identity'] ?? '');
                if ($generated === 's' && $default !== null) {
                    $line .= ' GENERATED ALWAYS AS (' . $default . ') STORED';
                } elseif ($identity === 'a' || $identity === 'd') {
                    $line .= ' GENERATED ' . ($identity === 'a' ? 'ALWAYS' : 'BY DEFAULT') . ' AS IDENTITY';
                } elseif ($default !== null) {
                    $line .= ' DEFAULT ' . $default;
                }
                if (SqlSchema::flag($row['not_null'] ?? null) === true) {
                    $line .= ' NOT NULL';
                }
                $lines[] = $line;
            }
            foreach ($catalog['constraints'] ?? [] as $row) {
                $row = self::assoc($row);
                $lines[] = '    CONSTRAINT ' . $row['name'] . ' ' . $row['definition'];
            }
            $create = 'CREATE ' . (($relation['relpersistence'] ?? 'p') === 'u' ? 'UNLOGGED ' : '') . ($relkind === 'f' ? 'FOREIGN ' : '') . 'TABLE ' . $name . " (\n" . implode(",\n", $lines) . "\n)";
            $parents = array_map(static function ($row): string {
                return (string) (self::assoc($row)['name'] ?? '');
            }, $catalog['parents'] ?? []);
            $partitioned = SqlSchema::flag($relation['relispartition'] ?? null) === true;
            if ($parents !== [] && !$partitioned) {
                $create .= "\nINHERITS (" . implode(', ', $parents) . ')';
            }
            if (isset($relation['partition_key']) && is_string($relation['partition_key']) && $relation['partition_key'] !== '') {
                $create .= "\nPARTITION BY " . $relation['partition_key'];
            }
            $create .= $options . ';';
            if ($partitioned && $parents !== []) {
                $create = '-- A partition of ' . $parents[0] . ' ' . ($relation['partition_bound'] ?? '') . ":\n-- ALTER TABLE " . $parents[0] . ' ATTACH PARTITION ' . $name . ' ' . ($relation['partition_bound'] ?? '') . ";\n" . $create;
            }
            $statements[] = $create;
        }
        $indexes = [];
        foreach ($catalog['indexes'] ?? [] as $row) {
            $indexes[] = self::statement((string) (self::assoc($row)['definition'] ?? ''));
        }
        if ($indexes !== []) {
            $statements[] = implode("\n", $indexes);
        }
        foreach ($catalog['triggers'] ?? [] as $row) {
            $statements[] = self::statement((string) (self::assoc($row)['definition'] ?? ''));
        }
        $comments = [];
        if (isset($relation['comment']) && is_string($relation['comment'])) {
            $comments[] = 'COMMENT ON ' . strtoupper($kind === 'partitioned table' ? 'table' : $kind) . ' ' . $name . ' IS ' . self::pgLiteral($relation['comment']) . ';';
        }
        foreach ($catalog['columns'] ?? [] as $row) {
            $row = self::assoc($row);
            if (isset($row['comment']) && is_string($row['comment'])) {
                $comments[] = 'COMMENT ON COLUMN ' . $name . '.' . $row['name'] . ' IS ' . self::pgLiteral($row['comment']) . ';';
            }
        }
        if ($comments !== []) {
            $statements[] = implode("\n", $comments);
        }
        if ($kind === 'view' || $kind === 'materialized view') {
            $notes[] = 'Reconstructed by Runlet around PostgreSQL\'s pg_get_viewdef().';
            $notes[] = 'Left out: owner and privileges.';
        } else {
            $notes[] = 'Reconstructed by Runlet from the catalog: PostgreSQL has no SHOW CREATE TABLE.';
            $notes[] = 'Left out: owner, privileges, policies, rules, and the sequences behind serial columns.';
        }

        return ['kind' => $kind, 'how' => 'pg_catalog', 'sql' => implode("\n\n", $statements), 'reconstructed' => true, 'notes' => $notes];
    }

    /**
     * @param string[] $statements
     * @param string[] $notes
     * @return array<string, mixed>
     */
    private static function result(string $kind, string $how, array $statements, array $notes): array
    {
        $result = ['kind' => $kind, 'how' => $how, 'sql' => implode("\n\n", $statements)];
        if ($notes !== []) {
            $result['notes'] = $notes;
        }

        return $result;
    }

    /** One statement, ending in exactly one semicolon. */
    private static function statement(string $sql): string
    {
        return rtrim(rtrim(trim($sql)), ';') . ';';
    }

    /**
     * The DDL within MAX_BYTES, cut at a line, with a note when it was cut.
     *
     * @param array<string, mixed> $result
     */
    private static function bounded(string $sql, array &$result): string
    {
        if (preg_match('//u', $sql) !== 1) {
            $sql = (string) preg_replace('/[^\x09\x0A\x0D\x20-\x7E]/', '?', $sql);
        }
        if (strlen($sql) <= self::MAX_BYTES) {
            return $sql;
        }
        $cut = substr($sql, 0, self::MAX_BYTES);
        $line = strrpos($cut, "\n");
        $result['notes'][] = 'The definition is longer than ' . (self::MAX_BYTES >> 20) . ' MB, so Runlet cut it.';

        return $line === false ? $cut : substr($cut, 0, $line);
    }

    /** A MySQL identifier in backticks. */
    private static function backticks(string $name): string
    {
        return '`' . str_replace('`', '``', $name) . '`';
    }

    /** A PostgreSQL string literal (doubled quotes, standard strings). */
    public static function pgLiteral(string $value): string
    {
        return strpos($value, '\\') === false ? "'" . str_replace("'", "''", $value) . "'" : "E'" . str_replace(['\\', "'"], ['\\\\', "''"], $value) . "'";
    }

    /** The server, e.g. "MariaDB 11.4.2", "PostgreSQL 14.13", "SQLite 3.45.1"; null when unknown. */
    private static function server(\PDO $pdo, string $dialect): ?string
    {
        try {
            $version = (string) $pdo->getAttribute(\PDO::ATTR_SERVER_VERSION);
        } catch (\Throwable $error) {
            return null;
        }
        if ($version === '' || strlen($version) > 120) {
            return null;
        }
        if ($dialect === 'mysql') {
            if (stripos($version, 'mariadb') !== false) {
                return 'MariaDB ' . preg_replace('/^(5\.5\.5-)?([0-9.]+).*$/', '$2', $version);
            }

            return 'MySQL ' . preg_replace('/^([0-9.]+).*$/', '$1', $version);
        }

        return ($dialect === 'pgsql' ? 'PostgreSQL ' : 'SQLite ') . preg_replace('/^([0-9.]+).*$/', '$1', $version);
    }

    /**
     * Rows of a catalog query as associative arrays (keys as the query names them, and their
     * positions), at most `$limit`. PDO binds `$params`; a callable gets them as literals.
     *
     * @param \PDO|callable $source
     * @param array<string, string|int> $params
     * @return array<int, array<int|string, mixed>>
     */
    private static function rows($source, string $dialect, string $sql, array $params, int $limit): array
    {
        $rows = [];
        if ($source instanceof \PDO) {
            $source->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
            if ($params === []) {
                $statement = $source->query($sql);
            } else {
                $statement = $source->prepare($sql);
                foreach ($params as $key => $value) {
                    $statement->bindValue(':' . $key, $value, is_int($value) ? \PDO::PARAM_INT : \PDO::PARAM_STR);
                }
                $statement->execute();
            }
            while (($row = $statement->fetch(\PDO::FETCH_BOTH)) !== false) {
                $rows[] = $row;
                if (count($rows) >= $limit) {
                    break;
                }
            }
            $statement->closeCursor();

            return $rows;
        }
        $inline = preg_replace_callback('/(?<!:):([a-z]+)\b/', static function (array $match) use ($params, $dialect): string {
            if (!array_key_exists($match[1], $params)) {
                return $match[0];
            }
            $value = $params[$match[1]];
            if (is_int($value)) {
                return (string) $value;
            }

            return $dialect === 'pgsql' ? self::pgLiteral($value) : ($dialect === 'mysql' ? "'" . str_replace(['\\', "'"], ['\\\\', "''"], $value) . "'" : "'" . str_replace("'", "''", $value) . "'");
        }, $sql);
        $returned = $source((string) $inline);
        if (!is_iterable($returned)) {
            throw new \UnexpectedValueException('the connection returned no rows for the catalog query');
        }
        foreach ($returned as $row) {
            $assoc = is_object($row) ? get_object_vars($row) : (array) $row;
            $rows[] = $assoc + array_values($assoc);
            if (count($rows) >= $limit) {
                break;
            }
        }

        return $rows;
    }

    /**
     * A row's value by name (any case), else by position.
     *
     * @param array<int|string, mixed> $row
     * @param string|int $key
     * @return mixed
     */
    private static function value(array $row, $key)
    {
        if (array_key_exists($key, $row)) {
            return $row[$key];
        }
        if (is_string($key)) {
            foreach ($row as $name => $value) {
                if (is_string($name) && strcasecmp($name, $key) === 0) {
                    return $value;
                }
            }
        }

        return null;
    }

    /**
     * A row as an associative array with lowercase names.
     *
     * @param mixed $row
     * @return array<string, mixed>
     */
    private static function assoc($row): array
    {
        $values = is_object($row) ? get_object_vars($row) : (array) $row;
        $assoc = [];
        foreach ($values as $key => $value) {
            if (is_string($key)) {
                $assoc[strtolower($key)] = $value;
            }
        }

        return $assoc;
    }
}
}

/*
 * Stop cancels an SQL tab's statement on the database server (#144).
 *
 * A run reports its connection's server-side session as an `sqlSession` event right after
 * connecting, before the statement runs (report()). On Stop, the app starts a second, short
 * runner on the same target with the same connection, which calls SqlTab::cancel() and so
 * cancel(): it checks that its connection reached the same server, that the session still runs
 * something, sends the one cancel statement for the dialect, and watches the statement end. It
 * emits an `sqlCancel` event. Then the app stops the first runner's process, as Stop always did.
 *
 * Only Runlet's own statements run here: KILL QUERY <id> (MySQL, MariaDB), SELECT
 * pg_cancel_backend(<pid>) (PostgreSQL), KILL <spid> (SQL Server). They are allowed in a
 * read-only session (#139). No event carries credentials.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

final class SqlCancel
{
    /** How long cancel() watches the statement end after the server took the cancel. */
    private const VERIFY_MS = 1500;
    /** Between two looks at the session. */
    private const POLL_MS = 50;

    /**
     * Emits the `sqlSession` event for `$source` when it is a PDO connection to a server Runlet
     * can cancel on. Never fails the run: a session that can't be read just isn't reported, and
     * Stop then only ends the runner, as before.
     *
     * @param \PDO|callable $source
     */
    public static function report($source, ?string $connection, bool $transaction = false): void
    {
        if (!$source instanceof \PDO) {
            return; // A callable connection: no session Runlet can name.
        }
        $identity = self::identify($source);
        if ($identity === null) {
            return;
        }
        Channel::emit('sqlSession', array_filter([
            'driver' => $identity['driver'],
            'id' => $identity['id'],
            'connection' => SqlConnect::isConfigured() ? null : $connection,
            'saved' => SqlConnect::isConfigured() ? true : null,
            'transaction' => $transaction ? true : null,
            'server' => $identity['server'],
        ], static function ($value): bool {
            return $value !== null;
        }));
    }

    /**
     * The cancel statement of `$session` in `$dialect`; null for dialects without one.
     */
    public static function statement(string $dialect, int $session): ?string
    {
        if ($session <= 0) {
            return null;
        }
        switch ($dialect) {
            case 'mysql':
                return 'KILL QUERY ' . $session;
            case 'pgsql':
                return 'SELECT pg_cancel_backend(' . $session . ')';
            case 'sqlsrv':
                return 'KILL ' . $session;
            default:
                return null;
        }
    }

    /**
     * Cancels `$session`'s statement through `$source` (the same connection, opened again) and
     * returns the `sqlCancel` event: `outcome` (cancelled, stillRunning, alreadyEnded, idle,
     * refused, failed), `detail`, `state`, `verified`, `elapsedMs`.
     *
     * @param \PDO|callable $source
     * @return array<string, mixed>
     */
    public static function cancel($source, string $origin, string $dialect, int $session, string $statement, string $server): array
    {
        $started = hrtime(true);
        $done = static function (string $outcome, array $fields = []) use ($dialect, $session, $statement, $started): array {
            return array_filter([
                'outcome' => $outcome,
                'driver' => $dialect,
                'session' => $session,
                'statement' => $statement,
                'detail' => $fields['detail'] ?? null,
                'state' => $fields['state'] ?? null,
                'verified' => $fields['verified'] ?? null,
                'elapsedMs' => round((hrtime(true) - $started) / 1e6, 3),
            ], static function ($value): bool {
                return $value !== null;
            });
        };
        if (!$source instanceof \PDO) {
            return $done('failed', ['detail' => 'the connection (' . $origin . ') is no longer a PDO connection, so Runlet has nothing to send the cancel through']);
        }
        $pdo = $source;
        $pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        $identity = self::identify($pdo);
        if ($identity === null || self::dialect($identity['driver']) !== $dialect) {
            $actual = $identity === null ? self::driverName($pdo) : $identity['driver'];

            return $done('failed', ['detail' => 'the connection is ' . ($actual === null ? 'of an unknown kind' : 'a ' . $actual . ' connection') . ' now, and the statement ran on ' . $dialect]);
        }
        if (self::statement($dialect, $session) !== $statement) {
            return $done('refused', ['detail' => 'Runlet sends only its own cancel statement for session ' . $session]);
        }
        if ($identity['id'] === $session) {
            return $done('refused', ['detail' => 'the second connection got session ' . $session . ' itself']);
        }
        if ($server !== '' && $identity['server'] !== null && $identity['server'] !== $server) {
            return $done('refused', ['detail' => 'the second connection reached another database server (a list of hosts, a load balancer, or a failover?), so Runlet sent nothing there']);
        }
        $before = self::activity($pdo, $dialect, $session);
        if ($before !== null && $before['gone'] && $dialect === 'mysql') {
            // MySQL shows only the user's own threads without the PROCESS privilege: KILL QUERY
            // says whether the thread exists (1094) and whether this user may cancel it (1095).
            $before = null;
        }
        if ($before !== null) {
            if ($before['gone']) {
                return $done('alreadyEnded');
            }
            if ($before['otherUser']) {
                return $done('refused', ['detail' => 'session ' . $session . ' belongs to another database user now']);
            }
            if ($before['running'] === false) {
                return $done('idle');
            }
        }
        try {
            if ($dialect === 'pgsql') {
                $result = $pdo->query($statement);
                $sent = $result === false ? false : $result->fetchColumn();
                if (!in_array($sent, [true, 1, '1', 't', 'true'], true)) {
                    // PostgreSQL: false (with a warning) when no backend has the pid.
                    return $done('alreadyEnded');
                }
            } else {
                $pdo->exec($statement);
            }
        } catch (\PDOException $error) {
            return self::refusal($done, $dialect, $session, $error);
        }
        if ($before === null) {
            // The session isn't visible to this user (another user's MySQL thread, SQL Server
            // without VIEW SERVER STATE): the server took the cancel; Runlet can't watch it end.
            return $done('cancelled', ['verified' => false]);
        }
        $deadline = hrtime(true) + self::VERIFY_MS * 1000000;
        $now = $before;
        while (true) {
            $now = self::activity($pdo, $dialect, $session);
            if ($now === null) {
                return $done('cancelled', ['verified' => false]);
            }
            if ($now['gone'] || $now['running'] === false || !self::same($before, $now)) {
                return $done('cancelled', ['verified' => true]);
            }
            if (hrtime(true) >= $deadline) {
                break;
            }
            usleep(self::POLL_MS * 1000);
        }

        return $done('stillRunning', ['state' => $now['state'] ?? null]);
    }

    /**
     * Why the database refused the cancel, as an outcome: the session had ended, or the user
     * may not cancel it.
     *
     * @param callable(string, array<string, mixed>=): array<string, mixed> $done
     * @return array<string, mixed>
     */
    private static function refusal(callable $done, string $dialect, int $session, \PDOException $error): array
    {
        $code = is_array($error->errorInfo) ? ($error->errorInfo[1] ?? null) : null;
        $state = is_array($error->errorInfo) ? (string) ($error->errorInfo[0] ?? '') : (string) $error->getCode();
        $message = self::databaseMessage($error);
        if ($dialect === 'mysql') {
            if ((int) $code === 1094) {
                return $done('alreadyEnded'); // Unknown thread id.
            }
            if ((int) $code === 1095) {
                return $done('refused', ['detail' => 'the database user may not cancel session ' . $session . ' (' . $message . '); cancelling another user\'s statement needs the CONNECTION_ADMIN or SUPER privilege']);
            }
        } elseif ($dialect === 'pgsql') {
            if ($state === '42501') {
                return $done('refused', ['detail' => 'the database user may not cancel session ' . $session . ' (' . $message . '); pg_cancel_backend needs the same role, or membership in pg_signal_backend']);
            }
        } elseif ($dialect === 'sqlsrv') {
            if ((int) $code === 6106) {
                return $done('alreadyEnded'); // Process ID is not an active process ID.
            }
            if ((int) $code === 6102) {
                return $done('refused', ['detail' => 'the database user may not cancel session ' . $session . ' (' . $message . '); SQL Server\'s KILL needs the ALTER ANY CONNECTION permission']);
            }
        }

        return $done('failed', ['detail' => $message]);
    }

    /** The database's own words, without PDO's SQLSTATE prefix. */
    private static function databaseMessage(\PDOException $error): string
    {
        $info = $error->errorInfo;
        if (is_array($info) && isset($info[2]) && is_string($info[2]) && $info[2] !== '') {
            return trim(preg_replace('/^ERROR:\s+/', '', $info[2]) ?? $info[2]);
        }

        return $error->getMessage();
    }

    /**
     * This connection's session id, its PDO driver, and a fingerprint of its server; null for
     * drivers Runlet can't cancel on (SQLite needs nothing: the database is in this process).
     * The server panel (#150) uses it too.
     *
     * @return array{driver: string, id: int, server: string|null}|null
     */
    public static function identify(\PDO $pdo): ?array
    {
        $driver = self::driverName($pdo);
        $queries = [
            'mysql' => 'SELECT CONNECTION_ID(), @@hostname, @@port',
            'pgsql' => 'SELECT pg_backend_pid(), pg_postmaster_start_time()::text, inet_server_port()',
            'sqlsrv' => 'SELECT @@SPID, @@SERVERNAME',
        ];
        $dialect = self::dialect($driver);
        if ($driver === null || $dialect === null || !isset($queries[$dialect])) {
            return null;
        }
        $mode = null;
        try {
            $mode = $pdo->getAttribute(\PDO::ATTR_ERRMODE);
            $pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
            $statement = $pdo->query($queries[$dialect]);
            $row = $statement === false ? false : $statement->fetch(\PDO::FETCH_NUM);
            if ($statement !== false) {
                $statement->closeCursor();
            }
        } catch (\Throwable $error) {
            $row = false;
        } finally {
            if ($mode !== null) {
                try {
                    $pdo->setAttribute(\PDO::ATTR_ERRMODE, $mode);
                } catch (\Throwable $error) {
                    // Keep going; the run sets its own error mode for the statement.
                }
            }
        }
        if (!is_array($row) || !isset($row[0]) || (int) $row[0] <= 0) {
            return null;
        }
        $parts = array_map(static function ($part): string {
            return $part === null ? '' : (string) $part;
        }, array_slice($row, 1));

        return ['driver' => $driver, 'id' => (int) $row[0], 'server' => substr(sha1($dialect . '|' . implode('|', $parts)), 0, 16)];
    }

    /**
     * What `$session` is doing, as far as this user may see: `gone` (no such session),
     * `running` (null when unknown), `otherUser`, `state`, and what identifies the statement
     * (`since`, `text`). Null when Runlet can't look (no view, no rights, SQL Server).
     *
     * @return array{gone: bool, running: bool|null, otherUser: bool, state: string|null, since: string|null, text: string|null}|null
     */
    private static function activity(\PDO $pdo, string $dialect, int $session): ?array
    {
        try {
            if ($dialect === 'mysql') {
                $statement = $pdo->prepare('SELECT COMMAND, TIME, STATE, INFO, USER, SUBSTRING_INDEX(USER(), \'@\', 1) FROM information_schema.PROCESSLIST WHERE ID = ?');
                $statement->execute([$session]);
                $row = $statement->fetch(\PDO::FETCH_NUM);
                $statement->closeCursor();
                if (!is_array($row)) {
                    // Gone, or (without the PROCESS privilege) another user's thread: cancel()
                    // tells them apart.
                    return ['gone' => true, 'running' => null, 'otherUser' => false, 'state' => null, 'since' => null, 'text' => null];
                }
                $command = (string) $row[0];

                return [
                    'gone' => false,
                    'running' => $command !== 'Sleep',
                    'otherUser' => (string) $row[4] !== '' && (string) $row[5] !== '' && (string) $row[4] !== (string) $row[5],
                    'state' => trim($command . ($row[2] !== null && (string) $row[2] !== '' ? ', ' . $row[2] : '')),
                    'since' => (string) $row[1],
                    'text' => $row[3] === null ? null : (string) $row[3],
                ];
            }
            if ($dialect === 'pgsql') {
                $statement = $pdo->prepare('SELECT state, query_start::text, usename, session_user FROM pg_stat_activity WHERE pid = ?');
                $statement->execute([$session]);
                $row = $statement->fetch(\PDO::FETCH_NUM);
                $statement->closeCursor();
                if (!is_array($row)) {
                    return ['gone' => true, 'running' => null, 'otherUser' => false, 'state' => null, 'since' => null, 'text' => null];
                }
                $state = $row[0] === null ? null : (string) $row[0];

                return [
                    'gone' => false,
                    // Null for another role's session: its state isn't shown.
                    'running' => $state === null ? null : $state === 'active',
                    'otherUser' => $row[2] !== null && (string) $row[2] !== (string) $row[3],
                    'state' => $state,
                    'since' => $row[1] === null ? null : (string) $row[1],
                    'text' => null,
                ];
            }
        } catch (\Throwable $error) {
            return null;
        }

        return null;
    }

    /**
     * Whether `$now` is still the statement `$before` saw: PostgreSQL's query start, or MySQL's
     * statement text with a time that didn't start over.
     *
     * @param array<string, mixed> $before
     * @param array<string, mixed> $now
     */
    private static function same(array $before, array $now): bool
    {
        if ($before['text'] !== null || $now['text'] !== null) {
            return $before['text'] === $now['text'] && (int) $now['since'] >= (int) $before['since'];
        }

        return $before['since'] === $now['since'];
    }

    private static function driverName(\PDO $pdo): ?string
    {
        try {
            return (string) $pdo->getAttribute(\PDO::ATTR_DRIVER_NAME);
        } catch (\Throwable $error) {
            return null;
        }
    }

    /** `mysql`, `pgsql`, or `sqlsrv` (also through dblib); null for the rest. */
    private static function dialect(?string $driver): ?string
    {
        switch ($driver) {
            case 'mysql':
            case 'pgsql':
                return $driver;
            case 'sqlsrv':
            case 'dblib':
                return 'sqlsrv';
            default:
                return null;
        }
    }
}
}

/*
 * The Database pane's Server section (#150): what the server of an SQL tab's connection is,
 * how big its database and largest tables are, and which sessions it has, read on demand in a
 * fresh runner; and a confirmed Cancel Query or Kill Session on one of those sessions.
 *
 * read() reads only the catalog and the server's status, never rows of tables:
 *  - overview: the server and its version, the current database and user, uptime, TLS;
 *  - sizes: the database's size and its largest tables with data and index sizes
 *    (information_schema.TABLES on MySQL and MariaDB, pg_database_size()/pg_table_size()/
 *    pg_indexes_size()/pg_total_relation_size() on PostgreSQL, the dbstat table or the file's
 *    page count on SQLite);
 *  - sessions: information_schema.PROCESSLIST (MySQL, MariaDB) or pg_stat_activity
 *    (PostgreSQL), with what this user may see. SQLite has no sessions.
 * Each part fails on its own (a missing privilege), so the others still show.
 *
 * act() sends one of Runlet's own statements: KILL QUERY <id> or KILL <id> (MySQL, MariaDB),
 * SELECT pg_cancel_backend(<pid>) or SELECT pg_terminate_backend(<pid>) (PostgreSQL), after
 * checking that its connection reached the same server the list came from (#144's server
 * fingerprint), that the session isn't the one the list was read with nor its own, and that
 * the session is still the one listed (its user; PostgreSQL's backend start, as pids are
 * reused). Then it watches the statement or the session end. They are allowed in a read-only
 * session (#139): they change no data. SQL Server and callable connections aren't supported.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

final class SqlServerInfo
{
    /** Largest tables reported. */
    public const MAX_TABLES = 20;
    /** Sessions reported at most. */
    public const MAX_SESSIONS = 200;
    /** Bytes kept of one session's statement, and of all of them together. */
    public const MAX_QUERY_BYTES = 4096;
    public const MAX_QUERIES_BYTES = 1048576;
    /** How long act() watches the statement or session end. */
    private const VERIFY_MS = 2000;
    private const POLL_MS = 50;
    /**
     * PostgreSQL's client sessions: `client backend`, or (another role's, whose backend type
     * PostgreSQL hides without pg_read_all_stats) a session with a database and a role.
     */
    private const PG_CLIENTS = "(backend_type = 'client backend' OR (backend_type IS NULL AND datid IS NOT NULL AND usesysid IS NOT NULL))";

    /**
     * The parts of the server report asked for (`overview`, `sizes`, `sessions`), as the
     * `sqlServer` event's fields; `errors` holds the parts that failed, by name.
     *
     * @param \PDO|callable $source
     * @param string[] $parts
     * @return array<string, mixed>
     */
    public static function read($source, string $origin, ?string $driverName, array $parts): array
    {
        $parts = array_values(array_intersect(['overview', 'sizes', 'sessions'], $parts));
        if ($parts === []) {
            $parts = ['overview', 'sizes', 'sessions'];
        }
        $pdo = self::pdo($source, $origin, $driverName, 'read server details');
        $dialect = self::dialect($driverName);
        $pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        $result = ['dialect' => $dialect, 'parts' => $parts];
        $identity = $dialect === 'sqlite' ? null : SqlCancel::identify($pdo);
        if ($identity !== null) {
            $result['sessionId'] = $identity['id'];
            $result['server'] = $identity['server'];
        }
        $errors = [];
        foreach ($parts as $part) {
            try {
                if ($part === 'overview') {
                    $result['overview'] = self::overview($pdo, $dialect);
                } elseif ($part === 'sizes') {
                    $result['sizes'] = self::sizes($pdo, $dialect);
                } else {
                    $result['sessions'] = self::sessions($pdo, $dialect, $identity === null ? 0 : $identity['id']);
                }
            } catch (DriverFailure $failure) {
                throw $failure;
            } catch (\Throwable $error) {
                $errors[$part] = self::message($error);
            }
        }
        if ($errors !== []) {
            $result['errors'] = $errors;
        }

        return $result;
    }

    /**
     * Runlet's statement for `$action` (`cancel`, `kill`) on `$session`; null where there is none.
     */
    public static function statement(string $action, string $dialect, int $session): ?string
    {
        if ($session <= 0) {
            return null;
        }
        if ($action === 'cancel') {
            return in_array($dialect, ['mysql', 'pgsql'], true) ? SqlCancel::statement($dialect, $session) : null;
        }
        if ($action === 'kill') {
            if ($dialect === 'mysql') {
                return 'KILL ' . $session;
            }
            if ($dialect === 'pgsql') {
                return 'SELECT pg_terminate_backend(' . $session . ')';
            }
        }

        return null;
    }

    /**
     * Cancel Query or Kill Session on `$session`, which the list read with session `$listedBy`
     * on server `$server` showed for user `$user` (and, on PostgreSQL, started at `$started`).
     * Returns the `sqlServerAction` event: `outcome` (cancelled, killed, stillRunning,
     * alreadyEnded, idle, refused, failed), `detail`, `state`, `verified`, `elapsedMs`.
     *
     * @param \PDO|callable $source
     * @return array<string, mixed>
     */
    public static function act($source, string $origin, ?string $driverName, string $action, string $dialect, int $session, string $statement, string $server, int $listedBy, string $user, string $started): array
    {
        $begun = hrtime(true);
        $done = static function (string $outcome, array $fields = []) use ($action, $dialect, $session, $statement, $begun): array {
            return array_filter([
                'action' => $action,
                'outcome' => $outcome,
                'driver' => $dialect,
                'session' => $session,
                'statement' => $statement,
                'detail' => $fields['detail'] ?? null,
                'state' => $fields['state'] ?? null,
                'verified' => $fields['verified'] ?? null,
                'elapsedMs' => round((hrtime(true) - $begun) / 1e6, 3),
            ], static function ($value): bool {
                return $value !== null;
            });
        };
        if (!in_array($action, ['cancel', 'kill'], true) || self::statement($action, $dialect, $session) !== $statement) {
            return $done('refused', ['detail' => 'Runlet sends only its own ' . ($action === 'kill' ? 'kill' : 'cancel') . ' statement for session ' . $session]);
        }
        if (!$source instanceof \PDO) {
            return $done('failed', ['detail' => 'the connection (' . $origin . ') is a callable, so Runlet has nothing to send the statement through']);
        }
        $pdo = $source;
        $pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        $identity = SqlCancel::identify($pdo);
        if ($identity === null || self::dialect($identity['driver']) !== $dialect) {
            return $done('failed', ['detail' => 'the connection is ' . ($driverName === null ? 'of an unknown kind' : 'a ' . $driverName . ' connection') . ' now, and the session was listed on ' . $dialect]);
        }
        if ($listedBy > 0 && $session === $listedBy) {
            return $done('refused', ['detail' => 'session ' . $session . ' is the one the panel read the list with']);
        }
        if ($identity['id'] === $session) {
            return $done('refused', ['detail' => 'session ' . $session . ' is this runner\'s own connection']);
        }
        if ($server !== '' && $identity['server'] !== null && $identity['server'] !== $server) {
            return $done('refused', ['detail' => 'this connection reached another database server than the list came from (a list of hosts, a load balancer, or a failover?), so Runlet sent nothing there']);
        }
        $before = self::session($pdo, $dialect, $session);
        if ($before === null) {
            // MySQL without the PROCESS privilege shows only this user's own threads: KILL says
            // whether the thread exists (1094) and whether this user may end it (1095).
            if ($dialect === 'pgsql') {
                return $done('alreadyEnded');
            }
            $self = self::currentUserName($pdo);
            if ($user === '' || $self === null || $self === $user) {
                return $done('alreadyEnded');
            }
        } else {
            if ($user !== '' && $before['user'] !== null && $before['user'] !== $user) {
                return $done('refused', ['detail' => 'session ' . $session . ' belongs to ' . $before['user'] . ' now, not ' . $user . ', so it isn\'t the session the panel listed']);
            }
            if ($dialect === 'pgsql' && $started !== '' && $before['started'] !== null && $before['started'] !== $started) {
                return $done('refused', ['detail' => 'process ' . $session . ' is another session now (it started at ' . $before['started'] . ', the listed one at ' . $started . ')']);
            }
            if ($action === 'cancel' && $before['running'] === false) {
                return $done('idle', ['state' => $before['state']]);
            }
        }
        try {
            if ($dialect === 'pgsql') {
                $sent = $pdo->query($statement);
                $answer = $sent === false ? false : $sent->fetchColumn();
                if (!in_array($answer, [true, 1, '1', 't', 'true'], true)) {
                    return $done('alreadyEnded'); // No backend has the pid (any more).
                }
            } else {
                $pdo->exec($statement);
            }
        } catch (\PDOException $error) {
            return self::refusal($done, $action, $dialect, $session, $error);
        }
        if ($before === null) {
            return $done($action === 'kill' ? 'killed' : 'cancelled', ['verified' => false]);
        }
        $deadline = hrtime(true) + self::VERIFY_MS * 1000000;
        $now = $before;
        while (true) {
            usleep(self::POLL_MS * 1000);
            $now = self::session($pdo, $dialect, $session);
            if ($now === null) {
                return $done($action === 'kill' ? 'killed' : 'cancelled', ['verified' => true]);
            }
            if ($action === 'cancel' && ($now['running'] === false || !self::sameStatement($before, $now))) {
                return $done('cancelled', ['verified' => true]);
            }
            if (hrtime(true) >= $deadline) {
                break;
            }
        }

        return $done('stillRunning', ['state' => $now['state']]);
    }

    /**
     * The connection as a PDO, or why the panel can't use it.
     *
     * @param \PDO|callable $source
     */
    private static function pdo($source, string $origin, ?string $driverName, string $what): \PDO
    {
        if (!$source instanceof \PDO) {
            throw new SqlUnavailable('Runlet can\'t ' . $what . ' here: this connection is a callable from ' . $origin . ', so Runlet doesn\'t know its database and can\'t send its own queries through it. The server panel needs a PDO connection (MySQL, MariaDB, PostgreSQL, or SQLite).');
        }
        $dialect = self::dialect($driverName);
        if ($dialect === null) {
            if ($driverName === 'sqlsrv' || $driverName === 'dblib') {
                throw new SqlUnavailable('Runlet\'s server panel doesn\'t support SQL Server yet. Use sys.dm_exec_sessions and sp_who2 in a query, or your database tool.');
            }
            throw new SqlUnavailable('Runlet can\'t ' . $what . ' on ' . ($driverName ?? 'this kind of') . ' connections: the server panel reads MySQL, MariaDB, PostgreSQL, and SQLite.');
        }

        return $source;
    }

    /** `mysql`, `pgsql`, or `sqlite`; null for the rest. */
    private static function dialect(?string $driver): ?string
    {
        switch ($driver) {
            case 'mysql':
            case 'pgsql':
            case 'sqlite':
                return $driver;
            case 'sqlite2':
                return 'sqlite';
            default:
                return null;
        }
    }

    /**
     * The server, its version, the current database and user, uptime, and TLS.
     *
     * @return array<string, mixed>
     */
    private static function overview(\PDO $pdo, string $dialect): array
    {
        $version = (string) $pdo->getAttribute(\PDO::ATTR_SERVER_VERSION);
        if ($dialect === 'mysql') {
            $row = $pdo->query('SELECT VERSION(), DATABASE(), CURRENT_USER(), @@version_comment')->fetch(\PDO::FETCH_NUM);
            $status = self::status($pdo, ['Uptime', 'Threads_connected', 'Ssl_version', 'Ssl_cipher'], 'GLOBAL');
            $session = self::status($pdo, ['Ssl_version', 'Ssl_cipher'], 'SESSION');
            $full = is_array($row) && $row[0] !== null ? (string) $row[0] : $version;
            $cipher = (string) ($session['Ssl_cipher'] ?? '');
            $mariadb = stripos($full, 'mariadb') !== false || (is_array($row) && stripos((string) $row[3], 'mariadb') !== false);

            return self::filtered([
                'product' => $mariadb ? 'MariaDB' : 'MySQL',
                'version' => self::number($full),
                'versionText' => self::bounded($full . (is_array($row) && $row[3] !== null && (string) $row[3] !== '' ? ' (' . $row[3] . ')' : ''), 200),
                'database' => is_array($row) && $row[1] !== null ? (string) $row[1] : null,
                'user' => is_array($row) && $row[2] !== null ? (string) $row[2] : null,
                'uptimeSeconds' => isset($status['Uptime']) ? (int) $status['Uptime'] : null,
                'connections' => isset($status['Threads_connected']) ? (int) $status['Threads_connected'] : null,
                'tls' => $session === [] ? null : $cipher !== '',
                'tlsVersion' => $cipher === '' ? null : (string) ($session['Ssl_version'] ?? ''),
                'tlsCipher' => $cipher === '' ? null : $cipher,
            ]);
        }
        if ($dialect === 'pgsql') {
            $row = $pdo->query("SELECT version(), current_setting('server_version'), current_database(), current_user, EXTRACT(EPOCH FROM (now() - pg_postmaster_start_time()))::bigint, (SELECT COUNT(*) FROM pg_stat_activity WHERE " . self::PG_CLIENTS . ')')->fetch(\PDO::FETCH_NUM);
            $tls = [];
            try {
                $ssl = $pdo->query('SELECT ssl, version, cipher FROM pg_stat_ssl WHERE pid = pg_backend_pid()')->fetch(\PDO::FETCH_NUM);
                if (is_array($ssl)) {
                    $on = self::truthy($ssl[0]);
                    $tls = ['tls' => $on, 'tlsVersion' => $on ? (string) $ssl[1] : null, 'tlsCipher' => $on ? (string) $ssl[2] : null];
                }
            } catch (\Throwable $error) {
                $tls = [];
            }

            return self::filtered([
                'product' => 'PostgreSQL',
                'version' => self::number(is_array($row) ? (string) $row[1] : $version),
                'versionText' => is_array($row) ? self::bounded((string) $row[0], 200) : $version,
                'database' => is_array($row) ? (string) $row[2] : null,
                'user' => is_array($row) ? (string) $row[3] : null,
                'uptimeSeconds' => is_array($row) && $row[4] !== null ? (int) $row[4] : null,
                'connections' => is_array($row) && $row[5] !== null ? (int) $row[5] : null,
            ] + $tls);
        }
        $file = null;
        foreach ($pdo->query('PRAGMA database_list')->fetchAll(\PDO::FETCH_ASSOC) as $database) {
            if (($database['name'] ?? '') === 'main') {
                $file = (string) ($database['file'] ?? '');
            }
        }

        return self::filtered([
            'product' => 'SQLite',
            'version' => self::number((string) $pdo->query('SELECT sqlite_version()')->fetchColumn()),
            'database' => $file === null || $file === '' ? ':memory:' : $file,
            'journalMode' => (string) $pdo->query('PRAGMA journal_mode')->fetchColumn(),
        ]);
    }

    /**
     * The database's size and its largest tables (data, indexes, total, estimated rows).
     *
     * @return array<string, mixed>
     */
    private static function sizes(\PDO $pdo, string $dialect): array
    {
        if ($dialect === 'mysql') {
            $database = $pdo->query('SELECT DATABASE()')->fetchColumn();
            if ($database === null || $database === false) {
                return ['tables' => [], 'how' => 'information_schema.TABLES', 'notes' => ['The connection has no current database, so there are no table sizes to read.']];
            }
            $total = $pdo->query("SELECT SUM(DATA_LENGTH), SUM(INDEX_LENGTH), SUM(DATA_FREE), SUM(TABLE_TYPE <> 'VIEW'), SUM(TABLE_TYPE = 'VIEW') FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE()")->fetch(\PDO::FETCH_NUM);
            $statement = $pdo->query("SELECT TABLE_NAME, ENGINE, TABLE_ROWS, DATA_LENGTH, INDEX_LENGTH, DATA_FREE FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_TYPE <> 'VIEW' ORDER BY COALESCE(DATA_LENGTH, 0) + COALESCE(INDEX_LENGTH, 0) DESC, TABLE_NAME LIMIT " . self::MAX_TABLES);
            $tables = [];
            $innodb = false;
            while (($row = $statement->fetch(\PDO::FETCH_NUM)) !== false) {
                $innodb = $innodb || strcasecmp((string) $row[1], 'InnoDB') === 0;
                $tables[] = self::filtered([
                    'name' => (string) $row[0],
                    'engine' => $row[1] === null ? null : (string) $row[1],
                    'rows' => $row[2] === null ? null : (int) $row[2],
                    'dataBytes' => $row[3] === null ? null : (int) $row[3],
                    'indexBytes' => $row[4] === null ? null : (int) $row[4],
                    'totalBytes' => $row[3] === null && $row[4] === null ? null : (int) $row[3] + (int) $row[4],
                    'freeBytes' => $row[5] === null || (int) $row[5] === 0 ? null : (int) $row[5],
                ]);
            }
            $statement->closeCursor();
            $data = is_array($total) ? (int) $total[0] : 0;
            $indexes = is_array($total) ? (int) $total[1] : 0;

            return self::filtered([
                'database' => (string) $database,
                'databaseBytes' => $data + $indexes,
                'dataBytes' => $data,
                'indexBytes' => $indexes,
                'freeBytes' => is_array($total) && (int) $total[2] > 0 ? (int) $total[2] : null,
                'tableCount' => is_array($total) ? (int) $total[3] : count($tables),
                'viewCount' => is_array($total) && (int) $total[4] > 0 ? (int) $total[4] : null,
                'tables' => $tables,
                'how' => 'information_schema.TABLES',
                'estimated' => $innodb ? true : null,
                'notes' => $innodb ? ['InnoDB sizes and row counts are the server\'s estimates (ANALYZE TABLE refreshes them).'] : null,
            ]);
        }
        if ($dialect === 'pgsql') {
            $database = $pdo->query('SELECT current_database(), pg_database_size(current_database())')->fetch(\PDO::FETCH_NUM);
            $where = "c.relkind IN ('r', 'p', 'm') AND n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname NOT LIKE 'pg\\_toast%' AND n.nspname NOT LIKE 'pg\\_temp%'";
            $counts = $pdo->query("SELECT COUNT(*) FILTER (WHERE c.relkind IN ('r', 'p')), COUNT(*) FILTER (WHERE c.relkind = 'm') FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE " . $where)->fetch(\PDO::FETCH_NUM);
            $statement = $pdo->query('SELECT n.nspname, c.relname, c.relkind, c.reltuples::bigint, pg_table_size(c.oid), pg_indexes_size(c.oid), pg_total_relation_size(c.oid) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE ' . $where . ' ORDER BY pg_total_relation_size(c.oid) DESC, n.nspname, c.relname LIMIT ' . self::MAX_TABLES);
            $tables = [];
            while (($row = $statement->fetch(\PDO::FETCH_NUM)) !== false) {
                $tables[] = self::filtered([
                    'name' => (string) $row[1],
                    'schema' => (string) $row[0],
                    'kind' => $row[2] === 'p' ? 'partitioned table' : ($row[2] === 'm' ? 'materialized view' : null),
                    // -1: never analyzed (PostgreSQL 14 and later).
                    'rows' => $row[3] === null || (int) $row[3] < 0 ? null : (int) $row[3],
                    'dataBytes' => (int) $row[4],
                    'indexBytes' => (int) $row[5],
                    'totalBytes' => (int) $row[6],
                ]);
            }
            $statement->closeCursor();

            return self::filtered([
                'database' => is_array($database) ? (string) $database[0] : null,
                'databaseBytes' => is_array($database) ? (int) $database[1] : null,
                'tableCount' => is_array($counts) ? (int) $counts[0] : count($tables),
                'viewCount' => is_array($counts) && (int) $counts[1] > 0 ? (int) $counts[1] : null,
                'tables' => $tables,
                'how' => 'pg_database_size, pg_total_relation_size',
                'estimated' => true,
                'notes' => ['Row counts are PostgreSQL\'s estimates from the last ANALYZE or VACUUM. Data includes TOAST; partitioned tables count their partitions apart.'],
            ]);
        }
        $pageSize = (int) $pdo->query('PRAGMA page_size')->fetchColumn();
        $pages = (int) $pdo->query('PRAGMA page_count')->fetchColumn();
        $free = (int) $pdo->query('PRAGMA freelist_count')->fetchColumn();
        $count = (int) $pdo->query("SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite\\_%' ESCAPE '\\'")->fetchColumn();
        $views = (int) $pdo->query("SELECT COUNT(*) FROM sqlite_master WHERE type = 'view'")->fetchColumn();
        $result = [
            'databaseBytes' => $pageSize * $pages,
            'freeBytes' => $free > 0 ? $pageSize * $free : null,
            'tableCount' => $count,
            'viewCount' => $views > 0 ? $views : null,
            'tables' => [],
        ];
        try {
            $owners = [];
            foreach ($pdo->query("SELECT name, type, tbl_name FROM sqlite_master WHERE type IN ('table', 'index')")->fetchAll(\PDO::FETCH_NUM) as $object) {
                $owners[(string) $object[0]] = [(string) $object[1], (string) $object[2]];
            }
            $sizes = [];
            foreach ($pdo->query('SELECT name, SUM(pgsize) FROM dbstat GROUP BY name')->fetchAll(\PDO::FETCH_NUM) as $row) {
                $owner = $owners[(string) $row[0]] ?? null;
                if ($owner === null || strpos($owner[1], 'sqlite_') === 0) {
                    continue; // The schema table itself, or SQLite's own tables.
                }
                $table = $owner[1];
                $sizes[$table] = $sizes[$table] ?? ['name' => $table, 'dataBytes' => 0, 'indexBytes' => 0];
                $sizes[$table][$owner[0] === 'index' ? 'indexBytes' : 'dataBytes'] += (int) $row[1];
            }
            foreach ($sizes as $name => $size) {
                $sizes[$name]['totalBytes'] = $size['dataBytes'] + $size['indexBytes'];
            }
            usort($sizes, static function (array $a, array $b): int {
                return [$b['totalBytes'], $a['name']] <=> [$a['totalBytes'], $b['name']];
            });
            $result['tables'] = array_slice($sizes, 0, self::MAX_TABLES);
            $result['how'] = 'dbstat';
        } catch (\Throwable $error) {
            $result['how'] = 'page_count';
            $result['notes'] = ['Per-table sizes need SQLite\'s dbstat table, which this PHP\'s SQLite leaves out; the size is the whole file\'s.'];
        }

        return self::filtered($result);
    }

    /**
     * The server's sessions this user may see, and what it may not see or end.
     *
     * @return array<string, mixed>
     */
    private static function sessions(\PDO $pdo, string $dialect, int $own): array
    {
        if ($dialect === 'sqlite') {
            return ['list' => [], 'visibility' => 'none', 'notes' => ['SQLite has no server and no sessions: the database is a file the runner\'s PHP opens itself.']];
        }
        $budget = self::MAX_QUERIES_BYTES;
        $list = [];
        $notes = [];
        if ($dialect === 'mysql') {
            $current = self::currentUserName($pdo);
            $privileges = self::privileges($pdo);
            $statement = $pdo->query("SELECT ID, USER, HOST, DB, COMMAND, TIME, STATE, INFO FROM information_schema.PROCESSLIST ORDER BY COMMAND = 'Sleep', TIME DESC, ID LIMIT " . (self::MAX_SESSIONS + 1));
            $others = false;
            while (($row = $statement->fetch(\PDO::FETCH_NUM)) !== false) {
                $command = (string) $row[4];
                $others = $others || ($current !== null && (string) $row[1] !== $current);
                $list[] = self::filtered([
                    'id' => (int) $row[0],
                    'user' => $row[1] === null ? null : (string) $row[1],
                    'host' => $row[2] === null || (string) $row[2] === '' ? null : (string) $row[2],
                    'database' => $row[3] === null ? null : (string) $row[3],
                    'command' => $command,
                    'state' => $row[6] === null || (string) $row[6] === '' ? null : (string) $row[6],
                    'active' => !in_array($command, ['Sleep', 'Daemon', 'Binlog Dump', 'Killed'], true) ? true : null,
                    'seconds' => $row[5] === null ? null : (float) $row[5],
                    'own' => (int) $row[0] === $own ? true : null,
                ] + self::query($row[7], $budget));
            }
            $statement->closeCursor();
            self::lockWaits($pdo, $list);
            $process = $privileges === null ? null : in_array('PROCESS', $privileges, true);
            $all = $process === true || $others;
            $endOthers = $privileges === null ? null : count(array_intersect(['SUPER', 'CONNECTION ADMIN', 'CONNECTION_ADMIN'], $privileges)) > 0;
            if (!$all) {
                $connected = self::status($pdo, ['Threads_connected'], 'GLOBAL');
                $notes[] = 'You see only your own sessions: seeing every session needs the PROCESS privilege' . (isset($connected['Threads_connected']) ? ' (' . (int) $connected['Threads_connected'] . ' connected in all).' : '.');
            }
            if ($endOthers === false) {
                $notes[] = 'You can cancel and kill only your own sessions: other users\' need ' . (stripos((string) $pdo->getAttribute(\PDO::ATTR_SERVER_VERSION), 'mariadb') !== false ? 'CONNECTION ADMIN' : 'CONNECTION_ADMIN') . ' or SUPER.';
            }
            $visibility = $all ? 'all' : 'own';
        } else {
            $roles = $pdo->query("SELECT r.rolsuper, pg_has_role(current_user, 'pg_read_all_stats', 'MEMBER'), pg_has_role(current_user, 'pg_signal_backend', 'MEMBER') FROM pg_roles r WHERE r.rolname = current_user")->fetch(\PDO::FETCH_NUM);
            $super = is_array($roles) && self::truthy($roles[0]);
            $readAll = $super || (is_array($roles) && self::truthy($roles[1]));
            $signal = $super || (is_array($roles) && self::truthy($roles[2]));
            $statement = $pdo->query("SELECT pid, usename, host(client_addr), client_port, client_hostname, datname, application_name, state, EXTRACT(EPOCH FROM (now() - COALESCE(state_change, backend_start)))::float8, EXTRACT(EPOCH FROM (now() - xact_start))::float8, backend_start::text, query_start::text, wait_event_type, wait_event, pg_blocking_pids(pid), query FROM pg_stat_activity WHERE " . self::PG_CLIENTS . " ORDER BY state IS DISTINCT FROM 'active', state_change, pid LIMIT " . (self::MAX_SESSIONS + 1));
            $hidden = 0;
            while (($row = $statement->fetch(\PDO::FETCH_NUM)) !== false) {
                $state = $row[7] === null ? null : (string) $row[7];
                $query = $row[15];
                if ($query === '<insufficient privilege>') {
                    $query = null;
                    ++$hidden;
                }
                $host = $row[2] === null ? ($row[3] !== null && (int) $row[3] === -1 ? 'local socket' : null) : (string) $row[2] . ($row[3] === null ? '' : ':' . $row[3]);
                $list[] = self::filtered([
                    'id' => (int) $row[0],
                    'user' => $row[1] === null ? null : (string) $row[1],
                    'host' => $host,
                    'database' => $row[5] === null ? null : (string) $row[5],
                    'application' => $row[6] === null || (string) $row[6] === '' ? null : (string) $row[6],
                    'state' => $state,
                    'active' => $state === 'active' ? true : null,
                    'seconds' => $row[8] === null ? null : max(0.0, round((float) $row[8], 1)),
                    'transactionSeconds' => $row[9] === null ? null : max(0.0, round((float) $row[9], 1)),
                    'started' => $row[10] === null ? null : (string) $row[10],
                    'queryStarted' => $row[11] === null ? null : (string) $row[11],
                    'waiting' => $row[12] === null ? null : (string) $row[12] . ($row[13] === null ? '' : ': ' . $row[13]),
                    'blockedBy' => self::pids($row[14]),
                    'own' => (int) $row[0] === $own ? true : null,
                ] + self::query($query, $budget));
            }
            $statement->closeCursor();
            $background = (int) $pdo->query('SELECT COUNT(*) FROM pg_stat_activity WHERE NOT COALESCE(' . self::PG_CLIENTS . ', false)')->fetchColumn();
            if (!$readAll) {
                $notes[] = 'Other roles\' sessions show without their state and statement' . ($hidden > 0 ? ' (' . $hidden . ' here)' : '') . ': seeing them needs the pg_read_all_stats role.';
            }
            if (!$signal) {
                $notes[] = 'You can cancel and kill only your own role\'s sessions: other roles\' need the pg_signal_backend role (a superuser\'s need a superuser).';
            }
            if ($background > 0) {
                $notes[] = 'Not listed: ' . $background . ' background process' . ($background === 1 ? '' : 'es') . ' of the server (autovacuum, WAL writer, …).';
            }
            $visibility = $readAll ? 'all' : 'partial';
            $endOthers = $signal;
        }
        $truncated = count($list) > self::MAX_SESSIONS;
        if ($truncated) {
            $list = array_slice($list, 0, self::MAX_SESSIONS);
            $notes[] = 'Only the first ' . self::MAX_SESSIONS . ' sessions are listed (active ones first).';
        }

        return self::filtered([
            'list' => $list,
            'visibility' => $visibility,
            'endOthers' => $endOthers,
            'truncated' => $truncated ? true : null,
            'notes' => $notes === [] ? null : $notes,
        ]);
    }

    /**
     * MySQL and MariaDB: which sessions wait for a lock another session holds (InnoDB), as
     * `blockedBy` and `transactionSeconds`. Quietly nothing when the views aren't there or
     * readable (they need PROCESS; MySQL 8 moved lock waits to performance_schema).
     *
     * @param array<int, array<string, mixed>> $list
     */
    private static function lockWaits(\PDO $pdo, array &$list): void
    {
        if ($list === []) {
            return;
        }
        $index = [];
        foreach ($list as $position => $session) {
            $index[$session['id']] = $position;
        }
        try {
            foreach ($pdo->query('SELECT trx_mysql_thread_id, TIMESTAMPDIFF(SECOND, trx_started, NOW()) FROM information_schema.INNODB_TRX')->fetchAll(\PDO::FETCH_NUM) as $row) {
                if (isset($index[(int) $row[0]]) && $row[1] !== null) {
                    $list[$index[(int) $row[0]]]['transactionSeconds'] = (float) $row[1];
                }
            }
        } catch (\Throwable $error) {
            return;
        }
        $waits = [];
        foreach ([
            'SELECT r.trx_mysql_thread_id, b.trx_mysql_thread_id FROM information_schema.INNODB_LOCK_WAITS w JOIN information_schema.INNODB_TRX r ON r.trx_id = w.requesting_trx_id JOIN information_schema.INNODB_TRX b ON b.trx_id = w.blocking_trx_id',
            'SELECT r.trx_mysql_thread_id, b.trx_mysql_thread_id FROM performance_schema.data_lock_waits w JOIN information_schema.INNODB_TRX r ON r.trx_id = w.REQUESTING_ENGINE_TRANSACTION_ID JOIN information_schema.INNODB_TRX b ON b.trx_id = w.BLOCKING_ENGINE_TRANSACTION_ID',
        ] as $sql) {
            try {
                $waits = $pdo->query($sql)->fetchAll(\PDO::FETCH_NUM);
                break;
            } catch (\Throwable $error) {
                continue;
            }
        }
        foreach ($waits as $wait) {
            $position = $index[(int) $wait[0]] ?? null;
            if ($position !== null && !in_array((int) $wait[1], $list[$position]['blockedBy'] ?? [], true)) {
                $list[$position]['blockedBy'][] = (int) $wait[1];
            }
        }
    }

    /**
     * A session's statement, cut to MAX_QUERY_BYTES at a character boundary and within what is
     * left of the event's budget.
     *
     * @param mixed $query
     * @return array<string, mixed>
     */
    private static function query($query, int &$budget): array
    {
        if ($query === null) {
            return [];
        }
        $text = trim((string) $query);
        if ($text === '') {
            return [];
        }
        $limit = min(self::MAX_QUERY_BYTES, max(0, $budget));
        if (strlen($text) <= $limit) {
            $budget -= strlen($text);

            return ['query' => $text];
        }
        $cut = self::cut($text, $limit);
        $budget -= strlen($cut);

        return ['query' => $cut, 'queryBytes' => strlen($text)];
    }

    /** `$text` cut to at most `$bytes` bytes at a UTF-8 character boundary. */
    private static function cut(string $text, int $bytes): string
    {
        $cut = substr($text, 0, $bytes);
        while ($cut !== '' && preg_match('//u', $cut) !== 1) {
            $cut = substr($cut, 0, -1);
        }

        return $cut;
    }

    private static function bounded(string $text, int $bytes): string
    {
        return strlen($text) <= $bytes ? $text : self::cut($text, $bytes) . '…';
    }

    /**
     * What one session is now: its user, whether it runs a statement, its state, PostgreSQL's
     * backend start, and what tells its statement apart. Null when it isn't listed (gone, or
     * not visible to this user).
     *
     * @return array{user: string|null, running: bool|null, state: string|null, started: string|null, since: string|null, text: string|null}|null
     */
    private static function session(\PDO $pdo, string $dialect, int $session): ?array
    {
        try {
            if ($dialect === 'mysql') {
                $statement = $pdo->prepare('SELECT USER, COMMAND, TIME, STATE, INFO FROM information_schema.PROCESSLIST WHERE ID = ?');
                $statement->execute([$session]);
                $row = $statement->fetch(\PDO::FETCH_NUM);
                $statement->closeCursor();
                if (!is_array($row)) {
                    return null;
                }
                $command = (string) $row[1];

                return [
                    'user' => $row[0] === null ? null : (string) $row[0],
                    'running' => $command === 'Killed' ? false : $command !== 'Sleep',
                    'state' => trim($command . ($row[3] !== null && (string) $row[3] !== '' ? ', ' . $row[3] : '')),
                    'started' => null,
                    'since' => (string) $row[2],
                    'text' => $row[4] === null ? null : (string) $row[4],
                ];
            }
            $statement = $pdo->prepare('SELECT usename, state, backend_start::text, query_start::text FROM pg_stat_activity WHERE pid = ?');
            $statement->execute([$session]);
            $row = $statement->fetch(\PDO::FETCH_NUM);
            $statement->closeCursor();
            if (!is_array($row)) {
                return null;
            }
            $state = $row[1] === null ? null : (string) $row[1];

            return [
                'user' => $row[0] === null ? null : (string) $row[0],
                // Null for another role's session without pg_read_all_stats: its state isn't shown.
                'running' => $state === null ? null : $state === 'active',
                'state' => $state,
                'started' => $row[2] === null ? null : (string) $row[2],
                'since' => $row[3] === null ? null : (string) $row[3],
                'text' => null,
            ];
        } catch (\Throwable $error) {
            return null;
        }
    }

    /**
     * Whether `$now` still runs the statement `$before` saw.
     *
     * @param array<string, mixed> $before
     * @param array<string, mixed> $now
     */
    private static function sameStatement(array $before, array $now): bool
    {
        if ($before['text'] !== null || $now['text'] !== null) {
            return $before['text'] === $now['text'] && (int) $now['since'] >= (int) $before['since'];
        }

        return $before['since'] === $now['since'];
    }

    /**
     * Why the database refused the statement, as an outcome.
     *
     * @param callable(string, array<string, mixed>=): array<string, mixed> $done
     * @return array<string, mixed>
     */
    private static function refusal(callable $done, string $action, string $dialect, int $session, \PDOException $error): array
    {
        $code = is_array($error->errorInfo) ? ($error->errorInfo[1] ?? null) : null;
        $state = is_array($error->errorInfo) ? (string) ($error->errorInfo[0] ?? '') : (string) $error->getCode();
        $message = self::message($error);
        $verb = $action === 'kill' ? 'kill' : 'cancel the statement of';
        if ($dialect === 'mysql') {
            if ((int) $code === 1094) {
                return $done('alreadyEnded'); // Unknown thread id.
            }
            if ((int) $code === 1095) {
                return $done('refused', ['detail' => 'the database user may not ' . $verb . ' session ' . $session . ' (' . $message . '); other users\' sessions need the CONNECTION ADMIN (MariaDB), CONNECTION_ADMIN (MySQL), or SUPER privilege']);
            }
        } elseif ($state === '42501') {
            return $done('refused', ['detail' => 'the database user may not ' . $verb . ' session ' . $session . ' (' . $message . '); other roles\' sessions need membership in pg_signal_backend, and a superuser\'s need a superuser']);
        }

        return $done('failed', ['detail' => $message]);
    }

    /** The database's own words, without PDO's SQLSTATE prefix. */
    private static function message(\Throwable $error): string
    {
        if ($error instanceof \PDOException) {
            $info = $error->errorInfo;
            if (is_array($info) && isset($info[2]) && is_string($info[2]) && $info[2] !== '') {
                return trim(preg_replace('/^ERROR:\s+/', '', $info[2]) ?? $info[2]);
            }
        }

        return $error->getMessage();
    }

    /**
     * MySQL status variables by name (`SHOW GLOBAL|SESSION STATUS` needs no privilege).
     *
     * @param string[] $names
     * @return array<string, string>
     */
    private static function status(\PDO $pdo, array $names, string $scope): array
    {
        try {
            $quoted = implode(', ', array_map(static function (string $name): string {
                return "'" . $name . "'";
            }, $names));

            return array_map('strval', $pdo->query('SHOW ' . $scope . ' STATUS WHERE Variable_name IN (' . $quoted . ')')->fetchAll(\PDO::FETCH_KEY_PAIR));
        } catch (\Throwable $error) {
            return [];
        }
    }

    /**
     * MySQL: the current account's global privileges (information_schema.USER_PRIVILEGES lists
     * the user's own); null when Runlet can't tell. Roles' privileges may be missing.
     *
     * @return string[]|null
     */
    private static function privileges(\PDO $pdo): ?array
    {
        try {
            $account = (string) $pdo->query('SELECT CURRENT_USER()')->fetchColumn();
            $at = strrpos($account, '@');
            if ($at === false) {
                return null;
            }
            $grantee = "'" . substr($account, 0, $at) . "'@'" . substr($account, $at + 1) . "'";
            $statement = $pdo->prepare('SELECT PRIVILEGE_TYPE FROM information_schema.USER_PRIVILEGES WHERE GRANTEE = ?');
            $statement->execute([$grantee]);

            return array_map('strval', $statement->fetchAll(\PDO::FETCH_COLUMN));
        } catch (\Throwable $error) {
            return null;
        }
    }

    /** MySQL: the user name the server lists this user's threads under. */
    private static function currentUserName(\PDO $pdo): ?string
    {
        try {
            $user = $pdo->query("SELECT SUBSTRING_INDEX(USER(), '@', 1)")->fetchColumn();

            return $user === false || $user === null ? null : (string) $user;
        } catch (\Throwable $error) {
            return null;
        }
    }

    /**
     * PostgreSQL's int[] as text ("{12,34}") or an array, as ints; null when empty.
     *
     * @param mixed $value
     * @return int[]|null
     */
    private static function pids($value): ?array
    {
        if (is_array($value)) {
            $items = $value;
        } else {
            $text = trim((string) $value, '{} ');
            $items = $text === '' ? [] : explode(',', $text);
        }
        $pids = array_values(array_filter(array_map('intval', $items), static function (int $pid): bool {
            return $pid > 0;
        }));

        return $pids === [] ? null : $pids;
    }

    /** "11.4.2" from "11.4.2-MariaDB-ubu2404", "5.5.5-10.6.12-MariaDB", or "14.23 (Debian …)". */
    private static function number(string $version): string
    {
        $version = preg_replace('/^5\.5\.5-/', '', $version) ?? $version;

        return preg_match('/^\d+(\.\d+)*/', $version, $match) === 1 ? $match[0] : self::bounded($version, 60);
    }

    /** @param mixed $value */
    private static function truthy($value): bool
    {
        return in_array($value, [true, 1, '1', 't', 'true', 'on'], true);
    }

    /**
     * @param array<string, mixed> $fields
     * @return array<string, mixed>
     */
    private static function filtered(array $fields): array
    {
        return array_filter($fields, static function ($value): bool {
            return $value !== null;
        });
    }
}
}

/*
 * Redis tabs (#190): runs a Redis tab's commands and reports each reply as a `redis` event;
 * the key browser (SCAN pages, a key's value and memory) and the server panel (INFO, CLIENT
 * LIST, CLIENT KILL). The app generates the snippet that calls RedisTab (RedisTabRun in
 * RunletCore): each command's arguments are PHP string literals, never credentials.
 *
 * Where the connection comes from:
 *  0. a saved Redis connection (#138's `sqlConnection` with driver `redis`): Runner::main()
 *     hands it to RedisConnect::configure() and drops it from the request; the run boots no
 *     project code. Runlet's own RESP client (RedisClient) opens it with stream_socket_client
 *     (tcp://, tls://, unix://), sends AUTH (password or ACL user) and SELECT, and speaks
 *     RESP2 (it reads RESP3 types too, for HELLO 3). No PHP extension is needed, so it works on
 *     every target and from this Mac;
 *  1. the booted driver's redisConnection(): a project driver's own, or Laravel's
 *     Redis::connection($name) (phpredis through rawCommand(), Predis through executeRaw()).
 *     The application's own connections need no credentials from Runlet;
 *  2. otherwise a RedisUnavailable error that says so.
 *
 * Safety: streaming commands (SUBSCRIBE, MONITOR, …) are refused. A read-only saved
 * connection refuses every command that isn't a read (RedisCommands, the app's table again)
 * and asks the server's COMMAND INFO too, before anything is sent. Passwords: the saved
 * connection's is never a function argument and is forgotten once the connection is open;
 * typed AUTH passwords are echoed as ••• and scrubbed from every event (Channel::addSecret).
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

/** The project has no Redis connection Redis tabs can use. */
final class RedisUnavailable extends \RuntimeException
{
}

/** The connection could not be opened or broke (a refused AUTH, a closed socket, …). */
final class RedisConnectionFailed extends \RuntimeException
{
}

/** Runlet refused to send a command (read-only, streaming). Nothing was sent. */
final class RedisRefused extends \RuntimeException
{
}

/** A command got an error reply; Run All stops there. */
final class RedisCommandFailed extends \RuntimeException
{
}

/**
 * Which commands read (#190): the same lists as RedisCommands.swift (RedisCommandTableTests
 * compares them). Anything that isn't a read, connection state, or transaction control may
 * write, and a read-only connection refuses it.
 */
final class RedisCommands
{
    public const CONTAINERS = ['ACL', 'CLIENT', 'CLUSTER', 'COMMAND', 'CONFIG', 'FUNCTION', 'LATENCY', 'MEMORY', 'MODULE', 'OBJECT', 'PUBSUB', 'SCRIPT', 'SLOWLOG', 'XGROUP', 'XINFO'];

    public const READS = [
        'GET', 'MGET', 'GETRANGE', 'SUBSTR', 'STRLEN', 'EXISTS', 'TYPE', 'TTL', 'PTTL', 'EXPIRETIME', 'PEXPIRETIME', 'DBSIZE',
        'RANDOMKEY', 'SCAN', 'KEYS', 'DUMP', 'TOUCH', 'LCS', 'SORT_RO', 'GETBIT', 'BITCOUNT', 'BITPOS', 'BITFIELD_RO',
        'OBJECT|ENCODING', 'OBJECT|FREQ', 'OBJECT|IDLETIME', 'OBJECT|REFCOUNT', 'OBJECT|HELP',
        'HGET', 'HMGET', 'HGETALL', 'HKEYS', 'HVALS', 'HLEN', 'HEXISTS', 'HSTRLEN', 'HSCAN', 'HRANDFIELD',
        'HTTL', 'HPTTL', 'HEXPIRETIME', 'HPEXPIRETIME',
        'LINDEX', 'LLEN', 'LRANGE', 'LPOS',
        'SCARD', 'SISMEMBER', 'SMISMEMBER', 'SMEMBERS', 'SRANDMEMBER', 'SSCAN', 'SINTER', 'SINTERCARD', 'SUNION', 'SDIFF',
        'ZCARD', 'ZCOUNT', 'ZLEXCOUNT', 'ZRANGE', 'ZRANGEBYSCORE', 'ZRANGEBYLEX', 'ZREVRANGE', 'ZREVRANGEBYSCORE',
        'ZREVRANGEBYLEX', 'ZRANK', 'ZREVRANK', 'ZSCORE', 'ZMSCORE', 'ZSCAN', 'ZRANDMEMBER', 'ZINTER', 'ZINTERCARD', 'ZUNION', 'ZDIFF',
        'XRANGE', 'XREVRANGE', 'XLEN', 'XREAD', 'XPENDING', 'XINFO|STREAM', 'XINFO|GROUPS', 'XINFO|CONSUMERS', 'XINFO|HELP',
        'XGROUP|HELP',
        'GEOPOS', 'GEODIST', 'GEOHASH', 'GEORADIUS_RO', 'GEORADIUSBYMEMBER_RO', 'GEOSEARCH', 'PFCOUNT',
        'EVAL_RO', 'EVALSHA_RO', 'FCALL_RO', 'SCRIPT|EXISTS', 'SCRIPT|HELP', 'FUNCTION|LIST', 'FUNCTION|DUMP', 'FUNCTION|STATS',
        'FUNCTION|HELP',
        'INFO', 'TIME', 'LASTSAVE', 'ROLE', 'LOLWUT', 'MEMORY|USAGE', 'MEMORY|STATS', 'MEMORY|DOCTOR', 'MEMORY|MALLOC-STATS',
        'MEMORY|HELP', 'LATENCY|LATEST', 'LATENCY|HISTORY', 'LATENCY|DOCTOR', 'LATENCY|GRAPH', 'LATENCY|HISTOGRAM',
        'LATENCY|HELP', 'SLOWLOG|GET', 'SLOWLOG|LEN', 'SLOWLOG|HELP', 'CONFIG|GET', 'CONFIG|HELP', 'CLIENT|LIST',
        'CLIENT|INFO', 'CLIENT|ID', 'CLIENT|GETNAME', 'CLIENT|GETREDIR', 'CLIENT|TRACKINGINFO', 'CLIENT|HELP', 'COMMAND',
        'COMMAND|COUNT', 'COMMAND|DOCS', 'COMMAND|GETKEYS', 'COMMAND|GETKEYSANDFLAGS', 'COMMAND|INFO', 'COMMAND|LIST',
        'COMMAND|HELP', 'MODULE|LIST', 'MODULE|HELP', 'ACL|WHOAMI', 'ACL|LIST', 'ACL|USERS', 'ACL|GETUSER', 'ACL|CAT',
        'ACL|LOG', 'ACL|GENPASS', 'ACL|DRYRUN', 'ACL|HELP', 'PUBSUB|CHANNELS', 'PUBSUB|NUMSUB', 'PUBSUB|NUMPAT',
        'PUBSUB|SHARDCHANNELS', 'PUBSUB|SHARDNUMSUB', 'PUBSUB|HELP', 'CLUSTER|INFO', 'CLUSTER|NODES', 'CLUSTER|SLOTS',
        'CLUSTER|SHARDS', 'CLUSTER|MYID', 'CLUSTER|MYSHARDID', 'CLUSTER|KEYSLOT', 'CLUSTER|COUNTKEYSINSLOT',
        'CLUSTER|GETKEYSINSLOT', 'CLUSTER|LINKS', 'CLUSTER|HELP',
    ];

    public const CONNECTION = [
        'AUTH', 'HELLO', 'PING', 'ECHO', 'SELECT', 'QUIT', 'RESET', 'READONLY', 'READWRITE', 'ASKING', 'WAIT', 'WAITAOF',
        'CLIENT|SETNAME', 'CLIENT|SETINFO', 'CLIENT|TRACKING', 'CLIENT|CACHING', 'CLIENT|NO-EVICT', 'CLIENT|NO-TOUCH',
    ];

    public const TRANSACTION = ['MULTI', 'EXEC', 'DISCARD', 'WATCH', 'UNWATCH'];

    public const STREAMING = [
        'SUBSCRIBE', 'PSUBSCRIBE', 'SSUBSCRIBE', 'UNSUBSCRIBE', 'PUNSUBSCRIBE', 'SUNSUBSCRIBE', 'MONITOR', 'SYNC', 'PSYNC',
        'REPLCONF', 'CLIENT|REPLY',
    ];

    /** @param string[] $argv */
    public static function key(array $argv): string
    {
        $first = strtoupper((string) ($argv[0] ?? ''));
        if (in_array($first, self::CONTAINERS, true) && count($argv) > 1) {
            return $first . '|' . strtoupper((string) $argv[1]);
        }

        return $first;
    }

    /** "CONFIG GET" */
    public static function name(array $argv): string
    {
        return str_replace('|', ' ', self::key($argv));
    }

    /**
     * Why a read-only connection refuses `$argv` ("can change data or the server (SET)"), or null.
     *
     * @param string[] $argv
     */
    public static function readOnlyRefusal(array $argv): ?string
    {
        $key = self::key($argv);
        $name = self::name($argv);
        if (in_array($key, self::STREAMING, true)) {
            return 'streams replies (' . $name . '), which Redis tabs don\'t read yet';
        }
        if ($key === 'ACL|LOG' && in_array('RESET', array_map('strtoupper', array_slice($argv, 2)), true)) {
            return 'can change data or the server (ACL LOG RESET)';
        }
        if (in_array($key, self::READS, true) || in_array($key, self::CONNECTION, true) || in_array($key, self::TRANSACTION, true)) {
            return null;
        }
        $known = in_array(strtoupper((string) ($argv[0] ?? '')), self::CONTAINERS, true) || self::isWrite($key);

        return $known ? 'can change data or the server (' . $name . ')' : 'is a command Runlet doesn\'t know (' . $name . '), so it can\'t tell whether it writes';
    }

    /** Whether the key names a command Runlet knows writes (the rest of the table is the app's). */
    private static function isWrite(string $key): bool
    {
        return preg_match('/^(SET|MSET|GETSET|GETDEL|GETEX|APPEND|INCR|DECR|DEL|UNLINK|EXPIRE|PEXPIRE|PERSIST|RENAME|MOVE|COPY|RESTORE|SORT|BIT|H(SET|MSET|DEL|INCR|EXPIRE|PEXPIRE|PERSIST)|[LR]PUSH|[LR]POP|LINSERT|LSET|LREM|LTRIM|LMOVE|LMPOP|B[LRZ]|S(ADD|REM|POP|MOVE)|S(INTER|UNION|DIFF)STORE|Z(ADD|INCRBY|REM|POP|MPOP|RANGESTORE|INTERSTORE|UNIONSTORE|DIFFSTORE)|X(ADD|DEL|TRIM|ACK|CLAIM|AUTOCLAIM|SETID|READGROUP|GROUP)|GEO(ADD|RADIUS|SEARCHSTORE)|PF(ADD|MERGE|DEBUG|SELFTEST)|EVAL|FCALL|PUBLISH|SPUBLISH|FLUSH|SWAPDB|SHUTDOWN|DEBUG|MIGRATE|REPLICAOF|SLAVEOF|SAVE|BGSAVE|BGREWRITEAOF|FAILOVER)/', $key) === 1;
    }

    /** Why a Redis tab never sends `$argv` on any connection, or null. */
    public static function refusal(array $argv): ?string
    {
        $key = self::key($argv);
        if (!in_array($key, self::STREAMING, true)) {
            return null;
        }
        $name = self::name($argv);
        if ($key === 'CLIENT|REPLY') {
            return 'CLIENT REPLY turns replies off, and Runlet reads one reply per command. Nothing ran.';
        }

        return $name . ' streams messages until the connection closes, and Redis tabs read one reply per command (streaming is a later feature). Use redis-cli for ' . $name . '. Nothing ran.';
    }
}

/**
 * Builds reply trees with Runlet's caps: strings are shortened (a top-level string to 512 KiB,
 * others to 8 KiB), aggregates keep `$cap` elements and count the rest, and the whole reply
 * keeps at most 8 MiB of strings. Shared by the RESP client and the application adapters.
 */
final class RedisReplyBudget
{
    public const TOP_STRING_BYTES = 524288;
    public const STRING_BYTES = 8192;
    public const TOTAL_BYTES = 8388608;

    /** @var int */
    public $left = self::TOTAL_BYTES;
    /** @var int */
    public $used = 0;

    /**
     * A string node: UTF-8 text (shortened, with `o` the bytes left out), or binary (`x`).
     *
     * @return array<string, mixed>
     */
    public function text(string $kept, int $total, bool $top): array
    {
        $limit = min($top ? self::TOP_STRING_BYTES : self::STRING_BYTES, max(0, $this->left));
        if (strlen($kept) > $limit) {
            $kept = substr($kept, 0, $limit);
        }
        if (preg_match('//u', $kept) !== 1) {
            // A cut in the middle of a character, or bytes that aren't UTF-8.
            $trimmed = $kept;
            for ($i = 0; $i < 3 && $trimmed !== '' && preg_match('//u', $trimmed) !== 1; $i++) {
                $trimmed = substr($trimmed, 0, -1);
            }
            if (preg_match('//u', $trimmed) !== 1 || ($trimmed === '' && $kept !== '')) {
                $this->spend(80);

                return ['t' => 'x', 'n' => $total, 'h' => strtoupper(bin2hex(substr($kept, 0, 32)))];
            }
            $kept = $trimmed;
        }
        $this->spend(strlen($kept));

        return $total > strlen($kept) ? ['t' => 's', 'v' => $kept, 'o' => $total - strlen($kept)] : ['t' => 's', 'v' => $kept];
    }

    public function spend(int $bytes): void
    {
        $this->left -= $bytes;
        $this->used += $bytes;
    }

    public function exhausted(): bool
    {
        return $this->left <= 0;
    }
}

/**
 * Runlet's RESP client (#190): one connection, commands sent as RESP arrays, replies read
 * with caps. It reads RESP2 and RESP3 types. Blocking commands wait until they're answered;
 * Stop ends the process, which closes the socket, and Redis unblocks the client.
 */
final class RedisClient
{
    /** @var resource */
    private $stream;
    /** @var string */
    private $buffer = '';

    /** @param resource $stream */
    public function __construct($stream)
    {
        $this->stream = $stream;
    }

    /** @return resource */
    public function stream()
    {
        return $this->stream;
    }

    /**
     * Sends `$argv` and reads its reply.
     *
     * @param string[] $argv
     * @return array<string, mixed>
     */
    public function command(array $argv, int $cap = 1000, ?RedisReplyBudget $budget = null): array
    {
        $this->send($argv);

        return $this->read($cap, $budget ?? new RedisReplyBudget());
    }

    /** @param string[] $argv */
    public function send(array $argv): void
    {
        $out = '*' . count($argv) . "\r\n";
        foreach ($argv as $argument) {
            $argument = (string) $argument;
            $out .= '$' . strlen($argument) . "\r\n" . $argument . "\r\n";
        }
        $length = strlen($out);
        $written = 0;
        while ($written < $length) {
            $result = @fwrite($this->stream, substr($out, $written, 65536));
            if ($result === false || $result === 0) {
                throw new RedisConnectionFailed('Runlet could not send the command: the connection to Redis closed.');
            }
            $written += $result;
        }
    }

    /**
     * Reads one reply.
     *
     * @return array<string, mixed>
     */
    public function read(int $cap, RedisReplyBudget $budget, int $depth = 0): array
    {
        $line = $this->line();
        $type = $line === '' ? '' : $line[0];
        $rest = (string) substr($line, 1);
        switch ($type) {
            case '+':
                return ['t' => '+', 'v' => $this->scrubbed($rest)];
            case '-':
                return ['t' => '-', 'v' => $this->scrubbed($rest)];
            case ':':
                return ['t' => 'i', 'v' => (int) $rest];
            case ',':
                return ['t' => 'd', 'v' => $rest];
            case '#':
                return ['t' => 'b', 'v' => $rest === 't'];
            case '_':
                return ['t' => 'n'];
            case '(':
                return ['t' => 's', 'v' => $rest];
            case '$':
            case '=':
            case '!':
                $length = (int) $rest;
                if ($length < 0) {
                    return ['t' => 'n'];
                }
                $keep = $depth === 0 ? RedisReplyBudget::TOP_STRING_BYTES : RedisReplyBudget::STRING_BYTES;
                $kept = $this->bulk($length, min($keep, max(0, $budget->left)));
                if ($type === '!') {
                    return ['t' => '-', 'v' => $this->scrubbed($kept)];
                }
                if ($type === '=' && strlen($kept) >= 4 && $kept[3] === ':') {
                    // A verbatim string: "txt:" or "mkd:" first.
                    $kept = substr($kept, 4);
                    $length -= 4;
                }

                return $budget->text($kept, $length, $depth === 0);
            case '*':
            case '~':
            case '>':
            case '%':
            case '|':
                $count = (int) $rest;
                if ($count < 0) {
                    return ['t' => 'n'];
                }
                if ($type === '|') {
                    // RESP3 attributes come before the reply they describe: skipped.
                    for ($i = 0; $i < $count * 2; $i++) {
                        $this->skip();
                    }

                    return $this->read($cap, $budget, $depth);
                }
                $pairs = $type === '%';
                $elements = $pairs ? $count * 2 : $count;
                $items = [];
                $omitted = 0;
                $keep = $pairs ? max(2, $cap - $cap % 2) : $cap;
                for ($i = 0; $i < $elements; $i++) {
                    if ($i >= $keep || $budget->exhausted()) {
                        $this->skip();
                        $omitted++;
                        continue;
                    }
                    $items[] = $this->read($cap, $budget, $depth + 1);
                }
                if ($pairs) {
                    $grouped = [];
                    for ($i = 0; $i + 1 < count($items); $i += 2) {
                        $grouped[] = [$items[$i], $items[$i + 1]];
                    }
                    $node = ['t' => '%', 'v' => $grouped];
                    if ($omitted > 0) {
                        $node['o'] = intdiv($omitted + 1, 2);
                    }

                    return $node;
                }
                $node = ['t' => $type === '~' ? '~' : '*', 'v' => $items];
                if ($omitted > 0) {
                    $node['o'] = $omitted;
                }

                return $node;
            default:
                throw new RedisConnectionFailed('Runlet could not read the reply (it starts with ' . json_encode(substr($line, 0, 20)) . '). Is this a Redis server?');
        }
    }

    /** Reads and drops one reply (an element past the cap). */
    private function skip(): void
    {
        $line = $this->line();
        $type = $line === '' ? '' : $line[0];
        $count = (int) substr($line, 1);
        switch ($type) {
            case '$':
            case '=':
            case '!':
                if ($count >= 0) {
                    $this->bulk($count, 0);
                }

                return;
            case '*':
            case '~':
            case '>':
            case '%':
            case '|':
                $elements = $type === '%' || $type === '|' ? $count * 2 : $count;
                for ($i = 0; $i < $elements; $i++) {
                    $this->skip();
                }
                if ($type === '|') {
                    $this->skip();
                }

                return;
            default:
                return;
        }
    }

    /** A status or error line, without the saved connection's password. */
    private function scrubbed(string $text): string
    {
        return Channel::scrub($text);
    }

    /** One line, without its CRLF. */
    private function line(): string
    {
        while (($end = strpos($this->buffer, "\r\n")) === false) {
            $this->fill();
        }
        $line = substr($this->buffer, 0, $end);
        $this->buffer = (string) substr($this->buffer, $end + 2);

        return $line;
    }

    /** A bulk string of `$length` bytes and its CRLF: the first `$keep` bytes, the rest dropped. */
    private function bulk(int $length, int $keep): string
    {
        $needed = $length + 2;
        $kept = '';
        while ($needed > 0) {
            if ($this->buffer === '') {
                $this->fill();
            }
            $take = min($needed, strlen($this->buffer));
            $chunk = substr($this->buffer, 0, $take);
            $this->buffer = (string) substr($this->buffer, $take);
            $room = $keep - strlen($kept);
            if ($room > 0) {
                $kept .= substr($chunk, 0, $room);
            }
            $needed -= $take;
        }
        // The CRLF may have been kept with the bytes.
        return strlen($kept) > $length ? substr($kept, 0, $length) : $kept;
    }

    private function fill(): void
    {
        $chunk = @fread($this->stream, 65536);
        if ($chunk === false || $chunk === '') {
            $meta = @stream_get_meta_data($this->stream);
            if (is_array($meta) && !empty($meta['timed_out'])) {
                throw new RedisConnectionFailed('Redis didn\'t answer in time.');
            }
            if (!is_resource($this->stream) || feof($this->stream)) {
                throw new RedisConnectionFailed('The connection to Redis closed before the reply was complete.');
            }
            if ($chunk === false) {
                throw new RedisConnectionFailed('Runlet could not read from the connection to Redis.');
            }

            return;
        }
        $this->buffer .= $chunk;
    }

    public function close(): void
    {
        if (is_resource($this->stream)) {
            @fclose($this->stream);
        }
    }
}

/**
 * A saved Redis connection (#190): its definition from the runner request (the password is
 * forgotten once the connection is open), and opening it with RedisClient.
 */
final class RedisConnect
{
    private const TLS_MODES = ['', 'disable', 'require', 'verify-full'];

    /** @var array<string, mixed>|null */
    private static $definition;
    /** @var string|null */
    private static $password;
    /** @var RedisClient|null */
    private static $client;
    /** @var float|null */
    private static $connectMs;
    /** @var array<string, mixed> */
    private static $crypto = [];

    /** @param array<string, mixed> $connection */
    public static function configure(array $connection): void
    {
        $password = isset($connection['password']) && is_string($connection['password']) ? $connection['password'] : null;
        unset($connection['password']);
        $tls = is_array($connection['tls'] ?? null) ? $connection['tls'] : [];
        $tunnel = is_array($connection['tunnel'] ?? null) ? $connection['tunnel'] : [];
        self::$definition = [
            'id' => (string) ($connection['id'] ?? ''),
            'name' => (string) ($connection['name'] ?? ''),
            'host' => (string) ($connection['host'] ?? ''),
            'port' => isset($connection['port']) ? (int) $connection['port'] : 6379,
            'database' => (string) ($connection['database'] ?? ''),
            'user' => (string) ($connection['user'] ?? ''),
            'timeout' => max(1, min(300, (int) ($connection['timeout'] ?? 10))),
            'summary' => (string) ($connection['summary'] ?? ''),
            'readOnly' => ($connection['readOnly'] ?? false) === true,
            'socket' => (string) ($connection['socket'] ?? ''),
            'tls' => [
                'mode' => (string) ($tls['mode'] ?? ''),
                'ca' => (string) ($tls['ca'] ?? ''),
                'cert' => (string) ($tls['cert'] ?? ''),
                'key' => (string) ($tls['key'] ?? ''),
            ],
            'place' => ($connection['place'] ?? '') === 'mac' ? 'mac' : 'target',
            'tunnel' => [
                'port' => max(0, min(65535, (int) ($tunnel['port'] ?? 0))),
                'via' => (string) ($tunnel['via'] ?? ''),
            ],
        ];
        self::$password = $password;
        if ($password !== null && $password !== '') {
            Channel::addSecret($password);
        }
    }

    public static function isConfigured(): bool
    {
        return self::$definition !== null;
    }

    public static function name(): string
    {
        return (string) (self::$definition['name'] ?? '');
    }

    public static function isReadOnly(): bool
    {
        return (self::$definition['readOnly'] ?? false) === true;
    }

    /** The database the connection selects (0 when it names none). */
    public static function database(): int
    {
        return (int) (self::$definition['database'] ?? 0);
    }

    /** `saved connection "Cache" (redis, 127.0.0.1:6379/0)`, read-only noted. */
    public static function origin(): string
    {
        $summary = (string) (self::$definition['summary'] ?? '');

        return 'saved connection "' . self::name() . '"' . ($summary === '' ? '' : ' (' . $summary . ')') . (self::isReadOnly() ? ', read-only' : '');
    }

    private static function here(): string
    {
        return (self::$definition['place'] ?? '') === 'mac' ? 'this Mac' : 'this target';
    }

    /** The open connection; opens it on first use. */
    public static function client(): RedisClient
    {
        if (self::$client === null) {
            $started = hrtime(true);
            try {
                self::$client = self::connect();
            } finally {
                self::$password = null;
            }
            self::$connectMs = round((hrtime(true) - $started) / 1e6, 3);
        }

        return self::$client;
    }

    /**
     * Opens the connection: the address and stream context, AUTH, SELECT. Takes no arguments,
     * so the password is never in a stack frame; errors carry their message only.
     */
    private static function connect(): RedisClient
    {
        $definition = self::$definition;
        if ($definition === null) {
            throw new RedisConnectionFailed('No saved connection was sent with this run.');
        }
        $name = '"' . $definition['name'] . '"';
        $where = $name . ' (' . $definition['summary'] . ')';
        $tls = $definition['tls'];
        if (!in_array($tls['mode'], self::TLS_MODES, true)) {
            throw new RedisConnectionFailed('The saved connection ' . $name . ' asks for the TLS mode "' . $tls['mode'] . '", which Runlet\'s Redis client can\'t express. Choose Off, Require, or Verify CA and host name.');
        }
        $secure = $tls['mode'] === 'require' || $tls['mode'] === 'verify-full';
        $host = (string) $definition['host'];
        $socket = (string) $definition['socket'];
        $tunnel = (int) $definition['tunnel']['port'];
        if ($socket !== '') {
            if ($socket[0] !== '/' || preg_match('/[\x00-\x1f]/', $socket) === 1) {
                throw new RedisConnectionFailed('The socket "' . $socket . '" must be an absolute path.');
            }
            if ($tunnel > 0) {
                throw new RedisConnectionFailed('The saved connection ' . $name . ' goes through an SSH tunnel, which forwards a host and port, not a Unix socket. Nothing ran.');
            }
            $address = 'unix://' . $socket;
        } else {
            if ($host === '' || preg_match('/^[A-Za-z0-9._:%\[\]-]+$/', $host) !== 1 || $host[0] === '-') {
                throw new RedisConnectionFailed('The saved connection\'s host "' . $host . '" isn\'t a host name or IP address.');
            }
            $connectHost = $tunnel > 0 ? '127.0.0.1' : (strpos($host, ':') !== false && $host[0] !== '[' ? '[' . $host . ']' : $host);
            $port = $tunnel > 0 ? $tunnel : (int) $definition['port'];
            $address = ($secure ? 'tls://' : 'tcp://') . $connectHost . ':' . $port;
        }
        $ssl = [];
        if ($secure) {
            $verify = $tls['mode'] === 'verify-full';
            $ssl = [
                'verify_peer' => $verify,
                'verify_peer_name' => $verify,
                'allow_self_signed' => false,
                'SNI_enabled' => true,
                // #143: through a tunnel, the certificate still names the server.
                'peer_name' => trim($host, '[]'),
                'capture_session_meta' => true,
            ];
            foreach (['ca' => 'cafile', 'cert' => 'local_cert', 'key' => 'local_pk'] as $field => $option) {
                if ($tls[$field] !== '') {
                    $path = $tls[$field];
                    if ($path[0] !== '/' || !is_readable($path)) {
                        throw new RedisConnectionFailed('The TLS file ' . $path . ' doesn\'t exist on ' . self::here() . ', or its PHP can\'t read it. Nothing ran.');
                    }
                    $ssl[$option] = $path;
                }
            }
            if ($socket !== '') {
                throw new RedisConnectionFailed('Runlet\'s Redis client connects to a Unix socket without TLS. Turn TLS off for a socket connection.');
            }
            if (!extension_loaded('openssl')) {
                throw new RedisConnectionFailed((self::here() === 'this Mac' ? 'This Mac\'s PHP ' : 'This target\'s PHP ') . PHP_VERSION . ' has no openssl extension, so it can\'t open a TLS connection.');
            }
        }
        $context = stream_context_create(['ssl' => $ssl, 'socket' => ['tcp_nodelay' => true]]);
        $warnings = [];
        set_error_handler(static function (int $severity, string $message) use (&$warnings): bool {
            $warnings[] = $message;

            return true;
        });
        $errno = 0;
        $errstr = '';
        try {
            $stream = stream_socket_client($address, $errno, $errstr, (float) $definition['timeout'], STREAM_CLIENT_CONNECT, $context);
        } finally {
            restore_error_handler();
        }
        if ($stream === false) {
            $hint = $tunnel > 0
                ? ' The SSH server of "' . $definition['tunnel']['via'] . '" connects to Redis for the tunnel, so the host and port are as that server sees them; check it can reach them.'
                : '';
            $detail = trim($errstr . ($warnings === [] ? '' : ' ' . implode(' ', array_unique($warnings))));
            throw new RedisConnectionFailed(Channel::scrub('Runlet could not open the saved connection ' . $where . ': ' . ($detail === '' ? 'error ' . $errno : $detail) . $hint));
        }
        stream_set_timeout($stream, 31536000);
        if ($secure) {
            $meta = stream_get_meta_data($stream);
            self::$crypto = is_array($meta['crypto'] ?? null) ? $meta['crypto'] : ['protocol' => 'TLS'];
        }
        $client = new RedisClient($stream);
        $password = self::$password;
        $user = (string) $definition['user'];
        if (($password !== null && $password !== '') || $user !== '') {
            $reply = $client->command($user !== '' ? ['AUTH', $user, (string) $password] : ['AUTH', (string) $password]);
            $password = null;
            if (($reply['t'] ?? '') === '-') {
                $client->close();
                throw new RedisConnectionFailed(Channel::scrub('Redis refused the login of the saved connection ' . $where . ': ' . (string) $reply['v']));
            }
        }
        $password = null;
        $database = self::database();
        if ($database !== 0) {
            $reply = $client->command(['SELECT', (string) $database]);
            if (($reply['t'] ?? '') === '-') {
                $client->close();
                throw new RedisConnectionFailed('Redis refused SELECT ' . $database . ' on the saved connection ' . $where . ': ' . (string) $reply['v']);
            }
        }

        return $client;
    }

    /**
     * Test Connection: PING, the server's version, the database, the ACL user, and TLS.
     *
     * @return array<string, mixed>
     */
    public static function test(): array
    {
        $client = self::client();
        $started = hrtime(true);
        $client->command(['PING']);
        $roundTrip = round((hrtime(true) - $started) / 1e6, 3);
        $version = null;
        $info = $client->command(['INFO', 'server']);
        if (($info['t'] ?? '') === 's' && preg_match('/^redis_version:(\S+)/m', (string) $info['v'], $match) === 1) {
            $version = $match[1];
        }
        $user = $client->command(['ACL', 'WHOAMI']);
        $tls = (self::$definition['tls']['mode'] ?? '') === 'require' || (self::$definition['tls']['mode'] ?? '') === 'verify-full';

        return array_filter([
            'driver' => 'redis',
            'serverVersion' => $version,
            'database' => (string) self::database(),
            // ACL WHOAMI needs a permission an ACL user may lack: the configured user then.
            'user' => ($user['t'] ?? '') === 's' ? (string) $user['v'] : ((string) (self::$definition['user'] ?? '') !== '' ? (string) self::$definition['user'] : null),
            'connectMs' => self::$connectMs,
            'roundTripMs' => $roundTrip,
            'phpVersion' => PHP_VERSION,
            'readOnly' => self::isReadOnly() ? true : null,
            'tls' => $tls,
            'tlsVersion' => $tls ? (string) (self::$crypto['protocol'] ?? 'TLS') : null,
            'tlsCipher' => $tls && isset(self::$crypto['cipher_name']) ? (string) self::$crypto['cipher_name'] : null,
        ], static function ($value): bool {
            return $value !== null;
        });
    }
}

/**
 * An application's Redis connection (#190), wrapped as `function (array $argv, int $cap,
 * RedisReplyBudget $budget): array` returning a reply tree: phpredis through rawCommand()
 * (status replies kept as text, errors from getLastError()), Predis through executeRaw(), a
 * Laravel connection through its client(), or a driver's own callable.
 */
final class RedisAppConnection
{
    /**
     * @param mixed $value
     */
    public static function executor($value, string $origin): callable
    {
        if (is_object($value) && is_a($value, 'Illuminate\Redis\Connections\Connection') && method_exists($value, 'client')) {
            $client = $value->client();
            if (is_object($client) && (is_a($client, 'Redis') || is_a($client, 'Predis\ClientInterface') || is_a($client, 'RedisCluster') || is_a($client, 'Predis\Client'))) {
                return self::executor($client, $origin);
            }
            throw new RedisConnectionFailed($origin . ' returned a ' . get_class($value) . ' whose client() is ' . (is_object($client) ? get_class($client) : gettype($client)) . ', which Runlet can\'t send raw commands through.');
        }
        if (is_object($value) && is_a($value, 'RedisCluster')) {
            throw new RedisUnavailable('This is a Redis Cluster connection (' . $origin . '). Redis tabs don\'t support Cluster yet: save a connection to one node, or use a non-cluster connection.');
        }
        if (is_object($value) && is_a($value, 'Redis')) {
            return static function (array $argv, int $cap, RedisReplyBudget $budget) use ($value): array {
                return self::phpredis($value, $argv, $cap, $budget);
            };
        }
        if (is_object($value) && (is_a($value, 'Predis\ClientInterface') || method_exists($value, 'executeRaw'))) {
            return static function (array $argv, int $cap, RedisReplyBudget $budget) use ($value): array {
                $error = false;
                $reply = $value->executeRaw(array_values($argv), $error);
                if ($error === true) {
                    return ['t' => '-', 'v' => Channel::scrub(is_object($reply) && method_exists($reply, 'getMessage') ? (string) $reply->getMessage() : (string) $reply)];
                }

                return self::convert($reply, $cap, $budget, 0);
            };
        }
        if (is_callable($value)) {
            return static function (array $argv, int $cap, RedisReplyBudget $budget) use ($value): array {
                return self::convert($value(array_values($argv)), $cap, $budget, 0);
            };
        }
        throw new RedisConnectionFailed($origin . ' returned ' . (is_object($value) ? get_class($value) : gettype($value)) . '; return a phpredis Redis, a Predis client, a Laravel Redis connection, a callable, or null.');
    }

    /**
     * @param \Redis $redis
     * @param string[] $argv
     * @return array<string, mixed>
     */
    private static function phpredis($redis, array $argv, int $cap, RedisReplyBudget $budget): array
    {
        $literal = defined('Redis::OPT_REPLY_LITERAL') ? constant('Redis::OPT_REPLY_LITERAL') : null;
        $previous = null;
        if ($literal !== null) {
            try {
                $previous = $redis->getOption($literal);
                $redis->setOption($literal, true);
            } catch (\Throwable $error) {
                $literal = null;
            }
        }
        try {
            if (method_exists($redis, 'clearLastError')) {
                $redis->clearLastError();
            }
            $reply = $redis->rawCommand(...array_values($argv));
            if ($reply === false && method_exists($redis, 'getLastError')) {
                $last = $redis->getLastError();
                if (is_string($last) && $last !== '') {
                    return ['t' => '-', 'v' => Channel::scrub($last)];
                }
            }
        } catch (\Throwable $error) {
            return ['t' => '-', 'v' => Channel::scrub($error->getMessage())];
        } finally {
            if ($literal !== null) {
                try {
                    $redis->setOption($literal, $previous);
                } catch (\Throwable $error) {
                    // Best effort.
                }
            }
        }

        return self::convert($reply, $cap, $budget, 0);
    }

    /**
     * A PHP value from a client as a reply tree.
     *
     * @param mixed $value
     * @return array<string, mixed>
     */
    public static function convert($value, int $cap, RedisReplyBudget $budget, int $depth): array
    {
        if ($value === null || $value === false) {
            return ['t' => 'n'];
        }
        if ($value === true) {
            return ['t' => '+', 'v' => 'OK'];
        }
        if (is_int($value)) {
            return ['t' => 'i', 'v' => $value];
        }
        if (is_float($value)) {
            return ['t' => 'd', 'v' => is_finite($value) ? (string) $value : ($value > 0 ? 'inf' : ($value < 0 ? '-inf' : 'nan'))];
        }
        if (is_string($value)) {
            return $budget->text($value, strlen($value), $depth === 0);
        }
        if (is_object($value)) {
            $class = get_class($value);
            if (is_a($value, 'Predis\Response\ErrorInterface') && method_exists($value, 'getMessage')) {
                return ['t' => '-', 'v' => Channel::scrub((string) $value->getMessage())];
            }
            if (is_a($value, 'Predis\Response\Status') || method_exists($value, 'getPayload')) {
                return ['t' => '+', 'v' => (string) $value->getPayload()];
            }
            if (method_exists($value, '__toString')) {
                return $budget->text((string) $value, strlen((string) $value), $depth === 0);
            }

            return ['t' => 's', 'v' => $class];
        }
        if (is_array($value)) {
            $list = array_keys($value) === range(0, count($value) - 1) || $value === [];
            $items = [];
            $omitted = 0;
            foreach ($value as $key => $item) {
                if (count($items) >= ($list ? $cap : intdiv($cap, 2)) || $budget->exhausted()) {
                    $omitted++;
                    continue;
                }
                $items[] = $list ? self::convert($item, $cap, $budget, $depth + 1) : [self::convert((string) $key, $cap, $budget, $depth + 1), self::convert($item, $cap, $budget, $depth + 1)];
            }
            $node = ['t' => $list ? '*' : '%', 'v' => $items];
            if ($omitted > 0) {
                $node['o'] = $omitted;
            }

            return $node;
        }

        return ['t' => 's', 'v' => gettype($value)];
    }
}

final class RedisTab
{
    /** Bytes of an argument echoed back with its reply. */
    private const MAX_ARGUMENT_ECHO = 300;
    private const MAX_ARGUMENTS_ECHOED = 30;

    /** @var callable|null */
    private static $executor;
    /** @var string */
    private static $origin = '';
    /** @var string[] */
    private static $names = [];

    /**
     * Runs `$commands` in order on the tab's connection (`$connection`: the application's
     * connection name, null for its default; ignored for a saved connection) and emits a
     * `redis` event for each reply. `$all` (Run All) numbers them and stops at the first
     * error; `$multi` wraps them in MULTI/EXEC, and every command's reply comes from EXEC.
     *
     * @param array<int, array{argv: string[], line: int, cap?: int, secret?: int[]}> $commands
     */
    public static function run(array $commands, ?string $connection, int $maxElements, bool $all = false, bool $multi = false): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        $commands = array_values($commands);
        $count = count($commands);
        if ($count === 0) {
            throw new \InvalidArgumentException('There are no commands to run.');
        }
        foreach ($commands as $index => $command) {
            $argv = array_map('strval', array_values((array) ($command['argv'] ?? [])));
            if ($argv === []) {
                throw new \InvalidArgumentException('Command ' . ($index + 1) . ' is empty.');
            }
            foreach ((array) ($command['secret'] ?? []) as $secret) {
                if (isset($argv[(int) $secret]) && $argv[(int) $secret] !== '') {
                    Channel::addSecret($argv[(int) $secret]);
                }
            }
            $refusal = RedisCommands::refusal($argv);
            if ($refusal !== null) {
                throw new RedisRefused(($count === 1 ? '' : 'Command ' . ($index + 1) . ' of ' . $count . ' (line ' . (int) $command['line'] . '): ') . $refusal);
            }
        }
        self::refuseOnReadOnly($commands, null);
        [$execute, $origin] = self::resolve($connection);
        self::refuseOnReadOnly($commands, $execute);
        $db = RedisConnect::isConfigured() ? RedisConnect::database() : null;
        self::reportSession($execute, $connection);
        if ($multi) {
            self::runMulti($commands, $execute, $origin, $connection, $maxElements, $db);

            return NoResult::instance();
        }
        foreach ($commands as $index => $command) {
            $argv = array_map('strval', array_values($command['argv']));
            $budget = new RedisReplyBudget();
            $started = hrtime(true);
            $reply = $execute($argv, max(1, (int) ($command['cap'] ?? $maxElements)), $budget);
            $elapsed = round((hrtime(true) - $started) / 1e6, 3);
            if (($reply['t'] ?? '') === '-') {
                $where = $count === 1 || !$all ? '' : 'Command ' . ($index + 1) . ' of ' . $count . ' (line ' . (int) $command['line'] . '): ';
                $notes = [];
                if ($all && $index + 1 < $count) {
                    $notes[] = ($index + 2 === $count ? 'Command ' . $count . ' did' : 'Commands ' . ($index + 2) . '–' . $count . ' did') . ' not run.';
                    if ($index > 0) {
                        $notes[] = ($index === 1 ? 'Command 1 ran' : 'Commands 1–' . $index . ' ran') . ' and stay' . ($index === 1 ? 's' : '') . ': Redis has no rollback. Turn on "In a Transaction" (MULTI/EXEC) to queue the commands first.';
                    }
                }
                throw new RedisCommandFailed($where . (string) $reply['v'] . ($notes === [] ? '' : "\n\n" . implode(' ', $notes)));
            }
            if (strtoupper($argv[0]) === 'SELECT' && ($reply['t'] ?? '') === '+') {
                $db = (int) ($argv[1] ?? 0);
            }
            $event = self::event($argv, $command, $reply, $elapsed, $origin, $connection, $db, $maxElements, $budget);
            if ($all) {
                $event['statement'] = ['index' => $index + 1, 'count' => $count, 'line' => (int) $command['line'], 'text' => self::echoLine($argv, $command)];
            }
            if ($index === 0 && self::$names !== []) {
                $event['connections'] = self::$names;
            }
            Channel::emit('redis', $event);
        }

        return NoResult::instance();
    }

    /**
     * Run All in a transaction: MULTI, each command (Redis queues it), EXEC. A command Redis
     * refuses to queue discards the transaction, so nothing runs.
     *
     * @param array<int, array<string, mixed>> $commands
     */
    private static function runMulti(array $commands, callable $execute, string $origin, ?string $connection, int $maxElements, ?int $db): void
    {
        $count = count($commands);
        foreach ($commands as $index => $command) {
            if (in_array(strtoupper((string) $command['argv'][0]), RedisCommands::TRANSACTION, true)) {
                throw new RedisRefused('Command ' . ($index + 1) . ' (line ' . (int) $command['line'] . ') is ' . strtoupper((string) $command['argv'][0]) . ', and Run All already wraps the commands in MULTI/EXEC. Turn off "In a Transaction" to run them as written.');
            }
        }
        $started = hrtime(true);
        $begin = $execute(['MULTI'], 1, new RedisReplyBudget());
        if (($begin['t'] ?? '') === '-') {
            throw new RedisCommandFailed('Redis refused MULTI: ' . (string) $begin['v'] . ' Nothing ran.');
        }
        foreach ($commands as $index => $command) {
            $argv = array_map('strval', array_values($command['argv']));
            $queued = $execute($argv, 1, new RedisReplyBudget());
            if (($queued['t'] ?? '') === '-') {
                $execute(['DISCARD'], 1, new RedisReplyBudget());
                throw new RedisCommandFailed('Command ' . ($index + 1) . ' of ' . $count . ' (line ' . (int) $command['line'] . '): ' . (string) $queued['v'] . "\n\nRedis didn't queue it, so Runlet discarded the transaction: nothing ran.");
            }
        }
        $budget = new RedisReplyBudget();
        $cap = 1;
        foreach ($commands as $command) {
            $cap = max($cap, (int) ($command['cap'] ?? $maxElements));
        }
        $replies = $execute(['EXEC'], max($count, $cap), $budget);
        $elapsed = round((hrtime(true) - $started) / 1e6, 3);
        if (($replies['t'] ?? '') === '-') {
            throw new RedisCommandFailed('EXEC failed: ' . (string) $replies['v'] . ' Redis ran none of the commands.');
        }
        if (($replies['t'] ?? '') === 'n') {
            throw new RedisCommandFailed('Redis aborted the transaction (a WATCHed key changed), so none of the commands ran.');
        }
        $items = is_array($replies['v'] ?? null) ? $replies['v'] : [];
        foreach ($commands as $index => $command) {
            $argv = array_map('strval', array_values($command['argv']));
            $reply = $items[$index] ?? ['t' => 'n'];
            $event = self::event($argv, $command, $reply, $index === 0 ? $elapsed : null, $origin, $connection, $db, $maxElements, $budget);
            $event['transaction'] = true;
            $event['statement'] = ['index' => $index + 1, 'count' => $count, 'line' => (int) $command['line'], 'text' => self::echoLine($argv, $command)];
            if ($index === 0 && self::$names !== []) {
                $event['connections'] = self::$names;
            }
            Channel::emit('redis', $event);
            if (strtoupper($argv[0]) === 'SELECT' && ($reply['t'] ?? '') === '+') {
                $db = (int) ($argv[1] ?? 0);
            }
        }
        $errors = 0;
        foreach ($items as $item) {
            if (is_array($item) && ($item['t'] ?? '') === '-') {
                $errors++;
            }
        }
        Channel::emit('notice', ['message' => 'Ran ' . ($count === 1 ? 'the command' : 'all ' . $count . ' commands') . ' in one MULTI/EXEC transaction' . ($errors > 0 ? ': ' . $errors . ' of them returned an error, and Redis ran the others (it has no rollback).' : '.')]);
    }

    /**
     * @param string[] $argv
     * @param array<string, mixed> $command
     * @param array<string, mixed> $reply
     * @return array<string, mixed>
     */
    private static function event(array $argv, array $command, array $reply, ?float $elapsed, string $origin, ?string $connection, ?int $db, int $maxElements, RedisReplyBudget $budget): array
    {
        $event = [
            'argv' => self::echoArguments($argv, $command),
            'reply' => $reply,
            'source' => $origin,
            'maxElements' => $maxElements,
            'bytes' => $budget->used,
        ];
        if ($elapsed !== null) {
            $event['elapsedMs'] = $elapsed;
        }
        if (RedisConnect::isConfigured()) {
            $event['connection'] = RedisConnect::name();
            $event['saved'] = true;
        } elseif ($connection !== null) {
            $event['connection'] = $connection;
        }
        if ($db !== null) {
            $event['db'] = $db;
        }

        return $event;
    }

    /**
     * The arguments as echoed: passwords as •••, long ones shortened, bytes that aren't UTF-8
     * as \xHH.
     *
     * @param string[] $argv
     * @param array<string, mixed> $command
     * @return string[]
     */
    private static function echoArguments(array $argv, array $command): array
    {
        $secrets = array_map('intval', (array) ($command['secret'] ?? []));
        $echo = [];
        foreach (array_slice($argv, 0, self::MAX_ARGUMENTS_ECHOED) as $index => $argument) {
            if (in_array($index, $secrets, true)) {
                $echo[] = '•••';
                continue;
            }
            // Control characters, and bytes that aren't UTF-8, as \xHH.
            $argument = preg_replace_callback(preg_match('//u', $argument) === 1 ? '/[\x00-\x1f\x7f]/' : '/[\x00-\x1f\x7f-\xff]/', static function (array $match): string {
                return '\\x' . strtoupper(bin2hex($match[0]));
            }, $argument) ?? '';
            if (strlen($argument) > self::MAX_ARGUMENT_ECHO) {
                $cut = substr($argument, 0, self::MAX_ARGUMENT_ECHO);
                while ($cut !== '' && preg_match('//u', $cut) !== 1) {
                    $cut = substr($cut, 0, -1);
                }
                $argument = $cut . '…';
            }
            $echo[] = $argument;
        }
        if (count($argv) > self::MAX_ARGUMENTS_ECHOED) {
            $echo[] = '… ' . (count($argv) - self::MAX_ARGUMENTS_ECHOED) . ' more';
        }

        return $echo;
    }

    /** @param string[] $argv */
    private static function echoLine(array $argv, array $command): string
    {
        return implode(' ', self::echoArguments($argv, $command));
    }

    /**
     * Read-only saved connections: refuses the whole run, before anything is sent, when a
     * command isn't a read by Runlet's table; with `$execute`, also by the server's COMMAND
     * INFO flags (`write`), when the server answers it.
     *
     * @param array<int, array<string, mixed>> $commands
     */
    private static function refuseOnReadOnly(array $commands, ?callable $execute): void
    {
        if (!RedisConnect::isConfigured() || !RedisConnect::isReadOnly()) {
            return;
        }
        $count = count($commands);
        $name = '"' . RedisConnect::name() . '"';
        $flags = [];
        foreach ($commands as $index => $command) {
            $argv = array_map('strval', array_values((array) $command['argv']));
            $why = RedisCommands::readOnlyRefusal($argv);
            if ($why === null && $execute !== null) {
                $key = RedisCommands::key($argv);
                if (!array_key_exists($key, $flags)) {
                    $flags[$key] = self::commandFlags($execute, $key);
                }
                if (is_array($flags[$key]) && in_array('write', $flags[$key], true)) {
                    $why = 'can change data (the server flags ' . RedisCommands::name($argv) . ' as a write)';
                }
            }
            if ($why === null) {
                continue;
            }
            throw new RedisRefused($count === 1
                ? 'Runlet refused this command on the read-only connection ' . $name . ': it ' . $why . '. Nothing ran.'
                : 'Command ' . ($index + 1) . ' of ' . $count . ' (line ' . (int) $command['line'] . ') ' . $why . ', so Runlet ran none of them on the read-only connection ' . $name . '. Nothing ran.');
        }
    }

    /**
     * The server's flags for a command (`COMMAND INFO get`, `COMMAND INFO config|get`); null
     * when the server doesn't answer (COMMAND renamed or refused).
     *
     * @return string[]|null
     */
    private static function commandFlags(callable $execute, string $key): ?array
    {
        $reply = $execute(['COMMAND', 'INFO', strtolower($key)], 20, new RedisReplyBudget());
        $info = $reply['v'][0] ?? null;
        if (($reply['t'] ?? '') !== '*' || !is_array($info) || ($info['t'] ?? '') !== '*') {
            return null;
        }
        $flags = $info['v'][2]['v'] ?? null;
        if (!is_array($flags)) {
            return null;
        }
        $names = [];
        foreach ($flags as $flag) {
            if (is_array($flag) && isset($flag['v']) && is_string($flag['v'])) {
                $names[] = strtolower($flag['v']);
            }
        }

        return $names;
    }

    /**
     * #144, #180: the connection's client id, for the Connection Manager (Stop closes the
     * connection; Redis unblocks a blocked client when it does).
     */
    private static function reportSession(callable $execute, ?string $connection): void
    {
        try {
            $reply = $execute(['CLIENT', 'ID'], 1, new RedisReplyBudget());
        } catch (\Throwable $error) {
            return;
        }
        if (($reply['t'] ?? '') !== 'i') {
            return;
        }
        Channel::emit('sqlSession', array_filter([
            'driver' => 'redis',
            'id' => (int) $reply['v'],
            'connection' => RedisConnect::isConfigured() ? null : $connection,
            'saved' => RedisConnect::isConfigured() ? true : null,
        ], static function ($value): bool {
            return $value !== null;
        }));
    }

    /**
     * The connection to use, as an executor, and where it came from.
     *
     * @return array{0: callable, 1: string}
     */
    public static function resolve(?string $connection): array
    {
        if (self::$executor !== null) {
            return [self::$executor, self::$origin];
        }
        if (RedisConnect::isConfigured()) {
            $client = RedisConnect::client();
            self::$executor = static function (array $argv, int $cap, RedisReplyBudget $budget) use ($client): array {
                return $client->command($argv, $cap, $budget);
            };
            self::$origin = RedisConnect::origin();

            return [self::$executor, self::$origin];
        }
        $driver = Runner::bootedDriver();
        $what = $connection === null ? 'the default Redis connection' : 'the Redis connection "' . $connection . '"';
        if ($driver !== null && method_exists($driver, 'redisConnections')) {
            try {
                $names = Runner::callBootedDriver('redisConnections()', static function () use ($driver) {
                    return $driver->redisConnections();
                });
                foreach (is_array($names) ? $names : [] as $name) {
                    if ((is_string($name) || is_int($name)) && (string) $name !== '' && strlen((string) $name) <= 200 && !in_array((string) $name, self::$names, true)) {
                        self::$names[] = (string) $name;
                    }
                }
                self::$names = array_slice(self::$names, 0, 100);
            } catch (DriverFailure $failure) {
                throw $failure;
            } catch (\Throwable $error) {
                Channel::emit('notice', ['message' => 'The Redis connection list is unavailable: ' . $error->getMessage()]);
            }
        }
        $known = self::$names === [] ? '' : ' Connections: ' . implode(', ', self::$names) . '.';
        $value = null;
        if ($driver !== null && method_exists($driver, 'redisConnection')) {
            try {
                $value = Runner::callBootedDriver('redisConnection()', static function () use ($driver, $connection) {
                    return $driver->redisConnection($connection);
                });
            } catch (DriverFailure $failure) {
                throw $failure;
            } catch (\Throwable $error) {
                throw new RedisConnectionFailed('Runlet could not open ' . $what . ': ' . $error->getMessage() . $known, 0, $error);
            }
        }
        if ($value === null) {
            $name = $driver === null ? 'none' : $driver->name();
            throw new RedisUnavailable('This project has no Redis connection that Redis tabs can use. Its driver (' . $name . ') provides none. '
                . 'To run Redis commands here, save a Redis connection (New Connection… in the Redis bar\'s connection menu; its password goes to the Keychain), or return one from redisConnection() in a project driver (.runlet/<Name>Driver.php; see "Redis connections" in the drivers guide).');
        }
        $declaring = (new \ReflectionMethod($driver, 'redisConnection'))->getDeclaringClass()->getName();
        $origin = $declaring === 'Runlet\Drivers\LaravelDriver' ? 'Laravel Redis::connection()' : $declaring . '::redisConnection()';
        try {
            self::$executor = RedisAppConnection::executor($value, $origin);
        } catch (RedisUnavailable | RedisConnectionFailed $refused) {
            throw $refused;
        }
        self::$origin = $origin;

        return [self::$executor, self::$origin];
    }

    /** Test Connection for a saved Redis connection: emits an `sqlTest` event. */
    public static function test(): NoResult
    {
        if (!RedisConnect::isConfigured()) {
            throw new RedisUnavailable('Test Connection needs a saved connection, and this run has none.');
        }
        Channel::emit('sqlTest', RedisConnect::test());

        return NoResult::instance();
    }

    /** Selects `$db` on the connection when it isn't selected yet (key browser). */
    private static function select(callable $execute, int $db): void
    {
        $reply = $execute(['SELECT', (string) $db], 1, new RedisReplyBudget());
        if (($reply['t'] ?? '') === '-') {
            throw new RedisCommandFailed('Redis refused SELECT ' . $db . ': ' . (string) $reply['v']);
        }
    }

    /**
     * The key browser: one SCAN page of `$db` (never KEYS), with each key's TYPE and PTTL,
     * and the keyspace (INFO keyspace) for the database picker. Emits `redisKeys`. Without
     * `$details` (Load Keys for Completion, #206) it sends the SCAN only: key names, nothing else.
     */
    public static function keys(int $db, string $pattern, string $cursor, int $count, ?string $type, ?string $connection, bool $details = true): NoResult
    {
        [$execute, $origin] = self::resolve($connection === '' ? null : $connection);
        self::select($execute, $db);
        $started = hrtime(true);
        $argv = ['SCAN', $cursor === '' ? '0' : $cursor, 'MATCH', $pattern === '' ? '*' : $pattern, 'COUNT', (string) max(1, min(10000, $count))];
        if ($type !== null && $type !== '') {
            $argv[] = 'TYPE';
            $argv[] = $type;
        }
        $reply = $execute($argv, 10000, new RedisReplyBudget());
        if (($reply['t'] ?? '') === '-') {
            throw new RedisCommandFailed('SCAN failed: ' . (string) $reply['v']);
        }
        $next = (string) ($reply['v'][0]['v'] ?? '0');
        $names = [];
        foreach ((array) ($reply['v'][1]['v'] ?? []) as $item) {
            if (is_array($item) && ($item['t'] ?? '') === 's') {
                $names[] = (string) $item['v'];
            }
        }
        $keys = [];
        foreach ($names as $name) {
            if (!$details) {
                $keys[] = array_filter([
                    'key' => preg_match('//u', $name) === 1 ? $name : null,
                    'raw' => base64_encode($name),
                ], static function ($value): bool {
                    return $value !== null;
                });
                continue;
            }
            $keyType = $execute(['TYPE', $name], 1, new RedisReplyBudget());
            $ttl = $execute(['PTTL', $name], 1, new RedisReplyBudget());
            $keys[] = array_filter([
                'key' => preg_match('//u', $name) === 1 ? $name : null,
                'raw' => base64_encode($name),
                'type' => ($keyType['t'] ?? '') === '+' ? (string) $keyType['v'] : null,
                'ttl' => ($ttl['t'] ?? '') === 'i' ? (int) $ttl['v'] : null,
            ], static function ($value): bool {
                return $value !== null;
            });
        }
        $keyspace = [];
        $info = $details ? $execute(['INFO', 'keyspace'], 1, new RedisReplyBudget()) : [];
        if (($info['t'] ?? '') === 's' && preg_match_all('/^db(\d+):keys=(\d+),expires=(\d+)/m', (string) $info['v'], $matches, PREG_SET_ORDER) > 0) {
            foreach ($matches as $match) {
                $keyspace[] = ['db' => (int) $match[1], 'keys' => (int) $match[2], 'expires' => (int) $match[3]];
            }
        }
        $databases = null;
        $config = $details ? $execute(['CONFIG', 'GET', 'databases'], 2, new RedisReplyBudget()) : [];
        if (($config['t'] ?? '') === '*' && isset($config['v'][1]['v'])) {
            $databases = (int) $config['v'][1]['v'];
        }
        Channel::emit('redisKeys', array_filter([
            'db' => $db,
            'pattern' => $pattern,
            'cursor' => $cursor,
            'next' => $next,
            'keys' => $keys,
            'keyspace' => $keyspace,
            'databases' => $databases,
            'source' => $origin,
            'connections' => self::$names === [] ? null : self::$names,
            'elapsedMs' => round((hrtime(true) - $started) / 1e6, 3),
        ], static function ($value): bool {
            return $value !== null;
        }));

        return NoResult::instance();
    }

    /**
     * The key browser's Open Value: the key's value read by its type, as a `redis` event whose
     * `argv` is the equivalent command (so it shows like a tab's reply).
     */
    public static function value(int $db, string $key, int $maxElements, ?string $connection): NoResult
    {
        [$execute, $origin] = self::resolve($connection === '' ? null : $connection);
        self::select($execute, $db);
        $maxElements = max(1, $maxElements);
        $type = $execute(['TYPE', $key], 1, new RedisReplyBudget());
        $kind = ($type['t'] ?? '') === '+' ? (string) $type['v'] : 'none';
        $budget = new RedisReplyBudget();
        $started = hrtime(true);
        switch ($kind) {
            case 'string':
                $argv = ['GET', $key];
                $reply = $execute($argv, 1, $budget);
                break;
            case 'hash':
                $argv = ['HGETALL', $key];
                $reply = self::scanned($execute, 'HSCAN', $key, $maxElements, $budget, true);
                break;
            case 'list':
                $argv = ['LRANGE', $key, '0', (string) ($maxElements - 1)];
                $reply = $execute($argv, $maxElements, $budget);
                $length = $execute(['LLEN', $key], 1, new RedisReplyBudget());
                if (($length['t'] ?? '') === 'i' && (int) $length['v'] > count((array) ($reply['v'] ?? []))) {
                    $reply['o'] = (int) $length['v'] - count((array) $reply['v']);
                }
                break;
            case 'set':
                $argv = ['SMEMBERS', $key];
                $reply = self::scanned($execute, 'SSCAN', $key, $maxElements, $budget, false);
                break;
            case 'zset':
                $argv = ['ZRANGE', $key, '0', (string) ($maxElements - 1), 'WITHSCORES'];
                $reply = $execute($argv, $maxElements * 2, $budget);
                $length = $execute(['ZCARD', $key], 1, new RedisReplyBudget());
                if (($length['t'] ?? '') === 'i' && (int) $length['v'] * 2 > count((array) ($reply['v'] ?? []))) {
                    $reply['o'] = (int) $length['v'] * 2 - count((array) $reply['v']);
                }
                break;
            case 'stream':
                $argv = ['XRANGE', $key, '-', '+', 'COUNT', (string) $maxElements];
                $reply = $execute($argv, $maxElements, $budget);
                $length = $execute(['XLEN', $key], 1, new RedisReplyBudget());
                if (($length['t'] ?? '') === 'i' && (int) $length['v'] > count((array) ($reply['v'] ?? []))) {
                    $reply['o'] = (int) $length['v'] - count((array) $reply['v']);
                }
                break;
            case 'none':
                throw new RedisCommandFailed('The key doesn\'t exist any more (it expired or was deleted).');
            default:
                $argv = ['TYPE', $key];
                $reply = ['t' => '+', 'v' => $kind];
                Channel::emit('notice', ['message' => 'The key is a ' . $kind . ', which Runlet doesn\'t read by itself: run the module\'s own command in the Redis tab.']);
        }
        $event = self::event($argv, [], $reply, round((hrtime(true) - $started) / 1e6, 3), $origin, $connection, $db, $maxElements, $budget);
        if (self::$names !== []) {
            $event['connections'] = self::$names;
        }
        Channel::emit('redis', $event);

        return NoResult::instance();
    }

    /**
     * A hash's or set's elements through HSCAN/SSCAN (never one call for a huge key), until
     * `$maxElements` rows or the end; the rest are counted (HLEN/SCARD).
     *
     * @return array<string, mixed>
     */
    private static function scanned(callable $execute, string $command, string $key, int $maxElements, RedisReplyBudget $budget, bool $pairs): array
    {
        $items = [];
        $cursor = '0';
        $rows = 0;
        $rounds = 0;
        do {
            $page = $execute([$command, $key, $cursor, 'COUNT', '500'], 2000, $budget);
            if (($page['t'] ?? '') === '-') {
                return $page;
            }
            $cursor = (string) ($page['v'][0]['v'] ?? '0');
            foreach ((array) ($page['v'][1]['v'] ?? []) as $item) {
                $items[] = $item;
            }
            $rows = $pairs ? intdiv(count($items), 2) : count($items);
            $rounds++;
        } while ($cursor !== '0' && $rows < $maxElements && !$budget->exhausted() && $rounds < 10000);
        $keep = $pairs ? $maxElements * 2 : $maxElements;
        $omitted = max(0, count($items) - $keep);
        $items = array_slice($items, 0, $keep);
        $total = $execute([$pairs ? 'HLEN' : 'SCARD', $key], 1, new RedisReplyBudget());
        if (($total['t'] ?? '') === 'i') {
            $omitted = max($omitted, ((int) $total['v']) * ($pairs ? 2 : 1) - count($items));
        }
        $node = ['t' => '*', 'v' => $items];
        if ($omitted > 0) {
            $node['o'] = $omitted;
        }

        return $node;
    }

    /**
     * The key browser's Memory Usage: the key's type, TTL, encoding, length, and MEMORY USAGE.
     * Emits `redisKeyInfo`.
     */
    public static function keyInfo(int $db, string $key, ?string $connection): NoResult
    {
        [$execute] = self::resolve($connection === '' ? null : $connection);
        self::select($execute, $db);
        $type = $execute(['TYPE', $key], 1, new RedisReplyBudget());
        $kind = ($type['t'] ?? '') === '+' ? (string) $type['v'] : null;
        $ttl = $execute(['PTTL', $key], 1, new RedisReplyBudget());
        $encoding = $execute(['OBJECT', 'ENCODING', $key], 1, new RedisReplyBudget());
        $memory = $execute(['MEMORY', 'USAGE', $key], 1, new RedisReplyBudget());
        $lengthCommand = ['string' => 'STRLEN', 'hash' => 'HLEN', 'list' => 'LLEN', 'set' => 'SCARD', 'zset' => 'ZCARD', 'stream' => 'XLEN'][$kind ?? ''] ?? null;
        $length = $lengthCommand === null ? null : $execute([$lengthCommand, $key], 1, new RedisReplyBudget());
        Channel::emit('redisKeyInfo', array_filter([
            'raw' => base64_encode($key),
            'type' => $kind,
            'ttl' => ($ttl['t'] ?? '') === 'i' ? (int) $ttl['v'] : null,
            'encoding' => ($encoding['t'] ?? '') === 's' ? (string) $encoding['v'] : null,
            'memory' => ($memory['t'] ?? '') === 'i' ? (int) $memory['v'] : null,
            'memoryError' => ($memory['t'] ?? '') === '-' ? (string) $memory['v'] : null,
            'length' => is_array($length) && ($length['t'] ?? '') === 'i' ? (int) $length['v'] : null,
        ], static function ($value): bool {
            return $value !== null;
        }));

        return NoResult::instance();
    }

    /**
     * The server panel: INFO (every default section), CLIENT LIST, and this connection's own
     * CLIENT ID. Emits `redisServer` with the raw texts (the app parses them).
     */
    public static function server(?string $connection): NoResult
    {
        [$execute, $origin] = self::resolve($connection === '' ? null : $connection);
        $started = hrtime(true);
        $info = $execute(['INFO'], 1, new RedisReplyBudget());
        $clients = $execute(['CLIENT', 'LIST'], 1, new RedisReplyBudget());
        $own = $execute(['CLIENT', 'ID'], 1, new RedisReplyBudget());
        Channel::emit('redisServer', array_filter([
            'info' => ($info['t'] ?? '') === 's' ? (string) $info['v'] : null,
            'infoError' => ($info['t'] ?? '') === '-' ? (string) $info['v'] : null,
            'clients' => ($clients['t'] ?? '') === 's' ? (string) $clients['v'] : null,
            'clientsError' => ($clients['t'] ?? '') === '-' ? (string) $clients['v'] : null,
            'ownId' => ($own['t'] ?? '') === 'i' ? (int) $own['v'] : null,
            'source' => $origin,
            'connection' => RedisConnect::isConfigured() ? RedisConnect::name() : $connection,
            'saved' => RedisConnect::isConfigured() ? true : null,
            'elapsedMs' => round((hrtime(true) - $started) / 1e6, 3),
        ], static function ($value): bool {
            return $value !== null;
        }));

        return NoResult::instance();
    }

    /**
     * The server panel's Kill Client, confirmed in the app: refuses another server (INFO's
     * run_id), the panel's own client (`$listedBy`), this runner's own, and a client that isn't
     * the one listed any more (its address changed or it's gone); then CLIENT KILL ID. Emits
     * `redisKill`.
     */
    public static function kill(int $clientId, string $address, string $runId, int $listedBy, ?string $connection): NoResult
    {
        [$execute] = self::resolve($connection === '' ? null : $connection);
        $report = static function (string $outcome, string $detail) use ($clientId): NoResult {
            Channel::emit('redisKill', ['id' => $clientId, 'outcome' => $outcome, 'detail' => $detail]);

            return NoResult::instance();
        };
        $info = $execute(['INFO', 'server'], 1, new RedisReplyBudget());
        $actual = ($info['t'] ?? '') === 's' && preg_match('/^run_id:(\S+)/m', (string) $info['v'], $match) === 1 ? $match[1] : '';
        if ($runId !== '' && $actual !== $runId) {
            return $report('refused', 'This connection reached another Redis server than the one the list came from (its run_id differs), so Runlet killed nothing. Refresh the list.');
        }
        $own = $execute(['CLIENT', 'ID'], 1, new RedisReplyBudget());
        if ($clientId === $listedBy || (($own['t'] ?? '') === 'i' && (int) $own['v'] === $clientId)) {
            return $report('refused', 'Client ' . $clientId . ' is Runlet\'s own connection, so it wasn\'t killed.');
        }
        $listed = $execute(['CLIENT', 'LIST', 'ID', (string) $clientId], 1, new RedisReplyBudget());
        $line = ($listed['t'] ?? '') === 's' ? trim((string) $listed['v']) : '';
        if ($line === '') {
            return $report('gone', 'Client ' . $clientId . ' isn\'t connected any more.');
        }
        if ($address !== '' && preg_match('/(?:^| )addr=(\S+)/', $line, $match) === 1 && $match[1] !== $address) {
            return $report('refused', 'Client ' . $clientId . ' now connects from ' . $match[1] . ', not ' . $address . ' as listed, so Runlet killed nothing. Refresh the list.');
        }
        $killed = $execute(['CLIENT', 'KILL', 'ID', (string) $clientId], 1, new RedisReplyBudget());
        if (($killed['t'] ?? '') === '-') {
            return $report('failed', 'Redis refused CLIENT KILL: ' . (string) $killed['v']);
        }
        if (($killed['t'] ?? '') === 'i' && (int) $killed['v'] === 0) {
            return $report('gone', 'Client ' . $clientId . ' had already disconnected.');
        }

        return $report('killed', 'Killed client ' . $clientId . ' (CLIENT KILL ID ' . $clientId . ').');
    }
}
}

/*
 * Export Query to CSV and Import CSV (#152), on an SQL tab's connection (SqlTab::openFor: the
 * application's own, or a saved one, with the same refusals as a run).
 *
 * Export streams every row of a read statement as `sqlExport` frames (the columns, then at most
 * FRAME_ROWS rows or about FRAME_BYTES of cells per frame, then `done`), with no row cap, while
 * this process holds one frame at a time: MySQL and MariaDB fetch unbuffered, PostgreSQL through
 * a cursor in a read transaction (FETCH FORWARD), SQLite and SQL Server step through the rows.
 * The app writes each frame to the chosen file as it arrives (CSV is formatted there, with the
 * sheet's options). Stop cancels the statement on the server first (#144).
 *
 * Import inserts rows the app parsed from a CSV file and sent as data, in batches of JSON (never
 * SQL), with bound values, all in one transaction: committed after the last row, rolled back at
 * the first error, which says which row failed (a savepoint per statement lets Runlet find it).
 * A read-only connection refuses it (#139).
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

/** Export Query to CSV refused the statement or the connection; nothing was exported. */
final class SqlExportRefused extends \RuntimeException
{
}

/** Import CSV failed: the transaction was rolled back (the message says what came of it). */
final class SqlImportFailed extends \RuntimeException
{
}

/** One row (or one statement's rows) of an import that the database refused. */
final class SqlImportRowFailed extends \RuntimeException
{
    /** @var int|null 1-based data row; null when the statement failed but no single row did. */
    public $row;

    public function __construct(\Throwable $cause, ?int $row)
    {
        parent::__construct($cause->getMessage(), 0, $cause);
        $this->row = $row;
    }
}

final class SqlCsv
{
    /** Rows per `sqlExport` frame. */
    private const FRAME_ROWS = 1000;
    /** Cell bytes after which a frame is sent before it has FRAME_ROWS rows. */
    private const FRAME_BYTES = 262144;
    /** Rows a PostgreSQL cursor fetches at a time. */
    private const CURSOR_ROWS = 1000;
    /** Placeholders per INSERT at most (SQLite before 3.32 allows 999). */
    private const MAX_PLACEHOLDERS = 999;
    /** Rows per INSERT at most. */
    private const MAX_STATEMENT_ROWS = 500;

    /**
     * Export Query to CSV: every row of `$sql` (a read; the app checks Load Next's rules first)
     * as `sqlExport` frames. `$params` are its bound values (#145).
     *
     * @param array<int, array<string, mixed>> $params
     */
    public static function export(string $sql, ?string $connection, array $params = []): NoResult
    {
        $connection = $connection === '' ? null : $connection;
        [$source, $origin, $driver, $fields] = SqlTab::openFor($sql, $connection, $params);
        SqlCancel::report($source, $connection); // #144: Stop cancels the statement on the server.
        $started = hrtime(true);
        $total = $source instanceof \PDO ? self::exportPdo($source, $driver, $sql, $params) : self::exportCallable($source, $sql);
        Channel::emit('sqlExport', ['done' => true, 'total' => $total, 'driver' => $driver, 'elapsedMs' => round((hrtime(true) - $started) / 1e6, 3), 'source' => $origin] + $fields);

        return NoResult::instance();
    }

    /**
     * Import CSV: inserts the rows of the request's batches (Runner::takeSqlBatches: JSON arrays
     * of rows of `$columns` values, a string or null each; `$batches` in tests) with `$prefix` (`INSERT INTO <table> (<columns>) VALUES`) and one
     * `$placeholders` (`(?, ?)`) per row, both built by the app, in one transaction. Emits
     * `sqlImport` after each batch, and at the end (`done`) or on a failure (`failedRow`,
     * `rolledBack`, then an SqlImportFailed error).
     *
     * @param string[] $batches
     */
    public static function import(string $prefix, string $placeholders, int $columns, ?string $connection, ?array $batches = null): NoResult
    {
        $batches = $batches ?? Runner::takeSqlBatches();
        $connection = $connection === '' ? null : $connection;
        if ($columns < 1 || preg_match('/^INSERT INTO\s.+\sVALUES$/s', $prefix) !== 1 || $placeholders !== '(' . implode(', ', array_fill(0, $columns, '?')) . ')') {
            throw new \InvalidArgumentException('Import CSV got a statement Runlet didn\'t build. Nothing was imported.');
        }
        // A read-only connection (#139) refuses the INSERT here, before anything is sent.
        [$source, $origin, $driver, $fields] = SqlTab::openFor($prefix . ' ' . $placeholders, $connection);
        if (!$source instanceof \PDO) {
            throw new SqlImportFailed('Import CSV binds every value, and this connection (' . $origin . ') runs statements through a callable, which can\'t bind values. Nothing was imported. Return a PDO from the driver\'s sqlConnection(), or save a connection for this database.');
        }
        SqlCancel::report($source, $connection, true); // #144
        $source->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        if ($driver === 'mysql') {
            try {
                $source->setAttribute(\PDO::ATTR_EMULATE_PREPARES, false);
            } catch (\Throwable $error) {
                // Bound either way.
            }
        }
        $perStatement = max(1, min(self::MAX_STATEMENT_ROWS, intdiv(self::MAX_PLACEHOLDERS, $columns)));
        $savepoints = in_array($driver, ['sqlite', 'mysql', 'pgsql'], true);
        $started = hrtime(true);
        try {
            $source->beginTransaction();
        } catch (\Throwable $error) {
            throw new SqlImportFailed('Runlet could not start a transaction on this connection: ' . $error->getMessage() . ' Nothing was imported.', 0, $error);
        }
        $inserted = 0;
        $statements = [];
        try {
            foreach (array_keys($batches) as $key) {
                // One batch at a time, freed once read.
                $rows = json_decode((string) $batches[$key], true);
                unset($batches[$key]);
                if (!is_array($rows)) {
                    throw new \InvalidArgumentException('Import CSV got a batch of rows it can\'t read.');
                }
                foreach (array_chunk($rows, $perStatement) as $chunk) {
                    self::insert($source, $prefix, $placeholders, $columns, $chunk, $inserted, $savepoints, $statements);
                    $inserted += count($chunk);
                }
                $rows = null;
                Channel::emit('sqlImport', ['inserted' => $inserted]);
            }
            $source->commit();
        } catch (\Throwable $error) {
            $row = $error instanceof SqlImportRowFailed ? $error->row : null;
            $cause = $error instanceof SqlImportRowFailed && $error->getPrevious() !== null ? $error->getPrevious() : $error;
            $rolledBack = true;
            $note = '';
            try {
                if ($source->inTransaction()) {
                    $source->rollBack();
                }
            } catch (\Throwable $rollback) {
                $rolledBack = false;
                $note = ' Runlet could not roll back the transaction (' . $rollback->getMessage() . '); the database rolls it back when the connection closes, right after this.';
            }
            $where = $row !== null ? 'Row ' . $row : ($inserted > 0 ? 'A row after the first ' . $inserted : 'A row');
            Channel::emit('sqlImport', array_filter(['inserted' => 0, 'failedRow' => $row, 'message' => $cause->getMessage(), 'rolledBack' => $rolledBack, 'driver' => $driver], static function ($value): bool {
                return $value !== null;
            }));
            $message = rtrim($cause->getMessage());
            $message .= preg_match('/[.!?]$/', $message) === 1 ? '' : '.';
            throw new SqlImportFailed($where . ' failed: ' . $message . ($rolledBack ? ' Rolled back the transaction: no rows were imported.' : '') . $note, 0, $cause);
        }
        Channel::emit('sqlImport', ['inserted' => $inserted, 'done' => true, 'driver' => $driver, 'elapsedMs' => round((hrtime(true) - $started) / 1e6, 3), 'source' => $origin] + $fields);

        return NoResult::instance();
    }

    /**
     * Inserts one statement's rows. When it fails, the savepoint before it is restored and the
     * rows go in one at a time, so the error names the row the database refused.
     *
     * @param array<int, mixed> $chunk
     * @param array<int, \PDOStatement> $statements Prepared INSERTs by row count.
     */
    private static function insert(\PDO $pdo, string $prefix, string $placeholders, int $columns, array $chunk, int $before, bool $savepoints, array &$statements): void
    {
        $count = count($chunk);
        $values = [];
        foreach ($chunk as $index => $row) {
            if (!is_array($row) || count($row) !== $columns) {
                throw new SqlImportRowFailed(new \InvalidArgumentException('The row has ' . (is_array($row) ? count($row) : 0) . ' values for ' . $columns . ' columns.'), $before + $index + 1);
            }
            foreach ($row as $value) {
                $values[] = $value === null ? null : (string) $value;
            }
        }
        if (!isset($statements[$count])) {
            $statements[$count] = $pdo->prepare($prefix . ' ' . implode(', ', array_fill(0, $count, $placeholders)));
        }
        if ($savepoints && $count > 1) {
            $pdo->exec('SAVEPOINT runlet_import');
        }
        try {
            self::bindAll($statements[$count], $values);
            $statements[$count]->execute();
            if ($savepoints && $count > 1) {
                $pdo->exec('RELEASE SAVEPOINT runlet_import');
            }

            return;
        } catch (\PDOException $error) {
            if (!$savepoints || $count === 1) {
                throw new SqlImportRowFailed($error, $count === 1 ? $before + 1 : null);
            }
            $pdo->exec('ROLLBACK TO SAVEPOINT runlet_import');
        }
        if (!isset($statements[1])) {
            $statements[1] = $pdo->prepare($prefix . ' ' . $placeholders);
        }
        foreach ($chunk as $index => $row) {
            try {
                self::bindAll($statements[1], array_map(static function ($value) {
                    return $value === null ? null : (string) $value;
                }, array_values($row)));
                $statements[1]->execute();
            } catch (\PDOException $error) {
                throw new SqlImportRowFailed($error, $before + $index + 1);
            }
        }
        // The rows went in one by one; the statement of all of them didn't (a limit of the database's).
    }

    /** @param array<int, string|null> $values */
    private static function bindAll(\PDOStatement $statement, array $values): void
    {
        foreach ($values as $index => $value) {
            $statement->bindValue($index + 1, $value, $value === null ? \PDO::PARAM_NULL : \PDO::PARAM_STR);
        }
    }

    /**
     * @param array<int, array<string, mixed>> $params
     */
    private static function exportPdo(\PDO $pdo, ?string $driver, string $sql, array $params): int
    {
        $restore = [\PDO::ATTR_ERRMODE => $pdo->getAttribute(\PDO::ATTR_ERRMODE)];
        $pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        $attributes = [];
        if ($driver === 'mysql' || $params !== []) {
            // Native prepares, as for a run: one statement, values apart from the SQL.
            $attributes[\PDO::ATTR_EMULATE_PREPARES] = false;
        }
        if ($driver === 'mysql') {
            // Unbuffered: the rows stream from the server instead of being held here.
            $buffered = defined('Pdo\Mysql::ATTR_USE_BUFFERED_QUERY') ? constant('Pdo\Mysql::ATTR_USE_BUFFERED_QUERY') : (defined('PDO::MYSQL_ATTR_USE_BUFFERED_QUERY') ? constant('PDO::MYSQL_ATTR_USE_BUFFERED_QUERY') : null);
            if ($buffered !== null) {
                $attributes[(int) $buffered] = false;
            }
        }
        foreach ($attributes as $attribute => $value) {
            try {
                $previous = $pdo->getAttribute($attribute);
                if ($pdo->setAttribute($attribute, $value)) {
                    $restore[$attribute] = $previous;
                }
            } catch (\Throwable $error) {
                // Not supported here: the connection's setting stays.
            }
        }
        try {
            if ($driver === 'pgsql' && !$pdo->inTransaction()) {
                return self::exportCursor($pdo, $sql, $params);
            }
            $statement = $pdo->prepare($sql);
            SqlTab::bindValues($statement, $params);
            $statement->execute();
            if ($statement->columnCount() <= 0) {
                throw new SqlExportRefused('The statement returned no rows to export (it affected ' . $statement->rowCount() . ').');
            }
            self::emitColumns($statement, $driver);
            $total = 0;
            $frame = [];
            $bytes = 0;
            while (($row = $statement->fetch(\PDO::FETCH_NUM)) !== false) {
                self::add($row, $frame, $bytes, $total);
            }
            self::flush($frame, $bytes, $total);
            $statement->closeCursor();

            return $total;
        } finally {
            foreach ($restore as $attribute => $value) {
                try {
                    $pdo->setAttribute($attribute, $value);
                } catch (\Throwable $error) {
                    // Best effort: the run ends right after this.
                }
            }
        }
    }

    /**
     * PostgreSQL holds a whole result in the client unless it comes through a cursor: in a
     * transaction that only reads (rolled back at the end), `DECLARE … CURSOR FOR` the
     * statement, then FETCH FORWARD in steps of CURSOR_ROWS.
     *
     * @param array<int, array<string, mixed>> $params
     */
    private static function exportCursor(\PDO $pdo, string $sql, array $params): int
    {
        $pdo->beginTransaction();
        try {
            $declare = $pdo->prepare('DECLARE runlet_export NO SCROLL CURSOR FOR ' . $sql);
            SqlTab::bindValues($declare, $params);
            $declare->execute();
            $total = 0;
            $frame = [];
            $bytes = 0;
            $first = true;
            while (true) {
                $fetch = $pdo->query('FETCH FORWARD ' . self::CURSOR_ROWS . ' FROM runlet_export');
                if ($fetch === false) {
                    break;
                }
                if ($first) {
                    self::emitColumns($fetch, 'pgsql');
                    $first = false;
                }
                $fetched = 0;
                while (($row = $fetch->fetch(\PDO::FETCH_NUM)) !== false) {
                    $fetched++;
                    self::add($row, $frame, $bytes, $total);
                }
                $fetch->closeCursor();
                if ($fetched < self::CURSOR_ROWS) {
                    break;
                }
            }
            self::flush($frame, $bytes, $total);
            $pdo->exec('CLOSE runlet_export');

            return $total;
        } finally {
            try {
                if ($pdo->inTransaction()) {
                    $pdo->rollBack(); // It only read.
                }
            } catch (\Throwable $error) {
                // The connection closes right after this.
            }
        }
    }

    /** A callable connection (WordPress's $wpdb, …): the rows it returns, in frames. */
    private static function exportCallable(callable $run, string $sql): int
    {
        $returned = $run($sql);
        if (is_int($returned)) {
            throw new SqlExportRefused('The statement returned no rows to export (it affected ' . $returned . ').');
        }
        if (!is_iterable($returned)) {
            throw new \UnexpectedValueException('The SQL connection callable returned ' . (is_object($returned) ? get_class($returned) : gettype($returned)) . '; return the rows (an iterable of arrays or objects) or the number of affected rows (an int).');
        }
        $columns = null;
        $total = 0;
        $frame = [];
        $bytes = 0;
        foreach ($returned as $row) {
            $fields = is_object($row) ? get_object_vars($row) : (is_array($row) ? $row : ['value' => $row]);
            if ($columns === null) {
                $columns = array_map('strval', array_keys($fields));
                Channel::emit('sqlExport', ['columns' => $columns]);
            }
            $values = [];
            foreach ($columns as $column) {
                $values[] = array_key_exists($column, $fields) ? $fields[$column] : null;
            }
            self::add($values, $frame, $bytes, $total);
        }
        if ($columns === null) {
            Channel::emit('sqlExport', ['columns' => []]);
        }
        self::flush($frame, $bytes, $total);

        return $total;
    }

    private static function emitColumns(\PDOStatement $statement, ?string $driver): void
    {
        $columns = [];
        for ($index = 0; $index < $statement->columnCount(); $index++) {
            try {
                $meta = $statement->getColumnMeta($index);
            } catch (\Throwable $error) {
                $meta = false;
            }
            $columns[] = is_array($meta) && isset($meta['name']) && $meta['name'] !== '' ? (string) $meta['name'] : 'column ' . ($index + 1);
        }
        Channel::emit('sqlExport', ['columns' => $columns, 'driver' => $driver]);
    }

    /**
     * @param array<int, mixed> $row
     * @param array<int, array<int, mixed>> $frame
     */
    private static function add(array $row, array &$frame, int &$bytes, int &$total): void
    {
        $cells = [];
        foreach ($row as $value) {
            $cells[] = self::cell($value, $bytes);
        }
        $frame[] = $cells;
        $total++;
        if (count($frame) >= self::FRAME_ROWS || $bytes >= self::FRAME_BYTES) {
            self::flush($frame, $bytes, $total);
        }
    }

    /** @param array<int, array<int, mixed>> $frame */
    private static function flush(array &$frame, int &$bytes, int $total): void
    {
        if ($frame === []) {
            return;
        }
        Channel::emit('sqlExport', ['rows' => $frame, 'total' => $total, 'bytes' => $bytes]);
        $frame = [];
        $bytes = 0;
    }

    /**
     * A whole value: null, a bool, a number, text, or `binary` (byte count) and `hex` (every
     * byte) for bytes that aren't UTF-8. Nothing is shortened.
     *
     * @param mixed $value
     * @return mixed
     */
    private static function cell($value, int &$bytes)
    {
        if ($value === null || is_bool($value) || is_int($value)) {
            $bytes += 8;

            return $value;
        }
        if (is_float($value)) {
            $bytes += 16;

            return is_finite($value) ? $value : (string) $value;
        }
        if (is_resource($value)) {
            // Large objects (PostgreSQL bytea, …) arrive as streams.
            $read = @stream_get_contents($value);
            $value = $read === false ? '' : $read;
        } elseif ($value instanceof \DateTimeInterface) {
            $value = $value->format('Y-m-d H:i:s.uP');
        } elseif (is_object($value)) {
            $value = method_exists($value, '__toString') ? (string) $value : get_class($value);
        } elseif (is_array($value)) {
            $encoded = json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR);
            $value = $encoded === false ? 'array' : $encoded;
        }
        $string = (string) $value;
        if (preg_match('//u', $string) !== 1) {
            $bytes += 2 * strlen($string);

            return ['binary' => strlen($string), 'hex' => strtoupper(bin2hex($string))];
        }
        $bytes += strlen($string);

        return $string;
    }
}
}

/*
 * Browse Table (#151): the schema explorer opens one table in the result window, a page at a
 * time, and on a table with a primary key lets the user change cells, add rows, and delete
 * rows. The app writes every statement (SQLTableBrowse and SQLTableEdits in RunletCore): names
 * come from the schema's column list, quoted for the dialect, and every value is bound, never
 * written into the SQL. This file checks what it is given and runs it:
 *  - checkBrowse(): a page is one SELECT, written for the connection's dialect
 *    (SqlTab::browse() runs it like a statement and emits its `sql` event);
 *  - apply(): the reviewed changes, in one transaction. Each must affect exactly one row;
 *    otherwise everything is rolled back and the error says which change and why (a row that
 *    someone else changed or deleted since the page was read is not found). MySQL and MariaDB
 *    count only the rows an UPDATE changed, so when one reports none, the change's `verify`
 *    count (the same WHERE, written by the app) decides whether the row was there.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

/** Browse Table (#151) refused what it was given; nothing ran. */
final class SqlTableRefused extends \RuntimeException
{
}

/**
 * Apply (#151) stopped at a change that failed or didn't affect exactly one row, and rolled
 * everything back. The message says which change, why, and what the rollback did.
 */
final class SqlEditsFailed extends \RuntimeException
{
}

final class SqlTable
{
    /** The statements Apply runs, by kind. */
    private const KINDS = ['update' => 'UPDATE', 'insert' => 'INSERT', 'delete' => 'DELETE'];
    /** Bytes of a change's SQL echoed back with its result. */
    private const MAX_ECHO_BYTES = 2000;

    /**
     * A page's SQL: one SELECT that reads, written for the dialect of the connection's PDO driver
     * (`$expected`; null for a callable connection, whose dialect Runlet can't check).
     */
    public static function checkBrowse(string $sql, ?string $actual, ?string $expected): void
    {
        self::checkDialect($actual, $expected, 'Browse Table');
        if (preg_match('/^\s*SELECT\s/i', $sql) !== 1 || SqlReadOnly::refusal($sql, $actual ?? $expected) !== null) {
            throw new SqlTableRefused('Browse Table runs only the SELECT Runlet wrote for a page of the table. Nothing ran.');
        }
    }

    /** The SQL was written for `$expected`'s dialect; the connection must still be one. */
    public static function checkDialect(?string $actual, ?string $expected, string $what): void
    {
        if ($expected === null || $expected === '') {
            return;
        }
        if (self::dialect($actual) !== self::dialect($expected)) {
            throw new SqlTableRefused('The connection is ' . ($actual === null ? 'no PDO connection' : 'a ' . $actual . ' connection') . ' now, and ' . $what . ' wrote its SQL for ' . $expected . '. Load the schema again and browse the table again. Nothing ran.');
        }
    }

    /**
     * Apply's changes, before the connection opens: each is an UPDATE, INSERT, or DELETE of its
     * kind, and a `verify` count is a SELECT.
     *
     * @param array<int, array<string, mixed>> $statements
     */
    public static function checkEdits(array $statements): void
    {
        if ($statements === []) {
            throw new SqlTableRefused('There are no changes to apply.');
        }
        foreach (array_values($statements) as $index => $statement) {
            $kind = (string) ($statement['kind'] ?? '');
            $sql = (string) ($statement['sql'] ?? '');
            $verify = isset($statement['verify']) ? (string) $statement['verify'] : null;
            if (!isset(self::KINDS[$kind]) || preg_match('/^\s*' . self::KINDS[$kind] . '\s/i', $sql) !== 1
                || ($verify !== null && ($kind !== 'update' || preg_match('/^\s*SELECT\s+COUNT\(\*\)\s/i', $verify) !== 1))) {
                throw new SqlTableRefused('Change ' . ($index + 1) . ' isn\'t an UPDATE, INSERT, or DELETE that Review Changes wrote. Nothing ran.');
            }
        }
    }

    /**
     * Runs `$statements` in order, in one transaction on `$pdo`, and returns one `sql` event
     * payload per change (its affected rows and the change). Each change must affect exactly
     * one row: when one affects none (the row is gone, or changed where the WHERE checks it) or
     * more, or fails, the transaction is rolled back and SqlEditsFailed says which change and
     * why. Values are bound by `$bind` (SqlTab::bind()), with native prepares.
     *
     * @param array<int, array<string, mixed>> $statements
     * @param callable(\PDOStatement, array<int, array<string, mixed>>): void $bind
     * @return array<int, array<string, mixed>>
     */
    public static function apply(\PDO $pdo, ?string $driverName, array $statements, callable $bind): array
    {
        $statements = array_values($statements);
        $count = count($statements);
        $restore = [\PDO::ATTR_ERRMODE => $pdo->getAttribute(\PDO::ATTR_ERRMODE)];
        $pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        try {
            // Native prepares: the values go to the database apart from the SQL.
            $previous = $pdo->getAttribute(\PDO::ATTR_EMULATE_PREPARES);
            if ($pdo->setAttribute(\PDO::ATTR_EMULATE_PREPARES, false)) {
                $restore[\PDO::ATTR_EMULATE_PREPARES] = $previous;
            }
        } catch (\Throwable $error) {
            // The driver has no such setting (SQLite always binds natively).
        }
        try {
            try {
                $pdo->beginTransaction();
            } catch (\Throwable $error) {
                throw new SqlEditsFailed('Runlet could not start a transaction on this connection: ' . $error->getMessage() . ' Nothing was changed.', 0, $error);
            }
            $results = [];
            foreach ($statements as $index => $statement) {
                $kind = (string) $statement['kind'];
                $sql = (string) $statement['sql'];
                $label = isset($statement['label']) ? (string) $statement['label'] : '';
                $which = 'Change ' . ($index + 1) . ' of ' . $count . ($label === '' ? '' : ' (' . $label . ')');
                $started = hrtime(true);
                $unchanged = false;
                try {
                    $prepared = $pdo->prepare($sql);
                    $bind($prepared, self::params($statement, 'params'));
                    $prepared->execute();
                    $affected = $prepared->rowCount();
                    $prepared->closeCursor();
                    if ($affected === 0 && $kind === 'update' && isset($statement['verify'])) {
                        // MySQL and MariaDB count changed rows: an UPDATE to the values the row
                        // already has changes none. The same WHERE, counted, says whether the
                        // row was there.
                        $check = $pdo->prepare((string) $statement['verify']);
                        $bind($check, self::params($statement, 'verifyParams'));
                        $check->execute();
                        $matched = (int) $check->fetchColumn();
                        $check->closeCursor();
                        if ($matched === 1) {
                            $affected = 1;
                            $unchanged = true;
                        } else {
                            $affected = $matched;
                        }
                    }
                } catch (DriverFailure $failure) {
                    self::rollBack($pdo);
                    throw $failure;
                } catch (\Throwable $error) {
                    throw new SqlEditsFailed($which . ': ' . $error->getMessage() . "\n\n" . self::rollBack($pdo), 0, $error);
                }
                if ($affected !== 1) {
                    if ($affected === 0) {
                        $why = $kind === 'insert'
                            ? 'the INSERT added no row'
                            : 'row not found: it was changed or deleted by someone else since the page was read (Runlet looks it up by its primary key' . ($kind === 'update' ? ' and the values you changed' : '') . ')';
                    } else {
                        $why = 'it would have affected ' . $affected . ' rows, not one';
                    }
                    throw new SqlEditsFailed($which . ': ' . $why . '.' . "\n\n" . self::rollBack($pdo));
                }
                $results[] = array_filter([
                    'driver' => $driverName,
                    'affectedRows' => 1,
                    'elapsedMs' => round((hrtime(true) - $started) / 1e6, 3),
                    'unchanged' => $unchanged ? true : null,
                    'statement' => ['index' => $index + 1, 'count' => $count, 'line' => $index + 1, 'text' => self::echoed($sql)],
                ], static function ($value): bool {
                    return $value !== null;
                });
            }
            try {
                $pdo->commit();
            } catch (\Throwable $error) {
                throw new SqlEditsFailed('All ' . $count . ' changes ran, but Runlet could not commit the transaction: ' . $error->getMessage() . ' The database has probably rolled it back.', 0, $error);
            }

            return $results;
        } finally {
            foreach ($restore as $attribute => $value) {
                try {
                    $pdo->setAttribute($attribute, $value);
                } catch (\Throwable $error) {
                    // Best effort: the run ends right after this anyway.
                }
            }
        }
    }

    /** The notice after a commit. */
    public static function committed(int $count): string
    {
        return 'Committed the transaction: ' . ($count === 1 ? 'the change affected its row.' : 'all ' . $count . ' changes affected exactly one row each.');
    }

    /**
     * @param array<string, mixed> $statement
     * @return array<int, array<string, mixed>>
     */
    private static function params(array $statement, string $key): array
    {
        return isset($statement[$key]) && is_array($statement[$key]) ? array_values($statement[$key]) : [];
    }

    /** Rolls back and says so. */
    private static function rollBack(\PDO $pdo): string
    {
        try {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
        } catch (\Throwable $error) {
            return 'Runlet could not roll back the transaction: ' . $error->getMessage() . ' Check the table: changes before this one may have stayed.';
        }

        return 'Rolled back the transaction: nothing was changed.';
    }

    /** sqlsrv and dblib are both SQL Server; sqlite2 is SQLite. */
    private static function dialect(?string $driver): ?string
    {
        switch ($driver) {
            case 'dblib':
                return 'sqlsrv';
            case 'sqlite2':
                return 'sqlite';
            default:
                return $driver;
        }
    }

    /** A change's SQL for its result, cut at a UTF-8 boundary. */
    private static function echoed(string $sql): string
    {
        $sql = trim($sql);
        if (strlen($sql) <= self::MAX_ECHO_BYTES) {
            return $sql;
        }
        $cut = substr($sql, 0, self::MAX_ECHO_BYTES);
        while ($cut !== '' && preg_match('//u', $cut) !== 1) {
            $cut = substr($cut, 0, -1);
        }

        return $cut . '…';
    }
}
}

/*
 * Magic comments (#10): inline values without dump() calls or temporary variables.
 * (Below, `*\/` stands for the end of a comment.)
 *
 *     $users = User::all(); //?            the line's value (here: the assigned value)
 *     $total = $a /*?*\/ + $b;             the value of the expression right before the comment
 *     $query->get() /*?->count()*\/        a projection of that value; the chain still gets the value
 *     sleep(1); /*?.*\/                    milliseconds since the previous /*?.*\/ (or the start)
 *
 * MagicComments finds the comments with the tokenizer (so text inside strings, heredocs, other
 * comments, and inline HTML never counts) and the expressions they refer to with php-parser,
 * then inserts calls to Probe at byte offsets. Nothing is pretty-printed or moved, and nothing
 * inserted contains a newline, so every line keeps its number. A comment in a place where a
 * call would change what the code does (an assignment target, a by-reference argument, isset(),
 * a constant expression, …) is left alone and reported, and the run is otherwise unaffected.
 *
 * Probe records `inline` events while the code runs: the first 100 hits of each probe with
 * their values, then counts with a value sampled about four times a second, then the final
 * count when the run finishes.
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

use RunletVendor\PhpParser\Node;
use RunletVendor\PhpParser\Node\Expr;
use RunletVendor\PhpParser\Node\Stmt;

final class MagicComments
{
    /** Contexts an expression can be in (see childContext()). */
    private const READ = 'read';
    private const WRITE = 'write';
    private const REF = 'ref';
    private const REF_ITEM = 'refItem';
    private const ISSET = 'isset';
    private const CONSTANT = 'const';
    private const INTERPOLATION = 'interpolation';
    private const NO_WRAP = 'noWrap';
    private const ARGUMENT = 'arg';
    private const ARGUMENT_CHAIN = 'argChain';
    private const ARGUMENT_NODE = 'argNode';
    private const REF_SYNTAX = 'refSyntax';

    private const PROBE = '\\RunletRunner\\Probe::';
    private const PROJECTION_VARIABLE = '$__runletProbe';

    /** @var string */
    private $source;
    /** @var \RunletVendor\PhpParser\Parser */
    private $parser;
    /** @var array<int, array{0: int|null, 1: string, 2: int, 3: int}> [token id or null, text, byte offset, line] */
    private $tokens = [];
    /** @var int[] token start offsets, ascending */
    private $offsets = [];
    /** @var array<int, int> bracket token index => matching token index, both ways */
    private $match = [];
    /** @var array<int, array<int, array<string, mixed>>> expressions by end offset, outermost first */
    private $exprByEnd = [];
    /** @var array<int, array<int, Node\Stmt>> statements by end offset, outermost first */
    private $stmtByEnd = [];
    /** @var array<int, array{open: int, close: int, stmts: Node\Stmt[]}> statement lists */
    private $regions = [];
    /** @var array<string, Stmt\Function_> functions the snippet declares, by lowercase name */
    private $functions = [];
    /** @var array<string, Stmt\ClassLike> classes the snippet declares, by lowercase name */
    private $classes = [];
    /** @var Stmt\Expression|null the last statement, which the compiler turns into `return …;` */
    private $returned;

    /** @param \RunletVendor\PhpParser\Parser $parser */
    private function __construct(string $source, $parser, ?Stmt\Expression $returned)
    {
        $this->source = $source;
        $this->parser = $parser;
        $this->returned = $returned;
    }

    /** Quick check before any work: the snippet mentions a magic comment at all. */
    public static function mentioned(string $source): bool
    {
        return strpos($source, '//?') !== false || strpos($source, '/*?') !== false;
    }

    /**
     * Plans the probes for $source (already parsed into $statements by $parser).
     *
     * Returns `edits` ([offset, deleteLength, text, group, key1, key2], see SnippetCompiler),
     * `probes` (id => [line, kind, comment]), and `rejected` ([line, comment, reason]).
     * $returned is the final expression statement the compiler returns as the result:
     * a mark after it wraps its expression instead, since nothing after a return runs.
     *
     * @param Node\Stmt[] $statements
     * @param \RunletVendor\PhpParser\Parser $parser
     * @return array{edits: array<int, array<int, mixed>>, probes: array<int, array{line: int, kind: string, comment: string}>, rejected: array<int, array{line: int, comment: string, reason: string}>}
     */
    public static function plan(string $source, array $statements, $parser, ?Stmt\Expression $returned = null): array
    {
        $planner = new self($source, $parser, $returned);

        return $planner->run($statements);
    }

    /**
     * @param Node\Stmt[] $statements
     * @return array{edits: array<int, array<int, mixed>>, probes: array<int, array{line: int, kind: string, comment: string}>, rejected: array<int, array{line: int, comment: string, reason: string}>}
     */
    private function run(array $statements): array
    {
        $comments = $this->tokenize();
        $result = ['edits' => [], 'probes' => [], 'rejected' => []];
        if ($comments === []) {
            return $result;
        }
        $this->collectDeclarations($statements, '');
        $this->regions[] = ['open' => -1, 'close' => strlen($this->source), 'stmts' => $statements];
        $scope = ['byRef' => false, 'ns' => '', 'uses' => $this->collectUses($statements)];
        foreach ($statements as $statement) {
            $this->walk($statement, self::READ, null, '', null, $scope);
        }

        $id = 0;
        foreach ($comments as $comment) {
            $edits = [];
            $kind = '';
            $reason = $this->resolve($comment, $id + 1, $edits, $kind);
            if ($reason !== null) {
                $result['rejected'][] = ['line' => $comment['line'], 'comment' => self::shortComment($comment['text']), 'reason' => $reason, 'label' => self::label($reason)];
                continue;
            }
            $id++;
            $result['probes'][$id] = ['line' => $comment['line'], 'kind' => $kind, 'comment' => self::shortComment($comment['text'])];
            foreach ($edits as $edit) {
                $result['edits'][] = $edit;
            }
        }

        return $result;
    }

    // MARK: Tokens

    /**
     * Tokenizes the source and returns its magic comments in source order.
     *
     * @return array<int, array{form: string, text: string, offset: int, line: int, index: int, projection: string|null}>
     */
    private function tokenize(): array
    {
        $offset = 0;
        $line = 1;
        $stack = [];
        $comments = [];
        foreach (token_get_all($this->source) as $token) {
            if (is_array($token)) {
                [$id, $text] = $token;
            } else {
                $id = null;
                $text = $token;
            }
            $index = count($this->tokens);
            $this->tokens[] = [$id, $text, $offset, $line];
            $this->offsets[] = $offset;
            if ($id === null) {
                if ($text === '(' || $text === '{' || $text === '[') {
                    $stack[] = $index;
                } elseif ($text === ')' || $text === '}' || $text === ']') {
                    $open = array_pop($stack);
                    if ($open !== null) {
                        $this->match[$open] = $index;
                        $this->match[$index] = $open;
                    }
                }
            } elseif ($id === T_CURLY_OPEN || $id === T_DOLLAR_OPEN_CURLY_BRACES) {
                $stack[] = $index;
            } elseif ($id === T_COMMENT) {
                $form = self::form($text);
                if ($form !== null) {
                    $comments[] = ['form' => $form[0], 'text' => rtrim($text), 'offset' => $offset, 'line' => $line, 'index' => $index, 'projection' => $form[1]];
                }
            }
            $offset += strlen($text);
            $line += substr_count($text, "\n");
        }

        return $comments;
    }

    /**
     * The magic-comment form of a comment token, with a projection's chain: `line` (`//?`),
     * `value` (`/*?*\/`), `time` (`/*?.*\/`), `projection` (`/*?->…*\/` or `/*??->…*\/`).
     *
     * @return array{0: string, 1: string|null}|null
     */
    private static function form(string $text): ?array
    {
        if (preg_match('/^\/\/\?[ \t]*\r?\n?$/', $text)) {
            return ['line', null];
        }
        if (preg_match('/^\/\*\?\s*\*\/$/', $text)) {
            return ['value', null];
        }
        if (preg_match('/^\/\*\?\.\s*\*\/$/', $text)) {
            return ['time', null];
        }
        if (preg_match('/^\/\*\?(\??->.*?)\s*\*\/$/s', $text, $match)) {
            return ['projection', $match[1]];
        }

        return null;
    }

    /** A few words for the editor's inline text; the full reason shows on hover. */
    public static function label(string $reason): string
    {
        $labels = [
            'assigned or declared' => 'assigned here',
            'isset(), empty(), or ??' => 'inside isset/empty/??',
            'Constant expressions' => 'constant expression',
            '"{$…}"' => 'inside "{$…}"',
            'cannot tell whether' => 'may be by reference',
            'by reference' => 'taken by reference',
            'A projection is' => 'not a projection',
            'stop ?->' => 'would stop ?->',
            'exit has no value' => 'exit has no value',
            'cannot be wrapped' => 'cannot be wrapped',
            'could not add' => 'not added',
        ];
        foreach ($labels as $needle => $label) {
            if (strpos($reason, $needle) !== false) {
                return $label;
            }
        }

        return 'nothing to show';
    }

    private static function shortComment(string $text): string
    {
        $text = (string) preg_replace('/\s+/', ' ', $text);

        return strlen($text) > 80 ? substr($text, 0, 77) . '…' : $text;
    }

    private static function significant(?int $id): bool
    {
        return $id !== T_WHITESPACE && $id !== T_COMMENT && $id !== T_DOC_COMMENT;
    }

    /** Index of the first significant token starting at or after $offset. */
    private function nextSignificant(int $offset): ?int
    {
        $low = 0;
        $high = count($this->offsets);
        while ($low < $high) {
            $middle = intdiv($low + $high, 2);
            if ($this->offsets[$middle] < $offset) {
                $low = $middle + 1;
            } else {
                $high = $middle;
            }
        }
        for ($i = $low, $count = count($this->tokens); $i < $count; $i++) {
            if (self::significant($this->tokens[$i][0])) {
                return $i;
            }
        }

        return null;
    }

    /** Index of the last significant token before token $index. */
    private function previousSignificant(int $index): ?int
    {
        for ($i = $index - 1; $i >= 0; $i--) {
            if (self::significant($this->tokens[$i][0])) {
                return $i;
            }
        }

        return null;
    }

    private function tokenIndexAt(int $offset): ?int
    {
        $low = 0;
        $high = count($this->offsets) - 1;
        while ($low <= $high) {
            $middle = intdiv($low + $high, 2);
            if ($this->offsets[$middle] === $offset) {
                return $middle;
            }
            if ($this->offsets[$middle] < $offset) {
                $low = $middle + 1;
            } else {
                $high = $middle - 1;
            }
        }

        return null;
    }

    private function tokenText(?int $index): ?string
    {
        return $index === null ? null : $this->tokens[$index][1];
    }

    private function tokenEnd(int $index): int
    {
        return $this->tokens[$index][2] + strlen($this->tokens[$index][1]) - 1;
    }

    // MARK: Syntax tree

    /**
     * Records every expression (with the context it is evaluated in), every statement, and
     * every statement list ("region") where a statement can be inserted.
     *
     * @param array{call: Node, index: int, arg: Node\Arg}|null $call
     * @param array{byRef: bool, ns: string, uses: array<string, array<string, string>>} $scope
     */
    private function walk(Node $node, string $context, ?Node $parent, string $slot, ?array $call, array $scope): void
    {
        $start = $node->getStartFilePos();
        $end = $node->getEndFilePos();
        if ($start >= 0 && $end >= $start) {
            if ($node instanceof Expr) {
                $this->exprByEnd[$end][] = ['node' => $node, 'context' => $context, 'parent' => $parent, 'slot' => $slot, 'call' => $call, 'scope' => $scope];
            } elseif ($node instanceof Stmt && !($node instanceof Stmt\Nop)) {
                $this->stmtByEnd[$end][] = $node;
            }
        }

        $inner = $scope;
        if ($node instanceof Stmt\Namespace_) {
            $inner['ns'] = $node->name !== null ? $node->name->toString() : '';
            $inner['uses'] = $this->collectUses($node->stmts);
        }
        if ($node instanceof Node\FunctionLike) {
            $inner['byRef'] = $node->returnsByRef();
        }
        $this->recordRegions($node);

        foreach ($node->getSubNodeNames() as $name) {
            $value = $node->$name;
            $children = is_array($value) ? $value : [$value];
            foreach ($children as $index => $child) {
                if (!$child instanceof Node) {
                    continue;
                }
                [$childContext, $childCall] = $this->childContext($node, $name, $child, $context, is_int($index) ? $index : 0, $call, $inner);
                $this->walk($child, $childContext, $node, $name, $childCall, $inner);
            }
        }
    }

    /**
     * How $child (in $node's $name) is evaluated: read (a call may wrap it), written,
     * taken by reference, checked by isset/empty/??, a constant expression, the start of a
     * `{$…}` interpolation, a call argument (whether by reference depends on the callee), or
     * a slot that cannot hold a call at all.
     *
     * @param array{call: Node, index: int, arg: Node\Arg}|null $call
     * @param array{byRef: bool, ns: string, uses: array<string, array<string, string>>} $scope
     * @return array{0: string, 1: array{call: Node, index: int, arg: Node\Arg}|null}
     */
    private function childContext(Node $node, string $name, Node $child, string $context, int $index, ?array $call, array $scope): array
    {
        if ($context === self::CONSTANT || $name === 'attrGroups' || $node instanceof Node\AttributeGroup || $node instanceof Node\Attribute) {
            return [self::CONSTANT, null];
        }
        // Declarations.
        if ($node instanceof Node\Param) {
            return [$name === 'var' ? self::WRITE : ($name === 'default' ? self::CONSTANT : self::READ), null];
        }
        if ($node instanceof Node\Const_ || $node instanceof Node\DeclareItem) {
            return [$name === 'value' ? self::CONSTANT : self::READ, null];
        }
        if ($node instanceof Node\PropertyItem) {
            return [$name === 'default' ? self::CONSTANT : self::READ, null];
        }
        if ($node instanceof Node\StaticVar) {
            return [$name === 'var' ? self::WRITE : self::CONSTANT, null];
        }
        if ($node instanceof Stmt\EnumCase) {
            return [$name === 'expr' ? self::CONSTANT : self::READ, null];
        }
        if ($node instanceof Node\ClosureUse || $node instanceof Stmt\Global_ || $node instanceof Stmt\Unset_) {
            return [self::WRITE, null];
        }
        if ($node instanceof Stmt\Catch_) {
            return [$name === 'var' ? self::WRITE : self::READ, null];
        }
        // Writes.
        if ($node instanceof Expr\Assign || $node instanceof Expr\AssignOp) {
            return [$name === 'var' ? self::WRITE : self::READ, null];
        }
        if ($node instanceof Expr\AssignRef) {
            return [$name === 'var' ? self::WRITE : self::REF, null];
        }
        if ($node instanceof Expr\PreInc || $node instanceof Expr\PreDec || $node instanceof Expr\PostInc || $node instanceof Expr\PostDec) {
            return [self::WRITE, null];
        }
        if ($node instanceof Stmt\Foreach_) {
            if ($name === 'expr') {
                return [$node->byRef ? self::REF : self::READ, null];
            }

            return [$name === 'keyVar' || $name === 'valueVar' ? self::WRITE : self::READ, null];
        }
        if ($node instanceof Expr\List_) {
            return [self::WRITE, null];
        }
        if ($node instanceof Expr\Array_) {
            return [$context === self::WRITE || $context === self::REF ? self::WRITE : self::READ, null];
        }
        if ($node instanceof Node\ArrayItem) {
            if ($name !== 'value') {
                return [self::READ, null];
            }
            if ($context === self::WRITE) {
                return [self::WRITE, null];
            }

            return [$node->byRef ? self::REF_ITEM : self::READ, null];
        }
        // isset(), empty(), and ?? read without warnings.
        if ($node instanceof Expr\Isset_ || $node instanceof Expr\Empty_) {
            return [self::ISSET, null];
        }
        if ($node instanceof Expr\BinaryOp\Coalesce) {
            return [$name === 'left' ? self::ISSET : self::READ, null];
        }
        // `"{$…}"`: the expression must start with a variable.
        if ($node instanceof Node\Scalar\InterpolatedString || $node instanceof Expr\ShellExec) {
            return [self::INTERPOLATION, null];
        }
        // Fetch chains carry their context to the start of the chain.
        if ($node instanceof Expr\ArrayDimFetch) {
            return $name === 'var' ? [self::chain($context), $call] : [self::READ, null];
        }
        if ($node instanceof Expr\PropertyFetch || $node instanceof Expr\NullsafePropertyFetch) {
            return $name === 'var' ? [self::chain($context), $call] : [self::NO_WRAP, null];
        }
        if ($node instanceof Expr\StaticPropertyFetch || $node instanceof Expr\ClassConstFetch || $node instanceof Expr\Variable) {
            return [self::NO_WRAP, null];
        }
        if ($node instanceof Expr\MethodCall || $node instanceof Expr\NullsafeMethodCall || $node instanceof Expr\StaticCall || $node instanceof Expr\FuncCall || $node instanceof Expr\New_) {
            if ($name === 'args') {
                return $child instanceof Node\Arg ? [self::ARGUMENT_NODE, ['call' => $node, 'index' => $index, 'arg' => $child]] : [self::READ, null];
            }
            if (($node instanceof Expr\MethodCall || $node instanceof Expr\NullsafeMethodCall) && $name === 'var') {
                return [$context === self::INTERPOLATION || $context === self::NO_WRAP ? $context : self::READ, null];
            }
            if ($node instanceof Expr\FuncCall && $name === 'name') {
                return [$context === self::INTERPOLATION || $context === self::NO_WRAP ? $context : self::READ, null];
            }
            if ($node instanceof Expr\New_ && $child instanceof Stmt\Class_) {
                return [self::READ, null];
            }

            return [self::NO_WRAP, null];
        }
        if ($node instanceof Expr\Instanceof_) {
            return [$name === 'expr' ? self::READ : self::NO_WRAP, null];
        }
        if ($node instanceof Node\Arg) {
            if ($name !== 'value') {
                return [self::READ, null];
            }

            return $node->byRef ? [self::REF_SYNTAX, null] : [self::ARGUMENT, $call];
        }
        // Values returned or yielded by reference.
        if ($node instanceof Stmt\Return_ || ($node instanceof Expr\Yield_ && $name === 'value')) {
            return [$scope['byRef'] ? self::REF : self::READ, null];
        }
        if (($node instanceof Expr\ArrowFunction && $name === 'expr') || ($node instanceof Node\PropertyHook && $name === 'body' && $child instanceof Expr)) {
            return [$node->byRef ? self::REF : self::READ, null];
        }

        return [self::READ, null];
    }

    /** The context of the expression a fetch reads from: a written `$a[1]` writes into `$a`. */
    private static function chain(string $context): string
    {
        switch ($context) {
            case self::WRITE:
            case self::REF:
            case self::REF_ITEM:
                return self::WRITE;
            case self::ARGUMENT:
            case self::ARGUMENT_CHAIN:
                return self::ARGUMENT_CHAIN;
            case self::ISSET:
            case self::INTERPOLATION:
            case self::NO_WRAP:
            case self::CONSTANT:
                return $context;
            default:
                return self::READ;
        }
    }

    /**
     * `use` imports of one namespace (or the file): class and function aliases.
     *
     * @param Node\Stmt[] $statements
     * @return array<string, array<string, string>>
     */
    private function collectUses(array $statements): array
    {
        $uses = ['class' => [], 'function' => []];
        foreach ($statements as $statement) {
            if ($statement instanceof Stmt\Use_ || $statement instanceof Stmt\GroupUse) {
                $prefix = $statement instanceof Stmt\GroupUse ? $statement->prefix->toString() . '\\' : '';
                foreach ($statement->uses as $use) {
                    $type = $use->type !== Stmt\Use_::TYPE_UNKNOWN ? $use->type : $statement->type;
                    $kind = $type === Stmt\Use_::TYPE_FUNCTION ? 'function' : ($type === Stmt\Use_::TYPE_NORMAL ? 'class' : null);
                    if ($kind !== null) {
                        $uses[$kind][strtolower($use->getAlias()->toString())] = $prefix . $use->name->toString();
                    }
                }
            }
        }

        return $uses;
    }

    /**
     * Functions and classes the snippet declares, by fully qualified lowercase name.
     *
     * @param Node[] $nodes
     */
    private function collectDeclarations(array $nodes, string $namespace): void
    {
        foreach ($nodes as $node) {
            if (!$node instanceof Node) {
                continue;
            }
            if ($node instanceof Stmt\Namespace_) {
                $this->collectDeclarations($node->stmts, $node->name !== null ? $node->name->toString() : '');
                continue;
            }
            if ($node instanceof Stmt\Function_) {
                $this->functions[strtolower(ltrim($namespace . '\\' . $node->name->toString(), '\\'))] = $node;
            } elseif ($node instanceof Stmt\ClassLike && $node->name !== null) {
                $this->classes[strtolower(ltrim($namespace . '\\' . $node->name->toString(), '\\'))] = $node;
            }
            foreach (['stmts', 'else', 'elseifs', 'cases', 'catches', 'finally'] as $name) {
                if (!property_exists($node, $name)) {
                    continue;
                }
                $value = $node->$name;
                $this->collectDeclarations(is_array($value) ? $value : [$value], $namespace);
            }
        }
    }

    /** Records the statement lists inside $node where a statement can be inserted. */
    private function recordRegions(Node $node): void
    {
        if (($node instanceof Stmt\Function_ || $node instanceof Stmt\ClassMethod || $node instanceof Expr\Closure
                || $node instanceof Stmt\Catch_ || $node instanceof Stmt\Finally_ || $node instanceof Stmt\Block) && is_array($node->stmts ?? null)) {
            $close = $this->tokenIndexAt($node->getEndFilePos());
            if ($close !== null && $this->tokenText($close) === '}' && isset($this->match[$close])) {
                $this->addRegion($this->match[$close], $close, $node->stmts);
            }

            return;
        }
        if ($node instanceof Stmt\TryCatch || $node instanceof Stmt\Do_) {
            $open = $this->nextSignificant($node->getStartFilePos() + ($node instanceof Stmt\TryCatch ? 3 : 2));
            if ($open !== null && $this->tokenText($open) === '{' && isset($this->match[$open])) {
                $this->addRegion($open, $this->match[$open], $node->stmts);
            }

            return;
        }
        if ($node instanceof Stmt\If_) {
            $clauses = array_merge([$node], $node->elseifs, $node->else !== null ? [$node->else] : []);
            foreach ($clauses as $i => $clause) {
                $next = $clauses[$i + 1] ?? null;
                $altClose = $next !== null ? $next->getStartFilePos() - 1 : $node->getEndFilePos();
                if ($clause instanceof Stmt\Else_) {
                    $open = $this->nextSignificant($clause->getStartFilePos() + 4);
                } else {
                    $open = $this->afterParenthesis($clause->cond->getEndFilePos());
                }
                $this->addBodyRegion($open, $altClose, $clause->stmts);
            }

            return;
        }
        if ($node instanceof Stmt\While_) {
            $this->addBodyRegion($this->afterParenthesis($node->cond->getEndFilePos()), $node->getEndFilePos(), $node->stmts);

            return;
        }
        if ($node instanceof Stmt\Foreach_) {
            $this->addBodyRegion($this->afterParenthesis($node->valueVar->getEndFilePos()), $node->getEndFilePos(), $node->stmts);

            return;
        }
        if ($node instanceof Stmt\For_) {
            $keyword = $this->nextSignificant($node->getStartFilePos());
            $parenthesis = $keyword !== null ? $this->nextSignificant($this->tokenEnd($keyword) + 1) : null;
            if ($parenthesis !== null && $this->tokenText($parenthesis) === '(' && isset($this->match[$parenthesis])) {
                $this->addBodyRegion($this->nextSignificant($this->tokenEnd($this->match[$parenthesis]) + 1), $node->getEndFilePos(), $node->stmts);
            }

            return;
        }
        if ($node instanceof Stmt\Declare_ && is_array($node->stmts)) {
            $last = end($node->declares);
            if ($last !== false) {
                $this->addBodyRegion($this->afterParenthesis($last->getEndFilePos()), $node->getEndFilePos(), $node->stmts);
            }

            return;
        }
        if ($node instanceof Stmt\Switch_) {
            $close = $this->tokenIndexAt($node->getEndFilePos());
            $switchClose = $close !== null && $this->tokenText($close) === '}' ? $node->getEndFilePos() - 1 : $node->getEndFilePos();
            foreach ($node->cases as $i => $case) {
                $after = $case->cond !== null ? $case->cond->getEndFilePos() + 1 : $case->getStartFilePos() + 7;
                $open = $this->nextSignificant($after);
                if ($open !== null && ($this->tokenText($open) === ':' || $this->tokenText($open) === ';')) {
                    $next = $node->cases[$i + 1] ?? null;
                    $this->addRegion($open, null, $case->stmts, $next !== null ? $next->getStartFilePos() - 1 : $switchClose);
                }
            }

            return;
        }
        if ($node instanceof Stmt\Namespace_) {
            $after = $node->name !== null ? $node->name->getEndFilePos() + 1 : $node->getStartFilePos() + 9;
            $open = $this->nextSignificant($after);
            if ($open === null) {
                return;
            }
            if ($this->tokenText($open) === '{' && isset($this->match[$open])) {
                $this->addRegion($open, $this->match[$open], $node->stmts);
            } elseif ($this->tokenText($open) === ';') {
                // `namespace A;` holds the statements up to the next namespace.
                $this->addRegion($open, null, $node->stmts, max($node->getEndFilePos(), $this->tokens[$open][2]));
            }
        }
    }

    /** The first significant token after the `)` that follows offset $end. */
    private function afterParenthesis(int $end): ?int
    {
        $parenthesis = $this->nextSignificant($end + 1);
        if ($parenthesis === null || $this->tokenText($parenthesis) !== ')') {
            return null;
        }

        return $this->nextSignificant($this->tokenEnd($parenthesis) + 1);
    }

    /**
     * A body opened by `{` (closed by its `}`) or `:` (alternative syntax, closed at
     * $altClose). A single statement without braces has no region.
     *
     * @param Node\Stmt[] $statements
     */
    private function addBodyRegion(?int $open, int $altClose, array $statements): void
    {
        if ($open === null) {
            return;
        }
        if ($this->tokenText($open) === '{' && isset($this->match[$open])) {
            $this->addRegion($open, $this->match[$open], $statements);
        } elseif ($this->tokenText($open) === ':') {
            $this->addRegion($open, null, $statements, $altClose);
        }
    }

    /** @param Node\Stmt[] $statements */
    private function addRegion(int $openIndex, ?int $closeIndex, array $statements, ?int $closeOffset = null): void
    {
        $close = $closeIndex !== null ? $this->tokens[$closeIndex][2] - 1 : (int) $closeOffset;
        $this->regions[] = ['open' => $this->tokens[$openIndex][2], 'close' => $close, 'stmts' => $statements];
    }

    // MARK: Resolution

    /**
     * Plans one magic comment's probe. Returns null and fills $edits and $kind, or returns
     * why the comment cannot be shown.
     *
     * @param array{form: string, text: string, offset: int, line: int, index: int, projection: string|null} $comment
     * @param array<int, array<int, mixed>> $edits
     */
    private function resolve(array $comment, int $id, array &$edits, string &$kind): ?string
    {
        $previous = $this->previousSignificant($comment['index']);
        if ($previous === null) {
            return 'There is nothing before it to show.';
        }
        $projection = null;
        if ($comment['form'] === 'projection') {
            $projection = $this->projection((string) $comment['projection']);
            if ($projection === null) {
                return 'A projection is a chain that starts with -> or ?->, such as /*?->count()*/.';
            }
        }
        // `//?` at the end of a line inside a list (`foo($a, //?`) refers to the item before the comma.
        if ($comment['form'] === 'line' && $this->tokenText($previous) === ',') {
            $beforeComma = $this->previousSignificant($previous);
            if ($beforeComma !== null && $this->candidates($this->tokenEnd($beforeComma), $beforeComma) !== []) {
                $previous = $beforeComma;
            }
        }
        $previousEnd = $this->tokenEnd($previous);
        // `//?` is about its own line; a statement's value shows on the line it ends on.
        $sameLine = $this->tokens[$previous][3] + substr_count($this->tokens[$previous][1], "\n") === $comment['line'];

        // 1. An expression ends right before the comment.
        $candidates = $comment['form'] === 'line' && !$sameLine ? [] : $this->candidates($previousEnd, $previous);
        if ($candidates !== []) {
            $firstReason = null;
            foreach ($candidates as $entry) {
                $mode = $this->mode($entry, $reason);
                if ($mode !== null) {
                    return $this->wrap($entry, $mode, $comment['form'], $projection, $id, $edits, $kind);
                }
                $firstReason = $firstReason ?? $reason;
            }

            return $firstReason;
        }

        // 2. A statement with a value ends right before it on the same line: show that value.
        if ($comment['form'] !== 'time' && $sameLine) {
            foreach (array_reverse($this->stmtByEnd[$previousEnd] ?? []) as $statement) {
                $reason = $this->statementValue($statement, $comment['form'], $projection, $id, $edits, $kind);
                if ($reason !== false) {
                    return $reason;
                }
            }
        }

        // 3. Between statements: mark that the line was reached (or the time at that point).
        if ($comment['form'] !== 'projection') {
            $at = $this->gapInsertion($comment['offset'], $previous);
            if ($at !== null) {
                $kind = $comment['form'] === 'time' ? 'time' : 'reached';
                $returned = $this->returned;
                if ($returned !== null && $at > $returned->getEndFilePos()) {
                    // After the statement the compiler returns: mark once its value is ready.
                    $start = $returned->expr->getStartFilePos();
                    $end = $returned->expr->getEndFilePos();
                    $edits[] = [$start, 0, self::PROBE . ($kind === 'time' ? 'time(' : 'reached(') . $id . ', ', 4, $start - $end, -$id];
                    $edits[] = [$end + 1, 0, ')', 0, $end - $start, $id];

                    return null;
                }
                $call = $comment['form'] === 'time' ? 'mark' : 'hit';
                $edits[] = [$at, 0, self::PROBE . $call . '(' . $id . ');', 2, $id, 0];

                return null;
            }
        }

        return $comment['form'] === 'line'
            ? 'Nothing on this line has a value to show: put //? after a statement or an expression.'
            : 'Put it right after an expression, such as $total /*?*/ or $query->get() /*?->count()*/.';
    }

    /**
     * Expressions that end at $end, outermost first. A parenthesized expression ends inside
     * its parentheses, so `($a + $b) /*?*\/` finds `$a + $b`.
     *
     * @return array<int, array<string, mixed>>
     */
    private function candidates(int $end, int $tokenIndex): array
    {
        if (isset($this->exprByEnd[$end])) {
            // `fn ($x) => $x * 2 /*?*\/` means the body, not the closure (nor `$f = fn …`);
            // `yield $i /*?*\/` the yielded value, not the one sent back; same for print, throw.
            $candidates = $this->exprByEnd[$end];
            for ($i = count($candidates) - 1; $i >= 0; $i--) {
                $node = $candidates[$i]['node'];
                if ($node instanceof Expr\ArrowFunction || $node instanceof Expr\Yield_ || $node instanceof Expr\Print_ || $node instanceof Expr\Throw_) {
                    $inner = array_slice($candidates, $i + 1);

                    return $inner !== [] ? $inner : $candidates;
                }
            }

            return $candidates;
        }
        // Strip parentheses: `(…)` around one expression.
        while ($this->tokenText($tokenIndex) === ')' && isset($this->match[$tokenIndex])) {
            $open = $this->match[$tokenIndex];
            $first = $this->nextSignificant($this->tokenEnd($open) + 1);
            $last = $this->previousSignificant($tokenIndex);
            if ($first === null || $last === null || $first > $last) {
                return [];
            }
            $start = $this->tokens[$first][2];
            $innerEnd = $this->tokenEnd($last);
            $found = array_values(array_filter($this->exprByEnd[$innerEnd] ?? [], static function (array $entry) use ($start): bool {
                return $entry['node']->getStartFilePos() === $start;
            }));
            if ($found !== []) {
                return $found;
            }
            $tokenIndex = $last;
        }

        return [];
    }

    /**
     * How a probe can wrap $entry: `value` (a call taking the value), `ref` (a call taking
     * and returning a reference, where the code takes the expression by reference), or null
     * with the reason in $reason.
     *
     * @param array<string, mixed> $entry
     */
    private function mode(array $entry, ?string &$reason): ?string
    {
        $node = $entry['node'];
        $mode = null;
        switch ($entry['context']) {
            case self::READ:
                $mode = 'value';
                break;
            case self::WRITE:
                $reason = 'It is where a value is assigned or declared, not read.';
                break;
            case self::REF:
                if (self::writable($node)) {
                    $mode = 'ref';
                } else {
                    $reason = 'This value is taken by reference.';
                }
                break;
            case self::REF_ITEM:
            case self::REF_SYNTAX:
                $reason = 'This value is taken by reference (&).';
                break;
            case self::ISSET:
                if (self::writable($node)) {
                    $reason = 'It is checked with isset(), empty(), or ??, so reading it could warn.';
                } else {
                    $mode = 'value';
                }
                break;
            case self::CONSTANT:
                $reason = 'Constant expressions (defaults, constants, attributes) cannot call code.';
                break;
            case self::INTERPOLATION:
                $reason = 'Inside "{$…}" the expression has to start with a variable: put the comment after the string.';
                break;
            case self::ARGUMENT:
            case self::ARGUMENT_CHAIN:
                $byRef = $this->argumentByRef($entry['call']);
                $writable = $entry['context'] === self::ARGUMENT && self::writable($node);
                if ($byRef === true) {
                    if ($writable) {
                        $mode = 'ref';
                    } else {
                        $reason = 'The function takes this argument by reference.';
                    }
                } elseif ($byRef === false || (!$writable && $entry['context'] === self::ARGUMENT)) {
                    $mode = 'value';
                } else {
                    $reason = 'Runlet cannot tell whether this argument is passed by reference: put the comment after the call.';
                }
                break;
            default:
                $reason = 'This part of the expression cannot be wrapped.';
        }
        if ($mode !== null && $this->breaksNullsafe($entry)) {
            $reason = 'It would stop ?-> from skipping the rest of the chain: put the comment right before ?-> or after the chain.';
            $mode = null;
        }

        return $mode;
    }

    /** Variables, array elements, and properties: what PHP can pass or bind by reference. */
    private static function writable(Node $node): bool
    {
        if ($node instanceof Expr\Variable) {
            return $node->name !== 'this';
        }

        return $node instanceof Expr\ArrayDimFetch || $node instanceof Expr\PropertyFetch || $node instanceof Expr\StaticPropertyFetch;
    }

    /**
     * A nullsafe chain short-circuits to its end: in `$a?->b()->c()`, a null `$a` skips
     * `->c()` too. Wrapping `$a?->b()` would end the chain there and call `c()` on null.
     *
     * @param array<string, mixed> $entry
     */
    private function breaksNullsafe(array $entry): bool
    {
        $parent = $entry['parent'];
        $continues = ($entry['slot'] === 'var' && ($parent instanceof Expr\MethodCall || $parent instanceof Expr\PropertyFetch || $parent instanceof Expr\ArrayDimFetch))
            || ($entry['slot'] === 'name' && $parent instanceof Expr\FuncCall)
            || ($entry['slot'] === 'class' && ($parent instanceof Expr\StaticCall || $parent instanceof Expr\StaticPropertyFetch || $parent instanceof Expr\ClassConstFetch));
        if (!$continues) {
            return false;
        }
        $node = $entry['node'];
        while ($node instanceof Expr) {
            if ($node instanceof Expr\NullsafeMethodCall || $node instanceof Expr\NullsafePropertyFetch) {
                return true;
            }
            if ($node instanceof Expr\MethodCall || $node instanceof Expr\PropertyFetch || $node instanceof Expr\ArrayDimFetch) {
                $node = $node->var;
            } elseif ($node instanceof Expr\FuncCall && $node->name instanceof Expr) {
                $node = $node->name;
            } elseif (($node instanceof Expr\StaticCall || $node instanceof Expr\StaticPropertyFetch || $node instanceof Expr\ClassConstFetch) && $node->class instanceof Expr) {
                $node = $node->class;
            } else {
                break;
            }
        }

        return false;
    }

    /**
     * Whether the called function takes this argument by reference: true, false, or null
     * when Runlet cannot tell (a method on an object, a class not loaded yet, a dynamic name).
     * Classes are never autoloaded for this.
     *
     * @param array{call: Node, index: int, arg: Node\Arg} $call
     */
    private function argumentByRef(array $call): ?bool
    {
        $node = $call['call'];
        $arg = $call['arg'];
        foreach (array_slice($node->args, 0, $call['index']) as $earlier) {
            if ($earlier instanceof Node\Arg && $earlier->unpack) {
                return null;
            }
        }
        $parameters = null;
        $scope = $this->scopeOf($node);
        if ($node instanceof Expr\FuncCall && $node->name instanceof Node\Name) {
            $parameters = $this->functionParameters($node->name, $scope);
        } elseif ($node instanceof Expr\StaticCall && $node->class instanceof Node\Name && $node->name instanceof Node\Identifier) {
            $parameters = $this->methodParameters($node->class, $node->name->toString(), $scope);
        } elseif ($node instanceof Expr\New_ && $node->class instanceof Node\Name) {
            $parameters = $this->methodParameters($node->class, '__construct', $scope);
        }
        if ($parameters === null) {
            return null;
        }
        if ($arg->unpack) {
            foreach (array_slice($parameters, $call['index']) as $parameter) {
                if ($parameter['byRef']) {
                    return true;
                }
            }

            return false;
        }
        if ($arg->name !== null) {
            foreach ($parameters as $parameter) {
                if ($parameter['name'] === $arg->name->toString()) {
                    return $parameter['byRef'];
                }
            }
            $last = end($parameters);

            return $last !== false && $last['variadic'] ? $last['byRef'] : false;
        }
        if (isset($parameters[$call['index']])) {
            return $parameters[$call['index']]['byRef'];
        }
        $last = end($parameters);

        return $last !== false && $last['variadic'] ? $last['byRef'] : false;
    }

    /**
     * The scope a call was recorded with.
     *
     * @return array{byRef: bool, ns: string, uses: array<string, array<string, string>>}
     */
    private function scopeOf(Node $node): array
    {
        foreach ($this->exprByEnd[$node->getEndFilePos()] ?? [] as $entry) {
            if ($entry['node'] === $node) {
                return $entry['scope'];
            }
        }

        return ['byRef' => false, 'ns' => '', 'uses' => ['class' => [], 'function' => []]];
    }

    /**
     * @param array{byRef: bool, ns: string, uses: array<string, array<string, string>>} $scope
     * @return array<int, array{name: string, byRef: bool, variadic: bool}>|null
     */
    private function functionParameters(Node\Name $name, array $scope): ?array
    {
        $candidates = [];
        $text = $name->toString();
        if ($name->isFullyQualified()) {
            $candidates[] = $text;
        } elseif ($name->isUnqualified()) {
            $alias = $scope['uses']['function'][strtolower($text)] ?? null;
            if ($alias !== null) {
                $candidates[] = $alias;
            } else {
                if ($scope['ns'] !== '') {
                    $candidates[] = $scope['ns'] . '\\' . $text;
                }
                $candidates[] = $text;
            }
        } else {
            $candidates[] = $this->qualify($name, $scope);
        }
        foreach ($candidates as $candidate) {
            $key = strtolower(ltrim($candidate, '\\'));
            if (isset($this->functions[$key])) {
                return self::astParameters($this->functions[$key]->params);
            }
            if (function_exists($key)) {
                try {
                    return self::reflectedParameters((new \ReflectionFunction($key))->getParameters());
                } catch (\Throwable $error) {
                    return null;
                }
            }
        }

        return null;
    }

    /**
     * @param array{byRef: bool, ns: string, uses: array<string, array<string, string>>} $scope
     * @return array<int, array{name: string, byRef: bool, variadic: bool}>|null
     */
    private function methodParameters(Node\Name $class, string $method, array $scope, int $depth = 0): ?array
    {
        $lower = strtolower($class->toString());
        if ($depth > 10 || in_array($lower, ['self', 'static', 'parent'], true)) {
            return null;
        }
        $name = strtolower(ltrim($this->qualify($class, $scope), '\\'));
        if (isset($this->classes[$name])) {
            $declaration = $this->classes[$name];
            foreach ($declaration->getMethods() as $candidate) {
                if (strcasecmp($candidate->name->toString(), $method) === 0) {
                    return self::astParameters($candidate->params);
                }
            }
            if ($declaration instanceof Stmt\Class_ && $declaration->extends !== null) {
                return $this->methodParameters($declaration->extends, $method, $scope, $depth + 1);
            }

            return $method === '__construct' && $declaration instanceof Stmt\Class_ && $declaration->extends === null ? [] : null;
        }
        if (!class_exists($name, false) && !interface_exists($name, false) && !trait_exists($name, false)) {
            return null;
        }
        try {
            $reflection = new \ReflectionClass($name);
            if ($reflection->hasMethod($method)) {
                return self::reflectedParameters($reflection->getMethod($method)->getParameters());
            }
            if ($method === '__construct') {
                return [];
            }
            // __callStatic() receives its arguments as an array: always by value.
            return $reflection->hasMethod('__callStatic') ? [] : null;
        } catch (\Throwable $error) {
            return null;
        }
    }

    /** @param array{byRef: bool, ns: string, uses: array<string, array<string, string>>} $scope */
    private function qualify(Node\Name $name, array $scope): string
    {
        if ($name->isFullyQualified()) {
            return $name->toString();
        }
        $parts = explode('\\', $name->toString());
        $alias = $scope['uses']['class'][strtolower($parts[0])] ?? null;
        if ($alias !== null) {
            $parts[0] = $alias;

            return implode('\\', $parts);
        }

        return ($scope['ns'] !== '' ? $scope['ns'] . '\\' : '') . $name->toString();
    }

    /**
     * @param Node\Param[] $params
     * @return array<int, array{name: string, byRef: bool, variadic: bool}>
     */
    private static function astParameters(array $params): array
    {
        $result = [];
        foreach ($params as $param) {
            $result[] = ['name' => $param->var instanceof Expr\Variable && is_string($param->var->name) ? $param->var->name : '', 'byRef' => $param->byRef, 'variadic' => $param->variadic];
        }

        return $result;
    }

    /**
     * @param \ReflectionParameter[] $params
     * @return array<int, array{name: string, byRef: bool, variadic: bool}>
     */
    private static function reflectedParameters(array $params): array
    {
        $result = [];
        foreach ($params as $param) {
            $result[] = ['name' => $param->getName(), 'byRef' => $param->isPassedByReference(), 'variadic' => $param->isVariadic()];
        }

        return $result;
    }

    /**
     * The value of a statement that ends right before the comment: an expression statement,
     * a return, or an echo. Returns false when $statement has no value, null when planned,
     * or a reason.
     *
     * @param array<int, array<int, mixed>> $edits
     * @return string|false|null
     */
    private function statementValue(Node\Stmt $statement, string $form, ?string $projection, int $id, array &$edits, string &$kind)
    {
        $target = null;
        if ($statement instanceof Stmt\Expression) {
            $expr = $statement->expr;
            if ($expr instanceof Expr\Print_ || $expr instanceof Expr\Throw_) {
                $expr = $expr->expr;
            } elseif ($expr instanceof Expr\Yield_ && $expr->value !== null) {
                $expr = $expr->value;
            } elseif ($expr instanceof Expr\Exit_) {
                if ($expr->expr === null) {
                    return 'exit has no value to show.';
                }
                $expr = $expr->expr;
            } elseif (($expr instanceof Expr\PostInc || $expr instanceof Expr\PostDec) && $projection === null
                && $expr->var instanceof Expr\Variable && is_string($expr->var->name) && $expr->var->name !== 'this') {
                // `$i++; //?` shows $i after the increment (PHP's value of `$i++` is the old one).
                $start = $expr->getStartFilePos();
                $end = $expr->getEndFilePos();
                $edits[] = [$start, 0, self::PROBE . 'after(' . $id . ', ', 4, $start - $end, -$id];
                $edits[] = [$end + 1, 0, ', $' . $expr->var->name . ')', 0, $end - $start, $id];
                $kind = 'value';

                return null;
            }
            $target = $expr;
        } elseif ($statement instanceof Stmt\Return_) {
            if ($statement->expr === null) {
                return false;
            }
            $target = $statement->expr;
        } elseif ($statement instanceof Stmt\Echo_) {
            if (count($statement->exprs) === 1 || $projection !== null) {
                $target = end($statement->exprs);
            } else {
                $count = count($statement->exprs);
                foreach ($statement->exprs as $i => $expr) {
                    $start = $expr->getStartFilePos();
                    $end = $expr->getEndFilePos();
                    $edits[] = [$start, 0, self::PROBE . 'echoArg(' . $id . ', ' . $i . ', ' . $count . ', ', 4, $start - $end, -$id];
                    $edits[] = [$end + 1, 0, ')', 0, $end - $start, $id];
                }
                $kind = 'value';

                return null;
            }
        } else {
            return false;
        }
        $entry = null;
        foreach ($this->exprByEnd[$target->getEndFilePos()] ?? [] as $candidate) {
            if ($candidate['node'] === $target) {
                $entry = $candidate;
                break;
            }
        }
        if ($entry === null) {
            return false;
        }
        $mode = $this->mode($entry, $reason);
        if ($mode === null) {
            return $reason;
        }

        return $this->wrap($entry, $mode, $form, $projection, $id, $edits, $kind);
    }

    /**
     * Wraps the expression: `Probe::at(id, <expr>)`, `Probe::ref(…)` where it is taken by
     * reference, `Probe::tap(id, <expr>, fn ($v) => $v->projection)`, or `Probe::time(…)`.
     *
     * @param array<string, mixed> $entry
     * @param array<int, array<int, mixed>> $edits
     */
    private function wrap(array $entry, string $mode, string $form, ?string $projection, int $id, array &$edits, string &$kind): ?string
    {
        $node = $entry['node'];
        $start = $node->getStartFilePos();
        $end = $node->getEndFilePos();
        if ($form === 'time') {
            if ($mode === 'ref') {
                return 'This value is taken by reference: put /*?.*/ after the statement instead.';
            }
            $open = 'time(' . $id . ', ';
            $close = ')';
            $kind = 'time';
        } elseif ($form === 'projection') {
            if ($mode === 'ref') {
                return 'This value is taken by reference, so a projection cannot wrap it.';
            }
            $open = 'tap(' . $id . ', ';
            $close = ', fn (' . self::PROJECTION_VARIABLE . ') => ' . self::PROJECTION_VARIABLE . $projection . ')';
            $kind = 'value';
        } else {
            $open = ($mode === 'ref' ? 'ref(' : 'at(') . $id . ', ';
            $close = ')';
            $kind = 'value';
        }
        $edits[] = [$start, 0, self::PROBE . $open, 4, $start - $end, -$id];
        $edits[] = [$end + 1, 0, $close, 0, $end - $start, $id];

        return null;
    }

    /**
     * Validates a projection (`->count()`, `?->name`, `->items[0]->id`) and returns it on one
     * line without comments, or null.
     */
    private function projection(string $chain): ?string
    {
        $tokens = token_get_all('<?php ' . self::PROJECTION_VARIABLE . $chain . ';');
        $text = '';
        foreach (array_slice($tokens, 1) as $token) {
            if (is_array($token)) {
                if ($token[0] === T_COMMENT || $token[0] === T_DOC_COMMENT) {
                    continue;
                }
                if ($token[0] === T_WHITESPACE) {
                    $text .= ' ';
                    continue;
                }
                if (strpos($token[1], "\n") !== false || strpos($token[1], "\r") !== false) {
                    return null;
                }
                $text .= $token[1];
            } else {
                $text .= $token;
            }
        }
        try {
            $statements = $this->parser->parse('<?php ' . $text);
        } catch (\Throwable $error) {
            return null;
        }
        if ($statements === null || count($statements) !== 1 || !$statements[0] instanceof Stmt\Expression) {
            return null;
        }
        // A chain of fetches and calls that starts at the value with -> or ?->.
        $node = $statements[0]->expr;
        $first = null;
        while ($node instanceof Expr\MethodCall || $node instanceof Expr\NullsafeMethodCall || $node instanceof Expr\PropertyFetch
            || $node instanceof Expr\NullsafePropertyFetch || $node instanceof Expr\ArrayDimFetch) {
            $first = $node;
            $node = $node->var;
        }
        if (!$node instanceof Expr\Variable || $node->name !== substr(self::PROJECTION_VARIABLE, 1) || $first === null || $first instanceof Expr\ArrayDimFetch) {
            return null;
        }
        $result = substr(rtrim($text), strlen(self::PROJECTION_VARIABLE));

        return rtrim(substr($result, 0, -1));
    }

    /**
     * Where a statement can go for a comment between statements (`foreach (…) { //?`,
     * `} /*?.*\/`), or null. Before a `return`, `break`, `continue`, `throw`, or `exit` that
     * ends right before the comment, so the probe runs.
     */
    private function gapInsertion(int $offset, int $previous): ?int
    {
        $region = null;
        foreach ($this->regions as $candidate) {
            if ($candidate['open'] < $offset && $offset <= $candidate['close'] && ($region === null || $candidate['open'] > $region['open'])) {
                $region = $candidate;
            }
        }
        if ($region === null) {
            return null;
        }
        foreach ($region['stmts'] as $statement) {
            if ($statement->getStartFilePos() <= $offset && $offset <= $statement->getEndFilePos()) {
                return null;
            }
        }
        [$id, $text, $previousOffset] = $this->tokens[$previous];
        if ($previousOffset < $region['open']) {
            return null;
        }
        if (!in_array($text, ['{', '}', ';', ':'], true) && $id !== T_OPEN_TAG) {
            return null;
        }
        $previousEnd = $this->tokenEnd($previous);
        foreach ($region['stmts'] as $statement) {
            if ($statement->getEndFilePos() === $previousEnd && self::isJump($statement)) {
                return $statement->getStartFilePos();
            }
        }

        return $offset;
    }

    private static function isJump(Node\Stmt $statement): bool
    {
        if ($statement instanceof Stmt\Return_ || $statement instanceof Stmt\Break_ || $statement instanceof Stmt\Continue_ || $statement instanceof Stmt\Goto_) {
            return true;
        }

        return $statement instanceof Stmt\Expression && ($statement->expr instanceof Expr\Throw_ || $statement->expr instanceof Expr\Exit_);
    }
}

/**
 * Records magic-comment hits while the snippet runs and streams them as `inline` events.
 * Every method returns quickly and never throws or calls user code, except a projection's
 * own chain. Limits: the first 100 hits of each probe carry values; after that hits are
 * counted and a value is sent about four times a second; values stop (counts continue)
 * once 16 MiB of values were sent in the run.
 */
final class Probe
{
    /** @var bool */
    private static $active = false;
    /** @var array<int, array{line: int, kind: string}> */
    private static $probes = [];
    /** @var array<int, int> */
    private static $hits = [];
    /** @var array<int, int> hits sent with values */
    private static $sent = [];
    /** @var array<int, int> the last hit sent */
    private static $lastSent = [];
    /** @var array<int, float> */
    private static $sampledAt = [];
    /** @var float */
    private static $start = 0.0;
    /** @var float|null */
    private static $lastMark;
    /** @var int */
    private static $bytes = 0;
    /** @var array<int, array<int, mixed>> */
    private static $echo = [];
    /** @var ValueNormalizer|null */
    private static $normalizer;
    /** @var int */
    private static $maxHits = 100;
    /** @var int */
    private static $maxBytes = 16777216;

    /** Seconds between sampled values after a probe's first hits. */
    private const SAMPLE_SECONDS = 0.25;

    /**
     * @internal Called by the runner with the compiled probes before the snippet runs.
     * @param array<int, array{line: int, kind: string, comment: string}> $probes
     * @param array<string, mixed> $limits
     */
    public static function install(array $probes, array $limits): void
    {
        self::$probes = [];
        foreach ($probes as $id => $probe) {
            self::$probes[(int) $id] = ['line' => (int) $probe['line'], 'kind' => (string) $probe['kind']];
        }
        self::$hits = [];
        self::$sent = [];
        self::$lastSent = [];
        self::$sampledAt = [];
        self::$echo = [];
        self::$bytes = 0;
        self::$lastMark = null;
        self::$maxHits = max(1, (int) ($limits['maxInlineHits'] ?? 100));
        self::$maxBytes = max(0, (int) ($limits['maxInlineBytes'] ?? 16777216));
        self::$normalizer = new ValueNormalizer([
            'maxDepth' => min(5, (int) ($limits['maxDepth'] ?? 8)),
            'maxChildren' => 100,
            'maxStringBytes' => 8192,
            'maxNodes' => 2500,
            'maxValueBytes' => 262144,
        ]);
        self::$active = self::$probes !== [];
    }

    /** @internal The snippet starts running now: elapsed times count from here. */
    public static function begin(): void
    {
        self::$start = microtime(true);
        self::$lastMark = null;
    }

    /**
     * @param mixed $value
     * @return mixed
     */
    public static function at(int $id, $value)
    {
        self::value($id, $value);

        return $value;
    }

    /**
     * Where the code takes the expression by reference (a by-reference argument, `=&`,
     * `foreach (… as &$v)`, a by-reference return): the reference passes through.
     *
     * @param mixed $value
     * @return mixed
     */
    public static function &ref(int $id, &$value)
    {
        self::value($id, $value);

        return $value;
    }

    /**
     * `$i++; //?`: returns the expression's own value, shows the variable's new value.
     *
     * @param mixed $result
     * @param mixed $value
     * @return mixed
     */
    public static function after(int $id, $result, $value)
    {
        self::value($id, $value);

        return $result;
    }

    /**
     * `/*?->count()*\/`: shows the projection, returns the value itself. The projection is
     * user code (it may query a database); it runs only for hits whose values are sent.
     *
     * @param mixed $value
     * @return mixed
     */
    public static function tap(int $id, $value, \Closure $projection)
    {
        if (!self::$active || !isset(self::$probes[$id])) {
            return $value;
        }
        $hit = self::count($id);
        if (!self::sends($id, $hit)) {
            return $value;
        }
        try {
            $projected = $projection($value);
        } catch (\Throwable $error) {
            self::emit($id, $hit, ['error' => ['className' => get_class($error), 'message' => self::clip($error->getMessage(), 2000)]]);

            return $value;
        }
        self::emit($id, $hit, ['value' => self::normalize($projected)]);

        return $value;
    }

    /**
     * `/*?.*\/` after an expression: the time since the previous mark, then the value.
     *
     * @param mixed $value
     * @return mixed
     */
    public static function time(int $id, $value)
    {
        self::mark($id);

        return $value;
    }

    /** `/*?.*\/` between statements. */
    public static function mark(int $id): void
    {
        if (!self::$active || !isset(self::$probes[$id])) {
            return;
        }
        $now = microtime(true);
        $elapsed = ($now - (self::$lastMark ?? self::$start)) * 1000;
        self::$lastMark = $now;
        $hit = self::count($id);
        if (self::sends($id, $hit)) {
            self::emit($id, $hit, ['ms' => round($elapsed, 3)]);
        }
    }

    /**
     * `//?` after the snippet's final expression (which becomes its result): reached once
     * the value is ready.
     *
     * @param mixed $value
     * @return mixed
     */
    public static function reached(int $id, $value)
    {
        self::hit($id);

        return $value;
    }

    /** `//?` on a line with no value: the line was reached. */
    public static function hit(int $id): void
    {
        if (!self::$active || !isset(self::$probes[$id])) {
            return;
        }
        $hit = self::count($id);
        if (self::sends($id, $hit)) {
            self::emit($id, $hit, []);
        }
    }

    /**
     * `echo $a, $b; //?`: collects the arguments, shows them as a list after the last one.
     *
     * @param mixed $value
     * @return mixed
     */
    public static function echoArg(int $id, int $index, int $count, $value)
    {
        if (!self::$active) {
            return $value;
        }
        if ($index === 0) {
            self::$echo[$id] = [];
        }
        self::$echo[$id][] = $value;
        if ($index === $count - 1) {
            $values = self::$echo[$id];
            unset(self::$echo[$id]);
            self::value($id, $values);
        }

        return $value;
    }

    /** @internal Sends the final count of probes whose last hits were not sent. */
    public static function finish(): void
    {
        if (!self::$active) {
            return;
        }
        self::$active = false;
        foreach (self::$hits as $id => $hits) {
            if ($hits > (self::$lastSent[$id] ?? 0)) {
                Channel::emit('inline', ['probe' => $id, 'line' => self::$probes[$id]['line'], 'kind' => self::$probes[$id]['kind'], 'hit' => $hits, 'final' => true]);
            }
        }
        self::$echo = [];
    }

    /** @param mixed $value */
    private static function value(int $id, $value): void
    {
        if (!self::$active || !isset(self::$probes[$id])) {
            return;
        }
        $hit = self::count($id);
        if (self::sends($id, $hit)) {
            self::emit($id, $hit, ['value' => self::normalize($value)]);
        }
    }

    private static function count(int $id): int
    {
        self::$hits[$id] = (self::$hits[$id] ?? 0) + 1;

        return self::$hits[$id];
    }

    /** The first hits of a probe are sent; later ones about four times a second. */
    private static function sends(int $id, int $hit): bool
    {
        if ($hit <= self::$maxHits) {
            return true;
        }
        $now = microtime(true);
        if ($now - (self::$sampledAt[$id] ?? 0.0) >= self::SAMPLE_SECONDS) {
            self::$sampledAt[$id] = $now;

            return true;
        }

        return false;
    }

    /** @param array<string, mixed> $fields */
    private static function emit(int $id, int $hit, array $fields): void
    {
        try {
            $payload = [
                'probe' => $id,
                'line' => self::$probes[$id]['line'],
                'kind' => self::$probes[$id]['kind'],
                'hit' => $hit,
                't' => round((microtime(true) - self::$start) * 1000, 3),
            ];
            if ($hit > self::$maxHits) {
                $payload['sampled'] = true;
            }
            if (isset($fields['value'])) {
                $size = strlen((string) json_encode($fields['value'], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR));
                if (self::$bytes + $size > self::$maxBytes) {
                    unset($fields['value']);
                    $payload['omitted'] = 'bytes';
                } else {
                    self::$bytes += $size;
                }
            }
            self::$sent[$id] = (self::$sent[$id] ?? 0) + 1;
            self::$lastSent[$id] = $hit;
            Channel::emit('inline', $payload + $fields);
        } catch (\Throwable $error) {
            // A probe must never break the code it watches.
        }
    }

    /**
     * @param mixed $value
     * @return array<string, mixed>
     */
    private static function normalize($value): array
    {
        if (self::$normalizer === null) {
            return ['id' => 0, 'type' => 'unknown'];
        }
        try {
            return self::$normalizer->normalize($value);
        } catch (\Throwable $error) {
            return ['id' => 0, 'type' => 'unknown', 'scalar' => 'Runlet could not inspect this value: ' . $error->getMessage()];
        }
    }

    private static function clip(string $text, int $limit): string
    {
        return strlen($text) > $limit ? substr($text, 0, $limit) . '…' : $text;
    }
}
}

/*
 * App Info panels (#19).
 *
 * A request with `"mode": "panels"` boots the project exactly like a run, runs no snippet,
 * and reports key/value sections about the application instead: built-in ones for Laravel
 * (the data `artisan about` shows), Symfony, and WordPress, a PHP section for every target,
 * and then the driver's own `panels()`. Two `panels` events carry them (`origin` "builtin",
 * then "driver"), so a driver whose panels() fails or exits still leaves the built-ins.
 *
 * Everything is bounded (sections, rows, key and value lengths, total bytes) and passes
 * through the same redaction rule before it leaves the process: values whose key names a
 * secret (password, secret, token, key, salt, credential, …) are replaced, and so are
 * secret-looking values anywhere (credentials in URLs and DSNs, `password=` pairs, Laravel
 * `base64:` keys, JWTs, private key blocks, well-known API token prefixes). The app applies
 * the same rule again when it decodes the panels (`AppInfoRedaction` in RunletCore).
 *
 * This file must stay compatible with PHP 7.4 syntax and runtime.
 */

namespace RunletRunner {

final class AppInfo
{
    /** Most sections in all, rows per section, items in a list value. */
    public const MAX_SECTIONS = 20;
    public const MAX_ROWS = 100;
    public const MAX_LIST = 50;
    /** Longest section title, row key, and value (bytes, cut on a UTF-8 boundary). */
    public const MAX_TITLE = 120;
    public const MAX_KEY = 200;
    public const MAX_VALUE = 2000;
    /** Bytes of keys and values in all; later rows are left out and counted. */
    public const MAX_BYTES = 262144;
    /** What a redacted value shows. */
    public const REDACTED = '••••••';

    /** Words that make a key a secret (after splitting on case changes and punctuation). */
    private const SECRET_WORDS = ['password', 'passwords', 'passwd', 'pwd', 'pass', 'passphrase', 'secret', 'secrets', 'token', 'tokens',
        'key', 'keys', 'apikey', 'salt', 'salts', 'credential', 'credentials', 'signature', 'cookie', 'cookies', 'dsn', 'nonce'];
    /** Substrings of a key with its punctuation removed ("APIKEY", "dbpassword"). */
    private const SECRET_PARTS = ['password', 'passwd', 'secret', 'token', 'apikey', 'privatekey', 'accesskey', 'credential'];

    /** @var int */
    private static $sections = 0;
    /** @var int */
    private static $bytes = 0;
    /** @var string */
    private static $root = '';
    /** @var string */
    private static $home = '';

    /**
     * The built-in sections: the framework's own (by the driver that booted the project), then
     * PHP. A built-in that fails becomes a note; the others are still reported.
     *
     * A driver that extends LaravelDriver or SymfonyDriver gets that framework's section from
     * the application it booted; any driver gets the Laravel sections when it bootstrapped
     * Laravel's global application, and the WordPress ones once WordPress is loaded.
     *
     * @return array<string, mixed> the `panels` event payload
     */
    public static function builtin(\Runlet\Driver $driver, string $projectPath, string $source): array
    {
        self::$root = rtrim($projectPath, '/');
        $home = getenv('HOME');
        self::$home = is_string($home) && strlen($home) > 1 ? rtrim($home, '/') : '';
        $notes = [];
        $sections = [];
        $collectors = [];
        $app = $driver instanceof \Runlet\Drivers\LaravelDriver ? self::protectedProperty($driver, \Runlet\Drivers\LaravelDriver::class, 'app') : self::bootedLaravel();
        if (is_object($app)) {
            $collectors['Laravel'] = static function () use ($app, &$notes): array {
                try {
                    return self::laravel($app);
                } catch (\Throwable $error) {
                    // `about`'s data could not be read (a package's section failed, say).
                    $notes[] = 'Runlet could not read the data of `artisan about` (' . $error->getMessage() . '), so it shows the configuration instead.';

                    return self::laravelConfig($app);
                }
            };
        } elseif ($driver instanceof \Runlet\Drivers\SymfonyDriver) {
            $kernel = self::protectedProperty($driver, \Runlet\Drivers\SymfonyDriver::class, 'kernel');
            if (is_object($kernel)) {
                $collectors['Symfony'] = static function () use ($kernel): array {
                    return self::symfony($kernel);
                };
            }
        } elseif ($driver instanceof \Runlet\Drivers\WordPressDriver || (defined('ABSPATH') && function_exists('get_bloginfo'))) {
            $collectors['WordPress'] = static function (): array {
                return self::wordpress();
            };
        }
        $collectors['PHP'] = static function (): array {
            return self::php();
        };
        foreach ($collectors as $name => $collect) {
            try {
                $sections = array_merge($sections, $collect());
            } catch (\Throwable $error) {
                $notes[] = 'Runlet could not read the ' . $name . ' details: ' . $error->getMessage();
            }
        }

        return self::payload('builtin', $source, $sections, $notes);
    }

    /**
     * The driver's panels() as a `panels` event payload: sections keyed by title
     * (`'Acme' => ['Tenant' => 'acme', …]`), or a list of `['title' => …, 'rows' => …]`.
     *
     * @param mixed $panels what panels() returned
     * @return array<string, mixed>
     */
    public static function driver($panels, string $source): array
    {
        $notes = [];
        $sections = [];
        if (!is_array($panels)) {
            $notes[] = $source . ' returned ' . gettype($panels) . ' from panels(), not an array of sections.';
            $panels = [];
        }
        $skipped = [];
        foreach ($panels as $key => $entry) {
            if (is_array($entry) && is_int($key) && isset($entry['title']) && is_scalar($entry['title']) && is_array($entry['rows'] ?? null)) {
                $sections[] = [(string) $entry['title'], $entry['rows']];
            } elseif (is_array($entry) && is_string($key)) {
                $sections[] = [$key, $entry];
            } else {
                $skipped[] = is_string($key) ? $key : '#' . $key;
            }
        }
        if ($skipped !== []) {
            $notes[] = $source . ' returned panels that are not sections of rows, which Runlet skipped: ' . implode(', ', array_slice($skipped, 0, 10)) . '.';
        }

        return self::payload('driver', $source, $sections, $notes);
    }

    /**
     * Bounds and redacts sections given as [title, rows] pairs.
     *
     * @param array<int, array{0: string, 1: array<mixed>}> $sections
     * @param string[] $notes
     * @return array<string, mixed>
     */
    private static function payload(string $origin, string $source, array $sections, array $notes): array
    {
        $result = [];
        $omittedSections = 0;
        $redacted = 0;
        $omittedBytes = 0;
        foreach ($sections as [$title, $rows]) {
            if (self::$sections >= self::MAX_SECTIONS) {
                $omittedSections++;
                continue;
            }
            self::$sections++;
            $title = trim(self::clip(self::plain($title), self::MAX_TITLE));
            $section = ['title' => $title === '' ? 'Untitled' : $title, 'rows' => []];
            $omittedRows = 0;
            $index = 0;
            foreach ($rows as $key => $value) {
                $index++;
                if (is_int($key) && is_array($value) && (isset($value['key']) || isset($value['label'])) && array_key_exists('value', $value)) {
                    $key = $value['key'] ?? $value['label'];
                    $value = $value['value'];
                }
                if (count($section['rows']) >= self::MAX_ROWS || self::$bytes >= self::MAX_BYTES) {
                    $omittedRows++;
                    continue;
                }
                $key = trim(self::clip(self::paths(self::plain(is_scalar($key) ? (string) $key : '#' . $index)), self::MAX_KEY));
                $row = ['key' => $key === '' ? '#' . $index : $key];
                if (self::isSecretKey($row['key'])) {
                    $row['value'] = self::REDACTED;
                    $row['redacted'] = true;
                } else {
                    $value = self::value($value);
                    $masked = self::redactValue($value);
                    if ($masked !== $value) {
                        $row['redacted'] = true;
                    }
                    $row['value'] = $masked;
                }
                if (isset($row['redacted'])) {
                    $redacted++;
                }
                $size = strlen($row['key']) + strlen((string) json_encode($row['value'], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PARTIAL_OUTPUT_ON_ERROR));
                if (self::$bytes + $size > self::MAX_BYTES) {
                    self::$bytes = self::MAX_BYTES;
                    $omittedBytes++;
                    $omittedRows++;
                    continue;
                }
                self::$bytes += $size;
                $section['rows'][] = $row;
            }
            if ($omittedRows > 0) {
                $section['omittedRows'] = $omittedRows;
            }
            $result[] = $section;
        }
        if ($omittedSections > 0) {
            $notes[] = 'Runlet shows at most ' . self::MAX_SECTIONS . ' sections and left out ' . $omittedSections . ($omittedSections === 1 ? ' section' : ' sections') . ' from ' . $source . '.';
        }
        if ($omittedBytes > 0) {
            $notes[] = 'App Info is limited to ' . (self::MAX_BYTES / 1024) . ' KB, so ' . $omittedBytes . ($omittedBytes === 1 ? ' row' : ' rows') . ' from ' . $source . ' were left out.';
        }
        $payload = ['origin' => $origin, 'source' => $source, 'sections' => $result, 'redacted' => $redacted];
        if ($omittedSections > 0) {
            $payload['omittedSections'] = $omittedSections;
        }
        if ($notes !== []) {
            $payload['notes'] = array_map(static function (string $note): string {
                return self::clip($note, 1000);
            }, $notes);
        }

        return $payload;
    }

    // MARK: Redaction

    /** Whether a key names a secret: "APP_KEY", "DB_PASSWORD", "stripeSecret", "API token". */
    public static function isSecretKey(string $key): bool
    {
        $spaced = (string) preg_replace('/([a-z0-9])([A-Z])/', '$1 $2', $key);
        $words = preg_split('/[^a-z0-9]+/', strtolower($spaced), -1, PREG_SPLIT_NO_EMPTY) ?: [];
        foreach ($words as $word) {
            if (in_array($word, self::SECRET_WORDS, true)) {
                return true;
            }
        }
        $joined = implode('', $words);
        foreach (self::SECRET_PARTS as $part) {
            if (strpos($joined, $part) !== false) {
                return true;
            }
        }

        return false;
    }

    /**
     * Masks secret-looking parts of a value: the password in `scheme://user:password@host`,
     * `password=…` style pairs, and whole tokens (Laravel `base64:` keys, JWTs, private key
     * blocks, Stripe/GitHub/GitLab/Slack/AWS/Google keys, `Bearer …`). Lists are masked item
     * by item. Other values are returned unchanged.
     *
     * @param mixed $value
     * @return mixed
     */
    public static function redactValue($value)
    {
        if (is_array($value)) {
            return array_map([self::class, 'redactValue'], $value);
        }
        if (!is_string($value) || $value === '') {
            return $value;
        }
        $masked = (string) preg_replace('~-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----.*?(-----END [A-Z0-9 ]*PRIVATE KEY-----|$)~s', self::REDACTED, $value);
        $masked = (string) preg_replace('~^base64:[A-Za-z0-9+/]{16,}={0,2}$~', self::REDACTED, $masked);
        // user:password@ in URLs and DSNs (the user stays).
        $masked = (string) preg_replace('~([a-z][a-z0-9+.\-]*://[^:/?#@\s]*):[^@/?#\s]+@~i', '$1:' . self::REDACTED . '@', $masked);
        // password=…, token: …, api_key=… inside connection strings and query strings.
        $masked = (string) preg_replace('~\b((?:[a-z0-9]+[_\-.])*(?:password|passwd|pwd|pass|secret|token|api[_\-]?key|access[_\-]?key|private[_\-]?key|auth[_\-]?key|signature|sig))(\s*[=:]\s*)("[^"]*"|\'[^\']*\'|[^;&,\s]+)~i', '$1$2' . self::REDACTED, $masked);
        $masked = (string) preg_replace([
            '~\beyJ[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}~',
            '~\b(?:sk|pk|rk)_(?:live|test)_[A-Za-z0-9]{10,}~',
            '~\bgh[pousr]_[A-Za-z0-9]{20,}~',
            '~\bgithub_pat_[A-Za-z0-9_]{20,}~',
            '~\bglpat-[A-Za-z0-9_\-]{16,}~',
            '~\bxox[abprs]-[A-Za-z0-9\-]{10,}~',
            '~\bAKIA[0-9A-Z]{16}\b~',
            '~\bAIza[0-9A-Za-z_\-]{35}\b~',
            '#\b(Bearer|Basic)\s+[A-Za-z0-9._~+/\-]{16,}=*#',
        ], [self::REDACTED, self::REDACTED, self::REDACTED, self::REDACTED, self::REDACTED, self::REDACTED, self::REDACTED, self::REDACTED, '$1 ' . self::REDACTED], $masked);

        return $masked;
    }

    // MARK: Values

    /**
     * A row value: null, bool, int, a finite float, a string, or a list of strings; anything
     * else becomes a short string. Strings are bounded and paths are shortened.
     *
     * @param mixed $value
     * @return mixed
     */
    private static function value($value, int $depth = 0)
    {
        if ($value === null || is_bool($value) || is_int($value)) {
            return $value;
        }
        if (is_float($value)) {
            return is_finite($value) ? $value : (string) $value;
        }
        if (is_string($value)) {
            return self::clip(self::paths(self::plain($value)), self::MAX_VALUE);
        }
        if (is_array($value)) {
            $isList = $value === [] || array_keys($value) === range(0, count($value) - 1);
            if ($isList && $depth === 0) {
                $items = [];
                foreach (array_slice($value, 0, self::MAX_LIST) as $item) {
                    $item = self::value($item, 1);
                    $items[] = is_string($item) ? $item : self::scalarText($item);
                }
                if (count($value) > self::MAX_LIST) {
                    $items[] = '… ' . (count($value) - self::MAX_LIST) . ' more';
                }

                return $items;
            }
            $json = json_encode(self::jsonable($value, 0), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PARTIAL_OUTPUT_ON_ERROR);

            return self::clip(self::paths(is_string($json) ? $json : 'array(' . count($value) . ')'), self::MAX_VALUE);
        }
        if (is_object($value)) {
            return self::clip(self::paths(self::objectText($value)), self::MAX_VALUE);
        }

        return gettype($value);
    }

    /** @param mixed $value */
    private static function scalarText($value): string
    {
        if ($value === null) {
            return 'null';
        }
        if (is_bool($value)) {
            return $value ? 'true' : 'false';
        }

        return is_scalar($value) ? (string) $value : (string) json_encode($value);
    }

    private static function objectText(object $value): string
    {
        try {
            if ($value instanceof \DateTimeInterface) {
                return $value->format(DATE_ATOM);
            }
            if (function_exists('enum_exists') && $value instanceof \UnitEnum) {
                return $value instanceof \BackedEnum ? (string) $value->value : $value->name;
            }
            if (method_exists($value, '__toString')) {
                return (string) $value;
            }
            if ($value instanceof \JsonSerializable) {
                $json = json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PARTIAL_OUTPUT_ON_ERROR);

                return is_string($json) ? $json : get_class($value);
            }
        } catch (\Throwable $error) {
            // Fall back to the class name.
        }

        return \Runlet\Inspector::className(get_class($value)) . ' object';
    }

    /**
     * Nested arrays for JSON text: scalars as they are, objects as text, depth 3.
     *
     * @param mixed $value
     * @return mixed
     */
    private static function jsonable($value, int $depth)
    {
        if (is_array($value)) {
            if ($depth >= 3) {
                return 'array(' . count($value) . ')';
            }
            $result = [];
            foreach (array_slice($value, 0, self::MAX_LIST, true) as $key => $item) {
                $result[$key] = self::isSecretKey((string) $key) ? self::REDACTED : self::jsonable($item, $depth + 1);
            }

            return $result;
        }
        if (is_object($value)) {
            return self::objectText($value);
        }

        return is_float($value) && !is_finite($value) ? (string) $value : $value;
    }

    /** Removes console style tags (`<fg=yellow;options=bold>`, `</>`, `<info>`) and trims. */
    private static function plain(string $text): string
    {
        return trim((string) preg_replace('~</?(?:fg|bg|options|href)=[^>]*>|</>|</?(?:info|comment|question|error|warning)>~', '', $text));
    }

    /** Paths inside the project become relative to it; paths in the home folder start with ~. */
    private static function paths(string $text): string
    {
        if (self::$root !== '' && self::$root !== '/' && strpos($text, self::$root) !== false) {
            $root = preg_quote(self::$root, '~');
            $text = (string) preg_replace(['~' . $root . '/~', '~' . $root . '(?![\w.\-])~'], ['', '.'], $text);
        }
        if (self::$home !== '' && strpos($text, self::$home . '/') !== false) {
            $text = str_replace(self::$home . '/', '~/', $text);
        }

        return $text;
    }

    private static function clip(string $text, int $limit): string
    {
        [$clipped, $omitted] = \Runlet\Inspector::clip($text, $limit);

        return $omitted > 0 ? $clipped . '…' : $clipped;
    }

    /** Laravel's global application, when a project driver bootstrapped it. */
    private static function bootedLaravel(): ?object
    {
        $application = 'Illuminate\Foundation\Application';
        if (!class_exists($application, false) || !class_exists('Illuminate\Container\Container', false)) {
            return null;
        }
        $app = \Illuminate\Container\Container::getInstance();

        return $app instanceof $application && method_exists($app, 'hasBeenBootstrapped') && $app->hasBeenBootstrapped() ? $app : null;
    }

    /** @return mixed */
    private static function protectedProperty(object $object, string $class, string $name)
    {
        try {
            $property = new \ReflectionProperty($class, $name);
            $property->setAccessible(true);

            return $property->getValue($object);
        } catch (\Throwable $error) {
            return null;
        }
    }

    // MARK: Laravel

    /**
     * What `artisan about` shows (Environment, Cache, Drivers, Storage, and sections packages
     * add with AboutCommand::add()), read in-process from the command's data provider with
     * the console wording ("Enabled", "Not cached", "stack / single"). Runlet doesn't run
     * `composer --version` for it, so Composer's version is left out. Lumen and Laravel before
     * 9.21 have no `about`; they get the same rows from the configuration.
     *
     * @return array<int, array{0: string, 1: array<string, mixed>}>
     */
    private static function laravel(object $app): array
    {
        $about = 'Illuminate\Foundation\Console\AboutCommand';
        if (!class_exists($about) || !method_exists($about, 'format') || !method_exists($about, 'gatherApplicationInformation') || !method_exists($app, 'call')) {
            return self::laravelConfig($app);
        }
        $composer = self::quietComposer($app);
        $command = $composer !== null ? new $about($composer) : $app->make($about);
        if (method_exists($command, 'setLaravel')) {
            $command->setLaravel($app);
        }
        $gather = new \ReflectionMethod($about, 'gatherApplicationInformation');
        $gather->setAccessible(true);
        $gather->invoke($command);
        $property = new \ReflectionProperty($about, 'data');
        $property->setAccessible(true);
        $data = $property->getValue();
        if (!is_array($data)) {
            return self::laravelConfig($app);
        }

        $sections = [];
        foreach ($data as $title => $items) {
            $rows = [];
            foreach ((array) $items as $item) {
                if (is_array($item)) {
                    $pairs = [$item];
                } else {
                    $resolver = is_string($item) ? $app->make($item) : $item;
                    $pairs = [];
                    foreach ((array) $app->call($resolver) as $key => $value) {
                        $pairs[] = [$key, $value];
                    }
                }
                foreach ($pairs as $pair) {
                    if (!is_array($pair) || !array_key_exists(0, $pair)) {
                        continue;
                    }
                    $value = $pair[1] ?? null;
                    if ($value instanceof \Closure) {
                        $value = $value(false);
                    }
                    if ($composer !== null && (string) $pair[0] === 'Composer Version') {
                        continue;
                    }
                    $rows[(string) $pair[0]] = is_string($value) ? self::consoleWords($value) : $value;
                }
            }
            $sections[(string) $title] = $rows;
        }
        // `about` lists Environment, Cache, and Drivers first, in that order.
        $order = ['Environment', 'Cache', 'Drivers'];
        uksort($sections, static function ($left, $right) use ($order): int {
            $a = array_search($left, $order, true);
            $b = array_search($right, $order, true);

            return ($a === false ? 99 : $a) <=> ($b === false ? 99 : $b);
        });
        $result = [];
        foreach ($sections as $title => $rows) {
            $result[] = [(string) $title, $rows];
        }

        return $result;
    }

    /**
     * Illuminate\Support\Composer without `composer --version` (a process Runlet doesn't
     * start), when getVersion() can be overridden safely; else null (the container's).
     */
    private static function quietComposer(object $app): ?object
    {
        $class = 'Illuminate\Support\Composer';
        try {
            if (!class_exists($class) || !method_exists($app, 'make') || !method_exists($app, 'basePath')) {
                return null;
            }
            $method = new \ReflectionMethod($class, 'getVersion');
            $constructor = new \ReflectionMethod($class, '__construct');
            if ($method->hasReturnType() || $method->getNumberOfParameters() > 0 || $constructor->getNumberOfRequiredParameters() > 2) {
                return null;
            }

            return new class($app->make('files'), $app->basePath()) extends \Illuminate\Support\Composer {
                public function getVersion()
                {
                    return null;
                }
            };
        } catch (\Throwable $error) {
            return null;
        }
    }

    /** "ENABLED" → "Enabled", "NOT CACHED" → "Not cached"; other text unchanged. */
    private static function consoleWords(string $value): string
    {
        $value = trim(strip_tags($value));
        if (preg_match('/^[A-Z][A-Z ]+$/', $value) && in_array($value, ['ENABLED', 'OFF', 'CACHED', 'NOT CACHED', 'LINKED', 'NOT LINKED'], true)) {
            return ucfirst(strtolower($value));
        }

        return $value;
    }

    /**
     * The configuration rows of `about`, for Lumen and Laravel without the command.
     *
     * @return array<int, array{0: string, 1: array<string, mixed>}>
     */
    private static function laravelConfig(object $app): array
    {
        $config = null;
        if (method_exists($app, 'bound') && $app->bound('config')) {
            $config = $app->make('config');
        }
        $get = static function (string $key) use ($config) {
            return is_object($config) && method_exists($config, 'get') ? $config->get($key) : null;
        };
        $version = method_exists($app, 'version') ? (string) $app->version() : null;
        $environment = method_exists($app, 'environment') ? $app->environment() : $get('app.env');
        $maintenance = method_exists($app, 'isDownForMaintenance') ? $app->isDownForMaintenance() : null;

        return array_values(array_filter([
            ['Environment', array_filter([
                'Application Name' => $get('app.name'),
                'Laravel Version' => $version,
                'PHP Version' => PHP_VERSION,
                'Environment' => is_string($environment) ? $environment : null,
                'Debug Mode' => $get('app.debug') ? 'Enabled' : 'Off',
                'URL' => is_string($get('app.url')) ? preg_replace('~^https?://~', '', (string) $get('app.url')) : null,
                'Maintenance Mode' => $maintenance === null ? null : ($maintenance ? 'Enabled' : 'Off'),
                'Timezone' => $get('app.timezone'),
                'Locale' => $get('app.locale'),
            ], static function ($value): bool {
                return $value !== null;
            })],
            ['Drivers', array_filter([
                'Broadcasting' => $get('broadcasting.default'),
                'Cache' => $get('cache.default'),
                'Database' => $get('database.default'),
                'Logs' => $get('logging.default'),
                'Mail' => $get('mail.default') ?? $get('mail.driver'),
                'Queue' => $get('queue.default'),
                'Session' => $get('session.driver'),
            ], static function ($value): bool {
                return $value !== null;
            })],
        ], static function (array $section): bool {
            return $section[1] !== [];
        }));
    }

    // MARK: Symfony

    /**
     * The kernel part of `bin/console about`: version and support dates, environment, debug,
     * charset, kernel class, cache and log folders, and the number of bundles.
     *
     * @return array<int, array{0: string, 1: array<string, mixed>}>
     */
    private static function symfony(object $kernel): array
    {
        $kernelClass = 'Symfony\Component\HttpKernel\Kernel';
        $constant = static function (string $name) use ($kernelClass): ?string {
            return defined($kernelClass . '::' . $name) ? (string) constant($kernelClass . '::' . $name) : null;
        };
        $call = static function (string $method) use ($kernel) {
            return method_exists($kernel, $method) ? $kernel->{$method}() : null;
        };
        $debug = $call('isDebug');
        $bundles = $call('getBundles');

        return [['Symfony', array_filter([
            'Version' => $constant('VERSION'),
            'End of maintenance' => $constant('END_OF_MAINTENANCE'),
            'End of life' => $constant('END_OF_LIFE'),
            'Environment' => $call('getEnvironment'),
            'Debug' => $debug === null ? null : ($debug ? 'Enabled' : 'Off'),
            'Charset' => $call('getCharset'),
            'Kernel' => get_class($kernel),
            'Cache directory' => $call('getCacheDir'),
            'Build directory' => $call('getBuildDir'),
            'Log directory' => $call('getLogDir'),
            'Bundles' => is_array($bundles) ? count($bundles) : null,
        ], static function ($value): bool {
            return $value !== null;
        })]];
    }

    // MARK: WordPress

    /**
     * WordPress version, environment type, URLs, theme, multisite, plugins, and the debug
     * constants from wp-config.php.
     *
     * @return array<int, array{0: string, 1: array<string, mixed>}>
     */
    private static function wordpress(): array
    {
        $call = static function (string $function, ...$arguments) {
            return function_exists($function) ? $function(...$arguments) : null;
        };
        $theme = $call('wp_get_theme');
        $themeName = null;
        if (is_object($theme) && method_exists($theme, 'get')) {
            $themeName = trim($theme->get('Name') . ' ' . $theme->get('Version'));
            if ($call('is_child_theme') === true && method_exists($theme, 'parent') && is_object($theme->parent())) {
                $themeName .= ' (child of ' . $theme->parent()->get('Name') . ')';
            }
        }
        $plugins = $call('get_option', 'active_plugins', []);
        $multisite = $call('is_multisite') === true;
        $network = $multisite ? $call('get_site_option', 'active_sitewide_plugins', []) : [];
        $permalinks = $call('get_option', 'permalink_structure');
        $site = array_filter([
            'Version' => $call('get_bloginfo', 'version'),
            'Environment type' => $call('wp_get_environment_type'),
            'Site URL' => $call('site_url'),
            'Home URL' => $call('home_url'),
            'Active theme' => $themeName,
            'Multisite' => $multisite ? 'Yes' : 'No',
            'Active plugins' => is_array($plugins) ? count($plugins) + (is_array($network) ? count($network) : 0) : null,
            'Permalinks' => is_string($permalinks) ? ($permalinks === '' ? 'Plain' : $permalinks) : null,
            'Locale' => $call('get_locale'),
            'Timezone' => $call('wp_timezone_string'),
        ], static function ($value): bool {
            return $value !== null && $value !== '';
        });

        $flag = static function (string $name) {
            if (!defined($name)) {
                return null;
            }
            $value = constant($name);

            return is_bool($value) ? ($value ? 'On' : 'Off') : $value;
        };
        $debug = array_filter([
            'WP_DEBUG' => $flag('WP_DEBUG'),
            'WP_DEBUG_LOG' => $flag('WP_DEBUG_LOG'),
            'WP_DEBUG_DISPLAY' => $flag('WP_DEBUG_DISPLAY'),
            'SCRIPT_DEBUG' => $flag('SCRIPT_DEBUG'),
            'SAVEQUERIES' => $flag('SAVEQUERIES'),
            'WP_CACHE' => $flag('WP_CACHE'),
            'DISABLE_WP_CRON' => $flag('DISABLE_WP_CRON'),
            'WP_MEMORY_LIMIT' => $flag('WP_MEMORY_LIMIT'),
        ], static function ($value): bool {
            return $value !== null;
        });

        global $wpdb;
        $database = [];
        if (is_object($wpdb)) {
            $server = method_exists($wpdb, 'db_server_info') ? $wpdb->db_server_info() : (method_exists($wpdb, 'db_version') ? $wpdb->db_version() : null);
            $database = array_filter([
                'Server' => is_string($server) ? $server : null,
                'Name' => defined('DB_NAME') ? (string) DB_NAME : null,
                'Host' => defined('DB_HOST') ? (string) DB_HOST : null,
                'Charset' => defined('DB_CHARSET') ? (string) DB_CHARSET : null,
                'Table prefix' => isset($wpdb->prefix) && is_string($wpdb->prefix) ? $wpdb->prefix : null,
            ], static function ($value): bool {
                return $value !== null && $value !== '';
            });
        }

        return array_values(array_filter([['WordPress', $site], ['Debug', $debug], ['Database', $database]], static function (array $section): bool {
            return $section[1] !== [];
        }));
    }

    // MARK: PHP

    /**
     * The PHP that boots the project: version, memory limit, OPcache and Xdebug for the CLI,
     * time zone, php.ini, PDO drivers, and how many extensions are loaded.
     *
     * @return array<int, array{0: string, 1: array<string, mixed>}>
     */
    private static function php(): array
    {
        $opcache = 'Not loaded';
        if (extension_loaded('Zend OPcache')) {
            $opcache = filter_var(ini_get('opcache.enable_cli'), FILTER_VALIDATE_BOOLEAN) ? 'Enabled' : 'Off for the CLI';
        }
        $xdebug = phpversion('xdebug');
        $mode = ini_get('xdebug.mode');
        $ini = php_ini_loaded_file();

        return [['PHP', array_filter([
            'Version' => PHP_VERSION,
            'Memory limit' => (string) ini_get('memory_limit'),
            'OPcache' => $opcache,
            'Xdebug' => is_string($xdebug) ? $xdebug . (is_string($mode) && $mode !== '' ? ' (mode: ' . $mode . ')' : '') : 'Not loaded',
            'Time zone' => date_default_timezone_get(),
            'php.ini' => is_string($ini) ? $ini : 'None',
            'PDO drivers' => class_exists('PDO') ? \PDO::getAvailableDrivers() : null,
            'Extensions' => count(get_loaded_extensions()),
        ], static function ($value): bool {
            return $value !== null;
        })]];
    }
}
}

